pub const ColType = enum { int, float, text, boolean, date, timestamp };
pub fn mapType(name: []const u8) ColType {
    var buf: [64]u8 = undefined;
    const n = @min(name.len, buf.len);
    const lower = std.ascii.lowerString(buf[0..n], name[0..n]);
    if (std.mem.startsWith(u8, lower, "lowcardinality") or
        std.mem.startsWith(u8, lower, "nullable") or std.mem.startsWith(u8, lower, "string") or std.mem.startsWith(u8, lower, "text") or std.mem.startsWith(u8, lower, "varchar") or std.mem.startsWith(u8, lower, "char") or
        std.mem.startsWith(u8, lower, "uuid") or std.mem.startsWith(u8, lower, "json") or std.mem.startsWith(u8, lower, "txid_snapshot") or std.mem.startsWith(u8, lower, "pg_snapshot") or std.mem.startsWith(u8, lower, "xid")) return .text;
    if (std.mem.startsWith(u8, lower, "float") or std.mem.startsWith(u8, lower, "double") or std.mem.startsWith(u8, lower, "real") or std.mem.startsWith(u8, lower, "decimal") or std.mem.startsWith(u8, lower, "numeric")) return .float;
    if (std.mem.startsWith(u8, lower, "bool")) return .boolean;
    if (std.mem.startsWith(u8, lower, "\"char\"")) return .text;
    if (std.mem.startsWith(u8, lower, "date") and !std.mem.startsWith(u8, lower, "datetime")) return .date;
    if (std.mem.startsWith(u8, lower, "datetime") or std.mem.startsWith(u8, lower, "timestamp")) return .timestamp;
    if (std.mem.startsWith(u8, lower, "name") or std.mem.startsWith(u8, lower, "bytea") or
        std.mem.startsWith(u8, lower, "point") or std.mem.startsWith(u8, lower, "path") or std.mem.startsWith(u8, lower, "line") or std.mem.startsWith(u8, lower, "lseg") or std.mem.startsWith(u8, lower, "box") or std.mem.startsWith(u8, lower, "polygon") or
        std.mem.startsWith(u8, lower, "circle") or std.mem.startsWith(u8, lower, "inet") or std.mem.startsWith(u8, lower, "cidr") or std.mem.startsWith(u8, lower, "macaddr") or std.mem.startsWith(u8, lower, "bit") or std.mem.startsWith(u8, lower, "money") or
        std.mem.startsWith(u8, lower, "interval") or std.mem.startsWith(u8, lower, "timetz") or std.mem.startsWith(u8, lower, "time")) return .text;
    return .int;
}
