fn isClickHouseTypeName(name: []const u8) bool {
    var buf: [64]u8 = undefined;
    const n = @min(name.len, buf.len);
    const lower = std.ascii.lowerString(buf[0..n], name[0..n]);
    return std.mem.startsWith(u8, lower, "uint") or
        std.mem.startsWith(u8, lower, "int8") or std.mem.startsWith(u8, lower, "int16") or std.mem.startsWith(u8, lower, "int32") or std.mem.startsWith(u8, lower, "int64") or std.mem.startsWith(u8, lower, "float32") or
        std.mem.startsWith(u8, lower, "float64") or std.mem.startsWith(u8, lower, "string");
}
