            if (c.type_name.len > 0) gpa.free(c.type_name);
            if (c.default_text.len > 0) gpa.free(c.default_text);
        }
        gpa.free(self.cols);
        gpa.free(self.name);
        self.arena.deinit();
        gpa.destroy(self);
    }
};
