    var start: usize = 0;
    while (term - start >= 50) start += 1;
    if (start <= 3) start = 0;
    const prefix: []const u8 = if (start > 0) "..." else "";
    const suffix: []const u8 = if (term < src.len and src[term] != '\n' and src[term] != '\r') "..." else "";
