    i: usize = 0,
    fn next(self: *RawCur) ?[]const u8 {
        while (self.i < self.s.len and (std.ascii.isWhitespace(self.s[self.i]) or self.s[self.i] == ',' or self.s[self.i] == ';' or self.s[self.i] == '(' or self.s[self.i] == ')')) self.i += 1;
        if (self.i >= self.s.len) return null;
        const st = self.i;
        while (self.i < self.s.len and !(std.ascii.isWhitespace(self.s[self.i]) or self.s[self.i] == ',' or self.s[self.i] == ';' or self.s[self.i] == '(' or self.s[self.i] == ')')) self.i += 1;
        return self.s[st..self.i];
    }
    fn parens(self: *RawCur) ?[]const u8 {
        while (self.i < self.s.len and std.ascii.isWhitespace(self.s[self.i])) self.i += 1;
        if (self.i >= self.s.len or self.s[self.i] != '(') return null;
        self.i += 1;
        const st = self.i;
        var depth: usize = 1;
        while (self.i < self.s.len and depth > 0) {
            if (self.s[self.i] == '(') depth += 1;
            if (self.s[self.i] == ')') {
                depth -= 1;
                if (depth == 0) break;
            }
            self.i += 1;
        }
        const out = self.s[st..@min(self.i, self.s.len)];
        if (self.i < self.s.len) self.i += 1;
        return out;
    }
};
fn hex4(content: []const u8, at: usize) ?u16 {
    if (at + 4 > content.len) return null;
    var v: u16 = 0;
    for (content[at .. at + 4]) |c| {
        const d = std.fmt.charToDigit(c, 16) catch return null;
        v = v * 16 + d;
    }
    return v;
}
fn appendUtf8(out: *std.ArrayList(u8), alloc: std.mem.Allocator, cp: u32) !void {
    if (cp <= 0x7f) try out.append(alloc, @intCast(cp)) else if (cp <= 0x7ff) {
        try out.append(alloc, @intCast(0xc0 | (cp >> 6)));
        try out.append(alloc, @intCast(0x80 | (cp & 0x3f)));
    } else if (cp <= 0xffff) {
        try out.append(alloc, @intCast(0xe0 | (cp >> 12)));
        try out.append(alloc, @intCast(0x80 | ((cp >> 6) & 0x3f)));
        try out.append(alloc, @intCast(0x80 | (cp & 0x3f)));
    } else {
        try out.append(alloc, @intCast(0xf0 | (cp >> 18)));
        try out.append(alloc, @intCast(0x80 | ((cp >> 12) & 0x3f)));
        try out.append(alloc, @intCast(0x80 | ((cp >> 6) & 0x3f)));
        try out.append(alloc, @intCast(0x80 | (cp & 0x3f)));
    }
}
fn castJsonpath(alloc: std.mem.Allocator, input: []const u8) EngineError![]const u8 {
    var prefix: []const u8 = "";
    var body = input;
    if (std.mem.startsWith(u8, body, "$.\"")) {
        prefix = "$.\"";
        body = body[3..];
    } else if (body.len > 0 and body[0] == '"') {
        prefix = "\"";
        body = body[1..];
    } else return error.JsonpathInvalid;
    if (body.len == 0 or body[body.len - 1] != '"') return error.JsonpathInvalid;
    const content = body[0 .. body.len - 1];
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(alloc);
    var i: usize = 0;
    while (i < content.len) {
        const c = content[i];
        if (c != '\\') {
            try out.append(alloc, c);
            i += 1;
            continue;
        }
        if (i + 1 >= content.len) {
            try out.append(alloc, '\\');
            i += 1;
            continue;
        }
        if (content[i + 1] == '\\') {
            try out.appendSlice(alloc, "\\\\");
            i += 2;
            continue;
        }
        if (content[i + 1] != 'u') {
            try out.append(alloc, '\\');
            try out.append(alloc, content[i + 1]);
            i += 2;
            continue;
        }
        var digits: usize = 0;
        var cp: ?u16 = null;
        if (i + 2 + 4 <= content.len) {
            cp = hex4(content, i + 2);
            digits = if (cp == null) 0 else 4;
        }
        if (cp == null) {
            var n: usize = 0;
            while (n < 4 and i + 2 + n < content.len and std.ascii.isHex(content[i + 2 + n])) n += 1;
            const near = content[i .. i + 2 + n];
            setDiag("invalid Unicode escape sequence at or near \"{s}\" of jsonpath input", .{near});
            return error.InvalidUnicodeEscape;
        }
        const code = cp.?;
        if (code == 0) {
            setDiag("unsupported Unicode escape sequence\nDETAIL:  \\u0000 cannot be converted to text.", .{});
            return error.JsonpathUnsupportedUnicode;
        }
        if (code >= 0xD800 and code <= 0xDBFF) {
            if (i + 6 + 6 > content.len or content[i + 6] != '\\' or content[i + 7] != 'u' or hex4(content, i + 8) == null) {
                setDiag("invalid input syntax for type jsonpath\nDETAIL:  Unicode low surrogate must follow a high surrogate.", .{});
                return error.JsonpathInvalid;
            }
            const lo = hex4(content, i + 8).?;
            if (lo >= 0xD800 and lo <= 0xDBFF) {
                setDiag("invalid input syntax for type jsonpath\nDETAIL:  Unicode high surrogate must not follow a high surrogate.", .{});
                return error.JsonpathInvalid;
            }
            if (lo < 0xDC00 or lo > 0xDFFF) {
                setDiag("invalid input syntax for type jsonpath\nDETAIL:  Unicode low surrogate must follow a high surrogate.", .{});
                return error.JsonpathInvalid;
            }
            const combined: u32 = 0x10000 + (@as(u32, code - 0xD800) << 10) + (lo - 0xDC00);
            try appendUtf8(&out, alloc, combined);
            i += 12;
            continue;
        }
        if (code >= 0xDC00 and code <= 0xDFFF) {
            setDiag("invalid input syntax for type jsonpath\nDETAIL:  Unicode low surrogate must follow a high surrogate.", .{});
            return error.JsonpathInvalid;
        }
        try appendUtf8(&out, alloc, code);
        i += 6;
    }
    var res = std.ArrayList(u8).empty;
    errdefer res.deinit(alloc);
    try res.appendSlice(alloc, prefix);
    try res.appendSlice(alloc, out.items);
    try res.append(alloc, '"');
    return res.toOwnedSlice(alloc);
}
fn eqi(a: []const u8, b: []const u8) bool {
    return std.ascii.eqlIgnoreCase(a, b);
}
fn canonType(alloc: std.mem.Allocator, t0: []const u8) ![]const u8 {
    const t = std.mem.trim(u8, t0, " \t\r\n");
    var name = t;
    var arr = false;
    if (std.mem.endsWith(u8, name, "[]")) {
        arr = true;
        name = std.mem.trim(u8, name[0 .. name.len - 2], " ");
    }
    if (std.mem.lastIndexOfScalar(u8, name, '.')) |d| name = name[d + 1 ..];
    var base: []const u8 = name;
    if (eqi(name, "int") or eqi(name, "int4") or eqi(name, "integer")) base = "integer" else if (eqi(name, "int2")) base = "smallint" else if (eqi(name, "int8")) base = "bigint" else if (eqi(name, "bool")) base = "boolean" else if (eqi(name, "float8")) base = "double precision" else if (eqi(name, "float4")) base = "real" else if (eqi(name, "serial")) base = "integer" else if (eqi(name, "bigserial")) base = "bigint";
    var lbuf: [256]u8 = undefined;
    const low = std.ascii.lowerString(lbuf[0..@min(base.len, lbuf.len)], base[0..@min(base.len, lbuf.len)]);
    if (arr) return std.fmt.allocPrint(alloc, "{s}[]", .{low});
    return alloc.dupe(u8, low);
}
fn canonSig(alloc: std.mem.Allocator, args: []const u8) ![]const u8 {
    const a = std.mem.trim(u8, args, " \t\r\n");
    if (a.len == 0) return "";
    if (std.mem.eql(u8, a, "*")) return "*";
    var out = std.ArrayList(u8).empty;
    defer out.deinit(alloc);
    var it = std.mem.splitScalar(u8, a, ',');
    var first = true;
    while (it.next()) |part| {
        if (!first) try out.appendSlice(alloc, ", ");
        first = false;
        try out.appendSlice(alloc, try canonType(alloc, part));
    }
    return out.toOwnedSlice(alloc);
}
