            .create_matview => |mv0| blk: {
                var mv = mv0;
                if (self.resolveCreateName(mv.name)) |q| mv.name = q;
                const saved_m = tls_maintenance;
                tls_maintenance = true;
                const res = self.execSelect(alloc, mv.select, true) catch |e| {
                    tls_maintenance = saved_m;
