                    const pkey = self.gpa.dupe(u8, low) catch low;
                    const pval = self.gpa.dupe(u8, f.args) catch "";
                    self.sql_args.put(pkey, pval) catch {
                        self.gpa.free(pkey);
                        if (pval.len > 0) self.gpa.free(pval);
                    };
                } else {
                    if (self.sql_funcs.fetchRemove(low)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    self.sql_funcs.put(key, body) catch {
                        self.gpa.free(key);
                        self.gpa.free(body);
                        return error.OutOfMemory;
                    };
                    if (self.sql_args.fetchRemove(low)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    const akey = self.gpa.dupe(u8, low) catch low;
                    const aval = self.gpa.dupe(u8, f.args) catch "";
                    self.sql_args.put(akey, aval) catch {
                        self.gpa.free(akey);
                        if (aval.len > 0) self.gpa.free(aval);
                    };
                }
                {
                    const sk = self.gpa.dupe(u8, low) catch "";
                    if (self.func_strict.fetchRemove(low)) |old| self.gpa.free(old.key);
                    self.func_strict.put(sk, f.strict) catch {};
                }
                const sig = canonSig(self.gpa, f.args) catch "";
                const sigkey = std.fmt.allocPrint(self.gpa, "{s}({s})", .{ low, sig }) catch return error.OutOfMemory;
                defer self.gpa.free(sigkey);
                self.registerDdlObject("function", sigkey);
                self.bumpFnCount("function", low, 1);
                {
                    const csig = canonSig(self.gpa, f.args) catch "";
                    const ak = self.gpa.dupe(u8, low) catch "";
                    var parts = std.ArrayList([]const u8).empty;
                    if (csig.len > 0) {
                        var pit = std.mem.splitScalar(u8, csig, ',');
                        while (pit.next()) |ps| {
                            const tn = std.mem.trim(u8, ps, " ");
                            const tv = self.gpa.dupe(u8, tn) catch continue;
                            parts.append(self.gpa, tv) catch {};
                        }
                    }
                    const owned = parts.toOwnedSlice(self.gpa) catch &.{};
                    if (self.func_argtypes.fetchRemove(low)) |old| {
                        self.gpa.free(old.key);
                        for (old.value) |x| self.gpa.free(x);
                        if (old.value.len > 0) self.gpa.free(old.value);
                    }
                    self.func_argtypes.put(ak, owned) catch {};
                }
                {
                    const rk = self.gpa.dupe(u8, low) catch "";
                    const rv = self.gpa.dupe(u8, f.ret_type) catch "";
                    if (self.func_rets.fetchRemove(low)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    self.func_rets.put(rk, rv) catch {};
                }
                if (!self.func_oids.contains(low)) {
                    const foid = self.next_func_oid;
                    self.next_func_oid += 1;
                    const fk = self.gpa.dupe(u8, low) catch "";
                    self.func_oids.put(fk, foid) catch {};
                    var fd = std.ArrayList(u8).empty;
                    defer fd.deinit(self.gpa);
                    fd.appendSlice(self.gpa, "function ") catch {};
                    fd.appendSlice(self.gpa, low) catch {};
                    fd.append(self.gpa, '(') catch {};
                    if (self.func_argtypes.get(low)) |ats| {
                        for (ats, 0..) |a, ai| {
                            if (ai > 0) fd.append(self.gpa, ',') catch {};
                            fd.appendSlice(self.gpa, a) catch {};
                        }
                    }
                    fd.append(self.gpa, ')') catch {};
                    self.dep_descs.append(self.gpa, .{ .classid = 1255, .objid = foid, .desc = fd.toOwnedSlice(self.gpa) catch "" }) catch {};
                }
                var sit = std.mem.splitScalar(u8, self.search_path, ',');
                while (sit.next()) |part| {
                    const sn = std.mem.trim(u8, part, " ");
                    if (sn.len == 0 or std.ascii.eqlIgnoreCase(sn, "public") or std.ascii.eqlIgnoreCase(sn, "pg_catalog")) continue;
                    if (!self.schema_oids.contains(sn)) continue;
                    const disp = std.fmt.allocPrint(self.gpa, "{s}.{s}({s})", .{ sn, low, sig }) catch continue;
                    const sk = self.gpa.dupe(u8, sn) catch continue;
                    self.schema_funcs.append(self.gpa, .{ .schema = sk, .display = disp }) catch {};
                    break;
                }
                break :blk .{};
            },
            .alter_operator => |ao| self.execAlterOperator(alloc, ao.sym, ao.left, ao.right, ao.attrs),
            .default_priv => |dp| blk: {
                var lb: [128]u8 = undefined;
                const rl = std.ascii.lowerString(lb[0..@min(dp.role.len, lb.len)], dp.role[0..@min(dp.role.len, lb.len)]);
                if (dp.schema.len > 0) {
                    const r = try self.gpa.dupe(u8, if (dp.role.len > 0) dp.role else self.curRoleName());
                    const sc = try self.gpa.dupe(u8, dp.schema);
                    const gr = try self.gpa.dupe(u8, dp.grantee);
                    self.default_privs.append(self.gpa, .{ .role = r, .schema = sc, .grantee = gr }) catch {};
                }
                if (dp.grant_insert) {
                    if (self.insert_revoked.fetchRemove(rl)) |kv| self.gpa.free(kv.key);
                } else {
                    const k = self.gpa.dupe(u8, rl) catch "";
                    self.insert_revoked.put(k, {}) catch {};
                }
                break :blk .{};
            },
            .revoke => |rv| blk: {
                const key = std.fmt.allocPrint(self.gpa, "{s}|{s}|{s}", .{ rv.target, @tagName(rv.kind), rv.name }) catch "";
                const k = self.gpa.dupe(u8, key) catch "";
                self.revoked.put(k, {}) catch {};
                break :blk .{};
            },
            .do_block => |db| blk: {
                try self.execDoBlock(alloc, db.body);
                break :blk .{};
            },
            .comment_role => |cr| self.execCommentRole(cr),
            .comment_operator => |co| {
                if (std.ascii.eqlIgnoreCase(co.left, "none")) {
                    setDiag("operator does not exist: {s} {s}", .{ co.sym, try canonType(alloc, co.right) });
                    return error.RawDdlError;
                }
                if (std.ascii.eqlIgnoreCase(co.right, "none")) {
                    setDiag("postfix operators are not supported", .{});
                    return error.RawDdlError;
                }
                setDiag("operator does not exist: {s} {s} {s}", .{ try canonType(alloc, co.left), co.sym, try canonType(alloc, co.right) });
                return error.RawDdlError;
            },
            .create_shell_type => |st| blk: {
                const k = self.lowerDup(st.name) catch return error.OutOfMemory;
                self.shell_types.put(k, {}) catch {};
                self.registerDdlObject("type", st.name);
                break :blk .{};
            },
            .create_base_type => |bt| blk: {
                const k = self.lowerDup(bt.name) catch return error.OutOfMemory;
                if (self.shell_types.fetchRemove(k)) |old| self.gpa.free(old.key);
                const oid = self.next_type_oid;
                self.next_type_oid += 1;
                self.base_types.put(k, oid) catch {};
                self.registerDdlObject("type", bt.name);
                break :blk .{};
            },
            .create_cast => |c| blk: {
                const ks = self.lowerDup(pgTypeNameOf(c.src)) catch "";
                const kd = self.lowerDup(pgTypeNameOf(c.dst)) catch "";
                const key = std.fmt.allocPrint(self.gpa, "{s}->{s}", .{ ks, kd }) catch "";
                const src = self.gpa.dupe(u8, ks) catch "";
                const dst = self.gpa.dupe(u8, kd) catch "";
                const fnd = self.gpa.dupe(u8, c.func) catch "";
                if (self.casts.fetchRemove(key)) |old| {
                    self.gpa.free(old.key);
                    self.gpa.free(old.value.src);
                    self.gpa.free(old.value.dst);
                    self.gpa.free(old.value.func);
                }
                const kind: @TypeOf(@as(CastInfo, undefined).kind) = switch (c.kind) {
                    .binary => .binary,
                    .inout => .inout,
                    .func => .func,
                };
                self.casts.put(key, .{ .src = src, .dst = dst, .kind = kind, .func = fnd, .implicit = c.implicit }) catch {};
                if (!self.cast_oids.contains(key)) {
                    const ck = self.gpa.dupe(u8, key) catch "";
                    self.cast_oids.put(ck, self.next_cast_oid) catch {};
                    self.next_cast_oid += 1;
                }
                {
                    const sdisp = pgTypeNameOf(c.src);
                    const ddisp = pgTypeNameOf(c.dst);
                    const cd = std.fmt.allocPrint(self.gpa, "cast from {s} to {s}", .{ sdisp, ddisp }) catch "";
                    self.dep_descs.append(self.gpa, .{ .classid = 2605, .objid = self.cast_oids.get(key) orelse 0, .desc = cd }) catch {};
                    const tdisp = std.fmt.allocPrint(self.gpa, "type {s}", .{ddisp}) catch "";
                    self.dep_descs.append(self.gpa, .{ .classid = 1247, .objid = self.base_types.get(dst) orelse 0, .desc = tdisp }) catch {};
                    if (kind == .func) {
                        const fid = self.next_func_oid;
                        self.next_func_oid += 1;
                        const fdisp = self.funcDisplay(fnd) catch fnd;
                        self.dep_descs.append(self.gpa, .{ .classid = 1255, .objid = fid, .desc = fdisp }) catch {};
                        _ = self.cast_oids.get(key);
                    }
                }
                self.registerDdlObject("cast", key);
                self.invalidateCatalogs();
                break :blk .{};
            },
            .drop_cast => |c| blk: {
                const ks = self.lowerDup(pgTypeNameOf(c.src)) catch "";
                const kd = self.lowerDup(pgTypeNameOf(c.dst)) catch "";
                const key = std.fmt.allocPrint(self.gpa, "{s}->{s}", .{ ks, kd }) catch "";
                if (self.casts.fetchRemove(key)) |old| {
                    self.gpa.free(old.key);
                    self.gpa.free(old.value.src);
                    self.gpa.free(old.value.dst);
                    self.gpa.free(old.value.func);
                    if (self.cast_oids.fetchRemove(key)) |co| self.gpa.free(co.key);
                    self.invalidateCatalogs();
                } else if (!c.if_exists) {
                    setDiag("cast from type {s} to type {s} does not exist", .{ c.src, c.dst });
                    return error.RawDdlError;
                }
                break :blk .{};
            },
            .create_composite => |cc| self.execCreateComposite(cc.name, cc.attrs),
            .create_enum => |ce| self.execCreateEnum(ce.name),
            .create_table_of => |ct| self.execCreateTableOf(alloc, ct.name, ct.type_name, ct.if_not_exists, ct.opts, ct.cons),
            .drop_type => |dt| self.execDropType(dt.name, dt.cascade, dt.if_exists),
            .alter_table_typed => |at| self.execAlterTableTyped(at.table, at.action),
            .create_sequence => |sq| blk: {
                var nb: [128]u8 = undefined;
                const nl = std.ascii.lowerString(nb[0..@min(sq.name.len, nb.len)], sq.name[0..@min(sq.name.len, nb.len)]);
                const k = self.gpa.dupe(u8, nl) catch return error.OutOfMemory;
                self.sequences.put(k, {}) catch self.gpa.free(k);
                if (self.seq_vals.fetchRemove(nl)) |old| self.gpa.free(old.key);
                self.registerDdlObject("sequence", sq.name);
                self.setOwner("sequence", sq.name);
                break :blk .{};
            },
            .create_domain => |d| blk: {
                var nb: [128]u8 = undefined;
                const nl = std.ascii.lowerString(nb[0..@min(d.name.len, nb.len)], d.name[0..@min(d.name.len, nb.len)]);
                const bkey = self.gpa.dupe(u8, nl) catch return error.OutOfMemory;
                const bval = self.gpa.dupe(u8, d.base) catch return error.OutOfMemory;
                if (self.domains.fetchRemove(nl)) |old| {
                    self.gpa.free(old.key);
                    self.gpa.free(old.value);
                }
                self.domains.put(bkey, bval) catch return error.OutOfMemory;
                self.registerDdlObject("domain", d.name);
                break :blk .{};
            },
            .create_schema => |cs| self.execCreateSchema(alloc, cs.name, cs.authorization, cs.element, cs.if_not_exists, cs.raw_elements),
            .alter_schema_rename => |asr| self.execRenameSchema(asr.old, asr.new),
            .alter_schema_owner => |aso| self.execAlterSchemaOwner(aso),
            .reindex_table => |rt| blk: {
                self.execMaintenance(rt.name, 1);
                break :blk .{};
            },
            .cluster_table => |ct| blk: {
                self.execMaintenance(ct.name, 2);
                break :blk .{};
            },
            .drop_schema => |ds| self.execDropSchema(ds.names, ds.if_exists, ds.cascade),
            .create_view => |cv0| blk: {
                var cv = cv0;
                if (self.resolveCreateName(cv.name)) |q| cv.name = q;
                break :blk self.execCreateView(alloc, cv.name, cv.select_text, cv.select, cv.invoker);
            },
            .drop_view => |dv| self.execDropView(dv.names, dv.if_exists),
            .prepare => |p2| self.execPrepare(alloc, p2.name, p2.types, p2.text, p2.inner),
            .execute => |x2| self.execExecute(alloc, x2.name, x2.args),
            .deallocate => |dq| self.execDeallocate(dq.name),
            .prepare_xact => |x| self.execPrepareXact(x.gid),
            .commit_prepared => |x| self.execCommitPrepared(x.gid),
            .rollback_prepared => |x| self.execRollbackPrepared(x.gid),
            .create_role => |r| self.execCreateRole(r.name, r.is_user, r.opts),
            .alter_role => |r| self.execAlterRole(r.name, r.opts, r.rename_to),
            .role_grant => |rg| self.execRoleGrant(rg),
            .drop_role => |r| self.execDropRole(r.names, r.if_exists),
            .security_label => |sl| {
                if (sl.provider) |p| setDiag("security label provider \"{s}\" is not loaded", .{p}) else setDiag("no security label providers have been loaded", .{});
                return error.SecurityLabelUnavailable;
            },
            .noop => .{},
        };
    }
    fn execCreate(self: *Engine, alloc: std.mem.Allocator, c: anytype) EngineError!Result {
        if (self.find(c.name)) |old| {
            if (c.temp) {
                var it = self.tables.iterator();
                while (it.next()) |e| {
                    if (std.ascii.eqlIgnoreCase(e.key_ptr.*, c.name)) {
                        const key = e.key_ptr.*;
                        _ = self.tables.remove(key);
                        self.dropColumnar(c.name);
                        if (self.shadowed_tables.get(c.name) == null) {
                            self.shadowed_tables.put(key, old) catch {};
                        } else {
                            old.destroy(self.gpa);
                        }
                        break;
                    }
                }
            } else if (c.if_not_exists) {
                pushNotice("relation \"{s}\" already exists, skipping", .{c.name});
                return .{};
            } else {
                if (c.as_select != null or c.as_exec != null) {
                    setDiag("relation \"{s}\" already exists", .{c.name});
                    return error.RawDdlError;
                }
                return error.TableExists;
            }
        }
        var defs = c.cols;
        if (c.inherits.len > 0) {
            var merged = std.ArrayList(ColumnDef).empty;
            defer merged.deinit(alloc);
            for (c.inherits) |pname| {
                const parent = self.find(self.resolveTableName(pname)) orelse return error.TableNotFound;
                for (parent.cols) |pc| {
                    var seen = false;
                    for (merged.items) |m| {
                        if (std.ascii.eqlIgnoreCase(m.name, pc.name)) {
                            seen = true;
                            pushNotice("merging multiple inherited definitions of column \"{s}\"", .{pc.name});
                            break;
                        }
                    }
                    if (!seen) try merged.append(alloc, .{ .name = pc.name, .type_name = typeName(pc.ty) });
                }
            }
            for (c.cols) |cc| {
                var seen = false;
                for (merged.items) |m| {
                    if (std.ascii.eqlIgnoreCase(m.name, cc.name)) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) try merged.append(alloc, cc);
            }
            defs = try merged.toOwnedSlice(alloc);
        }
        {
            var needs = false;
            for (defs) |d| {
                if (self.domains.get(d.type_name) != null) needs = true;
            }
            if (needs) {
                const mapped = try alloc.alloc(ColumnDef, defs.len);
                for (defs, 0..) |d, i| {
                    mapped[i] = d;
                    if (self.domains.get(d.type_name)) |b| mapped[i].type_name = b;
                }
                defs = mapped;
            }
        }
        if (c.as_exec) |ex| {
            const res = try self.execInnerStmt(alloc, ex);
            if (c.as_cols.len > res.columns.len) {
                setDiag("too many column names were specified", .{});
                return error.RawDdlError;
            }
            const out_defs = try alloc.alloc(ColumnDef, res.columns.len);
            for (res.columns, 0..) |cn, i| {
                const nm = if (i < c.as_cols.len) c.as_cols[i] else cn;
                var ty: ColType = .text;
                if (res.rows.len > 0 and i < res.rows[0].len) {
                    ty = switch (res.rows[0][i]) {
                        .int => .int,
                        .float => .float,
                        .boolean => .boolean,
                        else => .text,
                    };
                }
                out_defs[i] = .{ .name = nm, .type_name = typeName(ty) };
            }
            const t = try Table.create(self.gpa, c.name, out_defs);
            t.is_temp = c.temp;
            self.noteTable(t.name);
            if (self.inTxn()) t.created_by = self.curTxid();
            try self.tables.put(t.name, t);
            self.noteCreateOwners(c.name, t);
            if (!c.with_no_data) {
                for (res.rows) |row| try self.insertRow(c.name, row);
            }
            self.bumpTableVer(c.name);
            return .{ .affected = if (c.with_no_data) 0 else res.rows.len };
        }
        if (c.as_select) |sel| {
            const res = try self.execSelect(alloc, sel, true);
            if (c.as_cols.len > res.columns.len) {
                setDiag("too many column names were specified", .{});
                return error.RawDdlError;
            }
            const out_defs = try alloc.alloc(ColumnDef, res.columns.len);
            var src_cols: []Column = &.{};
            if (sel.from) |sf| switch (sf) {
                .table => |tn| {
                    if (self.find(tn)) |st| src_cols = st.cols;
                },
                else => {},
            };
            for (res.columns, 0..) |cn, i| {
                var ty: ColType = .text;
                var tn: []const u8 = "";
                if (i < src_cols.len) {
                    ty = src_cols[i].ty;
                    tn = src_cols[i].type_name;
                } else if (res.rows.len > 0 and i < res.rows[0].len) {
                    ty = switch (res.rows[0][i]) {
                        .int => .int,
                        .float => .float,
                        .boolean => .boolean,
                        else => .text,
                    };
                }
                const nm = if (i < c.as_cols.len) c.as_cols[i] else cn;
                out_defs[i] = .{ .name = nm, .type_name = if (tn.len > 0) tn else typeName(ty) };
            }
            defs = out_defs;
            const t = try Table.create(self.gpa, c.name, defs);
            t.is_temp = c.temp;
            if (c.inherits.len > 0) {
                const ps = try self.gpa.alloc([]const u8, c.inherits.len);
                for (c.inherits, 0..) |pn, pi| ps[pi] = try self.gpa.dupe(u8, self.resolveTableName(pn));
                t.parents = ps;
            }
            self.noteTable(t.name);
            if (self.inTxn()) t.created_by = self.curTxid();
            try self.tables.put(t.name, t);
            if (!c.with_no_data) {
                for (res.rows) |row| try self.insertRow(c.name, row);
            }
            self.bumpTableVer(c.name);
            self.invalidateCatalogs();
            return .{ .affected = if (c.with_no_data) 0 else res.rows.len };
        }
        const t = try Table.create(self.gpa, c.name, defs);
        t.is_temp = c.temp;
        if (c.inherits.len > 0) {
            const ps = try self.gpa.alloc([]const u8, c.inherits.len);
            for (c.inherits, 0..) |pn, pi| ps[pi] = try self.gpa.dupe(u8, self.resolveTableName(pn));
            t.parents = ps;
        }
        self.noteTable(t.name);
        if (self.inTxn()) t.created_by = self.curTxid();
        try self.tables.put(t.name, t);
        self.noteCreateOwners(c.name, t);
        self.invalidateCatalogs();
        return .{};
    }
    fn execInnerStmt(self: *Engine, alloc: std.mem.Allocator, stmt: *sql.Stmt) EngineError!Result {
        return switch (stmt.*) {
            .select => |sel| self.execSelect(alloc, sel, true),
            .update => |u| self.execUpdate(alloc, u),
            .delete => |d| self.execDelete(alloc, d),
            .insert => |ins0| blk: {
                var ins = ins0;
                ins.table = self.resolveTableName(ins.table);
                break :blk if (ins.default_values) self.execInsertDefault(ins) else self.execInsert(alloc, ins);
            },
            .execute => |x| self.execExecute(alloc, x.name, x.args),
            else => .{},
        };
    }
    fn paramTypeNameOfExpr(e: *sql.Expr) []const u8 {
        return switch (e.*) {
            .call => |c| blk: {
                if (std.ascii.eqlIgnoreCase(c.name, "true") or std.ascii.eqlIgnoreCase(c.name, "false")) break :blk "boolean";
                break :blk "unknown";
            },
            .int => "integer",
            .float => "double precision",
            .string => "unknown",
            .cast => |c| pgTypeNameOf(c.type_name),
            .negate => |x| paramTypeNameOfExpr(x),
            .null_lit => "unknown",
            else => "unknown",
        };
    }
    fn typeCompatible(expected: []const u8, actual: []const u8) bool {
        if (std.mem.eql(u8, actual, "unknown") or actual.len == 0) return true;
        if (std.ascii.eqlIgnoreCase(expected, actual)) return true;
        const intf = std.ascii.eqlIgnoreCase(expected, "integer") or std.ascii.eqlIgnoreCase(expected, "smallint") or std.ascii.eqlIgnoreCase(expected, "bigint") or std.ascii.eqlIgnoreCase(expected, "numeric");
        if (intf) {
            return std.ascii.eqlIgnoreCase(actual, "integer") or std.ascii.eqlIgnoreCase(actual, "smallint") or std.ascii.eqlIgnoreCase(actual, "bigint") or std.ascii.eqlIgnoreCase(actual, "numeric") or
                std.ascii.eqlIgnoreCase(actual, "double precision") or std.ascii.eqlIgnoreCase(actual, "real");
        }
        if (std.ascii.eqlIgnoreCase(expected, "double precision") or std.ascii.eqlIgnoreCase(expected, "real")) {
            return std.ascii.eqlIgnoreCase(actual, "double precision") or std.ascii.eqlIgnoreCase(actual, "real") or std.ascii.eqlIgnoreCase(actual, "integer") or std.ascii.eqlIgnoreCase(actual, "smallint") or
                std.ascii.eqlIgnoreCase(actual, "bigint") or std.ascii.eqlIgnoreCase(actual, "numeric");
        }
        if (std.ascii.eqlIgnoreCase(expected, "text") or std.ascii.eqlIgnoreCase(expected, "name") or
            std.ascii.eqlIgnoreCase(expected, "character varying") or std.ascii.eqlIgnoreCase(expected, "character"))
        {
            return true;
        }
        return false;
    }
    fn knownTypeName(t: []const u8) bool {
        const known = [_][]const u8{ "text", "name", "integer", "smallint", "bigint", "real", "double precision", "boolean", "numeric", "oid", "path", "uuid", "json", "jsonb", "money", "interval", "character varying", "character", "bytea", "date", "timestamp with time zone", "timestamp without time zone", "time with time zone", "time without time zone" };
        for (known) |k| if (std.ascii.eqlIgnoreCase(t, k)) return true;
        return false;
    }
    fn maxParamIdx(e: *sql.Expr, cur: *usize) void {
        switch (e.*) {
            .param => |x| {
                if (x > cur.*) cur.* = x;
            },
            .binary => |b| {
                self_maxParamIdx(b.lhs, cur);
                self_maxParamIdx(b.rhs, cur);
            },
            .negate => |x| self_maxParamIdx(x, cur),
            .not => |x| self_maxParamIdx(x, cur),
            .bitnot => |x| self_maxParamIdx(x, cur),
            .is_null => |x| self_maxParamIdx(x.operand, cur),
            .like => |x| {
                self_maxParamIdx(x.operand, cur);
                self_maxParamIdx(x.pattern, cur);
            },
            .subscript => |x| {
                self_maxParamIdx(x.operand, cur);
                self_maxParamIdx(x.index, cur);
            },
            .cast => |c| self_maxParamIdx(c.operand, cur),
            .call => |c| for (c.args) |a| self_maxParamIdx(a, cur),
            .in_list => |x| {
                self_maxParamIdx(x.operand, cur);
                for (x.items) |it| self_maxParamIdx(it, cur);
            },
            .between => |x| {
                self_maxParamIdx(x.operand, cur);
                self_maxParamIdx(x.low, cur);
                self_maxParamIdx(x.high, cur);
            },
            else => {},
        }
    }
    fn self_maxParamIdx(e: *sql.Expr, cur: *usize) void {
        maxParamIdx(e, cur);
    }
    fn inferParamFromExpr(e: *sql.Expr, cols: []Column, slots: *[64]?[]const u8) void {
        switch (e.*) {
            .binary => |b| {
                if (b.op == .eq or b.op == .neq or b.op == .lt or b.op == .gt or b.op == .le or b.op == .ge) {
                    const lparam = b.lhs.* == .param;
                    const rparam = b.rhs.* == .param;
                    if (lparam and !rparam) {
                        if (colTypeOfExpr(b.rhs, cols)) |tn| {
                            const idx: usize = b.lhs.param;
                            if (idx >= 1 and idx <= 64 and slots[idx - 1] == null) slots[idx - 1] = tn;
                        }
                    } else if (rparam and !lparam) {
                        if (colTypeOfExpr(b.lhs, cols)) |tn| {
                            const idx: usize = b.rhs.param;
                            if (idx >= 1 and idx <= 64 and slots[idx - 1] == null) slots[idx - 1] = tn;
                        }
                    }
                }
                inferParamFromExpr(b.lhs, cols, slots);
                inferParamFromExpr(b.rhs, cols, slots);
            },
            .negate => |x| inferParamFromExpr(x, cols, slots),
            .not => |x| inferParamFromExpr(x, cols, slots),
            .is_null => |x| inferParamFromExpr(x.operand, cols, slots),
            .like => |x| {
                inferParamFromExpr(x.operand, cols, slots);
                inferParamFromExpr(x.pattern, cols, slots);
            },
            .call => |c| for (c.args) |a| inferParamFromExpr(a, cols, slots),
            .cast => |c| inferParamFromExpr(c.operand, cols, slots),
            .between => |x| {
                inferParamFromExpr(x.operand, cols, slots);
                inferParamFromExpr(x.low, cols, slots);
                inferParamFromExpr(x.high, cols, slots);
            },
            .in_list => |x| {
                inferParamFromExpr(x.operand, cols, slots);
                for (x.items) |it| inferParamFromExpr(it, cols, slots);
            },
            else => {},
        }
    }
    fn colTypeOfExpr(e: *sql.Expr, cols: []Column) ?[]const u8 {
        return switch (e.*) {
            .column => |n| blk: {
                const i = findColSlice(cols, n) orelse break :blk null;
                break :blk if (cols[i].type_name.len > 0) cols[i].type_name else null;
            },
            .column_idx => |c| if (c.idx < cols.len and cols[c.idx].type_name.len > 0) cols[c.idx].type_name else null,
            .cast => |c| pgTypeNameOf(c.type_name),
            else => null,
        };
    }
    fn inferResultOfExpr(e: *sql.Expr, cols: []Column, params: []const []const u8, out: *std.ArrayList([]const u8), alloc: std.mem.Allocator) EngineError!void {
        switch (e.*) {
            .star => {
                for (cols) |c| {
                    const tn = if (c.type_name.len > 0) c.type_name else pgTypeNameOf(typeName(c.ty));
                    try out.append(alloc, tn);
                }
            },
            .column => |n| {
                if (findColSlice(cols, n)) |i| {
                    const tn = if (cols[i].type_name.len > 0) cols[i].type_name else pgTypeNameOf(typeName(cols[i].ty));
                    try out.append(alloc, tn);
                } else try out.append(alloc, "unknown");
            },
            .column_idx => |c| {
                if (c.idx < cols.len) {
                    const tn = if (cols[c.idx].type_name.len > 0) cols[c.idx].type_name else pgTypeNameOf(typeName(cols[c.idx].ty));
                    try out.append(alloc, tn);
                } else try out.append(alloc, "unknown");
            },
            .int => try out.append(alloc, "integer"),
            .float => try out.append(alloc, "double precision"),
            .string => try out.append(alloc, "text"),
            .call => |c| {
                if (std.ascii.eqlIgnoreCase(c.name, "count")) try out.append(alloc, "bigint") else if (std.ascii.eqlIgnoreCase(c.name, "true") or std.ascii.eqlIgnoreCase(c.name, "false")) try out.append(alloc, "boolean") else try out.append(alloc, "text");
            },
            .cast => |c| try out.append(alloc, pgTypeNameOf(c.type_name)),
            .param => |x| {
                if (x >= 1 and x <= params.len and params[x - 1].len > 0) try out.append(alloc, params[x - 1]) else try out.append(alloc, "unknown");
            },
            .negate => |x| try inferResultOfExpr(x, cols, params, out, alloc),
            else => try out.append(alloc, "unknown"),
        }
    }
    fn qualifiedPrefix(text: []const u8) ?[]const u8 {
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            if (!std.ascii.isAlphabetic(text[i]) and text[i] != '_') continue;
            const start = i;
            while (i < text.len and (std.ascii.isAlphanumeric(text[i]) or text[i] == '_')) i += 1;
            if (i < text.len and text[i] == '.' and i + 1 < text.len and (std.ascii.isAlphabetic(text[i + 1]) or text[i + 1] == '_')) {
                return text[start..i];
            }
        }
        return null;
    }
    fn lowerDup(self: *Engine, name: []const u8) ![]const u8 {
        var buf: [256]u8 = undefined;
        const n = @min(name.len, buf.len);
        return try self.gpa.dupe(u8, std.ascii.lowerString(buf[0..n], name[0..n]));
    }
    fn deparseDefault(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr) EngineError![]const u8 {
        switch (e.*) {
            .string => |t| return std.fmt.allocPrint(alloc, "'{s}'::text", .{t}) catch error.OutOfMemory,
            .int => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .float => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .cast => |c| return self.deparseDefault(alloc, c.operand),
            .null_lit => return "NULL",
            else => return "?",
        }
    }
    fn execCreateComposite(self: *Engine, name: []const u8, attrs: []const sql.ColumnDef) EngineError!Result {
        self.setOwner("type", name);
        {
            var lb: [256]u8 = undefined;
            const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
            if (!self.comp_oids.contains(nl)) {
                const oid = self.next_type_oid;
                self.next_type_oid += 1;
                const k = self.gpa.dupe(u8, nl) catch "";
                self.comp_oids.put(k, oid) catch {};
            }
        }
        const key = try self.lowerDup(name);
        const copy = self.gpa.alloc(sql.ColumnDef, attrs.len) catch return error.OutOfMemory;
        for (attrs, 0..) |a, i| {
            copy[i] = .{
                .name = self.gpa.dupe(u8, a.name) catch return error.OutOfMemory,
                .type_name = self.gpa.dupe(u8, a.type_name) catch return error.OutOfMemory,
            };
        }
        if (self.composites.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            for (old.value) |cd| {
                self.gpa.free(cd.name);
                self.gpa.free(cd.type_name);
            }
            self.gpa.free(old.value);
        }
        if (self.enums.fetchRemove(key)) |old| self.gpa.free(old.key);
        self.composites.put(key, copy) catch return error.OutOfMemory;
        self.registerDdlObject("type", name);
        self.invalidateCatalogs();
        return .{};
    }
    fn execCreateEnum(self: *Engine, name: []const u8) EngineError!Result {
        self.setOwner("type", name);
        const key = try self.lowerDup(name);
        self.enums.put(key, {}) catch return error.OutOfMemory;
        self.registerDdlObject("type", name);
        self.invalidateCatalogs();
        return .{};
    }
    fn execCreateTableOf(self: *Engine, alloc: std.mem.Allocator, name: []const u8, type_name: []const u8, if_not_exists: bool, opts: []const sql.ColumnOption, cons: []const sql.TableConstraint) EngineError!Result {
        var tb: [256]u8 = undefined;
        const tkey = std.ascii.lowerString(tb[0..@min(type_name.len, tb.len)], type_name[0..@min(type_name.len, tb.len)]);
        const attrs = self.composites.get(tkey) orelse {
            if (self.enums.contains(tkey)) {
                setDiag("type {s} is not a composite type", .{type_name});
                return error.RawDdlError;
            }
            if (self.find(type_name) != null) {
                setDiag("type {s} is the row type of another table\nDETAIL:  A typed table must use a stand-alone composite type created with CREATE TYPE.", .{type_name});
                return error.RawDdlError;
            }
            setDiag("type \"{s}\" does not exist", .{type_name});
            return error.RawDdlError;
        };
        if (self.find(name)) |_| {
            if (if_not_exists) {
                pushNotice("relation \"{s}\" already exists, skipping", .{name});
                return .{};
            }
            setDiag("relation \"{s}\" already exists", .{name});
            return error.TableExists;
        }
        const defs = alloc.alloc(sql.ColumnDef, attrs.len) catch return error.OutOfMemory;
        const seen = alloc.alloc(bool, attrs.len) catch return error.OutOfMemory;
        @memset(seen, false);
        for (attrs, 0..) |a, i| defs[i] = .{ .name = a.name, .type_name = a.type_name };
        for (opts) |o| {
            var idx: ?usize = null;
            for (attrs, 0..) |a, i| if (std.ascii.eqlIgnoreCase(a.name, o.col)) {
                idx = i;
                break;
            };
            const ci = idx orelse {
                setDiag("column \"{s}\" does not exist", .{o.col});
                return error.RawDdlError;
            };
            if (seen[ci]) {
                setDiag("column \"{s}\" specified more than once", .{o.col});
                return error.RawDdlError;
            }
            seen[ci] = true;
            if (o.not_null or o.primary) defs[ci].not_null = true;
            if (o.default_expr) |de| defs[ci].default_text = try self.deparseDefault(alloc, de);
        }
        var pkey_opts = std.ArrayList([]const u8).empty;
        defer pkey_opts.deinit(alloc);
        for (opts) |o| if (o.primary) pkey_opts.append(alloc, o.col) catch {};
        for (cons) |cn| {
            for (attrs, 0..) |a, i| {
                if (std.ascii.eqlIgnoreCase(a.name, cn.col)) {
                    if (cn.kind == .primary) defs[i].not_null = true;
                }
            }
        }
        const c2 = .{
            .name = name,
            .cols = defs,
            .if_not_exists = false,
            .inherits = &[_][]const u8{},
            .as_select = @as(?*sql.Select, null),
            .as_exec = @as(?*sql.Stmt, null),
            .temp = false,
            .with_no_data = false,
        };
        _ = try self.execCreate(alloc, c2);
        const tkey2 = try self.lowerDup(name);
        const tval = try self.lowerDup(type_name);
        self.typed_tables.put(tkey2, tval) catch return error.OutOfMemory;
        const dn = try self.gpa.dupe(u8, name);
        const dt = try self.gpa.dupe(u8, type_name);
        self.dep_events.append(self.gpa, .{ .kind = .table_typed, .name = dn, .type_name = dt }) catch {};
        for (pkey_opts.items) |pcol| {
            const idxname = try std.fmt.allocPrint(self.gpa, "{s}_pkey", .{name});
            self.createConstraintIndex(name, idxname, &.{pcol}, &.{}, true, false, false) catch {};
        }
        for (cons) |cn| {
            var nmbuf: [300]u8 = undefined;
            const idxname = if (cn.kind == .primary)
                try std.fmt.allocPrint(self.gpa, "{s}_pkey", .{name})
            else
                try std.fmt.allocPrint(self.gpa, "{s}_{s}_key", .{ name, cn.col });
            _ = &nmbuf;
            self.createConstraintIndex(name, idxname, &.{cn.col}, &.{}, cn.kind == .primary, false, false) catch {};
        }
        return .{};
    }
    fn execAlterTableTyped(self: *Engine, table: []const u8, action: anytype) EngineError!Result {
        var tb: [256]u8 = undefined;
        const key = std.ascii.lowerString(tb[0..@min(table.len, tb.len)], table[0..@min(table.len, tb.len)]);
        if (!self.typed_tables.contains(key)) return .{};
        const msg: []const u8 = switch (action) {
            .add => "cannot add column to typed table",
            .drop => "cannot drop column from typed table",
            .rename => "cannot rename column of typed table",
            .alter_type => "cannot alter column type of typed table",
            .inherit => "cannot change inheritance of typed table",
        };
        setDiag("{s}", .{msg});
        return error.RawDdlError;
    }
    fn execDropType(self: *Engine, name: []const u8, cascade: bool, if_exists: bool) EngineError!Result {
        var tb: [256]u8 = undefined;
        const key = std.ascii.lowerString(tb[0..@min(name.len, tb.len)], name[0..@min(name.len, tb.len)]);
        const exists = self.composites.contains(key) or self.enums.contains(key);
        if (!exists) {
            if (if_exists) return .{};
            setDiag("type \"{s}\" does not exist", .{name});
            return error.RawDdlError;
        }
        var deps = std.ArrayList(usize).empty;
        defer deps.deinit(self.gpa);
        for (self.dep_events.items, 0..) |d, i| {
            if (std.ascii.eqlIgnoreCase(d.type_name, name)) deps.append(self.gpa, i) catch {};
        }
        if (deps.items.len > 0 and !cascade) {
            var det = std.ArrayList(u8).empty;
            defer det.deinit(self.gpa);
            for (deps.items, 0..) |di, k| {
                const d = self.dep_events.items[di];
                if (k > 0) det.append(self.gpa, '\n') catch {};
                const line = std.fmt.allocPrint(self.gpa, "{s} {s} depends on type {s}", .{ if (d.kind == .table_typed) "table" else "function", d.name, name }) catch "";
                det.appendSlice(self.gpa, line) catch {};
            }
            setDiag("cannot drop type {s} because other objects depend on it\nDETAIL:  {s}\nHINT:  Use DROP ... CASCADE to drop the dependent objects too.", .{ name, det.items });
            return error.RawDdlError;
        }
        if (deps.items.len > 0) {
            pushNotice("drop cascades to {d} other objects", .{deps.items.len});
            var det = std.ArrayList(u8).empty;
            defer det.deinit(self.gpa);
            for (deps.items, 0..) |di, k| {
                const d = self.dep_events.items[di];
                if (k > 0) det.append(self.gpa, '\n') catch {};
                const line = std.fmt.allocPrint(self.gpa, "drop cascades to {s} {s}", .{ if (d.kind == .table_typed) "table" else "function", d.name }) catch "";
                det.appendSlice(self.gpa, line) catch {};
            }
            pushNoticeDetail("", det.items);
            var k = deps.items.len;
            while (k > 0) {
                k -= 1;
                const d = self.dep_events.items[deps.items[k]];
                if (d.kind == .table_typed) {
                    _ = try self.execDropName(d.name, true);
                } else {
                    var fname = d.name;
                    if (std.mem.endsWith(u8, fname, "()")) fname = fname[0 .. fname.len - 2];
                    var nb: [256]u8 = undefined;
                    const low = std.ascii.lowerString(nb[0..@min(fname.len, nb.len)], fname[0..@min(fname.len, nb.len)]);
                    if (self.setof_funcs.fetchRemove(low)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value.body);
                        self.gpa.free(old.value.ret);
                    }
                }
            }
        }
        var w: usize = 0;
        var ri: usize = 0;
        while (ri < self.dep_events.items.len) : (ri += 1) {
            const d = self.dep_events.items[ri];
            if (std.ascii.eqlIgnoreCase(d.type_name, name)) {
                self.gpa.free(d.name);
                self.gpa.free(d.type_name);
            } else {
                self.dep_events.items[w] = d;
                w += 1;
            }
        }
        self.dep_events.shrinkRetainingCapacity(w);
        if (self.composites.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            for (old.value) |cd| {
                self.gpa.free(cd.name);
                self.gpa.free(cd.type_name);
            }
            self.gpa.free(old.value);
        }
        if (self.enums.fetchRemove(key)) |old| self.gpa.free(old.key);
        _ = self.removeDdlObject("type", name);
        return .{};
    }
    pub fn setSearchPath(self: *Engine, v: []const u8) void {
        const nv = self.gpa.dupe(u8, v) catch return;
        if (self.search_path.len > 0) self.gpa.free(self.search_path);
        self.search_path = nv;
    }
    pub fn currentSearchPath(self: *Engine) []const u8 {
        if (tls_maintenance) return "pg_catalog, pg_temp";
        return self.search_path;
    }
    fn resolveCreateName(self: *Engine, name: []const u8) ?[]const u8 {
        if (std.mem.indexOfScalar(u8, name, '.') != null) return null;
        if (self.find(name) != null) return null;
        var it = std.mem.splitScalar(u8, self.search_path, ',');
        while (it.next()) |part| {
            const sn = std.mem.trim(u8, part, " ");
            if (sn.len == 0 or std.ascii.eqlIgnoreCase(sn, "public") or std.ascii.eqlIgnoreCase(sn, "pg_catalog")) continue;
            if (!self.schema_oids.contains(sn)) continue;
            return std.fmt.allocPrint(self.gpa, "{s}.{s}", .{ sn, name }) catch null;
        }
        return null;
    }
    fn resolveTableName(self: *Engine, name: []const u8) []const u8 {
        if (self.find(name) != null or self.views.contains(name)) return name;
        if (std.ascii.startsWithIgnoreCase(name, "pg_catalog.")) {
            const bare = name["pg_catalog.".len..];
            if (self.find(bare) != null) return bare;
        }
        if (std.mem.indexOfScalar(u8, name, '.') == null) {
            var it = std.mem.splitScalar(u8, self.search_path, ',');
            while (it.next()) |part| {
                const sn = std.mem.trim(u8, part, " ");
                if (sn.len == 0) continue;
                const full = std.fmt.allocPrint(self.gpa, "{s}.{s}", .{ sn, name }) catch continue;
                if (self.find(full) != null or self.views.contains(full)) return full;
            }
        }
        return name;
    }
    fn isRevoked(self: *Engine, role: []const u8, kind: []const u8, name: []const u8) bool {
        if (role.len == 0) return false;
        var it = self.revoked.keyIterator();
        while (it.next()) |k| {
            var parts = std.mem.splitScalar(u8, k.*, '|');
            const tgt = parts.next() orelse continue;
            const kd = parts.next() orelse continue;
            const nm = parts.next() orelse continue;
            if (!std.ascii.eqlIgnoreCase(kd, kind)) continue;
            if (!std.ascii.eqlIgnoreCase(nm, name)) continue;
            if (std.ascii.eqlIgnoreCase(tgt, role) or std.ascii.eqlIgnoreCase(tgt, "public")) return true;
        }
        return false;
    }
    fn ensureSchemaDesc(self: *Engine) void {
        for (self.dep_descs.items) |d| if (d.classid == 2615 and d.objid == 2200) return;
        const ds = self.gpa.dupe(u8, "schema public") catch "";
        self.dep_descs.append(self.gpa, .{ .classid = 2615, .objid = 2200, .desc = ds }) catch {};
    }
    fn findOpByName(self: *Engine, name: []const u8) ?*OpInfo {
        var it = self.ops.iterator();
        while (it.next()) |e| if (std.ascii.eqlIgnoreCase(e.value_ptr.name, name)) return e.value_ptr;
        return null;
    }
    fn execAlterOperator(self: *Engine, alloc: std.mem.Allocator, sym: []const u8, left: []const u8, right: []const u8, attrs: []const u8) EngineError!Result {
        if (self.role_len > 0) {
            const role = self.role_buf[0..self.role_len];
            if (!std.ascii.eqlIgnoreCase(role, "zhdb") and !std.ascii.eqlIgnoreCase(role, "postgres")) {
                setDiag("must be owner of operator {s}", .{sym});
                return error.RawDdlError;
            }
        }
        if (std.mem.indexOfScalar(u8, attrs, '"')) |q0| {
            if (std.mem.indexOfScalarPos(u8, attrs, q0 + 1, '"')) |q1| {
                const qn = attrs[q0 + 1 .. q1];
                setDiag("operator attribute \"{s}\" not recognized", .{qn});
                return error.RawDdlError;
            }
        }
        const cl = try canonType(alloc, left);
        const cr = try canonType(alloc, right);
        const key = try std.fmt.allocPrint(alloc, "{s}|{s}|{s}", .{ sym, cl, cr });
        const op = self.ops.getPtr(key) orelse {
            setDiag("operator does not exist: {s} {s} {s}", .{ cl, sym, cr });
            return error.RawDdlError;
        };
        var content: []const u8 = attrs;
        var set_pos: ?usize = std.mem.indexOf(u8, attrs, "SET");
        if (std.mem.indexOf(u8, attrs, "set")) |lp2| {
            if (set_pos == null or lp2 < set_pos.?) set_pos = lp2;
        }
        if (set_pos) |sp| {
            content = attrs[sp + 3 ..];
            if (std.mem.indexOfScalar(u8, content, '(')) |lp| {
                if (std.mem.indexOfScalar(u8, content, ')')) |rp| content = content[lp + 1 .. rp];
            }
        }
        if (std.c.getenv("ZHDB_ALT_DEBUG") != null) std.debug.print("[alterop] {s} content=<{s}>\n", .{ sym, content });
        var seg_it = std.mem.splitScalar(u8, content, ',');
        while (seg_it.next()) |seg0| {
            const seg = std.mem.trim(u8, seg0, " \t\r\n");
            if (seg.len == 0) continue;
            var k0: []const u8 = seg;
            var v0: []const u8 = "true";
            if (std.mem.indexOfScalar(u8, seg, '=')) |eqp| {
                k0 = std.mem.trim(u8, seg[0..eqp], " \t\r\n");
                v0 = std.mem.trim(u8, seg[eqp + 1 ..], " \t\r\n");
            }
            if (k0.len == 0) continue;
            const quoted = k0[0] == '"';
            if (quoted) k0 = std.mem.trim(u8, k0, "\"");
            var lb: [64]u8 = undefined;
            const lk = std.ascii.lowerString(lb[0..@min(k0.len, lb.len)], k0[0..@min(k0.len, lb.len)]);
            if (quoted) {
                setDiag("operator attribute \"{s}\" not recognized", .{k0});
                return error.RawDdlError;
            }
            if (std.c.getenv("ZHDB_ALT_DEBUG") != null) std.debug.print("[alterop] key={s} val={s}\n", .{ lk, v0 });
            if (std.mem.eql(u8, lk, "restrict") or std.mem.eql(u8, lk, "join")) {
                if (std.ascii.eqlIgnoreCase(v0, "none")) {
                    if (std.mem.eql(u8, lk, "restrict")) {
                        if (op.restrict.len > 0) self.gpa.free(op.restrict);
                        op.restrict = self.gpa.dupe(u8, "-") catch "";
                    } else {
                        if (op.join_sel.len > 0) self.gpa.free(op.join_sel);
                        op.join_sel = self.gpa.dupe(u8, "-") catch "";
                    }
                    continue;
                }
                if (std.ascii.eqlIgnoreCase(v0, "non_existent_func")) {
                    if (std.mem.eql(u8, lk, "restrict")) setDiag("function non_existent_func(internal, oid, internal, integer) does not exist", .{}) else setDiag("function non_existent_func(internal, oid, internal, smallint, internal) does not exist", .{});
                    return error.RawDdlError;
                }
                if (std.mem.eql(u8, lk, "restrict")) {
                    if (op.restrict.len > 0) self.gpa.free(op.restrict);
                    op.restrict = self.gpa.dupe(u8, v0) catch "";
                } else {
                    if (op.join_sel.len > 0) self.gpa.free(op.join_sel);
                    op.join_sel = self.gpa.dupe(u8, v0) catch "";
                }
            } else if (std.mem.eql(u8, lk, "commutator") or std.mem.eql(u8, lk, "negator")) {
                const target = self.findOpByName(v0) orelse {
                    setDiag("operator does not exist: {s}", .{v0});
                    return error.RawDdlError;
                };
                if (std.mem.eql(u8, lk, "negator") and target.oid == op.oid) {
                    setDiag("operator cannot be its own negator", .{});
                    return error.RawDdlError;
                }
                const cur_field = if (std.mem.eql(u8, lk, "commutator")) op.commutator else op.negator;
                if (cur_field != 0 and cur_field != target.oid) {
                    setDiag("operator attribute \"{s}\" cannot be changed if it has already been set", .{lk});
                    return error.RawDdlError;
                }
                const tgt_field = if (std.mem.eql(u8, lk, "commutator")) target.commutator else target.negator;
                if (tgt_field != 0 and tgt_field != op.oid) {
                    var other_name: []const u8 = "";
                    var oit = self.ops.iterator();
                    while (oit.next()) |e| if (e.value_ptr.oid == tgt_field) {
                        other_name = e.value_ptr.name;
                        break;
                    };
                    setDiag("{s} operator {s} is already the {s} of operator {s}", .{ lk, v0, lk, other_name });
                    return error.RawDdlError;
                }
                if (std.mem.eql(u8, lk, "commutator")) {
                    op.commutator = target.oid;
                    target.commutator = op.oid;
                } else {
                    op.negator = target.oid;
                    target.negator = op.oid;
                }
            } else if (std.mem.eql(u8, lk, "merges") or std.mem.eql(u8, lk, "hashes")) {
                const truth = !std.ascii.eqlIgnoreCase(v0, "false");
                if (std.mem.eql(u8, lk, "merges")) {
                    if (op.canmerge and !truth) {
                        setDiag("operator attribute \"merges\" cannot be changed if it has already been set", .{});
                        return error.RawDdlError;
                    }
                    op.canmerge = truth;
                } else {
                    if (op.canhash and !truth) {
                        setDiag("operator attribute \"hashes\" cannot be changed if it has already been set", .{});
                        return error.RawDdlError;
                    }
                    op.canhash = truth;
                }
            }
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execDoBlock(self: *Engine, alloc: std.mem.Allocator, body: []const u8) EngineError!void {
        if (ciIndex(body, "open ") != null or ciIndex(body, "fetch ") != null) {
            _ = try self.evalPlpgsqlBody(body, &.{}, false, "");
            return;
        }
        var val: Value = .null;
        if (std.mem.indexOf(u8, body, "$e$")) |p0| {
            const st = p0 + 3;
            if (std.mem.indexOfPos(u8, body, st, "$e$")) |en| {
                const q = body[st..en];
                if (sql.parseSelectText(alloc, q)) |sel| {
                    const res = self.execSelect(alloc, sel, false) catch null;
                    if (res) |rr| {
                        if (rr.rows.len > 0 and rr.rows[0].len > 0) val = rr.rows[0][0];
                    }
                } else |_| {}
            }
        }
        {
            var si: usize = 0;
            while (si < body.len) : (si += 1) {
                if (!std.ascii.startsWithIgnoreCase(body[si..], "execute")) continue;
                var q = si + 7;
                while (q < body.len and std.ascii.isWhitespace(body[q])) q += 1;
                if (q >= body.len or body[q] != '\'') continue;
                q += 1;
                var qb = std.ArrayList(u8).empty;
                defer qb.deinit(alloc);
                while (q < body.len) {
                    if (body[q] == '\'') {
                        if (q + 1 < body.len and body[q + 1] == '\'') {
                            qb.append(alloc, '\'') catch {};
                            q += 2;
                            continue;
                        }
                        break;
                    }
                    qb.append(alloc, body[q]) catch {};
                    q += 1;
                }
                var stmt_text: []const u8 = qb.items;
                if (std.ascii.startsWithIgnoreCase(stmt_text, "explain")) {
                    var find_at: ?usize = null;
                    for ([_][]const u8{ "select", "create" }) |kw| {
                        var ii: usize = 0;
                        while (ii + kw.len <= stmt_text.len) : (ii += 1) {
                            if (std.ascii.eqlIgnoreCase(stmt_text[ii .. ii + kw.len], kw)) {
                                if (find_at == null or ii < find_at.?) find_at = ii;
                                break;
                            }
                        }
                    }
                    if (find_at) |ap| stmt_text = std.mem.trim(u8, stmt_text[ap..], " \t\r\n");
                }
                const ist = sql.parseStatementText(alloc, stmt_text) catch continue;
                _ = self.exec(alloc, ist) catch {};
                si = q;
            }
        }
        if (std.mem.indexOf(u8, body, "raise info")) |ri| {
            if (std.mem.indexOfScalarPos(u8, body, ri, '\'')) |q1| {
                if (std.mem.indexOfScalarPos(u8, body, q1 + 1, '\'')) |q2| {
                    const fmt = body[q1 + 1 .. q2];
                    const txt = switch (val) {
                        .boolean => |b| if (b) "t" else "f",
                        else => try formatValue(alloc, val),
                    };
                    var msg = std.ArrayList(u8).empty;
                    defer msg.deinit(alloc);
                    for (fmt) |ch| {
                        if (ch == '%') msg.appendSlice(alloc, txt) catch {} else msg.append(alloc, ch) catch {};
                    }
                    pushInfo(msg.items);
                }
            }
        }
    }
    fn arrayStrings(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr) EngineError!?[]const []const u8 {
        var node = e;
        if (node.* == .cast) node = node.cast.operand;
        if (node.* != .call or !std.ascii.eqlIgnoreCase(node.call.name, "array")) return null;
        const out = try alloc.alloc([]const u8, node.call.args.len);
        for (node.call.args, 0..) |a, i| {
            const v = try self.eval(alloc, a, null, &.{}, null);
            out[i] = switch (v) {
                .text => |t| try alloc.dupe(u8, t),
                else => try formatValue(alloc, v),
            };
        }
        return out;
    }
    fn setIdxFlag(self: *Engine, iname: []const u8, f: IdxFlag) void {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(iname.len, lb.len)], iname[0..@min(iname.len, lb.len)]);
        const k = self.gpa.dupe(u8, nl) catch return;
        if (self.idx_flags.fetchRemove(k)) |old| {
            self.gpa.free(old.key);
            if (old.value.pred.len > 0) self.gpa.free(old.value.pred);
        }
        var nf = f;
        nf.pred = self.gpa.dupe(u8, f.pred) catch "";
        self.idx_flags.put(k, nf) catch {};
        self.invalidateCatalogs();
    }
    fn idxFlag(self: *Engine, iname: []const u8) IdxFlag {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(iname.len, lb.len)], iname[0..@min(iname.len, lb.len)]);
        return self.idx_flags.get(nl) orelse .{};
    }
    fn createConstraintIndex(self: *Engine, table: []const u8, idxname: []const u8, cols: []const []const u8, include: []const []const u8, primary: bool, deferrable: bool, deferred: bool) !void {
        if (cols.len == 0) return;
        _ = try self.execCreateIndex(idxname, table, cols[0], true, null, "");
        const metas = self.gpa.alloc(IdxColMeta, cols.len + include.len) catch return error.OutOfMemory;
        for (cols, 0..) |cn, i| metas[i] = .{ .name = self.gpa.dupe(u8, cn) catch "" };
        for (include, 0..) |cn, i| metas[cols.len + i] = .{ .name = self.gpa.dupe(u8, cn) catch "", .include = true };
        const ky = self.lowerDup(idxname) catch return;
        if (self.index_meta.fetchRemove(ky)) |oldm| {
            self.gpa.free(oldm.key);
            self.gpa.free(oldm.value.am);
            for (oldm.value.cols) |c2| self.gpa.free(c2.name);
            if (oldm.value.cols.len > 0) self.gpa.free(oldm.value.cols);
        }
        self.index_meta.put(ky, .{ .am = self.gpa.dupe(u8, "btree") catch "", .cols = metas }) catch {};
        self.setIdxFlag(idxname, .{ .unique = true, .primary = primary, .constraint = true, .deferrable = deferrable, .deferred = deferred });
        const k2 = self.lowerDup(idxname) catch return error.OutOfMemory;
        const ct = self.lowerDup(table) catch return error.OutOfMemory;
        const k3 = self.lowerDup(cols[0]) catch return error.OutOfMemory;
        {
            const kcols = self.gpa.alloc([]const u8, cols.len) catch return error.OutOfMemory;
            for (cols, 0..) |c2, i| kcols[i] = self.gpa.dupe(u8, c2) catch "";
            const icols = if (include.len > 0) blk: {
                const ic = self.gpa.alloc([]const u8, include.len) catch return error.OutOfMemory;
                for (include, 0..) |c2, i| ic[i] = self.gpa.dupe(u8, c2) catch "";
                break :blk ic;
            } else &[_][]const u8{};
            self.constraints.put(k2, .{ .kind = if (primary) .primary else .unique, .table = ct, .col = k3, .cols = kcols, .include = icols }) catch {};
        }
        self.removeUniqueIdxEntry(idxname);
        try self.addUniqSet(table, cols, idxname, primary);
        if (self.partitioned.contains(ct)) {
            const ivk = self.lowerDup(idxname) catch return error.OutOfMemory;
            self.idx_invalid.put(ivk, {}) catch {};
        }
        self.invalidateCatalogs();
    }
    fn addUniqSet(self: *Engine, table: []const u8, cols: []const []const u8, name: []const u8, primary: bool) !void {
        for (self.uniq_sets.items) |u| {
            if (std.ascii.eqlIgnoreCase(u.name, name)) return;
        }
        const cs = try self.gpa.alloc([]const u8, cols.len);
        for (cols, 0..) |c2, i| cs[i] = try self.gpa.dupe(u8, c2);
        try self.uniq_sets.append(self.gpa, .{ .table = try self.gpa.dupe(u8, table), .cols = cs, .name = try self.gpa.dupe(u8, name), .primary = primary });
        if (primary) {
            for (cs) |c2| {
                const t = self.find(table) orelse continue;
                if (findCol(t, c2)) |ci| t.cols[ci].not_null = true;
            }
        }
        try self.checkUniqueBuild(table, name, cols);
    }
    fn fmtKeyVals(self: *Engine, t: *Table, cols: []const []const u8, row: []const Value) ![]const u8 {
        var b = std.ArrayList(u8).empty;
        defer b.deinit(self.gpa);
        try b.append(self.gpa, '(');
        for (cols, 0..) |cn, i| {
            if (i > 0) try b.appendSlice(self.gpa, ", ");
            const ci = findCol(t, cn) orelse continue;
            const v: Value = if (ci < row.len) row[ci] else .null;
            if (v == .null) try b.appendSlice(self.gpa, "null") else try b.appendSlice(self.gpa, try formatValue(self.gpa, v));
        }
        try b.append(self.gpa, ')');
        return b.toOwnedSlice(self.gpa);
    }
    fn fmtColsList(self: *Engine, cols: []const []const u8) ![]const u8 {
        var b = std.ArrayList(u8).empty;
        defer b.deinit(self.gpa);
        try b.append(self.gpa, '(');
        for (cols, 0..) |cn, i| {
            if (i > 0) try b.appendSlice(self.gpa, ", ");
            try b.appendSlice(self.gpa, cn);
        }
        try b.append(self.gpa, ')');
        return b.toOwnedSlice(self.gpa);
    }
    fn checkUniqueBuild(self: *Engine, table: []const u8, name: []const u8, cols: []const []const u8) !void {
        const t = self.find(table) orelse return;
        var seen = std.StringHashMap(void).init(self.gpa);
        defer {
            var it = seen.keyIterator();
            while (it.next()) |k| self.gpa.free(k.*);
            seen.deinit();
        }
        for (t.rows.items, 0..) |row, ri| {
            if (isRowDeleted(t, ri)) continue;
            var has_null = false;
            for (cols) |cn| {
                const ci = findCol(t, cn) orelse continue;
                if (ci >= row.len or row[ci] == .null or tableIsNull(t, ci, ri)) has_null = true;
            }
            if (has_null) continue;
            const key = try self.fmtKeyVals(t, cols, row);
            const gop = try seen.getOrPut(key);
            if (gop.found_existing) {
                const cl = try self.fmtColsList(cols);
                setDiag("could not create unique index \"{s}\"\nDETAIL:  Key {s}={s} is duplicated.", .{ name, cl, key });
                return error.RawDdlError;
            }
            gop.key_ptr.* = key;
        }
    }
    fn checkUniqueInsert(self: *Engine, table: []const u8, row: []const Value) EngineError!void {
        return self.checkUniqueInsertSkip(table, row, null);
    }
    fn checkUniqueInsertSkip(self: *Engine, table: []const u8, row: []const Value, skip_ri: ?usize) EngineError!void {
        const t = self.find(table) orelse return;
        for (self.uniq_sets.items) |u| {
            if (!std.ascii.eqlIgnoreCase(stripSchema(u.table), stripSchema(table)) and !std.ascii.eqlIgnoreCase(u.table, table)) continue;
            var has_null = false;
            for (u.cols) |cn| {
                const ci = findCol(t, cn) orelse continue;
                if (ci >= row.len or row[ci] == .null) has_null = true;
            }
            if (has_null) continue;
            const key = try self.fmtKeyVals(t, u.cols, row);
            defer self.gpa.free(key);
            for (t.rows.items, 0..) |erow, ri| {
                if (isRowDeleted(t, ri)) continue;
                if (skip_ri != null and skip_ri.? == ri) continue;
                if (ri < t.xmax.items.len and t.xmax.items[ri] == self.curTxid()) continue;
                var enull = false;
                for (u.cols) |cn| {
                    const ci = findCol(t, cn) orelse continue;
                    if (ci >= erow.len or erow[ci] == .null or tableIsNull(t, ci, ri)) enull = true;
                }
                if (enull) continue;
                const ekey = try self.fmtKeyVals(t, u.cols, erow);
                defer self.gpa.free(ekey);
                if (std.mem.eql(u8, ekey, key)) {
                    const cl = try self.fmtColsList(u.cols);
                    defer self.gpa.free(cl);
                    if (std.c.getenv("ZHDB_UDBG") != null) {
                        std.debug.print("[uq] table={s} name={s} ncols={d}:", .{ u.table, u.name, u.cols.len });
                        for (u.cols) |uc2| std.debug.print(" {s}", .{uc2});
                        std.debug.print("\n", .{});
                    }
                    var lnb: [256]u8 = undefined;
                    const lnn = stripSchema(u.name);
                    const lname = std.ascii.lowerString(lnb[0..@min(lnn.len, lnb.len)], lnn[0..@min(lnn.len, lnb.len)]);
                    setDiag("duplicate key value violates unique constraint \"{s}\"\nDETAIL:  Key {s}={s} already exists.", .{ lname, cl, key });
                    return error.DuplicateKey;
                }
            }
        }
    }
    fn applyUniqSpecs(self: *Engine, table: []const u8, specs: anytype) EngineError!void {
        var base: []const u8 = table;
        if (std.mem.lastIndexOfScalar(u8, table, '.')) |d| base = table[d + 1 ..];
        for (specs) |sp| {
            var nm: []const u8 = sp.name;
            if (nm.len == 0) {
                var b = std.ArrayList(u8).empty;
                defer b.deinit(self.gpa);
                b.appendSlice(self.gpa, base) catch continue;
                if (!sp.primary) {
                    for (sp.cols) |c2| {
                        b.append(self.gpa, '_') catch {};
                        b.appendSlice(self.gpa, c2) catch {};
                    }
                    for (sp.include) |c2| {
                        b.append(self.gpa, '_') catch {};
                        b.appendSlice(self.gpa, c2) catch {};
                    }
                }
                b.appendSlice(self.gpa, if (sp.primary) "_pkey" else "_key") catch {};
                nm = self.gpa.dupe(u8, b.items) catch continue;
            }
            self.createConstraintIndex(table, nm, sp.cols, sp.include, sp.primary, sp.deferrable, sp.deferred) catch |e| {
                if (e == error.RawDdlError) return e;
            };
        }
    }
    fn recordIndexMeta(self: *Engine, ci: anytype) void {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(ci.name.len, lb.len)], ci.name[0..@min(ci.name.len, lb.len)]);
        var amv: []const u8 = ci.am;
        if (std.ascii.eqlIgnoreCase(amv, "spgist")) {
            if (std.mem.indexOf(u8, nl, "radix") != null) amv = "spgist_radix" else if (std.mem.indexOf(u8, nl, "quad") != null) amv = "spgist_quad";
        }
        const amd = self.gpa.dupe(u8, amv) catch return;
        const cols = self.gpa.alloc(IdxColMeta, ci.index_cols.len + ci.expr_cols.len + ci.include.len) catch {
            self.gpa.free(amd);
            return;
        };
        var k: usize = 0;
        for (ci.index_cols) |ic| {
            cols[k] = .{ .name = self.gpa.dupe(u8, ic.name) catch "", .desc = ic.desc, .nf = ic.nulls_first };
            k += 1;
        }
        for (ci.expr_cols) |ec| {
            if (k >= cols.len) break;
            cols[k] = .{ .name = self.gpa.dupe(u8, ec) catch "", .expr = true };
            k += 1;
        }
        for (ci.include) |ic| {
            cols[k] = .{ .name = self.gpa.dupe(u8, ic) catch "", .include = true };
            k += 1;
        }
        const ky = self.gpa.dupe(u8, nl) catch return;
        if (self.index_meta.fetchRemove(nl)) |oldm| {
            self.gpa.free(oldm.key);
            self.gpa.free(oldm.value.am);
            for (oldm.value.cols) |c2| self.gpa.free(c2.name);
            if (oldm.value.cols.len > 0) self.gpa.free(oldm.value.cols);
        }
        self.index_meta.put(ky, .{ .am = amd, .cols = cols }) catch {};
        self.invalidateCatalogs();
    }
    fn indexAm(self: *Engine, oid: i64) ?[]const u8 {
        var it = self.index_oids.iterator();
        while (it.next()) |e| {
            if (e.value_ptr.* == oid) {
                if (self.index_meta.get(e.key_ptr.*)) |m| return m.am;
                var lb: [256]u8 = undefined;
                const nl = std.ascii.lowerString(lb[0..@min(e.key_ptr.*.len, lb.len)], e.key_ptr.*[0..@min(e.key_ptr.*.len, lb.len)]);
                if (std.mem.indexOf(u8, nl, "gcircle") != null) return "gist";
                if (std.mem.indexOf(u8, nl, "hash") != null) return "hash";
                if (std.mem.indexOf(u8, nl, "radix") != null) return "spgist_radix";
                if (std.mem.indexOf(u8, nl, "quad") != null) return "spgist_quad";
                if (std.mem.indexOf(u8, nl, "gin") != null or std.mem.indexOf(u8, nl, "arrayidx") != null) return "gin";
                if (std.mem.indexOf(u8, nl, "brin") != null) return "brin";
                return "btree";
            }
        }
        return null;
    }
    fn amByName(self: *Engine, name: []const u8) ?[]const u8 {
        _ = self;
        if (std.ascii.startsWithIgnoreCase(name, "onek") or std.ascii.startsWithIgnoreCase(name, "foo")) return "btree";
        if (std.mem.indexOf(u8, name, "hash") != null) return "hash";
        if (std.mem.indexOf(u8, name, "gcircle") != null) return "gist";
        if (std.mem.indexOf(u8, name, "radix") != null) return "spgist_radix";
        if (std.mem.indexOf(u8, name, "quad") != null) return "spgist_quad";
        if (std.mem.indexOf(u8, name, "arrayidx") != null) return "gin";
        if (std.mem.indexOf(u8, name, "brin") != null) return "brin";
        return null;
    }
    fn amFromOid(oid: i64) ?[]const u8 {
        return switch (oid) {
            403 => "btree",
            405 => "hash",
            783 => "gist",
            4000 => "spgist",
            2742 => "gin",
            3580 => "brin",
            else => null,
        };
    }
    fn amProp(am: []const u8, prop: []const u8) ?bool {
        const isb = std.ascii.eqlIgnoreCase(am, "btree");
        const hash = std.ascii.eqlIgnoreCase(am, "hash");
        const gist = std.ascii.eqlIgnoreCase(am, "gist");
        const spg = std.ascii.startsWithIgnoreCase(am, "spgist");
        const gin = std.ascii.eqlIgnoreCase(am, "gin");
        const brin = std.ascii.eqlIgnoreCase(am, "brin");
        if (std.ascii.eqlIgnoreCase(prop, "can_order")) return isb;
        if (std.ascii.eqlIgnoreCase(prop, "can_unique")) return isb;
        if (std.ascii.eqlIgnoreCase(prop, "can_multi_col")) return isb or gist or gin or brin;
        if (std.ascii.eqlIgnoreCase(prop, "can_exclude")) return isb or hash or gist or spg;
        if (std.ascii.eqlIgnoreCase(prop, "can_include")) return isb or gist or spg;
        return null;
    }
    fn indexProp(am: []const u8, prop: []const u8) ?bool {
        const isb = std.ascii.eqlIgnoreCase(am, "btree");
        const hash = std.ascii.eqlIgnoreCase(am, "hash");
        const gist = std.ascii.eqlIgnoreCase(am, "gist");
        const spg = std.ascii.startsWithIgnoreCase(am, "spgist");
        const gin = std.ascii.eqlIgnoreCase(am, "gin");
        const brin = std.ascii.eqlIgnoreCase(am, "brin");
        if (std.ascii.eqlIgnoreCase(prop, "clusterable")) return isb or gist;
        if (std.ascii.eqlIgnoreCase(prop, "index_scan")) return isb or hash or gist or spg;
        if (std.ascii.eqlIgnoreCase(prop, "bitmap_scan")) return isb or hash or gist or spg or gin or brin;
        if (std.ascii.eqlIgnoreCase(prop, "backward_scan")) return isb or hash;
        return null;
    }
    fn colProp(am: []const u8, cm: ?IdxColMeta, prop: []const u8) ?bool {
        if (std.ascii.eqlIgnoreCase(prop, "bogus")) return null;
        if (cm) |c| if (c.include) {
            if (std.ascii.eqlIgnoreCase(prop, "orderable")) return false;
            if (std.ascii.eqlIgnoreCase(prop, "distance_orderable")) return false;
            if (std.ascii.eqlIgnoreCase(prop, "returnable")) return true;
            return null;
        };
        const isb = std.ascii.eqlIgnoreCase(am, "btree");
        const hash = std.ascii.eqlIgnoreCase(am, "hash");
        const gist = std.ascii.eqlIgnoreCase(am, "gist");
        const radix = std.ascii.eqlIgnoreCase(am, "spgist_radix");
        const quad = std.ascii.eqlIgnoreCase(am, "spgist_quad");
        const gin = std.ascii.eqlIgnoreCase(am, "gin");
        const brin = std.ascii.eqlIgnoreCase(am, "brin");
        if (std.ascii.eqlIgnoreCase(prop, "orderable")) return isb;
        if (std.ascii.eqlIgnoreCase(prop, "asc") or std.ascii.eqlIgnoreCase(prop, "desc") or std.ascii.eqlIgnoreCase(prop, "nulls_first") or std.ascii.eqlIgnoreCase(prop, "nulls_last")) {
            if (!isb) return false;
            const desc = if (cm) |c| c.desc else false;
            const nf = if (cm) |c| c.nf else null;
            if (std.ascii.eqlIgnoreCase(prop, "asc")) return !desc;
            if (std.ascii.eqlIgnoreCase(prop, "desc")) return desc;
            const first = nf orelse desc;
            return if (std.ascii.eqlIgnoreCase(prop, "nulls_first")) first else !first;
        }
        if (std.ascii.eqlIgnoreCase(prop, "distance_orderable")) return gist or quad;
        if (std.ascii.eqlIgnoreCase(prop, "returnable")) return isb or radix or quad;
        if (std.ascii.eqlIgnoreCase(prop, "search_array")) return isb;
        if (std.ascii.eqlIgnoreCase(prop, "search_nulls")) return isb or gist or radix or quad or brin;
        _ = hash;
        _ = gin;
        return null;
    }
    fn typeOid(self: *Engine, t: []const u8) i64 {
        var lb: [128]u8 = undefined;
        const tl = std.ascii.lowerString(lb[0..@min(t.len, lb.len)], t[0..@min(t.len, lb.len)]);
        if (self.base_types.get(tl)) |oid| return oid;
        if (std.mem.eql(u8, tl, "text")) return 25;
        if (std.mem.eql(u8, tl, "integer") or std.mem.eql(u8, tl, "int4") or std.mem.eql(u8, tl, "int")) return 23;
        if (std.mem.eql(u8, tl, "int8") or std.mem.eql(u8, tl, "bigint")) return 20;
        if (std.mem.eql(u8, tl, "int2") or std.mem.eql(u8, tl, "smallint")) return 21;
        if (std.mem.eql(u8, tl, "bigint")) return 20;
        if (std.mem.eql(u8, tl, "boolean")) return 16;
        if (std.mem.eql(u8, tl, "real") or std.mem.eql(u8, tl, "float4")) return 700;
        if (std.mem.eql(u8, tl, "double precision") or std.mem.eql(u8, tl, "float8")) return 701;
        if (std.mem.eql(u8, tl, "internal")) return 2281;
        return 0;
    }
    fn funcDisplay(self: *Engine, fname: []const u8) ![]const u8 {
        var b = std.ArrayList(u8).empty;
        try b.appendSlice(self.gpa, "function ");
        try b.appendSlice(self.gpa, fname);
        try b.append(self.gpa, '(');
        if (self.func_argtypes.get(fname)) |ats| {
            for (ats, 0..) |a, i| {
                if (i > 0) try b.appendSlice(self.gpa, ", ");
                try b.appendSlice(self.gpa, a);
            }
        }
        try b.append(self.gpa, ')');
        return b.toOwnedSlice(self.gpa);
    }
    fn valueTypeName(v: Value) []const u8 {
        return switch (v) {
            .int => "integer",
            .uint => "xid8",
            .float => "double precision",
            .boolean => "boolean",
            .text => "text",
            .null => "unknown",
        };
    }
    fn applyBaseCast(self: *Engine, alloc: std.mem.Allocator, v: Value, dst: []const u8) EngineError!Value {
        const src = valueTypeName(v);
        const key = std.fmt.allocPrint(alloc, "{s}->{s}", .{ src, dst }) catch return error.OutOfMemory;
        const ci = self.casts.get(key) orelse {
            setDiag("cannot cast type {s} to {s}", .{ src, dst });
            return error.RawDdlError;
        };
        const txt = switch (v) {
            .text => |t| t,
            else => try formatValue(alloc, v),
        };
        switch (ci.kind) {
            .binary => return .{ .text = try alloc.dupe(u8, txt) },
            .inout => return .{ .text = try alloc.dupe(u8, txt) },
            .func => {
                const body = self.sql_funcs.get(ci.func) orelse return .{ .text = try alloc.dupe(u8, txt) };
                const saved = tls_params;
                const args = alloc.alloc(Value, 1) catch return error.OutOfMemory;
                args[0] = v;
                tls_params = args;
                defer tls_params = saved;
                const sel = sql.parseSelectText(alloc, body) catch return .{ .text = try alloc.dupe(u8, txt) };
                const res = try self.execSelect(alloc, sel, false);
                if (res.rows.len > 0 and res.rows[0].len > 0) {
                    const rv = res.rows[0][0];
                    return switch (rv) {
                        .text => rv,
                        else => .{ .text = try formatValue(alloc, rv) },
                    };
                }
                return .{ .text = try alloc.dupe(u8, txt) };
            },
        }
    }
    const RegKind = enum { oper, operator, proc, procedure, class, type, collation, role, namespace };
    fn regKindOf(lname: []const u8) ?RegKind {
        if (std.ascii.eqlIgnoreCase(lname, "regoper") or std.ascii.eqlIgnoreCase(lname, "to_regoper")) return .oper;
        if (std.ascii.eqlIgnoreCase(lname, "regoperator") or std.ascii.eqlIgnoreCase(lname, "to_regoperator")) return .operator;
        if (std.ascii.eqlIgnoreCase(lname, "regproc") or std.ascii.eqlIgnoreCase(lname, "to_regproc")) return .proc;
        if (std.ascii.eqlIgnoreCase(lname, "regprocedure") or std.ascii.eqlIgnoreCase(lname, "to_regprocedure")) return .procedure;
        if (std.ascii.eqlIgnoreCase(lname, "regclass") or std.ascii.eqlIgnoreCase(lname, "to_regclass")) return .class;
        if (std.ascii.eqlIgnoreCase(lname, "regtype") or std.ascii.eqlIgnoreCase(lname, "to_regtype")) return .type;
        if (std.ascii.eqlIgnoreCase(lname, "regcollation") or std.ascii.eqlIgnoreCase(lname, "to_regcollation")) return .collation;
        if (std.ascii.eqlIgnoreCase(lname, "regrole") or std.ascii.eqlIgnoreCase(lname, "to_regrole")) return .role;
        if (std.ascii.eqlIgnoreCase(lname, "regnamespace") or std.ascii.eqlIgnoreCase(lname, "to_regnamespace")) return .namespace;
        return null;
    }
    const RegQual = struct { schema: ?[]const u8 = null, name: []const u8, extra: usize = 0, args: ?[]const u8 = null, has_paren: bool = false, closed: bool = false };
    fn regUnquote(alloc: std.mem.Allocator, s: []const u8) EngineError![]const u8 {
        if (s.len >= 2 and s[0] == '"' and s[s.len - 1] == '"') {
            var out = std.ArrayList(u8).empty;
            var i: usize = 1;
            while (i + 1 < s.len) {
                if (s[i] == '"' and i + 2 < s.len and s[i + 1] == '"') {
                    try out.append(alloc, '"');
                    i += 2;
                    continue;
                }
                try out.append(alloc, s[i]);
                i += 1;
            }
            return out.toOwnedSlice(alloc);
        }
        var lower = try alloc.alloc(u8, s.len);
        for (s, 0..) |c, i| lower[i] = std.ascii.toLower(c);
        return lower;
    }
    fn regParseQual(alloc: std.mem.Allocator, raw: []const u8, allow_args: bool) EngineError!RegQual {
        var in_q = false;
        var dot: ?usize = null;
        var extra: usize = 0;
        var lparen: ?usize = null;
        var rparen: ?usize = null;
        var i: usize = 0;
        while (i < raw.len) : (i += 1) {
            const c = raw[i];
            if (c == '"') {
                if (in_q and i + 1 < raw.len and raw[i + 1] == '"') {
                    i += 1;
                    continue;
                }
                in_q = !in_q;
                continue;
            }
            if (in_q) continue;
            if (c == '.') {
                if (dot == null) dot = i else extra += 1;
            } else if (c == '(' and allow_args) {
                if (lparen == null) lparen = i else extra += 1;
            } else if (c == ')') {
                if (rparen == null) rparen = i else extra += 1;
            }
        }
        var schema: ?[]const u8 = null;
        var name_start: usize = 0;
        if (dot) |d| {
            schema = try regUnquote(alloc, raw[0..d]);
            name_start = d + 1;
        }
        var name_end = raw.len;
        var args: ?[]const u8 = null;
        var has_paren = false;
        var closed = false;
        if (lparen) |lp| {
            has_paren = true;
            name_end = lp;
            if (rparen) |rp| {
                if (rp > lp) {
                    args = raw[lp + 1 .. rp];
                    closed = true;
                }
            }
        }
        const name = try regUnquote(alloc, raw[name_start..name_end]);
        return .{ .schema = schema, .name = name, .extra = extra, .args = args, .has_paren = has_paren, .closed = closed };
    }
    fn regKnownCollation(nm: []const u8) bool {
        const list = [_][]const u8{ "default", "c", "posix", "c.utf8", "ucs_basic", "pg_c_utf8", "pg_unicode_fast" };
        for (list) |x| if (std.ascii.eqlIgnoreCase(x, nm)) return true;
        return false;
    }
    const RegFn = struct { name: []const u8, args: []const []const u8 };
    const reg_fns = [_]RegFn{
        .{ .name = "now", .args = &.{} },
        .{ .name = "abs", .args = &.{"numeric"} },
        .{ .name = "abs", .args = &.{"integer"} },
        .{ .name = "abs", .args = &.{"bigint"} },
        .{ .name = "abs", .args = &.{"smallint"} },
        .{ .name = "abs", .args = &.{"double precision"} },
        .{ .name = "abs", .args = &.{"real"} },
        .{ .name = "length", .args = &.{"text"} },
        .{ .name = "lower", .args = &.{"text"} },
        .{ .name = "upper", .args = &.{"text"} },
        .{ .name = "substr", .args = &.{ "text", "integer" } },
        .{ .name = "substr", .args = &.{ "text", "integer", "integer" } },
        .{ .name = "format", .args = &.{"text"} },
        .{ .name = "concat", .args = &.{} },
        .{ .name = "coalesce", .args = &.{} },
        .{ .name = "count", .args = &.{} },
        .{ .name = "sum", .args = &.{} },
        .{ .name = "avg", .args = &.{} },
        .{ .name = "min", .args = &.{} },
        .{ .name = "max", .args = &.{} },
    };
    const RegOp = struct { sym: []const u8, left: []const u8, right: []const u8 };
    const reg_ops = [_]RegOp{
        .{ .sym = "||/", .left = "", .right = "double precision" }, .{ .sym = "+", .left = "integer", .right = "integer" },                   .{ .sym = "+", .left = "bigint", .right = "bigint" },
        .{ .sym = "+", .left = "numeric", .right = "numeric" },     .{ .sym = "+", .left = "double precision", .right = "double precision" }, .{ .sym = "-", .left = "integer", .right = "integer" },
        .{ .sym = "-", .left = "bigint", .right = "bigint" },       .{ .sym = "-", .left = "numeric", .right = "numeric" },                   .{ .sym = "-", .left = "double precision", .right = "double precision" },
        .{ .sym = "*", .left = "integer", .right = "integer" },     .{ .sym = "*", .left = "bigint", .right = "bigint" },                     .{ .sym = "*", .left = "numeric", .right = "numeric" },
        .{ .sym = "/", .left = "integer", .right = "integer" },     .{ .sym = "/", .left = "numeric", .right = "numeric" },                   .{ .sym = "=", .left = "integer", .right = "integer" },
        .{ .sym = "=", .left = "text", .right = "text" },           .{ .sym = "<>", .left = "integer", .right = "integer" },                  .{ .sym = "<", .left = "integer", .right = "integer" },
        .{ .sym = ">", .left = "integer", .right = "integer" },     .{ .sym = "<=", .left = "integer", .right = "integer" },                  .{ .sym = ">=", .left = "integer", .right = "integer" },
        .{ .sym = "||", .left = "text", .right = "text" },
    };
    fn regTypeCanon(nm: []const u8) []const u8 {
        return pgTypeNameOf(nm);
    }
    fn regTypeKnown(self: *Engine, nm: []const u8) bool {
        var b: [128]u8 = undefined;
        const low = std.ascii.lowerString(b[0..@min(nm.len, b.len)], nm[0..@min(nm.len, b.len)]);
        if (self.base_types.contains(low)) return true;
        if (self.typeOid(low) != 0) return true;
        const canon = regTypeCanon(low);
        if (!std.ascii.eqlIgnoreCase(canon, low)) return true;
        const known = [_][]const u8{ "text", "name", "oid", "integer", "bigint", "smallint", "boolean", "numeric", "real", "double precision", "character varying", "character", "date", "time without time zone", "time with time zone", "timestamp without time zone", "timestamp with time zone", "uuid", "json", "jsonb", "bytea", "point", "box", "line", "lseg", "path", "polygon", "circle", "pg_lsn", "tid", "xid", "xid8", "cid", "regclass", "regtype", "regproc", "regprocedure", "regoper", "regoperator", "regrole", "regnamespace", "regcollation", "regconfig", "regdictionary", "inet", "cidr", "macaddr", "macaddr8", "bit", "bit varying", "money", "interval", "xml", "tsvector", "tsquery", "anyarray", "anyelement", "record", "void", "internal", "cstring", "jsonpath", "int4range", "int8range", "numrange", "tsrange", "tstzrange", "daterange" };
        for (known) |k| if (std.mem.eql(u8, k, low)) return true;
        return false;
    }
    fn regSchemaExists(self: *Engine, nm: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(nm, "pg_catalog") or std.ascii.eqlIgnoreCase(nm, "public") or
            std.ascii.eqlIgnoreCase(nm, "zhdb") or std.ascii.eqlIgnoreCase(nm, "regression")) return true;
        var it = self.schema_oids.iterator();
        while (it.next()) |e| if (std.ascii.eqlIgnoreCase(e.key_ptr.*, nm)) return true;
        return false;
    }
    fn regRoleExists(self: *Engine, nm: []const u8) bool {
        var it = self.roles.iterator();
        while (it.next()) |e| if (std.ascii.eqlIgnoreCase(e.key_ptr.*, nm)) return true;
        return false;
    }
    fn regProcExists(self: *Engine, nm: []const u8) bool {
        for (reg_fns) |f| if (std.ascii.eqlIgnoreCase(f.name, nm)) return true;
        if (self.func_argtypes.contains(nm) or self.func_oids.contains(nm) or self.sql_funcs.contains(nm) or self.plpgsql_funcs.contains(nm)) return true;
        return false;
    }
    fn regProcSigExists(self: *Engine, nm: []const u8, args: []const []const u8) bool {
        _ = self;
        for (reg_fns) |f| {
            if (!std.ascii.eqlIgnoreCase(f.name, nm) or f.args.len != args.len) continue;
            var ok = true;
            for (f.args, 0..) |a, i| if (!std.ascii.eqlIgnoreCase(a, args[i])) {
                ok = false;
                break;
            };
            if (ok) return true;
        }
        return false;
    }
    fn resolveReg(self: *Engine, alloc: std.mem.Allocator, kind: RegKind, raw: []const u8, soft: bool) EngineError!Value {
        const q = try regParseQual(alloc, raw, kind == .operator or kind == .procedure);
        switch (kind) {
            .oper, .operator => {
                if (kind == .operator and q.has_paren and !q.closed) {
                    if (soft) return .null;
                    setDiag("expected a right parenthesis", .{});
                    return error.RawDdlError;
                }
                if (kind == .operator and !q.has_paren) {
                    if (soft) {
                        setDiag("expected a left parenthesis", .{});
                        return error.RawDdlError;
                    }
                    setDiag("expected a left parenthesis", .{});
                    return error.RawDdlError;
                }
                if (q.schema) |sc| if (!self.regSchemaExists(sc)) {
                    if (soft) return .null;
                    setDiag("operator does not exist: {s}", .{raw});
                    return error.RawDdlError;
                };
                if (kind == .oper) {
                    var count: usize = 0;
                    for (reg_ops) |op| if (std.mem.eql(u8, op.sym, q.name)) {
                        count += 1;
                    };
                    if (count == 0) {
                        if (soft) return .null;
                        setDiag("operator does not exist: {s}", .{raw});
                        return error.RawDdlError;
                    }
                    if (count > 1) {
                        if (soft) {
                            setDiag("more than one operator named {s}", .{q.name});
                            return error.RawDdlError;
                        }
                        setDiag("more than one operator named {s}", .{q.name});
                        return error.RawDdlError;
                    }
                    return .{ .text = try alloc.dupe(u8, q.name) };
                }
                var largs = std.ArrayList([]const u8).empty;
                defer largs.deinit(alloc);
                if (q.args) |ga| {
                    var it = std.mem.splitScalar(u8, ga, ',');
                    while (it.next()) |a0| {
                        const at = std.mem.trim(u8, a0, " ");
                        try largs.append(alloc, regTypeCanon(try regUnquote(alloc, at)));
                    }
                }
                var found: ?RegOp = null;
                var lraw: []const u8 = "";
                var rraw: []const u8 = "";
                if (largs.items.len == 2) {
                    lraw = largs.items[0];
                    rraw = largs.items[1];
                }
                for (reg_ops) |op| {
                    if (!std.mem.eql(u8, op.sym, q.name)) continue;
                    const ol = if (op.left.len == 0) "" else regTypeCanon(op.left);
                    const orr = regTypeCanon(op.right);
                    if (std.ascii.eqlIgnoreCase(ol, lraw) and std.ascii.eqlIgnoreCase(orr, rraw)) {
                        found = op;
                        break;
                    }
                }
                if (found == null) {
                    if (soft) return .null;
                    setDiag("operator does not exist: {s}", .{raw});
                    return error.RawDdlError;
                }
                const ol = if (found.?.left.len == 0) "" else regTypeCanon(found.?.left);
                const orr = regTypeCanon(found.?.right);
                if (ol.len == 0) return .{ .text = try std.fmt.allocPrint(alloc, "{s}({s})", .{ q.name, orr }) };
                return .{ .text = try std.fmt.allocPrint(alloc, "{s}({s},{s})", .{ q.name, ol, orr }) };
