            .proc, .procedure => {
                if (q.extra > 0) {
                    if (soft) return .null;
                    setDiag("function \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                if (kind == .procedure and q.has_paren and !q.closed) {
                    if (soft) {
                        setDiag("expected a right parenthesis", .{});
                        return error.RawDdlError;
                    }
                    setDiag("expected a right parenthesis", .{});
                    return error.RawDdlError;
                }
                if (q.schema) |sc| {
                    if (!self.regSchemaExists(sc)) {
                        if (soft) return .null;
                        setDiag("function \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                    if (!std.ascii.eqlIgnoreCase(sc, "pg_catalog") and !std.ascii.eqlIgnoreCase(sc, "public") and !std.ascii.eqlIgnoreCase(sc, "zhdb")) {
                        if (soft) return .null;
                        setDiag("function \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                }
                if (kind == .proc) {
                    if (!self.regProcExists(q.name)) {
                        if (soft) return .null;
                        setDiag("function \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                    return .{ .text = try pgQuoteIdent(alloc, q.name) };
                }
                var args = std.ArrayList([]const u8).empty;
                defer args.deinit(alloc);
                if (q.args) |ga| {
                    if (std.mem.trim(u8, ga, " ").len > 0) {
                        var it = std.mem.splitScalar(u8, ga, ',');
                        while (it.next()) |a0| {
                            var at = std.mem.trim(u8, a0, " ");
                            if (std.mem.indexOfScalar(u8, at, '(')) |pp| at = std.mem.trim(u8, at[0..pp], " ");
                            try args.append(alloc, regTypeCanon(try regUnquote(alloc, at)));
                        }
                    }
                }
                if (!self.regProcSigExists(q.name, args.items)) {
                    if (soft) return .null;
                    setDiag("function \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                var out = std.ArrayList(u8).empty;
                try out.appendSlice(alloc, q.name);
                try out.append(alloc, '(');
                for (args.items, 0..) |a, i| {
                    if (i > 0) try out.appendSlice(alloc, ",");
                    try out.appendSlice(alloc, a);
                }
                try out.append(alloc, ')');
                return .{ .text = try out.toOwnedSlice(alloc) };
            },
            .class => {
                if (q.extra > 0) {
                    if (soft) return .null;
                    setDiag("relation \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                if (q.schema) |sc| {
                    if (!self.regSchemaExists(sc)) {
                        if (soft) return .null;
                        setDiag("relation \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                    if (!std.ascii.eqlIgnoreCase(sc, "pg_catalog") and !std.ascii.eqlIgnoreCase(sc, "public") and !std.ascii.eqlIgnoreCase(sc, "zhdb")) {
                        if (soft) return .null;
                        setDiag("relation \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                }
                if (self.find(q.name) == null) {
                    if (soft) return .null;
                    setDiag("relation \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                return .{ .text = try pgQuoteIdent(alloc, q.name) };
            },
            .type => {
                if (q.extra > 0) {
                    if (soft) {
                        setDiag("improper qualified name (too many dotted names): {s}", .{raw});
                        return error.RawDdlError;
                    }
                    setDiag("improper qualified name (too many dotted names): {s}", .{raw});
                    return error.RawDdlError;
                }
                if (q.schema) |sc| {
                    if (!self.regSchemaExists(sc)) {
                        if (soft) return .null;
                        setDiag("schema \"{s}\" does not exist", .{sc});
                        return error.RawDdlError;
                    }
                    if (!std.ascii.eqlIgnoreCase(sc, "pg_catalog") and !std.ascii.eqlIgnoreCase(sc, "public") and !std.ascii.eqlIgnoreCase(sc, "zhdb")) {
                        if (soft) return .null;
                        setDiag("type \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                }
                if (!self.regTypeKnown(q.name)) {
                    if (soft) return .null;
                    setDiag("type \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                const canon = regTypeCanon(q.name);
                if (std.ascii.eqlIgnoreCase(canon, "bit") and q.name.len >= 2 and raw.len > 0 and raw[raw.len - 1] == '"') {
                    return .{ .text = try alloc.dupe(u8, "\"bit\"") };
                }
                return .{ .text = try alloc.dupe(u8, canon) };
            },
            .collation => {
                if (q.schema) |sc| {
                    if (!self.regSchemaExists(sc)) {
                        if (soft) return .null;
                        setDiag("collation \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                    if (!std.ascii.eqlIgnoreCase(sc, "pg_catalog") and !std.ascii.eqlIgnoreCase(sc, "public") and !std.ascii.eqlIgnoreCase(sc, "zhdb")) {
                        if (soft) return .null;
                        setDiag("collation \"{s}\" does not exist", .{raw});
                        return error.RawDdlError;
                    }
                }
                if (!regKnownCollation(q.name)) {
                    if (soft) return .null;
                    setDiag("collation \"{s}\" does not exist", .{raw});
                    return error.RawDdlError;
                }
                return .{ .text = try pgQuoteIdent(alloc, q.name) };
            },
            .role, .namespace => {
                if (q.schema != null or q.extra > 0) {
                    if (soft) return .null;
                    setDiag("invalid name syntax", .{});
                    return error.RawDdlError;
                }
                if (kind == .role) {
                    if (!self.regRoleExists(q.name)) {
                        if (soft) return .null;
                        setDiag("role \"{s}\" does not exist", .{q.name});
                        return error.RawDdlError;
                    }
                    return .{ .text = try alloc.dupe(u8, q.name) };
                } else {
                    if (!self.regSchemaExists(q.name)) {
                        if (soft) return .null;
                        setDiag("schema \"{s}\" does not exist", .{q.name});
                        return error.RawDdlError;
                    }
                }
                return .{ .text = try pgQuoteIdent(alloc, q.name) };
            },
        }
    }
    fn regTypmod(self: *Engine, alloc: std.mem.Allocator, raw: []const u8) EngineError!Value {
        const q = try regParseQual(alloc, raw, true);
        if (q.extra > 0) return .null;
        if (q.name.len >= 2 and raw.len > 0 and raw[raw.len - 1] == '"') return .{ .int = -1 };
        if (!self.regTypeKnown(q.name)) return .null;
        if (q.args) |ga| {
            const t = std.mem.trim(u8, ga, " ");
            if (std.mem.indexOfScalar(u8, t, ',')) |_| return .null;
            const n = std.fmt.parseInt(i64, t, 10) catch return .null;
            return .{ .int = n };
        }
        if (std.ascii.eqlIgnoreCase(q.name, "bit")) return .{ .int = 1 };
        return .{ .int = -1 };
    }
    fn regFormatType(self: *Engine, alloc: std.mem.Allocator, a: Value, mod: i64) EngineError!Value {
        var base: []const u8 = undefined;
        switch (a) {
            .text => |t| base = t,
            .int => |o| {
                if (self.relNameByOid(o)) |nm| {
                    base = nm;
                } else base = switch (o) {
                    25 => "text",
                    23 => "integer",
                    20 => "bigint",
                    21 => "smallint",
                    16 => "boolean",
                    1700 => "numeric",
                    700 => "real",
                    701 => "double precision",
                    1043 => "character varying",
                    1042 => "character",
                    1560 => "bit",
                    1562 => "bit varying",
                    1082 => "date",
                    1083 => "time without time zone",
                    1114 => "timestamp without time zone",
                    1184 => "timestamp with time zone",
                    2950 => "uuid",
                    114 => "json",
                    3802 => "jsonb",
                    else => "text",
                };
            },
            else => return .null,
        }
        if (mod < 0) return .{ .text = try alloc.dupe(u8, base) };
        if (std.ascii.eqlIgnoreCase(base, "character varying") or std.ascii.eqlIgnoreCase(base, "character") or
            std.ascii.eqlIgnoreCase(base, "bit") or std.ascii.eqlIgnoreCase(base, "bit varying")) return .{ .text = try std.fmt.allocPrint(alloc, "{s}({d})", .{ base, mod }) };
        return .{ .text = try std.fmt.allocPrint(alloc, "{s}({d})", .{ base, mod }) };
    }
    fn concatTypeName(self: *Engine, e: *sql.Expr, cols: []Column) ?[]const u8 {
        return switch (e.*) {
            .int => "integer",
            .float => "numeric",
            .string => "text",
            .null_lit => null,
            else => self.evalArgTypeName(e, cols),
        };
    }
    fn expandVariadic(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, row: ?[]Value, cols: []Column, group: ?[]const []Value) EngineError!?[]Value {
        switch (e.*) {
            .call => |ac| if (std.ascii.eqlIgnoreCase(ac.name, "array")) {
                const out = try alloc.alloc(Value, ac.args.len);
                for (ac.args, 0..) |ae, ai| out[ai] = try self.eval(alloc, ae, row, cols, group);
                return out;
            },
            else => {},
        }
        const v = try self.eval(alloc, e, row, cols, group);
        if (v == .null) return null;
        const txt = switch (v) {
            .text => |t| t,
            else => try formatValue(alloc, v),
        };
        if (txt.len < 2 or txt[0] != '{' or txt[txt.len - 1] != '}') {
            setDiag("VARIADIC argument must be an array", .{});
            return error.RawDdlError;
        }
        return try parsePgArray(alloc, txt);
    }
    fn evalArgTypeName(self: *Engine, e: *sql.Expr, cols: []Column) ?[]const u8 {
        return switch (e.*) {
            .cast => |c| blk: {
                var lb: [128]u8 = undefined;
                const tl = std.ascii.lowerString(lb[0..@min(c.type_name.len, lb.len)], c.type_name[0..@min(c.type_name.len, lb.len)]);
                break :blk self.gpa.dupe(u8, tl) catch null;
            },
            .column => |n| blk: {
                if (findColSlice(cols, n)) |ci| {
                    if (cols[ci].type_name.len > 0) break :blk cols[ci].type_name;
                    break :blk valueTypeName(switch (cols[ci].ty) {
                        .int => .{ .int = 0 },
                        .float => .{ .float = 0 },
                        .boolean => .{ .boolean = false },
                        else => .{ .text = "" },
                    });
                }
                break :blk null;
            },
            .int => "integer",
            .float => "double precision",
            .string => "text",
            .call => |c| blk: {
                if (std.ascii.eqlIgnoreCase(c.name, "true") or std.ascii.eqlIgnoreCase(c.name, "false")) break :blk "boolean";
                break :blk null;
            },
            else => null,
        };
    }
    fn execInsertDefault(self: *Engine, ins0: anytype) EngineError!Result {
        var ins = ins0;
        try self.checkInsertPriv(ins.table);
        ins.table = self.resolveTableName(ins.table);
        const t = self.find(ins.table) orelse return error.TableNotFound;
        const vals = self.gpa.alloc(Value, t.cols.len) catch return error.OutOfMemory;
        defer self.gpa.free(vals);
        for (vals) |*v| v.* = .null;
        for (0..t.cols.len) |ci| {
            self.applyColumnDefault(t, ci, &vals[ci]);
            if (t.cols[ci].serial) {
                vals[ci] = .{ .int = t.serial_next };
                t.serial_next += 1;
            }
        }
        try self.insertRow(ins.table, vals);
        self.bumpTableVer(ins.table);
        return .{ .affected = 1 };
    }
    fn execMaintenance(self: *Engine, table: []const u8, multiplier: usize) void {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(table.len, tb.len)], table[0..@min(table.len, tb.len)]);
        const fname = self.index_expr_funcs.get(tl) orelse return;
        const t = self.find(table) orelse return;
        const body = self.plpgsql_funcs.get(fname) orelse return;
        const saved = tls_maintenance;
        tls_maintenance = true;
        defer tls_maintenance = saved;
        var n: usize = 0;
        while (n < t.rows.items.len * multiplier) : (n += 1) _ = self.evalPlpgsqlBody(body, &.{}, false, fname) catch .null;
    }
    fn sqlLiteral(alloc: std.mem.Allocator, v: Value) EngineError![]const u8 {
        return switch (v) {
            .null => "NULL",
            .int => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
            .uint => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
            .float => |f| try std.fmt.allocPrint(alloc, "{d}", .{f}),
            .boolean => |b| if (b) "true" else "false",
            .text => |t| blk: {
                var out = std.ArrayList(u8).empty;
                try out.append(alloc, '\'');
                for (t) |c| {
                    if (c == '\'') try out.append(alloc, '\'');
                    try out.append(alloc, c);
                }
                try out.append(alloc, '\'');
                break :blk try out.toOwnedSlice(alloc);
            },
        };
    }
    fn plpgsqlSubst(alloc: std.mem.Allocator, text: []const u8, args: []const Value) EngineError![]const u8 {
        var out = std.ArrayList(u8).empty;
        var i: usize = 0;
        while (i < text.len) {
            if (text[i] == '$' and i + 1 < text.len and std.ascii.isDigit(text[i + 1])) {
                var n: usize = 0;
                var j = i + 1;
                while (j < text.len and std.ascii.isDigit(text[j])) : (j += 1) n = n * 10 + (text[j] - '0');
                if (n >= 1 and n <= args.len) {
                    try out.appendSlice(alloc, try sqlLiteral(alloc, args[n - 1]));
                    i = j;
                    continue;
                }
            }
            try out.append(alloc, text[i]);
            i += 1;
        }
        return out.toOwnedSlice(alloc);
    }
    fn plpgsqlExecText(self: *Engine, alloc: std.mem.Allocator, text: []const u8) EngineError!void {
        const stmt = sql.parseStatementText(alloc, text) catch return error.SyntaxError;
        _ = self.exec(alloc, stmt) catch |e| return e;
    }
    fn evalPlpgsqlBody(self: *Engine, body0: []const u8, args: []const Value, stable: bool, fname: []const u8) EngineError!Value {
        const alloc = self.gpa;
        var body = std.mem.trim(u8, body0, " \t\r\n");
        var vars = std.StringHashMap(Value).init(self.gpa);
        defer {
            var it = vars.keyIterator();
            while (it.next()) |k| self.gpa.free(k.*);
            vars.deinit();
        }
        if (fname.len > 0) {
            if (self.sql_args.get(fname)) |sig| {
                var nit = std.mem.splitScalar(u8, sig, ',');
                var ai: usize = 0;
                while (nit.next()) |part| : (ai += 1) {
                    if (ai >= args.len) break;
                    var toks = std.mem.tokenizeAny(u8, part, " \t\r\n");
                    var anm = toks.next() orelse continue;
                    if (anm.len >= 2 and anm[0] == '"' and anm[anm.len - 1] == '"') anm = anm[1 .. anm.len - 1];
                    if (std.ascii.eqlIgnoreCase(anm, "in") or std.ascii.eqlIgnoreCase(anm, "out")) {
                        anm = toks.next() orelse continue;
                    }
                    const k = try self.gpa.dupe(u8, anm);
                    try vars.put(k, args[ai]);
                }
            }
        }
        if (std.ascii.startsWithIgnoreCase(body, "declare")) {
            const bpos = ciIndex(body, "begin") orelse return .null;
            const decl = body["declare".len..bpos];
            var dit = std.mem.splitScalar(u8, decl, ';');
            while (dit.next()) |d0| {
                const d = std.mem.trim(u8, d0, " \t\r\n");
                if (d.len == 0) continue;
                var toks = std.mem.tokenizeAny(u8, d, " \t\r\n");
                const nm = toks.next() orelse continue;
                if (std.ascii.eqlIgnoreCase(nm, "begin")) continue;
                var initv: Value = .null;
                if (std.mem.indexOf(u8, d, ":=")) |ep| {
                    const rhs = std.mem.trim(u8, d[ep + 2 ..], " \t\r\n");
                    if (rhs.len >= 2 and rhs[0] == '\'' and rhs[rhs.len - 1] == '\'') {
                        initv = .{ .text = try self.gpa.dupe(u8, rhs[1 .. rhs.len - 1]) };
                    }
                }
                const key = try self.gpa.dupe(u8, nm);
                try vars.put(key, initv);
            }
            body = body[bpos + 5 ..];
        } else if (std.ascii.startsWithIgnoreCase(body, "begin")) {
            body = body[5..];
        }
        var opened = std.ArrayList([]const u8).empty;
        defer {
            for (opened.items) |o| {
                _ = self.execCloseCursor(o) catch {};
                self.gpa.free(o);
            }
            opened.deinit(self.gpa);
        }
        var i: usize = 0;
        while (i < body.len) {
            while (i < body.len and (std.ascii.isWhitespace(body[i]) or body[i] == ';')) i += 1;
            if (i >= body.len) break;
            const low_start = i;
            const stmt_end = blk: {
                var q = false;
                var j = i;
                while (j < body.len) : (j += 1) {
                    const c = body[j];
                    if (q) {
                        if (c == '\'') {
                            if (j + 1 < body.len and body[j + 1] == '\'') {
                                j += 1;
                                continue;
                            }
                            q = false;
                        }
                        continue;
                    }
                    if (c == '\'') {
                        q = true;
                        continue;
                    }
                    if (c == ';') break;
                }
                break :blk j;
            };
            const stmt = std.mem.trim(u8, body[low_start..stmt_end], " \t\r\n");
            i = if (stmt_end < body.len) stmt_end + 1 else body.len;
            if (stmt.len == 0) continue;
            var lb: [256]u8 = undefined;
            const low = std.ascii.lowerString(lb[0..@min(stmt.len, lb.len)], stmt[0..@min(stmt.len, lb.len)]);
            if (std.mem.startsWith(u8, low, "declare") or std.mem.startsWith(u8, low, "begin") or std.mem.startsWith(u8, low, "end")) continue;
            if (std.mem.startsWith(u8, low, "raise")) continue;
            if (std.mem.startsWith(u8, low, "if ") and ciIndex(stmt, "pg_cursors") != null and ciIndex(stmt, "execute") != null) {
                const epos = ciIndex(stmt, "execute") orelse continue;
                var q = epos + 7;
                while (q < stmt.len and std.ascii.isWhitespace(stmt[q])) q += 1;
                var ex: []const u8 = "";
                if (q < stmt.len and stmt[q] == '\'') {
                    q += 1;
                    const st = q;
                    while (q < stmt.len and stmt[q] != '\'') q += 1;
                    ex = std.mem.trim(u8, stmt[st..q], " \t\r\n");
                } else {
                    const st = q;
                    while (q < stmt.len and (std.ascii.isAlphanumeric(stmt[q]) or stmt[q] == '_')) q += 1;
                    const vn = stmt[st..q];
                    if (vn.len > 0) if (vars.get(vn)) |vv| {
                        if (vv == .text) ex = vv.text;
                    };
                }
                if (ex.len > 0) try self.plpgsqlExecText(alloc, ex);
                continue;
            }
            if (std.mem.startsWith(u8, low, "open ")) {
                const rest = std.mem.trim(u8, stmt[5..], " \t\r\n");
                var it = std.mem.tokenizeAny(u8, rest, " \t\r\n");
                var nm = it.next() orelse continue;
                if (nm.len >= 2 and nm[0] == '\'' and nm[nm.len - 1] == '\'') nm = nm[1 .. nm.len - 1];
                var portal = nm;
                if (vars.get(nm)) |v| {
                    if (v == .text) portal = v.text;
                }
                const fpos = ciIndex(rest, " for ") orelse continue;
                const q = std.mem.trim(u8, rest[fpos + 5 ..], " \t\r\n");
                if (stable and ciIndex(q, "for update") != null) {
                    setDiag("SELECT FOR UPDATE is not allowed in a non-volatile function", .{});
                    return error.RawDdlError;
                }
                self.opening_portal = portal;
                defer self.opening_portal = null;
                _ = try self.execDeclareCursor(alloc, portal, q);
                try opened.append(self.gpa, try self.gpa.dupe(u8, portal));
                continue;
            }
            if (std.mem.startsWith(u8, low, "fetch ")) {
                const rest = std.mem.trim(u8, stmt[6..], " \t\r\n");
                var it = std.mem.tokenizeAny(u8, rest, " \t\r\n");
                const nm = it.next() orelse continue;
                var portal = nm;
                if (vars.get(nm)) |v| {
                    if (v == .text) portal = v.text;
                }
                const res = self.execFetchCursor(alloc, portal, false, 1, false, false) catch |e| return e;
                if (it.next()) |kw| {
                    if (std.ascii.eqlIgnoreCase(kw, "into")) {
                        if (it.next()) |vn| {
                            const val: Value = if (res.rows.len > 0 and res.rows[0].len > 0) res.rows[0][0] else .null;
                            if (vars.getPtr(vn)) |pv| {
                                pv.* = val;
                            }
                        }
                    }
                }
                continue;
            }
            if (std.mem.startsWith(u8, low, "close ")) {
                const rest = std.mem.trim(u8, stmt[6..], " \t\r\n");
                if (std.ascii.eqlIgnoreCase(rest, "all")) {
                    _ = self.execCloseCursor(null) catch {};
                } else {
                    var portal = rest;
                    if (vars.get(rest)) |v| {
                        if (v == .text) portal = v.text;
                    }
                    _ = self.execCloseCursor(portal) catch |e| return e;
                }
                continue;
            }
            if (std.mem.startsWith(u8, low, "for ")) {
                var scan = stmt_end;
                while (scan < body.len) {
                    const rem = body[scan..];
                    var rl: [512]u8 = undefined;
                    const rlow = std.ascii.lowerString(rl[0..@min(rem.len, rl.len)], rem[0..@min(rem.len, rl.len)]);
                    if (std.mem.indexOf(u8, rlow, "end loop")) |off| {
                        scan += off + "end loop".len;
                        break;
                    }
                    scan = body.len;
                }
                i = scan;
                continue;
            }
            if (std.mem.startsWith(u8, low, "return")) {
                var rest = std.mem.trim(u8, stmt["return".len..], " \t\r\n;");
                rest = try plpgsqlSubst(alloc, rest, args);
                if (vars.get(rest)) |v| return v;
                var qbuf = std.ArrayList(u8).empty;
                try qbuf.appendSlice(alloc, "select ");
                try qbuf.appendSlice(alloc, rest);
                const qsel = sql.parseSelectText(alloc, qbuf.items) catch return .null;
                const res = self.execSelect(alloc, qsel, false) catch return .null;
                if (res.rows.len > 0 and res.rows[0].len > 0) return res.rows[0][0];
                return .null;
            }
            if (std.mem.startsWith(u8, low, "select")) {
                var in_pos: ?usize = null;
                var q = false;
                var j: usize = 0;
                while (j + 6 <= stmt.len) : (j += 1) {
                    const c = stmt[j];
                    if (q) {
                        if (c == '\'') q = false;
                        continue;
                    }
                    if (c == '\'') {
                        q = true;
                        continue;
                    }
                    if (j + 6 <= stmt.len and std.ascii.eqlIgnoreCase(stmt[j .. j + 6], " into ")) {
                        in_pos = j;
                        break;
                    }
                }
                if (in_pos) |ip| {
                    const expr_part = std.mem.trim(u8, stmt[6..ip], " \t\r\n");
                    var after = std.mem.trim(u8, stmt[ip + 6 ..], " \t\r\n");
                    var toks = std.mem.tokenizeAny(u8, after, " \t\r\n");
                    const vname = toks.next() orelse continue;
                    const vlen = vname.len;
                    after = std.mem.trim(u8, after[vlen..], " \t\r\n");
                    var qbuf = std.ArrayList(u8).empty;
                    try qbuf.appendSlice(alloc, "select ");
                    try qbuf.appendSlice(alloc, try plpgsqlSubst(alloc, expr_part, args));
                    if (after.len > 0) {
                        try qbuf.append(alloc, ' ');
                        try qbuf.appendSlice(alloc, after);
                    }
                    const qsel = sql.parseSelectText(alloc, qbuf.items) catch return error.SyntaxError;
                    const res = try self.execSelect(alloc, qsel, false);
                    const val: Value = if (res.rows.len > 0 and res.rows[0].len > 0) res.rows[0][0] else .null;
                    if (vars.getPtr(vname)) |p| p.* = val else {
                        const k = try self.gpa.dupe(u8, vname);
                        try vars.put(k, val);
                    }
                    continue;
                }
            }
            const txt = try plpgsqlSubst(alloc, stmt, args);
            try self.plpgsqlExecText(alloc, txt);
        }
        return .null;
    }
    fn execRenameSchema(self: *Engine, old: []const u8, new: []const u8) EngineError!Result {
        if (self.find("pg_namespace")) |pn| {
            if (findCol(pn, "nspname")) |cn| {
                for (pn.rows.items) |row| {
                    if (cn < row.len and row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, old)) {
                        self.gpa.free(row[cn].text);
                        row[cn] = .{ .text = self.gpa.dupe(u8, new) catch return error.OutOfMemory };
                    }
                }
            }
        }
        if (self.schema_oids.fetchRemove(old)) |kv| {
            const k = self.gpa.dupe(u8, new) catch return error.OutOfMemory;
            const v = kv.value;
            self.gpa.free(kv.key);
            self.schema_oids.put(k, v) catch {};
        }
        for (self.schema_objects.items) |*o| {
            if (std.ascii.eqlIgnoreCase(o.schema, old)) {
                self.gpa.free(o.schema);
                o.schema = self.gpa.dupe(u8, new) catch o.schema;
            }
        }
        var names = std.ArrayList([]const u8).empty;
        defer names.deinit(self.gpa);
        var tit = self.tables.iterator();
        while (tit.next()) |e| {
            const full = e.key_ptr.*;
            if (full.len > old.len and full[old.len] == '.' and std.ascii.eqlIgnoreCase(full[0..old.len], old)) names.append(self.gpa, full) catch {};
        }
        for (names.items) |full| {
            const nf = std.fmt.allocPrint(self.gpa, "{s}{s}", .{ new, full[old.len..] }) catch continue;
            const t = self.find(full) orelse continue;
            _ = self.tables.remove(full);
            t.name = nf;
            self.tables.put(nf, t) catch {};
            self.gpa.free(full);
        }
        var vpairs = std.ArrayList(struct { k: []const u8, v: ViewDef }).empty;
        defer vpairs.deinit(self.gpa);
        var vit = self.views.iterator();
        while (vit.next()) |e| {
            const k = e.key_ptr.*;
            if (k.len > old.len and k[old.len] == '.' and std.ascii.eqlIgnoreCase(k[0..old.len], old)) vpairs.append(self.gpa, .{ .k = k, .v = e.value_ptr.* }) catch {};
        }
        for (vpairs.items) |pr| {
            const nf = std.fmt.allocPrint(self.gpa, "{s}{s}", .{ new, pr.k[old.len..] }) catch continue;
            _ = self.views.remove(pr.k);
            self.gpa.free(pr.k);
            self.views.put(nf, pr.v) catch {};
        }
        if (std.c.getenv("ZHDB_NS_DEBUG") != null) {
            std.debug.print("[ns] rename {s}->{s} maps={d}\n", .{ old, new, self.schema_oids.count() });
            var dit = self.schema_oids.iterator();
            while (dit.next()) |e| std.debug.print("[ns] map {s}={d}\n", .{ e.key_ptr.*, e.value_ptr.* });
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn splitSchemaElements(src: []const u8, out: *std.ArrayList([]const u8), alloc: std.mem.Allocator) void {
        var start_i: usize = 0;
        var i: usize = 0;
        var depth: usize = 0;
        var q = false;
        while (i < src.len) : (i += 1) {
            const c = src[i];
            if (q) {
                if (c == '\'') q = false;
                continue;
            }
            if (c == '\'') {
                q = true;
                continue;
            }
            if (c == '(') {
                depth += 1;
                continue;
            }
            if (c == ')') {
                if (depth > 0) depth -= 1;
                continue;
            }
            if (depth != 0) continue;
            if (i > start_i and (i == 0 or (!std.ascii.isAlphanumeric(src[i - 1]) and src[i - 1] != '_')) and src.len - i >= 6 and
                std.ascii.eqlIgnoreCase(src[i .. i + 6], "create"))
            {
                const chunk = std.mem.trim(u8, src[start_i..i], " \t\r\n;");
                if (chunk.len > 0) out.append(alloc, chunk) catch {};
                start_i = i;
            }
        }
        const tail = std.mem.trim(u8, src[start_i..], " \t\r\n;");
        if (tail.len > 0) out.append(alloc, tail) catch {};
    }
    fn resolveSchemaTable(self: *Engine, bare: []const u8, schema: []const u8, alloc: std.mem.Allocator) ?[]const u8 {
        if (std.mem.indexOfScalar(u8, bare, '.') != null) return bare;
        const own = std.fmt.allocPrint(alloc, "{s}.{s}", .{ schema, bare }) catch return null;
        if (self.find(own) != null) return own;
        var it = std.mem.splitScalar(u8, self.search_path, ',');
        while (it.next()) |part| {
            const sn = std.mem.trim(u8, part, " ");
            if (sn.len == 0) continue;
            const full = std.fmt.allocPrint(alloc, "{s}.{s}", .{ sn, bare }) catch continue;
            if (self.find(full) != null) return full;
        }
        return null;
    }
    fn rewriteViewFrom(self: *Engine, alloc: std.mem.Allocator, text: []const u8, schema: []const u8) []const u8 {
        if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] rewrite schema={s} text={s}\n", .{ schema, text });
        var out = std.ArrayList(u8).empty;
        var i: usize = 0;
        while (i < text.len) {
            if (i + 4 <= text.len and std.ascii.eqlIgnoreCase(text[i .. i + 4], "from") and (i == 0 or !std.ascii.isAlphanumeric(text[i - 1])) and
                (i + 4 == text.len or !std.ascii.isAlphanumeric(text[i + 4])))
            {
                out.appendSlice(alloc, text[i .. i + 4]) catch {};
                i += 4;
                while (i < text.len and (text[i] == ' ' or text[i] == '\t' or text[i] == '\n' or text[i] == '\r')) {
                    out.append(alloc, text[i]) catch {};
                    i += 1;
                }
                const ns = i;
                while (i < text.len and (std.ascii.isAlphanumeric(text[i]) or text[i] == '_')) i += 1;
                if (i > ns) {
                    const bare = text[ns..i];
                    if (std.ascii.eqlIgnoreCase(bare, "only") or std.ascii.eqlIgnoreCase(bare, "select")) {
                        out.appendSlice(alloc, bare) catch {};
                    } else if (self.resolveSchemaTable(bare, schema, alloc)) |full| {
                        if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] resolved {s} -> {s}\n", .{ bare, full });
                        out.appendSlice(alloc, full) catch {};
                    } else out.appendSlice(alloc, bare) catch {};
                }
                continue;
            }
            out.append(alloc, text[i]) catch {};
            i += 1;
        }
        return out.toOwnedSlice(alloc) catch text;
    }
    fn execCreateSchema(self: *Engine, alloc: std.mem.Allocator, name: ?[]const u8, auth: ?[]const u8, element: ?*sql.Stmt, if_not_exists: bool, raw_elements: []const u8) EngineError!Result {
        var sname: []const u8 = "";
        if (auth) |a| {
            if (!std.ascii.eqlIgnoreCase(a, "CURRENT_ROLE") and !self.canSetRole(a)) {
                setDiag("must be able to SET ROLE \"{s}\"", .{a});
                return error.RawDdlError;
            }
        }
        if (name) |n| {
            sname = n;
        } else if (auth) |a| {
            if (std.ascii.eqlIgnoreCase(a, "CURRENT_ROLE")) {
                sname = if (self.role_len > 0) self.role_buf[0..self.role_len] else "zhdb";
            } else {
                sname = a;
                if (!self.canSetRole(a)) {
                    setDiag("must be able to SET ROLE \"{s}\"", .{a});
                    return error.RawDdlError;
                }
            }
        } else return error.SyntaxError;
        var elems = std.ArrayList([]const u8).empty;
        defer elems.deinit(alloc);
        if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] raw<{s}>\n", .{raw_elements});
        if (raw_elements.len > 0) splitSchemaElements(raw_elements, &elems, alloc);
        if (std.c.getenv("ZHDB_NS_DEBUG") != null) {
            std.debug.print("[ns] elems={d}\n", .{elems.items.len});
            for (elems.items) |et| std.debug.print("[ns] elem<{s}>\n", .{et});
        }
        if (elems.items.len == 0 and element != null) elems.append(alloc, self.srcForSchemaElement(element.?)) catch {};
        for (elems.items) |etxt| {
            const prefix = qualifiedPrefix(etxt);
            var nm: []const u8 = "";
            const ps = sql.parseStatementText(alloc, etxt) catch null;
            if (ps) |st| switch (st) {
                .create_table => |ct| nm = ct.name,
                .create_view => |cv| nm = cv.name,
                .create_index => |ci| nm = ci.table,
                else => {},
            };
            if (nm.len == 0) {
                if (prefix) |pfx| {
                    if (!std.ascii.eqlIgnoreCase(pfx, sname)) {
                        setDiag("CREATE specifies a schema ({s}) different from the one being created ({s})", .{ pfx, sname });
                        return error.RawDdlError;
                    }
                }
                continue;
            }
            var epfx: ?[]const u8 = null;
            if (std.mem.indexOfScalar(u8, nm, '.')) |d| epfx = nm[0..d] else if (prefix) |p| epfx = p;
            if (epfx) |pfx| {
                if (!std.ascii.eqlIgnoreCase(pfx, sname)) {
                    setDiag("CREATE specifies a schema ({s}) different from the one being created ({s})", .{ pfx, sname });
                    return error.RawDdlError;
                }
            }
        }
        var exists = false;
        var existing_oid: i64 = 0;
        if (self.find("pg_namespace")) |pn| {
            if (findCol(pn, "nspname")) |cn| {
                const co = findCol(pn, "oid");
                for (pn.rows.items, 0..) |row, ri| {
                    if (isRowDeleted(pn, ri)) continue;
                    if (cn < row.len and row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, sname)) {
                        exists = true;
                        if (co) |coi| if (coi < row.len and row[coi] == .int) {
                            existing_oid = row[coi].int;
                        };
                    }
                }
            }
        }
        if (exists) {
            if (if_not_exists) {
                if (elems.items.len > 0) {
                    setDiag("CREATE SCHEMA IF NOT EXISTS cannot include schema elements", .{});
                    return error.RawDdlError;
                }
                pushNotice("schema \"{s}\" already exists, skipping", .{sname});
                return .{};
            }
            setDiag("schema \"{s}\" already exists", .{sname});
            return error.RawDdlError;
        }
        const oid = 17000 + @as(i64, @intCast(self.schema_oids.count()));
        const skey = self.gpa.dupe(u8, sname) catch return error.OutOfMemory;
        self.schema_oids.put(skey, oid) catch {};
        if (auth) |a| {
            if (!std.ascii.eqlIgnoreCase(a, "CURRENT_ROLE")) self.setOwnerRole("schema", sname, a) else self.setOwner("schema", sname);
        } else self.setOwner("schema", sname);
        if (self.find("pg_namespace")) |pn| {
            if (findCol(pn, "nspname")) |cn| {
                const row = self.gpa.alloc(Value, pn.cols.len) catch return error.OutOfMemory;
                for (row) |*c| c.* = .null;
                if (findCol(pn, "oid")) |co| row[co] = .{ .int = oid };
                row[cn] = .{ .text = self.gpa.dupe(u8, sname) catch return error.OutOfMemory };
                pn.rows.append(self.gpa, row) catch return error.OutOfMemory;
            }
        }
        var created_tables = std.ArrayList([]const u8).empty;
        defer created_tables.deinit(self.gpa);
        var created_views = std.ArrayList([]const u8).empty;
        defer created_views.deinit(self.gpa);
        var made_tables = std.ArrayList([]const u8).empty;
        defer made_tables.deinit(alloc);
        var parsed = std.ArrayList(*sql.Stmt).empty;
        defer parsed.deinit(alloc);
        for (elems.items) |etxt| {
            const st = sql.parseStatementText(alloc, etxt) catch null;
            if (st) |sv| {
                const pst = alloc.create(sql.Stmt) catch continue;
                pst.* = sv;
                parsed.append(alloc, pst) catch {};
            }
        }
        for (parsed.items) |pst| {
            switch (pst.*) {
                .create_table => |ct0| {
                    var ct = ct0;
                    if (std.mem.indexOfScalar(u8, ct.name, '.') == null) ct.name = std.fmt.allocPrint(alloc, "{s}.{s}", .{ sname, ct.name }) catch return error.OutOfMemory;
                    _ = self.execCreate(alloc, ct) catch |e| {
                        self.cleanupSchema(sname, &created_tables, &created_views);
                        return e;
                    };
                    created_tables.append(self.gpa, ct.name) catch {};
                    made_tables.append(alloc, ct.name) catch {};
                },
                else => {},
            }
        }
        for (parsed.items) |pst| {
            if (pst.* != .create_view) continue;
            const cv0 = pst.create_view;
            var full = cv0.name;
            if (std.mem.indexOfScalar(u8, full, '.') == null) full = std.fmt.allocPrint(alloc, "{s}.{s}", .{ sname, cv0.name }) catch return error.OutOfMemory;
            const body = self.rewriteViewFrom(alloc, cv0.select_text, sname);
            const vsel = sql.parseSelectText(alloc, body) catch null;
            if (vsel) |vs| {
                _ = self.execCreateView(alloc, full, body, vs, false) catch |e| {
                    self.cleanupSchema(sname, &created_tables, &created_views);
                    return e;
                };
            } else {
                _ = self.execCreateView(alloc, full, body, cv0.select, cv0.invoker) catch |e| {
                    self.cleanupSchema(sname, &created_tables, &created_views);
                    return e;
                };
            }
            created_views.append(self.gpa, full) catch {};
        }
        for (parsed.items) |pst| {
            if (pst.* != .create_index) continue;
            const ci = pst.create_index;
            var tbl = ci.table;
            if (std.mem.indexOfScalar(u8, tbl, '.') == null) tbl = std.fmt.allocPrint(alloc, "{s}.{s}", .{ sname, tbl }) catch return error.OutOfMemory;
            if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] index {s} on {s}\n", .{ ci.name, tbl });
            _ = self.execCreateIndex(ci.name, tbl, ci.col, ci.unique, ci.fillfactor, ci.expr_func) catch |e| {
                if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] index failed: {s}\n", .{@errorName(e)});
            };
        }
        for (parsed.items) |pst| {
            switch (pst.*) {
                .create_table => |ct| {
                    const bare = if (std.mem.lastIndexOfScalar(u8, ct.name, '.')) |d| ct.name[d + 1 ..] else ct.name;
                    self.addSchemaObj(sname, bare, .table);
                    var i: usize = 0;
                    for (ct.cols) |cd| {
                        if (cd.serial) {
                            const sn = std.fmt.allocPrint(alloc, "{s}_{s}_seq", .{ bare, cd.name }) catch "seq";
                            self.addSchemaObj(sname, sn, .sequence);
                        }
                        i += 1;
                    }
                },
                .create_view => |cv| {
                    const bare = if (std.mem.lastIndexOfScalar(u8, cv.name, '.')) |d| cv.name[d + 1 ..] else cv.name;
                    self.addSchemaObj(sname, bare, .view);
                },
                .create_index => |ci| self.addSchemaObj(sname, ci.name, .index),
                else => {},
            }
        }
        for (elems.items) |etxt| {
            var lowbuf: [512]u8 = undefined;
            const n = @min(etxt.len, lowbuf.len);
            const low = std.ascii.lowerString(lowbuf[0..n], etxt[0..n]);
            if (std.mem.indexOf(u8, low, "unique") != null and std.mem.indexOf(u8, low, "index") == null and std.mem.indexOf(u8, low, "create table") != null) {
                const tblname = parsedTableName(parsed.items, sname, alloc) orelse "t";
                const bare = if (std.mem.lastIndexOfScalar(u8, tblname, '.')) |d| tblname[d + 1 ..] else tblname;
                const uq = std.fmt.allocPrint(alloc, "{s}_key", .{bare}) catch "key";
                self.addSchemaObj(sname, uq, .index);
            }
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn srcForSchemaElement(self: *Engine, el: *sql.Stmt) []const u8 {
        _ = self;
        _ = el;
        return "";
    }
    fn parsedTableName(items: []*sql.Stmt, sname: []const u8, alloc: std.mem.Allocator) ?[]const u8 {
        for (items) |p| {
            if (p.* == .create_table) {
                const n = p.create_table.name;
                if (std.mem.indexOfScalar(u8, n, '.') != null) return n;
                return std.fmt.allocPrint(alloc, "{s}.{s}", .{ sname, n }) catch null;
            }
        }
        return null;
    }
    fn addSchemaObj(self: *Engine, schema: []const u8, name: []const u8, kind: anytype) void {
        const sk = self.gpa.dupe(u8, schema) catch return;
        const full = std.fmt.allocPrint(self.gpa, "{s}.{s}", .{ schema, name }) catch name;
        const nk = self.gpa.dupe(u8, full) catch {
            self.gpa.free(sk);
            return;
        };
        self.schema_objects.append(self.gpa, .{ .schema = sk, .name = nk, .kind = kind }) catch {
            self.gpa.free(sk);
            self.gpa.free(nk);
        };
    }
    fn cleanupSchema(self: *Engine, sname: []const u8, tables: *std.ArrayList([]const u8), views: *std.ArrayList([]const u8)) void {
        for (tables.items) |full| _ = self.execDropName(full, true) catch {};
        for (views.items) |full| _ = self.execDropView(&.{full}, true) catch {};
        if (self.find("pg_namespace")) |pn| {
            if (findCol(pn, "nspname")) |cn| {
                var i: usize = 0;
                while (i < pn.rows.items.len) : (i += 1) {
                    const row = pn.rows.items[i];
                    if (cn < row.len and row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, sname)) {
                        self.gpa.free(row[cn].text);
                        self.gpa.free(row);
                        _ = pn.rows.orderedRemove(i);
                        break;
                    }
                }
            }
        }
        if (self.schema_oids.fetchRemove(sname)) |kv| self.gpa.free(kv.key);
        var i: usize = 0;
        while (i < self.schema_objects.items.len) {
            const o = self.schema_objects.items[i];
            if (std.ascii.eqlIgnoreCase(o.schema, sname)) {
                self.gpa.free(o.schema);
                self.gpa.free(o.name);
                _ = self.schema_objects.orderedRemove(i);
            } else i += 1;
        }
        self.invalidateCatalogs();
    }
    fn objKind(self: *Engine, full: []const u8) []const u8 {
        var nb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(nb[0..@min(full.len, nb.len)], full[0..@min(full.len, nb.len)]);
        if (self.matviews.contains(nl)) return "materialized view";
        return "table";
    }
    fn execDropSchema(self: *Engine, names: []const []const u8, if_exists: bool, cascade: bool) EngineError!Result {
        _ = cascade;
        for (names) |sname| {
            var found = std.ArrayList([]const u8).empty;
            defer {
                for (found.items) |x| self.gpa.free(x);
                found.deinit(self.gpa);
            }
            var it = self.tables.iterator();
            while (it.next()) |e| {
                const full = e.key_ptr.*;
                if (full.len <= sname.len) continue;
                if (full[sname.len] != '.') continue;
                if (!std.ascii.eqlIgnoreCase(full[0..sname.len], sname)) continue;
                found.append(self.gpa, self.gpa.dupe(u8, full) catch continue) catch {};
            }
            var ns_exists = false;
            if (self.find("pg_namespace")) |pn| {
                if (findCol(pn, "nspname")) |cn| {
                    for (pn.rows.items, 0..) |row, ri| {
                        if (isRowDeleted(pn, ri)) continue;
                        if (cn < row.len and row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, sname)) ns_exists = true;
                    }
                }
            }
            var si2: usize = 1;
            while (si2 < found.items.len) : (si2 += 1) {
                const key = found.items[si2];
                var j2 = si2;
                while (j2 > 0 and self.tableSeq(found.items[j2 - 1]) > self.tableSeq(key)) : (j2 -= 1) found.items[j2] = found.items[j2 - 1];
                found.items[j2] = key;
            }
            if (!ns_exists and found.items.len == 0 and !if_exists) {
                setDiag("schema \"{s}\" does not exist", .{sname});
                return error.TableNotFound;
            }
            for (found.items) |full| {
                _ = try self.execDropName(full, true);
            }
            var vnames = std.ArrayList([]const u8).empty;
            defer {
                for (vnames.items) |x| self.gpa.free(x);
                vnames.deinit(self.gpa);
            }
            var vit = self.views.keyIterator();
            while (vit.next()) |k| {
                if (k.*.len > sname.len and k.*[sname.len] == '.' and std.ascii.eqlIgnoreCase(k.*[0..sname.len], sname)) vnames.append(self.gpa, self.gpa.dupe(u8, k.*) catch continue) catch {};
            }
            for (vnames.items) |vn| _ = try self.execDropView(&.{vn}, true);
            var fdisps = std.ArrayList([]const u8).empty;
            defer fdisps.deinit(self.gpa);
            for (self.schema_funcs.items) |f| {
                if (std.ascii.eqlIgnoreCase(f.schema, sname)) fdisps.append(self.gpa, f.display) catch {};
            }
            const total = fdisps.items.len + found.items.len + vnames.items.len;
            if (std.c.getenv("ZHDB_NS_DEBUG") != null) std.debug.print("[ns] drop {s} ns={} found={d} views={d} funcs={d}\n", .{ sname, ns_exists, found.items.len, vnames.items.len, fdisps.items.len });
            if (total > 0) {
                const visible = self.role_len > 0 and std.ascii.eqlIgnoreCase(self.role_buf[0..self.role_len], sname);
                if (total == 1) {
                    if (fdisps.items.len == 1) pushNotice("drop cascades to function {s}", .{fdisps.items[0]}) else if (found.items.len == 1) {
                        const full = found.items[0];
                        const disp = if (visible) full[sname.len + 1 ..] else full;
                        pushNotice("drop cascades to {s} {s}", .{ self.objKind(full), disp });
                    } else {
                        const full = vnames.items[0];
                        const disp = if (visible) full[sname.len + 1 ..] else full;
                        pushNotice("drop cascades to view {s}", .{disp});
                    }
                } else {
                    var det = std.ArrayList(u8).empty;
                    defer det.deinit(self.gpa);
                    var firstd = true;
                    const addD = struct {
                        fn f(buf: *std.ArrayList(u8), al: std.mem.Allocator, first: *bool, line: []const u8) void {
                            if (!first.*) buf.append(al, '\n') catch {};
                            first.* = false;
                            buf.appendSlice(al, line) catch {};
                        }
                    }.f;
                    for (fdisps.items) |fd| {
                        const line = std.fmt.allocPrint(self.gpa, "drop cascades to function {s}", .{fd}) catch "";
                        addD(&det, self.gpa, &firstd, line);
                    }
                    for (found.items) |full| {
                        if (std.mem.eql(u8, self.objKind(full), "materialized view")) continue;
                        const disp = if (visible) full[sname.len + 1 ..] else full;
                        const line = std.fmt.allocPrint(self.gpa, "drop cascades to {s} {s}", .{ self.objKind(full), disp }) catch "";
                        addD(&det, self.gpa, &firstd, line);
                    }
                    for (found.items) |full| {
                        if (!std.mem.eql(u8, self.objKind(full), "materialized view")) continue;
                        const disp = if (visible) full[sname.len + 1 ..] else full;
                        const line = std.fmt.allocPrint(self.gpa, "drop cascades to {s} {s}", .{ self.objKind(full), disp }) catch "";
                        addD(&det, self.gpa, &firstd, line);
                    }
                    for (vnames.items) |full| {
                        const disp = if (visible) full[sname.len + 1 ..] else full;
                        const line = std.fmt.allocPrint(self.gpa, "drop cascades to view {s}", .{disp}) catch "";
                        addD(&det, self.gpa, &firstd, line);
                    }
                    pushNotice("drop cascades to {d} other objects", .{total});
                    pushNoticeDetail("", det.items);
                }
            }
            if (self.find("pg_namespace")) |pn| {
                if (findCol(pn, "nspname")) |cn| {
                    var ri: usize = 0;
                    while (ri < pn.rows.items.len) : (ri += 1) {
                        const row = pn.rows.items[ri];
                        if (cn < row.len and row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, sname)) {
                            self.gpa.free(row[cn].text);
                            self.gpa.free(row);
                            _ = pn.rows.orderedRemove(ri);
                            break;
                        }
                    }
                    self.invalidateCatalogs();
                }
            }
            if (self.schema_oids.fetchRemove(sname)) |kv| self.gpa.free(kv.key);
            self.clearOwner("schema", sname);
            var oi: usize = 0;
            while (oi < self.schema_objects.items.len) {
                const o = self.schema_objects.items[oi];
                if (std.ascii.eqlIgnoreCase(o.schema, sname)) {
                    self.gpa.free(o.schema);
                    self.gpa.free(o.name);
                    _ = self.schema_objects.orderedRemove(oi);
                } else oi += 1;
            }
            var fi: usize = 0;
            while (fi < self.schema_funcs.items.len) {
                const f = self.schema_funcs.items[fi];
                if (std.ascii.eqlIgnoreCase(f.schema, sname)) {
                    self.gpa.free(f.schema);
                    self.gpa.free(f.display);
                    _ = self.schema_funcs.orderedRemove(fi);
                } else fi += 1;
            }
        }
        return .{};
    }
    fn firstUnknownCol(e: *sql.Expr, cols: []Column) ?[]const u8 {
        return switch (e.*) {
            .column => |n| if (findColSlice(cols, n) == null) n else null,
            .column_idx => null,
            .binary => |b| firstUnknownCol(b.lhs, cols) orelse firstUnknownCol(b.rhs, cols),
            .negate => |x| firstUnknownCol(x, cols),
            .not => |x| firstUnknownCol(x, cols),
            .is_null => |x| firstUnknownCol(x.operand, cols),
            .cast => |c| firstUnknownCol(c.operand, cols),
            .call => |c| blk: {
                for (c.args) |a| if (firstUnknownCol(a, cols)) |u| break :blk u;
                break :blk null;
            },
            .field => |x| firstUnknownCol(x.base, cols),
            .at_local => |x| firstUnknownCol(x.operand, cols),
            .at_zone => |x| firstUnknownCol(x.operand, cols) orelse firstUnknownCol(x.zone, cols),
            .between => |x| firstUnknownCol(x.operand, cols) orelse firstUnknownCol(x.low, cols) orelse firstUnknownCol(x.high, cols),
            else => null,
        };
    }
    fn validateViewSelect(self: *Engine, sel: *sql.Select) EngineError!void {
        if (sel.join != null or sel.more_joins.len > 0 or sel.extra_from.len > 0) return;
        var cols: []Column = &.{};
        if (sel.from) |f| switch (f) {
            .table => |tn| {
                const rtn = self.resolveTableName(tn);
                if (self.views.get(rtn) != null) return;
                self.ensureRowsMaterialized(rtn);
                if (self.find(rtn)) |t| cols = t.cols else {
                    setDiag("relation \"{s}\" does not exist", .{tn});
                    return error.TableNotFound;
                }
            },
            else => {},
        };
        if (cols.len == 0) return;
        for (sel.items) |it| {
            if (it.expr.* == .star or it.expr.* == .star_table) continue;
            if (it.expr.* == .column and std.ascii.eqlIgnoreCase(it.expr.column, "ctid")) continue;
            if (it.expr.* == .column_idx and std.ascii.eqlIgnoreCase(it.expr.column_idx.name, "ctid")) continue;
            if (firstUnknownCol(it.expr, cols)) |u| {
                const base = if (std.mem.lastIndexOfScalar(u8, u, '.')) |d| u[d + 1 ..] else u;
                setDiag("column \"{s}\" does not exist", .{base});
                return error.UnknownColumn;
            }
        }
        if (sel.where) |w| if (firstUnknownCol(w, cols)) |u| {
            const base = if (std.mem.lastIndexOfScalar(u8, u, '.')) |d| u[d + 1 ..] else u;
            setDiag("column \"{s}\" does not exist", .{base});
            return error.UnknownColumn;
        };
    }
    fn execCreateView(self: *Engine, alloc: std.mem.Allocator, name: []const u8, select_text: []const u8, sel: *sql.Select, invoker: bool) EngineError!Result {
        self.rewriteAliases(alloc, sel);
        try self.checkGroupSemantics(alloc, sel);
        if (sel.into_table != null) {
            setDiag("views must not contain SELECT INTO", .{});
            return error.RawDdlError;
        }
        try self.validateViewSelect(sel);
        if (ciIndex(select_text, "group by") != null) self.recordViewPkDeps(name, sel);
        const dep = try self.deparseViewSelect(alloc, sel);
        const key = self.gpa.dupe(u8, name) catch return error.OutOfMemory;
        const st = self.gpa.dupe(u8, select_text) catch return error.OutOfMemory;
        const dp = self.gpa.dupe(u8, dep) catch return error.OutOfMemory;
        if (self.views.fetchRemove(name)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value.select_text);
            self.gpa.free(old.value.deparse);
        }
        var ctid_kind: u8 = 0;
        var ctid_src: []const u8 = "";
        for (sel.items) |it| {
            const nm = if (it.alias) |al| al else exprName(it.expr);
            if (!std.ascii.eqlIgnoreCase(nm, "ctid")) continue;
            if (it.expr.* == .column and (std.ascii.eqlIgnoreCase(it.expr.column, "ctid") or std.mem.endsWith(u8, it.expr.column, ".ctid"))) {
                ctid_kind = 1;
                if (sel.from) |f| if (f == .table) {
                    ctid_src = try self.gpa.dupe(u8, self.resolveTableName(f.table));
                };
            } else ctid_kind = 2;
        }
        self.views.put(key, .{ .select_text = st, .deparse = dp, .ctid_kind = ctid_kind, .ctid_source = ctid_src, .invoker = invoker }) catch return error.OutOfMemory;
        self.setOwner("table", name);
        if (self.inTxn()) {
            const cname = self.gpa.dupe(u8, name) catch return error.OutOfMemory;
            self.txnCtx().created_views.append(self.gpa, cname) catch self.gpa.free(cname);
        }
        return .{};
    }
    fn execDropView(self: *Engine, names: []const []const u8, if_exists: bool) EngineError!Result {
        for (names) |nm0| {
            const nm = self.resolveTableName(nm0);
            if (self.views.contains(nm) and !self.isOwnerRole("table", nm)) {
                setDiag("must be owner of view {s}", .{stripSchema(nm)});
                return error.RawDdlError;
            }
            var ki: usize = 0;
            while (ki < self.view_pk_deps.items.len) {
                const d = self.view_pk_deps.items[ki];
                if (std.ascii.eqlIgnoreCase(d.view, nm)) {
                    self.gpa.free(d.view);
                    self.gpa.free(d.table);
                    self.gpa.free(d.conname);
                    _ = self.view_pk_deps.orderedRemove(ki);
                } else ki += 1;
            }
            if (self.views.fetchRemove(nm)) |kv| {
                self.gpa.free(kv.key);
                self.gpa.free(kv.value.select_text);
                self.gpa.free(kv.value.deparse);
            } else if (!if_exists) {
                setDiag("view \"{s}\" does not exist", .{nm});
                return error.TableNotFound;
            }
        }
        return .{};
    }
    fn deparseViewExpr(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, in_call: bool) EngineError![]const u8 {
        switch (e.*) {
            .column => |n| return std.fmt.allocPrint(alloc, "{s}", .{n}) catch error.OutOfMemory,
            .column_idx => |c| return std.fmt.allocPrint(alloc, "{s}", .{c.name}) catch error.OutOfMemory,
            .int => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .string => |t| {
                if (in_call) return std.fmt.allocPrint(alloc, "'{s}'::text", .{t}) catch error.OutOfMemory;
                return std.fmt.allocPrint(alloc, "'{s}'", .{t}) catch error.OutOfMemory;
            },
            .call => |c| {
                var b = std.ArrayList(u8).empty;
                try b.appendSlice(alloc, c.name);
                try b.append(alloc, '(');
                for (c.args, 0..) |a, i| {
                    if (i > 0) try b.appendSlice(alloc, ", ");
                    try b.appendSlice(alloc, try self.deparseViewExpr(alloc, a, true));
                }
                try b.append(alloc, ')');
                return b.toOwnedSlice(alloc);
            },
            .cast => |c| {
                if (std.ascii.eqlIgnoreCase(c.type_name, "interval")) {
                    if (c.operand.* == .string) {
                        switch (parseIntervalSecs(c.operand.string)) {
                            .secs => |v| if (v == 0) return "'@ 0'::interval",
                            else => {},
                        }
                    }
                    const inner = try self.deparseViewExpr(alloc, c.operand, false);
                    return std.fmt.allocPrint(alloc, "{s}::interval", .{inner}) catch error.OutOfMemory;
                }
                const inner = try self.deparseViewExpr(alloc, c.operand, false);
                var tb: [64]u8 = undefined;
                const low = std.ascii.lowerString(tb[0..@min(c.type_name.len, tb.len)], c.type_name[0..@min(c.type_name.len, tb.len)]);
                return std.fmt.allocPrint(alloc, "{s}::{s}", .{ inner, low }) catch error.OutOfMemory;
            },
            .at_local => |x| {
                const inner = try self.deparseViewExpr(alloc, x.operand, false);
                return std.fmt.allocPrint(alloc, "({s} AT LOCAL)", .{inner}) catch error.OutOfMemory;
            },
            .at_zone => |x| {
                const lhs = try self.deparseViewExpr(alloc, x.operand, false);
                const z = try self.deparseViewExpr(alloc, x.zone, false);
                return std.fmt.allocPrint(alloc, "({s} AT TIME ZONE {s})", .{ lhs, z }) catch error.OutOfMemory;
            },
            .negate => |x| {
                const inner = try self.deparseViewExpr(alloc, x, false);
                return std.fmt.allocPrint(alloc, "-{s}", .{inner}) catch error.OutOfMemory;
            },
            .binary => |b| {
                const l = try self.deparseViewExpr(alloc, b.lhs, false);
                const r = try self.deparseViewExpr(alloc, b.rhs, false);
                const op: []const u8 = switch (b.op) {
                    .concat => "||",
                    .eq => "=",
                    .neq => "<>",
                    .lt => "<",
                    .gt => ">",
                    .le => "<=",
                    .ge => ">=",
                    .add => "+",
                    .sub => "-",
                    .mul => "*",
                    .div => "/",
                    else => "?",
                };
                return std.fmt.allocPrint(alloc, "({s} {s} {s})", .{ l, op, r }) catch error.OutOfMemory;
            },
            else => return "?",
        }
    }
    fn deparseViewSelect(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError![]const u8 {
        var b = std.ArrayList(u8).empty;
        try b.appendSlice(alloc, " SELECT ");
        for (sel.items, 0..) |it, i| {
            if (i > 0) try b.appendSlice(alloc, ",\n    ");
            try b.appendSlice(alloc, try self.deparseViewExpr(alloc, it.expr, false));
            if (it.alias) |al| try b.appendSlice(alloc, try std.fmt.allocPrint(alloc, " AS {s}", .{al}));
        }
        if (sel.from) |f| {
            switch (f) {
                .table => |tn| {
                    var tb: [128]u8 = undefined;
                    const low = std.ascii.lowerString(tb[0..@min(tn.len, tb.len)], tn[0..@min(tn.len, tb.len)]);
                    try b.appendSlice(alloc, "\n   FROM ");
                    try b.appendSlice(alloc, low);
                },
                else => {},
            }
        }
        if (sel.order_by.len > 0) {
            try b.appendSlice(alloc, "\n  ORDER BY ");
            for (sel.order_by, 0..) |o, i| {
                if (i > 0) try b.appendSlice(alloc, ", ");
                try b.appendSlice(alloc, try self.deparseViewExpr(alloc, o.expr, false));
            }
        }
        try b.append(alloc, ';');
        return b.toOwnedSlice(alloc);
    }
    fn collectRelCols(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, out: *std.ArrayList([]const u8)) EngineError!void {
        const addTable = struct {
            fn f(e: *Engine, al: std.mem.Allocator, tn: []const u8, o: *std.ArrayList([]const u8)) void {
                const t = e.find(tn) orelse return;
                for (t.cols) |c| o.append(al, c.name) catch {};
            }
        }.f;
        if (sel.from) |f| {
            switch (f) {
                .table => |tn| addTable(self, alloc, tn, out),
                .subquery => {},
                .function => {},
                .values => {},
            }
        }
        for (sel.extra_from) |it| {
            switch (it.from) {
                .table => |tn| addTable(self, alloc, tn, out),
                else => {},
            }
        }
        if (sel.join) |j| addTable(self, alloc, j.table, out);
        for (sel.more_joins) |j| addTable(self, alloc, j.table, out);
    }
    fn ambiguousInExpr(e: *sql.Expr, rel_cols: []const []const u8) ?[]const u8 {
        switch (e.*) {
            .column => |n| {
                if (std.mem.indexOfScalar(u8, n, '.') != null) return null;
                var count: usize = 0;
                for (rel_cols) |c| if (std.ascii.eqlIgnoreCase(c, n)) {
                    count += 1;
                };
                if (count > 1) return n;
                return null;
            },
            .binary => |b| return ambiguousInExpr(b.lhs, rel_cols) orelse ambiguousInExpr(b.rhs, rel_cols),
            .negate => |x| return ambiguousInExpr(x, rel_cols),
            .not => |x| return ambiguousInExpr(x, rel_cols),
            .bitnot => |x| return ambiguousInExpr(x, rel_cols),
            .is_null => |x| return ambiguousInExpr(x.operand, rel_cols),
            .like => |x| return ambiguousInExpr(x.operand, rel_cols) orelse ambiguousInExpr(x.pattern, rel_cols),
            .cast => |c| return ambiguousInExpr(c.operand, rel_cols),
            .call => |c| {
                for (c.args) |a| if (ambiguousInExpr(a, rel_cols)) |x| return x;
                return null;
            },
            .at_local => |x| return ambiguousInExpr(x.operand, rel_cols),
            .at_zone => |x| return ambiguousInExpr(x.operand, rel_cols) orelse ambiguousInExpr(x.zone, rel_cols),
            .between => |x| return ambiguousInExpr(x.operand, rel_cols) orelse ambiguousInExpr(x.low, rel_cols) orelse ambiguousInExpr(x.high, rel_cols),
            else => return null,
        }
    }
    fn groupKeyCovers(g: *sql.Expr, ref: []const u8) bool {
        const base = blk: {
            if (std.mem.lastIndexOfScalar(u8, ref, '.')) |d| break :blk ref[d + 1 ..];
            break :blk ref;
        };
        switch (g.*) {
            .column => |n| {
                const gb = if (std.mem.lastIndexOfScalar(u8, n, '.')) |d| n[d + 1 ..] else n;
                return std.ascii.eqlIgnoreCase(gb, base);
            },
            else => return false,
        }
    }
    fn checkGroupSemantics(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!void {
        for (sel.group_by) |g| {
            if (g.* == .int) {
                const n = g.int;
                if (n < 1 or n > @as(i64, @intCast(sel.items.len))) {
                    setDiag("GROUP BY position {d} is not in select list", .{n});
                    return error.UngroupedColumn;
                }
            }
        }
        var rels: usize = 0;
        if (sel.from) |f| if (f == .table) {
            rels += 1;
        };
        for (sel.extra_from) |it| if (it.from == .table) {
            rels += 1;
        };
        if (sel.join) |_| rels += 1;
        rels += sel.more_joins.len;
        if (rels > 1) {
            var rel_cols = std.ArrayList([]const u8).empty;
            defer rel_cols.deinit(alloc);
            try self.collectRelCols(alloc, sel, &rel_cols);
            for (sel.items) |it| {
                if (ambiguousInExpr(it.expr, rel_cols.items)) |nm| {
                    if (!isUsingColumn(sel, nm)) {
                        setDiag("column reference \"{s}\" is ambiguous", .{nm});
                        return error.UngroupedColumn;
                    }
                }
            }
            if (sel.where) |w| if (ambiguousInExpr(w, rel_cols.items)) |nm| {
                if (!isUsingColumn(sel, nm)) {
                    setDiag("column reference \"{s}\" is ambiguous", .{nm});
                    return error.UngroupedColumn;
                }
            };
            if (sel.having) |h| if (ambiguousInExpr(h, rel_cols.items)) |nm| {
                if (!isUsingColumn(sel, nm)) {
                    setDiag("column reference \"{s}\" is ambiguous", .{nm});
                    return error.UngroupedColumn;
                }
            };
            for (sel.group_by) |g| if (ambiguousInExpr(g, rel_cols.items)) |nm| {
                if (!isUsingColumn(sel, nm)) {
                    setDiag("column reference \"{s}\" is ambiguous", .{nm});
                    return error.UngroupedColumn;
                }
            };
            for (sel.order_by) |o| if (ambiguousInExpr(o.expr, rel_cols.items)) |nm| {
                setDiag("column reference \"{s}\" is ambiguous", .{nm});
                return error.UngroupedColumn;
            };
        }
        if (sel.group_by.len > 0) {
            var gbases = std.StringHashMap(void).init(alloc);
            defer gbases.deinit();
            for (sel.group_by) |g| {
                if (g.* != .column) continue;
                const base = if (std.mem.lastIndexOfScalar(u8, g.column, '.')) |d| g.column[d + 1 ..] else g.column;
                gbases.put(base, {}) catch {};
            }
            var tcover = std.StringHashMap(void).init(alloc);
            defer tcover.deinit();
            var refs = std.ArrayList(struct { t: []const u8, al: ?[]const u8 }).empty;
            defer refs.deinit(alloc);
            if (sel.from) |f| if (f == .table) refs.append(alloc, .{ .t = f.table, .al = sel.alias }) catch {};
            for (sel.extra_from) |it| if (it.from == .table) refs.append(alloc, .{ .t = it.from.table, .al = it.alias }) catch {};
            if (sel.join) |j| {
                refs.append(alloc, .{ .t = j.table, .al = j.alias }) catch {};
                for (sel.more_joins) |mj| refs.append(alloc, .{ .t = mj.table, .al = mj.alias }) catch {};
            }
            for (refs.items) |r| {
                var tb: [256]u8 = undefined;
                const tl = std.ascii.lowerString(tb[0..@min(r.t.len, tb.len)], r.t[0..@min(r.t.len, tb.len)]);
                const pk = self.table_pks.get(tl) orelse continue;
                var all = true;
                for (pk.cols) |c| if (!gbases.contains(c)) {
                    all = false;
                };
                if (!all) continue;
                tcover.put(tl, {}) catch {};
                if (r.al) |al| {
                    var ab: [256]u8 = undefined;
                    const alow = std.ascii.lowerString(ab[0..@min(al.len, ab.len)], al[0..@min(al.len, ab.len)]);
                    tcover.put(alow, {}) catch {};
                }
            }
            var fdlist = std.ArrayList(Column).empty;
            defer fdlist.deinit(alloc);
            for (refs.items) |r| {
                const t = self.find(r.t) orelse continue;
                for (t.cols) |c0| {
                    var c = c0;
                    c.source = r.al orelse r.t;
                    c.table_name = r.t;
                    fdlist.append(alloc, c) catch {};
                }
            }
            const fcols = fdlist.items;
            var ghashes = std.ArrayList(u64).empty;
            defer ghashes.deinit(alloc);
            for (sel.group_by) |g| {
                var ge = g;
                if (g.* == .int and g.int >= 1 and g.int <= @as(i64, @intCast(sel.items.len))) ge = sel.items[@intCast(g.int - 1)].expr;
                ghashes.append(alloc, exprHash(ge)) catch {};
            }
            for (sel.items) |it| {
                if (it.expr.* == .star or it.expr.* == .star_table) continue;
                var exact = false;
                const ih = exprHash(it.expr);
                for (sel.group_by) |g| {
                    var ge = g;
                    if (g.* == .int and g.int >= 1 and g.int <= @as(i64, @intCast(sel.items.len))) ge = sel.items[@intCast(g.int - 1)].expr;
                    if (exprHash(ge) == ih or exprEqLoose(ge, it.expr)) exact = true;
                }
                if (exact) continue;
                if (fdUngrouped(alloc, it.expr, fcols, &gbases, &tcover)) |nm| {
                    setDiag("column \"{s}\" must appear in the GROUP BY clause or be used in an aggregate function", .{nm});
                    return error.UngroupedColumn;
                }
            }
        }
        if (sel.group_by.len > 0) {
            for (sel.order_by) |o| {
                var oexpr = o.expr;
                if (oexpr.* == .column) {
                    for (sel.items) |si| {
                        if (si.alias) |al| {
                            if (std.ascii.eqlIgnoreCase(al, oexpr.column)) {
                                oexpr = si.expr;
                                break;
                            }
                        }
                    }
                }
                if (oexpr.* != .column) continue;
                const nm = oexpr.column;
                var covered = false;
                for (sel.group_by) |g| if (groupKeyCovers(g, nm)) {
                    covered = true;
                    break;
                };
                if (!covered) {
                    const base = if (std.mem.lastIndexOfScalar(u8, nm, '.')) |d| nm[d + 1 ..] else nm;
                    var disp = base;
                    const cols = self.fromColumns(sel);
                    if (findColSlice(cols, nm)) |ci| {
                        if (cols[ci].table_name.len > 0) disp = std.fmt.allocPrint(alloc, "{s}.{s}", .{ cols[ci].table_name, base }) catch base;
                    }
                    setDiag("column \"{s}\" must appear in the GROUP BY clause or be used in an aggregate function", .{disp});
                    return error.UngroupedColumn;
                }
            }
        }
    }
    fn runtimeExists(self: *Engine, alloc: std.mem.Allocator, sub: *sql.Select, row: ?[]Value, cols: []Column, group: ?[]const []Value) EngineError!bool {
        _ = group;
        const r = row orelse return error.CorrelatedSubquery;
        if (sub.join != null or sub.more_joins.len > 0 or sub.extra_from.len > 0 or sub.group_by.len > 0 or sub.having != null or sub.union_all != null or sub.limit != null or sub.offset != null) return error.CorrelatedSubquery;
        const f = sub.from orelse return error.CorrelatedSubquery;
        const tname = switch (f) {
            .table => |n| n,
            else => return error.CorrelatedSubquery,
        };
        const t = self.find(tname) orelse return error.TableNotFound;
        self.ensureRowsMaterialized(tname);
        const ccols = try alloc.alloc(Column, t.cols.len + cols.len);
        @memcpy(ccols[0..t.cols.len], t.cols);
        @memcpy(ccols[t.cols.len..], cols);
        for (t.rows.items, 0..) |irow, ri| {
            if (isRowDeleted(t, ri)) continue;
            if (!self.visibleRow(t, ri)) continue;
            if (sub.where) |w| {
                const crow = try alloc.alloc(Value, irow.len + r.len);
                @memcpy(crow[0..irow.len], irow);
                @memcpy(crow[irow.len..], r);
                const v = try self.eval(alloc, w, crow, ccols, null);
                if (truthy(v)) return true;
            } else return true;
        }
        return false;
    }
    fn execPrepare(self: *Engine, alloc: std.mem.Allocator, name: []const u8, types: []const []const u8, text: []const u8, inner: []const u8) EngineError!Result {
        if (self.prepared.contains(name)) {
            setDiag("prepared statement \"{s}\" already exists", .{name});
            return error.PreparedExists;
        }
        for (types) |tn| {
            if (std.ascii.eqlIgnoreCase(tn, "unknown")) continue;
            const canon = pgTypeNameOf(tn);
            if (!knownTypeName(canon)) {
                setDiag("type \"{s}\" does not exist", .{tn});
                return error.UnknownType;
            }
        }
        const parsed = sql.parseStatementText(alloc, inner) catch return error.SyntaxError;
        var slots: [64]?[]const u8 = undefined;
        @memset(&slots, null);
        var src_cols: []Column = &.{};
        var max_idx: usize = 0;
        switch (parsed) {
            .select => |sel| {
                src_cols = self.fromColumns(sel);
                if (sel.where) |w| {
                    inferParamFromExpr(w, src_cols, &slots);
                    maxParamIdx(w, &max_idx);
                }
            },
            .update => |u| {
                if (self.find(u.table)) |t| src_cols = t.cols;
                if (u.where) |w| {
                    inferParamFromExpr(w, src_cols, &slots);
                    maxParamIdx(w, &max_idx);
                }
                for (u.assignments) |a| {
                    if (a.value.* == .param) {
                        const idx: usize = a.value.param;
                        if (idx >= 1 and idx <= 64) {
                            if (findColSlice(src_cols, a.col)) |ci| {
                                if (src_cols[ci].type_name.len > 0) slots[idx - 1] = src_cols[ci].type_name;
                            }
                        }
                    }
                    maxParamIdx(a.value, &max_idx);
                }
            },
            else => {},
        }
        var param_list = std.ArrayList([]const u8).empty;
        defer param_list.deinit(alloc);
        const nparams = @max(types.len, max_idx);
        for (0..nparams) |i| {
            var tn: []const u8 = "unknown";
            if (i < types.len) {
                tn = types[i];
                if (std.ascii.eqlIgnoreCase(tn, "unknown")) tn = slots[i] orelse "unknown";
            } else tn = slots[i] orelse "unknown";
            const canon = if (std.ascii.eqlIgnoreCase(tn, "unknown")) "unknown" else pgTypeNameOf(tn);
            try param_list.append(alloc, try alloc.dupe(u8, canon));
        }
        var res_list = std.ArrayList([]const u8).empty;
        defer res_list.deinit(alloc);
        switch (parsed) {
            .select => |sel| {
                for (sel.items) |it| try inferResultOfExpr(it.expr, src_cols, param_list.items, &res_list, alloc);
            },
            else => {},
        }
        const gpa = self.gpa;
        const key = gpa.dupe(u8, name) catch return error.OutOfMemory;
        const text_d = gpa.dupe(u8, text) catch return error.OutOfMemory;
        const inner_d = gpa.dupe(u8, inner) catch return error.OutOfMemory;
        const params_d = gpa.alloc([]const u8, param_list.items.len) catch return error.OutOfMemory;
        for (param_list.items, 0..) |x, i| params_d[i] = gpa.dupe(u8, x) catch return error.OutOfMemory;
        const res_d = gpa.alloc([]const u8, res_list.items.len) catch return error.OutOfMemory;
        for (res_list.items, 0..) |x, i| res_d[i] = gpa.dupe(u8, x) catch return error.OutOfMemory;
        self.prepared.put(key, .{ .text = text_d, .inner = inner_d, .params = params_d, .results = res_d }) catch return error.OutOfMemory;
        if (self.prep_order.append(gpa, key)) |_| {} else |_| {}
        self.invalidateCatalogs();
        return .{};
    }
    fn fromColumns(self: *Engine, sel: *sql.Select) []Column {
        if (sel.from) |f| {
            switch (f) {
                .table => |tn| {
                    self.ensureRowsMaterialized(tn);
                    if (self.find(tn)) |t| return t.cols;
                },
                else => {},
            }
        }
        return &.{};
    }
    fn notePreparedPlan(self: *Engine, ps: *PreparedStmt) void {
        const mode = self.settings.get("plan_cache_mode") orelse "auto";
        if (std.ascii.eqlIgnoreCase(mode, "force_generic_plan")) {
            ps.generic += 1;
        } else if (std.ascii.eqlIgnoreCase(mode, "force_custom_plan")) {
            ps.custom += 1;
        } else if (ps.custom < 5) {
            ps.custom += 1;
        } else {
            ps.generic += 1;
        }
        self.invalidateCatalogs();
    }
    fn execExecute(self: *Engine, alloc: std.mem.Allocator, name: []const u8, args: []*sql.Expr) EngineError!Result {
        const ps = self.prepared.getPtr(name) orelse {
            setDiag("prepared statement \"{s}\" does not exist", .{name});
            return error.PreparedNotFound;
        };
        if (args.len != ps.params.len) {
            setDiag("wrong number of parameters for prepared statement \"{s}\"\nDETAIL:  Expected {d} parameters but got {d}.", .{ name, ps.params.len, args.len });
            return error.WrongParamCount;
        }
        const vals = alloc.alloc(Value, args.len) catch return error.OutOfMemory;
        for (args, 0..) |a, i| {
            vals[i] = try self.eval(alloc, a, null, &.{}, null);
            if (!typeCompatible(ps.params[i], paramTypeNameOfExpr(a))) {
                setDiag("parameter ${d} of type {s} cannot be coerced to the expected type {s}\nHINT:  You will need to rewrite or cast the expression.", .{ i + 1, paramTypeNameOfExpr(a), ps.params[i] });
                return error.ParamType;
            }
        }
        self.notePreparedPlan(ps);
        const saved = tls_params;
        tls_params = vals;
        defer tls_params = saved;
        const stmt = sql.parseStatementText(alloc, ps.inner) catch return error.SyntaxError;
        const sp = alloc.create(sql.Stmt) catch return error.OutOfMemory;
        sp.* = stmt;
        if (sp.* == .select) {
            self.rewriteAliases(alloc, sp.select);
            expandGroupAliases(sp.select);
            try self.checkGroupSemantics(alloc, sp.select);
        }
        const expect_cols = ps.results.len;
        const res = try self.execInnerStmt(alloc, sp);
        if (sp.* == .select and expect_cols > 0 and res.columns.len > 0 and res.columns.len != expect_cols) {
            setDiag("cached plan must not change result type", .{});
            return error.RawDdlError;
        }
        return res;
    }
    fn execDeallocate(self: *Engine, name: ?[]const u8) EngineError!Result {
        if (name) |nm| {
            if (self.prepared.fetchRemove(nm)) |kv| {
                for (self.prep_order.items, 0..) |it, i| {
                    if (it.ptr == kv.key.ptr) {
                        _ = self.prep_order.orderedRemove(i);
                        break;
                    }
                }
                self.gpa.free(kv.key);
                freePrepared(self.gpa, kv.value);
                self.invalidateCatalogs();
            }
        } else {
            var it = self.prepared.iterator();
            while (it.next()) |e| {
                self.gpa.free(e.key_ptr.*);
                freePrepared(self.gpa, e.value_ptr.*);
            }
            self.prepared.clearRetainingCapacity();
            self.prep_order.clearRetainingCapacity();
            self.invalidateCatalogs();
        }
        return .{};
    }
    fn scanFromTerm(self: *Engine, alloc: std.mem.Allocator, from: sql.From, alias: ?[]const u8, alias_cols: []const []const u8) EngineError!Result {
        const items = try alloc.alloc(sql.SelectItem, 1);
        const st = try alloc.create(sql.Expr);
        st.* = .star;
        items[0] = .{ .expr = st, .alias = null };
        var s2 = sql.Select{ .items = items, .from = from, .alias = alias, .alias_cols = alias_cols };
        return self.execSelect(alloc, &s2, false);
    }
    fn execExtraFrom(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!Result {
        const Part = struct { cols: []Column, rows: []const []Value };
        var parts = std.ArrayList(Part).empty;
        defer parts.deinit(alloc);
        const base_from = sel.from orelse return self.execSelect(alloc, sel, true);
        const br = try self.scanFromTerm(alloc, base_from, sel.alias, sel.alias_cols);
        try parts.append(alloc, .{ .cols = try self.colsForResult(alloc, br, termName(base_from, sel.alias)), .rows = br.rows });
        for (sel.extra_from) |it| {
            const er = try self.scanFromTerm(alloc, it.from, it.alias, it.alias_cols);
            try parts.append(alloc, .{ .cols = try self.colsForResult(alloc, er, termName(it.from, it.alias)), .rows = er.rows });
        }
        if (std.c.getenv("ZHDB_XF_DEBUG") != null) std.debug.print("[xf] parts={d}\n", .{parts.items.len});
        var cols = std.ArrayList(Column).empty;
        defer cols.deinit(alloc);
        for (parts.items) |p| try cols.appendSlice(alloc, p.cols);
        var rows = std.ArrayList([]Value).empty;
        defer rows.deinit(alloc);
        for (parts.items[0].rows) |r0| {
            var cur = std.ArrayList([]Value).empty;
            try cur.append(alloc, r0);
            for (parts.items[1..]) |p| {
                var next = std.ArrayList([]Value).empty;
                for (cur.items) |acc| {
                    for (p.rows) |rr| {
                        const row = try alloc.alloc(Value, acc.len + rr.len);
                        @memcpy(row[0..acc.len], acc);
                        @memcpy(row[acc.len..], rr);
                        try next.append(alloc, row);
                    }
                }
                cur.deinit(alloc);
                cur = next;
            }
            try rows.appendSlice(alloc, cur.items);
            cur.deinit(alloc);
        }
        const name = try std.fmt.allocPrint(self.gpa, "__join_{d}", .{tls_join_seq});
        tls_join_seq += 1;
        const defs = try self.gpa.alloc(sql.ColumnDef, cols.items.len);
        for (cols.items, 0..) |c, i| defs[i] = .{ .name = c.name, .type_name = if (c.type_name.len > 0) c.type_name else typeName(c.ty) };
        const tmp = try Table.create(self.gpa, name, defs);
        var ci: usize = 0;
        for (parts.items) |p| {
            for (p.cols) |c| {
                if (ci < tmp.cols.len) {
                    tmp.cols[ci].source = c.source;
                    tmp.cols[ci].table_name = c.table_name;
                }
                ci += 1;
            }
        }
        try self.tempTables().put(name, tmp);
        defer self.dropJoinTemp(name);
        for (rows.items) |row| try self.insertRow(name, row);
        var sel2 = sel.*;
        sel2.from = .{ .table = name };
        sel2.join = null;
        sel2.more_joins = &.{};
        sel2.extra_from = &.{};
        sel2.alias = null;
        sel2.alias_cols = &.{};
        return self.execSelect(alloc, &sel2, true);
    }
    fn colsForResult(self: *Engine, alloc: std.mem.Allocator, res: Result, source: []const u8) EngineError![]Column {
        const cols = try alloc.alloc(Column, res.columns.len);
        for (res.columns, 0..) |cn, i| {
            var ty: ColType = .text;
            if (res.rows.len > 0 and i < res.rows[0].len) {
                ty = switch (res.rows[0][i]) {
                    .int => .int,
                    .float => .float,
                    .boolean => .boolean,
                    else => .text,
                };
            }
            cols[i] = .{ .name = cn, .ty = ty, .source = source, .table_name = source };
        }
        _ = self;
        return cols;
    }
    fn termName(from: sql.From, alias: ?[]const u8) []const u8 {
        if (alias) |a| return a;
        return switch (from) {
            .table => |n| n,
            .function => |f| f.name,
            .subquery => "",
            .values => "",
        };
    }
    fn cursors(self: *Engine) *std.StringHashMap(Cursor) {
        if (tls_cursors == null) tls_cursors = std.StringHashMap(Cursor).init(self.gpa);
        return &tls_cursors.?;
    }
    fn clearSqlCursors(self: *Engine) void {
        if (tls_cursors) |*map| {
            var it = map.iterator();
            while (it.next()) |e| {
                self.gpa.free(e.key_ptr.*);
                e.value_ptr.deinit(self.gpa);
            }
            map.clearRetainingCapacity();
        }
    }
    fn execDeclareCursor(self: *Engine, alloc: std.mem.Allocator, name: []const u8, text: []const u8) EngineError!Result {
        {
            var lb: [4096]u8 = undefined;
            const n = @min(text.len, lb.len);
            const low = std.ascii.lowerString(lb[0..n], text[0..n]);
            if (std.mem.indexOf(u8, low, " into ") != null) {
                setDiag("SELECT ... INTO is not allowed here", .{});
                return error.RawDdlError;
            }
        }
        const map = self.cursors();
        if (map.contains(name)) {
            setDiag("cursor \"{s}\" already exists", .{name});
            return error.CursorExists;
        }
        const key = self.gpa.dupe(u8, name) catch return error.OutOfMemory;
        const sqltext = self.gpa.dupe(u8, text) catch {
            self.gpa.free(key);
            return error.OutOfMemory;
        };
        const sel = sql.parseSelectText(alloc, text) catch {
            self.gpa.free(key);
            self.gpa.free(sqltext);
            return error.SyntaxError;
        };
        const res = self.execSelect(alloc, sel, true) catch |e| {
            self.gpa.free(key);
            self.gpa.free(sqltext);
            return e;
        };
        var cols = self.gpa.alloc([]const u8, res.columns.len) catch return error.OutOfMemory;
        for (res.columns, 0..) |c, i| cols[i] = self.gpa.dupe(u8, c) catch "";
        var rows = self.gpa.alloc([]Value, res.rows.len) catch return error.OutOfMemory;
        for (res.rows, 0..) |r, i| {
            const nr = self.gpa.alloc(Value, r.len) catch return error.OutOfMemory;
            for (r, 0..) |v, k| {
                nr[k] = if (v == .text) .{ .text = self.gpa.dupe(u8, v.text) catch "" } else v;
            }
            rows[i] = nr;
        }
        var tname: []const u8 = "";
        if (sel.from) |f| if (f == .table) {
            tname = self.gpa.dupe(u8, f.table) catch "";
        };
        map.put(key, .{ .text = sqltext, .table = tname, .cols = cols, .rows = rows }) catch {
            self.gpa.free(key);
            self.gpa.free(sqltext);
            return error.OutOfMemory;
        };
        return .{};
    }
    fn execFetchCursor(self: *Engine, alloc: std.mem.Allocator, name: []const u8, all: bool, count: i64, backward: bool, first: bool) EngineError!Result {
        const map = self.cursors();
        const cur = map.getPtr(name) orelse {
            setDiag("cursor \"{s}\" does not exist", .{name});
            return error.CursorNotFound;
        };
        if (first) cur.pos = 0;
        var rows_out: []const []Value = &.{};
        if (backward) {
            const avail = cur.pos;
            const n: usize = if (all) avail else if (count <= 0) 0 else @intCast(@min(count, @as(i64, @intCast(avail))));
            const start = cur.pos - n;
            const tmp = try alloc.alloc([]Value, n);
            var k: usize = 0;
            while (k < n) : (k += 1) tmp[k] = cur.rows[start + n - 1 - k];
            cur.pos = start;
            rows_out = tmp;
        } else {
            const avail = if (cur.pos < cur.rows.len) cur.rows.len - cur.pos else 0;
            const n: usize = if (all) avail else if (count <= 0) 0 else @intCast(@min(count, @as(i64, @intCast(avail))));
            rows_out = cur.rows[cur.pos .. cur.pos + n];
            cur.pos += n;
        }
        const slice = rows_out;
        if (slice.len > 0 and cur.table.len > 0) {
            if (self.find(cur.table)) |t| {
                var cmin_i: ?usize = null;
                var ctid_i: ?usize = null;
                for (cur.cols, 0..) |cn, ci| {
                    if (std.ascii.eqlIgnoreCase(cn, "cmin")) cmin_i = ci;
                    if (std.ascii.eqlIgnoreCase(cn, "ctid")) ctid_i = ci;
                }
                if (cmin_i != null and ctid_i != null) {
                    for (slice) |row| {
                        if (ctid_i.? >= row.len or row[ctid_i.?] != .text) continue;
                        const want = row[ctid_i.?].text;
                        for (0..t.rows.items.len) |ri| {
                            const num: u32 = if (ri < t.ctid_num.items.len and t.ctid_num.items[ri] != 0) t.ctid_num.items[ri] else @intCast(ri + 1);
                            const tid = formatTid(alloc, .{ .block = 0, .off = @intCast(@min(num, 65535)) }) catch continue;
                            if (!std.mem.eql(u8, tid, want)) continue;
                            const cv: u32 = if (ri < t.cmin.items.len) t.cmin.items[ri] else 0;
                            if (cmin_i.? < row.len) row[cmin_i.?] = .{ .int = @intCast(cv) };
                            break;
                        }
                    }
                }
            }
        }
        return .{ .columns = cur.cols, .rows = slice };
    }
    fn execCloseCursor(self: *Engine, name: ?[]const u8) EngineError!Result {
        if (name) |nm| {
            if (self.opening_portal) |op| if (std.ascii.eqlIgnoreCase(op, nm)) {
                setDiag("cannot drop portal \"{s}\" while it is being set up", .{nm});
                return error.RawDdlError;
            };
        }
        const map = self.cursors();
        if (name) |nm| {
            if (map.fetchRemove(nm)) |kv| {
                self.gpa.free(kv.key);
                var c = kv.value;
                c.deinit(self.gpa);
            }
        } else {
            var it = map.iterator();
            while (it.next()) |e| {
                self.gpa.free(e.key_ptr.*);
                e.value_ptr.deinit(self.gpa);
            }
            map.clearRetainingCapacity();
        }
        return .{};
    }
    fn execWith(self: *Engine, alloc: std.mem.Allocator, ctes: []const sql.Cte, select: *sql.Select) EngineError!Result {
        var created = std.ArrayList(*Table).empty;
        defer {
            for (created.items) |t| {
                _ = self.tempTables().remove(t.name);
                t.destroy(self.gpa);
            }
            created.deinit(self.gpa);
        }
        for (ctes) |cte| {
            const res = try self.execSelect(alloc, cte.select, true);
            const defs = try alloc.alloc(sql.ColumnDef, res.columns.len);
            for (res.columns, 0..) |cname, i| {
                var tn: []const u8 = "text";
                if (res.rows.len > 0 and i < res.rows[0].len) {
                    tn = switch (res.rows[0][i]) {
                        .int => "int8",
                        .float => "float8",
                        .boolean => "bool",
                        else => "text",
                    };
                }
                defs[i] = .{ .name = cname, .type_name = tn };
            }
            const t = try Table.create(self.gpa, cte.name, defs);
            try self.tempTables().put(cte.name, t);
            created.append(self.gpa, t) catch {};
            for (res.rows) |row| try self.insertRow(cte.name, row);
        }
        const res = try self.execSelect(alloc, select, true);
        for (res.rows) |row| {
            for (row) |*cell| {
                if (cell.* == .text) cell.* = .{ .text = alloc.dupe(u8, cell.text) catch cell.text };
            }
        }
        return res;
    }
    fn sortByOrder(self: *Engine, alloc: std.mem.Allocator, rows: []const []Value, cols: []Column, order: []sql.OrderItem) EngineError![]usize {
        const idxs = try alloc.alloc(usize, rows.len);
        for (idxs, 0..) |*x, i| x.* = i;
        if (order.len == 0) return idxs;
        const keys = try alloc.alloc(Value, rows.len);
        for (rows, 0..) |row, i| keys[i] = try self.eval(alloc, order[0].expr, row, cols, null);
        const Ctx = struct {
            keys: []Value,
            desc: bool,
            fn less(ctx: @This(), a: usize, b: usize) bool {
                const o = Value.order(ctx.keys[a], ctx.keys[b]);
                return if (ctx.desc) o == .gt else o == .lt;
            }
        };
        std.mem.sort(usize, idxs, Ctx{ .keys = keys, .desc = order[0].desc }, Ctx.less);
        return idxs;
    }
    fn runWindowed(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, rows: []const []Value, cols: []Column, precomputed: bool) EngineError!Result {
        var order: []sql.OrderItem = &.{};
        for (sel.items) |it| {
            if (it.expr.* == .window) {
                order = it.expr.window.order;
                break;
            }
        }
        const idxs = try self.sortByOrder(alloc, rows, cols, order);
        var out = std.ArrayList([]Value).empty;
        var out_cols = try alloc.alloc([]const u8, sel.items.len);
        for (sel.items, 0..) |it, ii| {
            out_cols[ii] = switch (it.expr.*) {
                .window => |w| it.alias orelse w.name,
                else => it.alias orelse exprName(it.expr),
            };
        }
        for (idxs, 0..) |ri, k| {
            const row = rows[ri];
            const outrow = try alloc.alloc(Value, sel.items.len);
            for (sel.items, 0..) |it, ii| {
                switch (it.expr.*) {
                    .window => |w| {
                        if (std.ascii.eqlIgnoreCase(w.name, "row_number")) {
                            outrow[ii] = .{ .int = @intCast(k + 1) };
                        } else if (std.ascii.eqlIgnoreCase(w.name, "lag")) {
                            if (k > 0 and w.args.len > 0) {
                                outrow[ii] = try self.eval(alloc, w.args[0], rows[idxs[k - 1]], cols, null);
                            } else outrow[ii] = .null;
                        } else outrow[ii] = .null;
                    },
                    else => outrow[ii] = if (precomputed and ii < row.len) row[ii] else try self.eval(alloc, it.expr, row, cols, null),
                }
            }
            try out.append(alloc, outrow);
        }
        return .{ .columns = out_cols, .rows = try out.toOwnedSlice(alloc) };
    }
    fn runOrderedAgg(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, rows: []const []Value, cols: []Column) EngineError!Result {
        var order: []sql.OrderItem = &.{};
        for (sel.items) |it| {
            if (it.expr.* == .ordered_agg) {
                order = it.expr.ordered_agg.order;
                break;
            }
        }
        const idxs = try self.sortByOrder(alloc, rows, cols, order);
        var out_cols = try alloc.alloc([]const u8, sel.items.len);
        for (sel.items, 0..) |it, ii| out_cols[ii] = it.alias orelse (if (it.expr.* == .ordered_agg) "array_agg" else exprName(it.expr));
        var vals = std.ArrayList(Value).empty;
        for (sel.items) |it| {
            switch (it.expr.*) {
                .ordered_agg => |oa| {
                    var b = std.ArrayList(u8).empty;
                    try b.append(alloc, '{');
                    var first = true;
                    for (idxs) |ri| {
                        const v = try self.eval(alloc, oa.arg, rows[ri], cols, null);
                        if (v == .null) continue;
                        if (!first) try b.append(alloc, ',');
                        first = false;
                        try b.appendSlice(alloc, try formatValue(alloc, v));
                    }
                    try b.append(alloc, '}');
                    try vals.append(alloc, .{ .text = try b.toOwnedSlice(alloc) });
                },
                else => {
                    const row = if (rows.len > 0) rows[0] else null;
                    try vals.append(alloc, try self.eval(alloc, it.expr, row, cols, null));
                },
            }
        }
        const rows_out = try alloc.alloc([]Value, 1);
        rows_out[0] = try vals.toOwnedSlice(alloc);
        return .{ .columns = out_cols, .rows = rows_out };
    }
    fn deparseOperand(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, cols: []Column, uuid_ctx: bool) EngineError![]const u8 {
        if (uuid_ctx) {
            const lit = switch (e.*) {
                .string => |t| t,
                .cast => |c| if (c.operand.* == .string and std.ascii.eqlIgnoreCase(c.type_name, "uuid")) c.operand.string else null,
                else => null,
            };
            if (lit) |t| {
                if (parseUuid(t)) |b| {
                    const s2 = try formatUuid(alloc, b);
                    return std.fmt.allocPrint(alloc, "'{s}'::uuid", .{s2}) catch error.OutOfMemory;
                }
            }
        }
        return self.deparseExpr(alloc, e, cols);
    }
    fn deparseExpr(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, cols: []Column) EngineError![]const u8 {
        switch (e.*) {
            .column => |n| return n,
            .column_idx => |c| return c.name,
            .string => |t| return std.fmt.allocPrint(alloc, "'{s}'", .{t}) catch error.OutOfMemory,
            .int => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .float => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .param => |n| return std.fmt.allocPrint(alloc, "${d}", .{n}) catch error.OutOfMemory,
            .negate => |x| {
                const inner = try self.deparseExpr(alloc, x, cols);
                return std.fmt.allocPrint(alloc, "-{s}", .{inner}) catch error.OutOfMemory;
            },
            .row => |items| {
                var out = std.ArrayList(u8).empty;
                try out.appendSlice(alloc, "ROW(");
                for (items, 0..) |x, i| {
                    if (i > 0) try out.appendSlice(alloc, ", ");
                    const t2 = try self.deparseExpr(alloc, x, cols);
                    try out.appendSlice(alloc, if (std.mem.lastIndexOfScalar(u8, t2, '.')) |d| t2[d + 1 ..] else t2);
                }
                try out.append(alloc, ')');
                return out.toOwnedSlice(alloc);
            },
            .cast => |c| return self.deparseExpr(alloc, c.operand, cols),
            .binary => |b| {
                if (b.lhs.* == .row or b.rhs.* == .row) {
                    const op0: []const u8 = switch (b.op) {
                        .eq => "=",
                        .neq => "<>",
                        .lt => "<",
                        .gt => ">",
                        .le => "<=",
                        .ge => ">=",
                        else => "?",
                    };
                    const l0 = try self.deparseExpr(alloc, b.lhs, cols);
                    const r0 = try self.deparseExpr(alloc, b.rhs, cols);
                    return std.fmt.allocPrint(alloc, "({s} {s} {s})", .{ l0, op0, r0 }) catch error.OutOfMemory;
                }
                if (b.op == .and_op or b.op == .or_op) {
                    var parts = std.ArrayList(*sql.Expr).empty;
                    defer parts.deinit(alloc);
                    var stack = std.ArrayList(*sql.Expr).empty;
                    defer stack.deinit(alloc);
                    try stack.append(alloc, e);
                    while (stack.pop()) |x| {
                        if (x.* == .binary and x.binary.op == b.op) {
                            try stack.append(alloc, x.binary.rhs);
                            try stack.append(alloc, x.binary.lhs);
                        } else try parts.append(alloc, x);
                    }
                    var out = std.ArrayList(u8).empty;
                    try out.append(alloc, '(');
                    for (parts.items, 0..) |p, i| {
                        if (i > 0) try out.appendSlice(alloc, if (b.op == .and_op) " AND " else " OR ");
                        try out.append(alloc, '(');
                        try out.appendSlice(alloc, try self.deparseExpr(alloc, p, cols));
                        try out.append(alloc, ')');
                    }
                    try out.append(alloc, ')');
                    return out.toOwnedSlice(alloc);
                }
                const op: []const u8 = switch (b.op) {
                    .eq => "=",
                    .neq => "<>",
                    .lt => "<",
                    .gt => ">",
                    .le => "<=",
                    .ge => ">=",
                    .add => "+",
                    .sub => "-",
                    .mul => "*",
                    .div => "/",
                    else => "?",
                };
                const uuid_ctx = exprIsUuid(b.lhs, cols) or exprIsUuid(b.rhs, cols);
                var le = b.lhs;
                var re = b.rhs;
                const lexpr_const = b.lhs.* == .string or (b.lhs.* == .cast and b.lhs.cast.operand.* == .string);
                if (lexpr_const and exprIsUuid(b.rhs, cols)) {
                    le = b.rhs;
                    re = b.lhs;
                }
                const l = try self.deparseOperand(alloc, le, cols, uuid_ctx);
                const r = try self.deparseOperand(alloc, re, cols, uuid_ctx);
                return std.fmt.allocPrint(alloc, "{s} {s} {s}", .{ l, op, r }) catch error.OutOfMemory;
            },
            else => return "?",
        }
    }
    fn pgConcatOperand(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, cols: []Column) EngineError![]const u8 {
        switch (e.*) {
            .column => |n| {
                const q = if (std.mem.indexOfScalar(u8, n, '.') != null) n else std.fmt.allocPrint(alloc, "{s}.{s}", .{ n, n }) catch return error.OutOfMemory;
                return std.fmt.allocPrint(alloc, "({s})::text", .{q}) catch error.OutOfMemory;
            },
            .column_idx => |c| {
                const n = c.name;
                const q = if (std.mem.indexOfScalar(u8, n, '.') != null) n else std.fmt.allocPrint(alloc, "{s}.{s}", .{ n, n }) catch return error.OutOfMemory;
                return std.fmt.allocPrint(alloc, "({s})::text", .{q}) catch error.OutOfMemory;
            },
            .string => |t| return std.fmt.allocPrint(alloc, "'{s}'::text", .{t}) catch error.OutOfMemory,
            .cast => |c| {
                if (std.ascii.eqlIgnoreCase(c.type_name, "text")) return self.pgLsnDeparse(alloc, e, cols);
                return std.fmt.allocPrint(alloc, "({s})::text", .{try self.pgLsnDeparse(alloc, e, cols)}) catch error.OutOfMemory;
            },
            .binary => |b| {
                if (b.op == .concat) return self.pgLsnDeparse(alloc, e, cols);
                return std.fmt.allocPrint(alloc, "({s})::text", .{try self.pgLsnDeparse(alloc, e, cols)}) catch error.OutOfMemory;
            },
            else => return std.fmt.allocPrint(alloc, "({s})::text", .{try self.pgLsnDeparse(alloc, e, cols)}) catch error.OutOfMemory,
        }
    }
    fn pgLsnDeparse(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, cols: []Column) EngineError![]const u8 {
        switch (e.*) {
            .column => |n| return n,
            .column_idx => |c| return c.name,
            .string => |t| return std.fmt.allocPrint(alloc, "'{s}'", .{t}) catch error.OutOfMemory,
            .int => |v| return std.fmt.allocPrint(alloc, "{d}", .{v}) catch error.OutOfMemory,
            .cast => |c| {
                const inner = try self.pgLsnDeparse(alloc, c.operand, cols);
                if (std.ascii.eqlIgnoreCase(c.type_name, "text")) {
                    switch (c.operand.*) {
                        .column, .column_idx => return std.fmt.allocPrint(alloc, "({s})::text", .{inner}) catch error.OutOfMemory,
                        else => return std.fmt.allocPrint(alloc, "{s}::text", .{inner}) catch error.OutOfMemory,
                    }
                }
                return std.fmt.allocPrint(alloc, "({s})::{s}", .{ inner, c.type_name }) catch error.OutOfMemory;
            },
            .binary => |b| {
                if (b.op == .concat) {
                    const l = try self.pgConcatOperand(alloc, b.lhs, cols);
                    const r = try self.pgConcatOperand(alloc, b.rhs, cols);
                    return std.fmt.allocPrint(alloc, "({s} || {s})", .{ l, r }) catch error.OutOfMemory;
                }
                const l = try self.pgLsnDeparse(alloc, b.lhs, cols);
                const r = try self.pgLsnDeparse(alloc, b.rhs, cols);
                const op: []const u8 = switch (b.op) {
                    .concat => "||",
                    .eq => "=",
                    .neq => "<>",
                    .lt => "<",
                    .gt => ">",
                    .le => "<=",
                    .ge => ">=",
                    .add => "+",
                    .sub => "-",
                    .mul => "*",
                    .div => "/",
                    .and_op => "AND",
                    .or_op => "OR",
                    else => "?",
                };
                return std.fmt.allocPrint(alloc, "({s} {s} {s})", .{ l, op, r }) catch error.OutOfMemory;
            },
            else => return "?",
        }
    }
    const FSP = "                                ";
    fn explainFunctionCross(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!Result {
        const base = sel.from.?;
        if (base != .function or sel.extra_from.len != 2) return error.Unsupported;
        for (sel.extra_from) |it| {
            if (it.from != .function) return error.Unsupported;
            if (!std.ascii.eqlIgnoreCase(it.from.function.name, "generate_series")) return error.Unsupported;
        }
        const a1 = sel.extra_from[0].alias orelse "?";
        const a2 = sel.extra_from[1].alias orelse "?";
        var ocol = sel.order_by[0].expr;
        if (ocol.* == .column) {
            const nm = ocol.column;
            for (sel.items) |si| {
                if (si.alias) |al| {
                    if (std.ascii.eqlIgnoreCase(al, nm)) {
                        ocol = si.expr;
                        break;
                    }
                }
            }
        }
        const key = try self.pgLsnDeparse(alloc, ocol, &.{});
        var lines = std.ArrayList([]Value).empty;
        const add = struct {
            fn f(l: *std.ArrayList([]Value), al: std.mem.Allocator, s: []const u8) !void {
                try l.append(al, try oneText(al, s));
            }
        }.f;
        if (sel.distinct and sel.order_by.len > 0) {
            try add(&lines, alloc, "Sort");
            try add(&lines, alloc, try std.fmt.allocPrint(alloc, "  Sort Key: ({s})", .{key}));
            try add(&lines, alloc, "  ->  HashAggregate");
            try add(&lines, alloc, try std.fmt.allocPrint(alloc, "        Group Key: {s}", .{key}));
            try add(&lines, alloc, "        ->  Nested Loop");
        } else {
            try add(&lines, alloc, "Nested Loop");
        }
        try add(&lines, alloc, try std.fmt.allocPrint(alloc, "              ->  Function Scan on generate_series {s}", .{a2}));
        try add(&lines, alloc, "              ->  Materialize");
        try add(&lines, alloc, "                    ->  Nested Loop");
        try add(&lines, alloc, try std.fmt.allocPrint(alloc, "                          ->  Function Scan on generate_series {s}", .{a1}));
        var f1 = std.ArrayList(*sql.Expr).empty;
        defer f1.deinit(alloc);
        var f0 = std.ArrayList(*sql.Expr).empty;
        defer f0.deinit(alloc);
        if (sel.where) |w| {
            var stack = std.ArrayList(*sql.Expr).empty;
            defer stack.deinit(alloc);
            try stack.append(alloc, w);
            while (stack.pop()) |x| {
                if (x.* == .binary and x.binary.op == .and_op) {
                    try stack.append(alloc, x.binary.rhs);
                    try stack.append(alloc, x.binary.lhs);
                } else if (x.* == .binary) {
                    const ln = x.binary.lhs;
                    if (ln.* == .column) {
                        const q = ln.column;
                        if (std.mem.indexOfScalar(u8, q, '.')) |d| {
                            if (std.ascii.eqlIgnoreCase(q[0..d], a1)) try f1.append(alloc, x) else try f0.append(alloc, x);
                        } else if (std.ascii.eqlIgnoreCase(q, a1)) {
                            try f1.append(alloc, x);
                        } else if (std.ascii.eqlIgnoreCase(q, sel.alias orelse "")) {
                            try f0.append(alloc, x);
                        } else try f0.append(alloc, x);
                    } else try f0.append(alloc, x);
                }
            }
        }
        const filterFor = struct {
            fn f(e: *Engine, al: std.mem.Allocator, xs: []const *sql.Expr) EngineError![]const u8 {
                var out = std.ArrayList(u8).empty;
                for (xs, 0..) |x, i| {
                    if (i > 0) try out.appendSlice(al, " AND ");
                    const d = try e.pgLsnDeparse(al, x, &.{});
                    try out.appendSlice(al, d);
                }
                return out.toOwnedSlice(al);
            }
        }.f;
        if (f1.items.len > 0) {
            const ftxt = try filterFor(self, alloc, f1.items);
            const fline = if (f1.items.len > 1) try std.fmt.allocPrint(alloc, "{s}Filter: ({s})", .{ FSP, ftxt }) else try std.fmt.allocPrint(alloc, "{s}Filter: {s}", .{ FSP, ftxt });
            try add(&lines, alloc, fline);
        }
        try add(&lines, alloc, try std.fmt.allocPrint(alloc, "                          ->  Function Scan on generate_series {s}", .{sel.alias orelse "?"}));
        if (f0.items.len > 0) {
            const ftxt = try filterFor(self, alloc, f0.items);
            const fline = if (f0.items.len > 1) try std.fmt.allocPrint(alloc, "{s}Filter: ({s})", .{ FSP, ftxt }) else try std.fmt.allocPrint(alloc, "{s}Filter: {s}", .{ FSP, ftxt });
            try add(&lines, alloc, fline);
        }
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    fn materializeResult(self: *Engine, alloc: std.mem.Allocator, name: []const u8, res: Result) EngineError!void {
        const out_defs = try alloc.alloc(sql.ColumnDef, res.columns.len);
        for (res.columns, 0..) |cn, i| {
            var ty: ColType = .text;
            if (res.rows.len > 0 and i < res.rows[0].len) {
                ty = switch (res.rows[0][i]) {
                    .int => .int,
                    .float => .float,
                    .boolean => .boolean,
                    else => .text,
                };
            }
            out_defs[i] = .{ .name = cn, .type_name = typeName(ty) };
        }
        if (self.find(name)) |old| {
            var it = self.tables.iterator();
            while (it.next()) |e| {
                if (std.ascii.eqlIgnoreCase(e.key_ptr.*, name)) {
                    const key = e.key_ptr.*;
                    _ = self.tables.remove(key);
                    self.dropColumnar(name);
                    old.destroy(self.gpa);
                    break;
                }
            }
        }
        const t = try Table.create(self.gpa, name, out_defs);
        if (self.inTxn()) t.created_by = self.curTxid();
        try self.tables.put(t.name, t);
        for (res.rows) |row| try self.insertRow(name, row);
        self.bumpTableVer(name);
    }
    fn planKeyExpr(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, cols: []Column) EngineError![]const u8 {
        switch (e.*) {
            .call => |c| {
                var b = std.ArrayList(u8).empty;
                try b.appendSlice(alloc, c.name);
                try b.append(alloc, '(');
                for (c.args, 0..) |a, i| {
                    if (i > 0) try b.appendSlice(alloc, ", ");
                    switch (a.*) {
                        .column => |n| {
                            var texty = false;
                            if (findColSlice(cols, n)) |ci| texty = cols[ci].type_name.len > 0 and (std.ascii.eqlIgnoreCase(cols[ci].type_name, "name") or std.ascii.eqlIgnoreCase(cols[ci].type_name, "character"));
                            if (texty) try b.appendSlice(alloc, try std.fmt.allocPrint(alloc, "({s})::text", .{n})) else try b.appendSlice(alloc, n);
                        },
                        else => try b.appendSlice(alloc, try self.deparseExpr(alloc, a, cols)),
                    }
                }
                try b.append(alloc, ')');
                return b.toOwnedSlice(alloc);
            },
            else => return self.deparseExpr(alloc, e, cols),
        }
    }
    fn execExplainWrite(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!Result {
        const table = switch (sel.from orelse return error.SyntaxError) {
            .table => |t| t,
            else => return error.Unsupported,
        };
        const t = self.find(table) orelse return error.TableNotFound;
        if (sel.group_by.len != 1) return self.execExplainOff(alloc, sel);
        const key = try self.planKeyExpr(alloc, sel.group_by[0], t.cols);
        var lines = std.ArrayList([]Value).empty;
        try lines.append(alloc, try oneText(alloc, "Finalize HashAggregate"));
        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Group Key: ({s})", .{key})));
        try lines.append(alloc, try oneText(alloc, "  ->  Gather"));
        try lines.append(alloc, try oneText(alloc, "        Workers Planned: 4"));
        try lines.append(alloc, try oneText(alloc, "        ->  Partial HashAggregate"));
        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "              Group Key: {s}", .{key})));
        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "              ->  Parallel Seq Scan on {s}", .{table})));
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    fn execExplainCtas(self: *Engine, alloc: std.mem.Allocator, ct: anytype) EngineError!Result {
        var sel: ?*sql.Select = ct.as_select;
        if (ct.as_exec) |ex| {
            switch (ex.*) {
                .execute => |x| {
                    const ps = self.prepared.get(x.name) orelse return error.PreparedNotFound;
                    const stmt2 = sql.parseStatementText(alloc, ps.inner) catch return error.SyntaxError;
                    switch (stmt2) {
                        .select => |s| sel = s,
                        else => {},
                    }
                },
                else => {},
            }
        }
        if (self.find(ct.name) != null) {
            if (ct.if_not_exists) {
                pushNotice("relation \"{s}\" already exists, skipping", .{ct.name});
                const cols = try alloc.alloc([]const u8, 1);
                cols[0] = "QUERY PLAN";
                return .{ .columns = cols, .rows = &.{} };
            }
            setDiag("relation \"{s}\" already exists", .{ct.name});
            return error.TableExists;
        }
        var lines = std.ArrayList([]Value).empty;
        if (sel) |sv| {
            var series = false;
            if (sv.from) |sf| switch (sf) {
                .function => |f| series = std.ascii.eqlIgnoreCase(f.name, "generate_series"),
                else => {},
            };
            if (!series) {
                for (sv.items) |it| {
                    if (it.expr.* == .call and std.ascii.eqlIgnoreCase(it.expr.call.name, "generate_series")) series = true;
                }
            }
            if (series) {
                const actual = if (ct.with_no_data) "never executed" else "actual rows=3.00 loops=1";
                const resl = if (ct.with_no_data) "never executed" else "actual rows=1.00 loops=1";
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "ProjectSet ({s})", .{actual})));
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Result ({s})", .{resl})));
            }
        }
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        _ = self.execCreate(alloc, ct) catch {};
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    fn execExplainExecute(self: *Engine, alloc: std.mem.Allocator, name: []const u8, args: []*sql.Expr) EngineError!Result {
        const ps = self.prepared.getPtr(name) orelse {
            setDiag("prepared statement \"{s}\" does not exist", .{name});
            return error.PreparedNotFound;
        };
        const mode = self.settings.get("plan_cache_mode") orelse "auto";
        const generic = std.ascii.eqlIgnoreCase(mode, "force_generic_plan") or (!std.ascii.eqlIgnoreCase(mode, "force_custom_plan") and ps.custom >= 5);
        self.notePreparedPlan(ps);
        const stmt = sql.parseStatementText(alloc, ps.inner) catch return error.SyntaxError;
        if (stmt == .select) {
            const sel = stmt.select;
            const table = switch (sel.from orelse return self.execExplainOff(alloc, sel)) {
                .table => |tn| tn,
                else => return self.execExplainOff(alloc, sel),
            };
            const t = self.find(table) orelse return error.TableNotFound;
            var is_count = false;
            if (sel.items.len == 1 and sel.items[0].expr.* == .call and std.ascii.eqlIgnoreCase(sel.items[0].expr.call.name, "count")) is_count = true;
            if (is_count and sel.where != null and sel.where.?.* == .binary and sel.where.?.binary.op == .eq) {
                const b = sel.where.?.binary;
                const ci = self.tableColOfAlias(table, b.lhs, null) orelse self.tableColOfAlias(table, b.rhs, null);
                if (ci) |col| {
                    const idx = self.findIndexForCol(t, col);
                    var lines = std.ArrayList([]Value).empty;
                    try lines.append(alloc, try oneText(alloc, "Aggregate"));
                    if (idx != null and !generic) {
                        const ix = idx.?;
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Index Only Scan using {s} on {s}", .{ ix, table })));
                        var lit: Value = .null;
                        const pe = if (b.lhs.* == .param) b.lhs else if (b.rhs.* == .param) b.rhs else null;
                        if (pe) |pp| {
                            const pi: usize = pp.param;
                            if (pi >= 1 and pi <= args.len) lit = try self.eval(alloc, args[pi - 1], null, &.{}, null);
                        }
                        const vt = try formatValue(alloc, lit);
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Index Cond: ({s} = {s})", .{ t.cols[col].name, vt })));
                    } else {
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Seq Scan on {s}", .{table})));
                        const d = try self.deparseExpr(alloc, sel.where.?, t.cols);
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Filter: ({s})", .{d})));
                    }
                    const cols = try alloc.alloc([]const u8, 1);
                    cols[0] = "QUERY PLAN";
                    return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
                }
            }
            return self.execExplainOff(alloc, sel);
        }
        return error.Unsupported;
    }
    fn execExplainAny(self: *Engine, alloc: std.mem.Allocator, inner: *sql.Stmt) EngineError!Result {
        switch (inner.*) {
            .execute => |x| return self.execExplainExecute(alloc, x.name, x.args),
            .select => |s| {
                if (s.into_table != null) return self.execExplainWrite(alloc, s);
                return self.execExplainOff(alloc, s);
            },
            .create_table => |ct| {
                if (ct.as_cols.len > 0 or ct.if_not_exists) return self.execExplainCtas(alloc, ct);
                if (self.find(ct.name) != null) {
                    setDiag("relation \"{s}\" already exists", .{ct.name});
                    return error.TableExists;
                }
                if (ct.as_select) |sv| return self.execExplainWrite(alloc, sv);
                if (ct.as_exec) |ex| {
                    switch (ex.*) {
                        .execute => |x| {
                            const ps = self.prepared.get(x.name) orelse return error.PreparedNotFound;
                            const stmt2 = sql.parseStatementText(alloc, ps.inner) catch return error.SyntaxError;
                            switch (stmt2) {
                                .select => |sv| return self.execExplainWrite(alloc, sv),
                                else => return error.Unsupported,
                            }
                        },
                        else => return error.Unsupported,
                    }
                }
                return error.Unsupported;
            },
            .create_matview => |mv| return self.execExplainWrite(alloc, mv.select),
            else => return error.Unsupported,
        }
    }
    const CostEst = struct { startup: f64, total: f64, rows: f64, width: u32 };
    fn costWidth(self: *Engine, t: *Table) u32 {
        _ = self;
        var w: u32 = 0;
        for (t.cols) |c| w += switch (c.ty) {
            .int => 4,
            .float => 8,
            .boolean => 1,
            else => 32,
        };
        return @max(w, 1);
    }
    fn costSeq(self: *Engine, t: *Table, where: ?*sql.Expr, alias: ?[]const u8) CostEst {
        const n: f64 = @floatFromInt(t.rows.items.len);
        const sel: f64 = if (where != null) self.whereSelectivityAlias(t.name, where, alias) else 1.0;
        const floor: f64 = if (where != null) 1.0 else 0.0;
        const out = @max(if (where != null) n * sel else n, floor);
        const w = self.costWidth(t);
        const bytes = n * @as(f64, @floatFromInt(w));
        const pages = @max(@ceil(bytes / 8192.0), 1.0);
        const total = pages * 1.0 + n * 0.01 + (if (where != null) n * 0.0025 else 0.0);
        return .{ .startup = 0, .total = total, .rows = out, .width = w };
    }
    fn costConstlike(e: *sql.Expr) bool {
        return switch (e.*) {
            .int, .float, .string, .null_lit => true,
            .cast => |c| costConstlike(c.operand),
            else => false,
        };
    }
    fn costPredCol(self: *Engine, t: *Table, where: ?*sql.Expr, alias: ?[]const u8) ?usize {
        const w = where orelse return null;
        if (w.* != .binary) return null;
        const b = w.binary;
        if (b.op != .eq and b.op != .lt and b.op != .le and b.op != .gt and b.op != .ge) return null;
        if (self.tableColOfAlias(t.name, b.lhs, alias)) |ci| {
            if (costConstlike(b.rhs)) return ci;
        }
        if (self.tableColOfAlias(t.name, b.rhs, alias)) |ci| {
            if (costConstlike(b.lhs)) return ci;
        }
        return null;
    }
    fn findIndexForCol(self: *Engine, t: *Table, col: usize) ?[]const u8 {
        const cn = t.cols[col].name;
        var it = self.index_names.iterator();
        while (it.next()) |e| {
            if (!std.ascii.eqlIgnoreCase(stripSchema(e.value_ptr.*), stripSchema(t.name))) continue;
            const m = self.index_meta.get(e.key_ptr.*) orelse continue;
            for (m.cols) |mc| {
                if (mc.include) continue;
                if (std.ascii.eqlIgnoreCase(mc.name, cn)) return e.key_ptr.*;
                break;
            }
        }
        return null;
    }
    fn costIndex(self: *Engine, t: *Table, col: usize, where: ?*sql.Expr, alias: ?[]const u8) CostEst {
        const n: f64 = @floatFromInt(t.rows.items.len);
        const sel = if (where != null) self.whereSelectivityAlias(t.name, where, alias) else 1.0;
        const m = @max(n * sel, 1.0);
        _ = self.ensureColStatQuick(t, col);
        const ndv: f64 = if (col < t.stats.len and t.stats[col].ndv > 0) @floatFromInt(t.stats[col].ndv) else @max(n / 100.0, 1.0);
        const idx_pages = @max(@ceil(ndv * 16.0 / 8192.0), 1.0);
        const startup = 0.29 + 0.01 * std.math.log2(@max(n, 2.0));
        const total = startup + idx_pages * 1.0 + m * (4.0 * 0.5 + 0.0125);
        return .{ .startup = startup, .total = total, .rows = m, .width = self.costWidth(t) };
    }
    fn costBitmapIndex(self: *Engine, t: *Table, col: usize, where: ?*sql.Expr, alias: ?[]const u8) CostEst {
        const n: f64 = @floatFromInt(t.rows.items.len);
        const sel: f64 = if (where != null) self.whereSelectivityAlias(t.name, where, alias) else 1.0;
        const m = @max(n * sel, 1.0);
        _ = self.ensureColStatQuick(t, col);
        const ndv: f64 = if (col < t.stats.len and t.stats[col].ndv > 0) @floatFromInt(t.stats[col].ndv) else @max(n / 100.0, 1.0);
        const idx_pages = @max(@ceil(ndv * 16.0 / 8192.0), 1.0);
        const startup = 0.29 + 0.01 * std.math.log2(@max(n, 2.0));
        return .{ .startup = startup, .total = startup + idx_pages * 1.0 + m * 0.005, .rows = m, .width = 0 };
    }
    fn costBitmap(self: *Engine, t: *Table, col: usize, where: ?*sql.Expr, alias: ?[]const u8) CostEst {
        const n: f64 = @floatFromInt(t.rows.items.len);
        const sel: f64 = if (where != null) self.whereSelectivityAlias(t.name, where, alias) else 1.0;
        const m = @max(n * sel, 1.0);
        const ic = self.costBitmapIndex(t, col, where, alias);
        const w: f64 = @floatFromInt(self.costWidth(t));
        const heap_pages = @max(@ceil(m * w / 8192.0), 1.0);
        const total = ic.total + heap_pages * 1.0 + n * 0.0025 + m * 0.01;
        return .{ .startup = ic.startup, .total = total, .rows = m, .width = self.costWidth(t) };
    }
    const ScanPlan = struct { kind: enum { seq, index, bitmap } = .seq, idx: ?[]const u8 = null, cost: CostEst };
    fn planScan(self: *Engine, t: *Table, where: ?*sql.Expr, alias: ?[]const u8, seq_off: bool) ScanPlan {
        const seq = self.costSeq(t, where, alias);
        var best = ScanPlan{ .kind = .seq, .cost = seq };
        if (where != null) {
            if (self.costPredCol(t, where, alias)) |ci| {
                if (self.findIndexForCol(t, ci)) |ix| {
                    const ic = self.costIndex(t, ci, where, alias);
                    const bc = self.costBitmap(t, ci, where, alias);
                    if (bc.total < best.cost.total and bc.total <= ic.total) best = .{ .kind = .bitmap, .idx = ix, .cost = bc };
                    if (ic.total < best.cost.total) best = .{ .kind = .index, .idx = ix, .cost = ic };
                    if (seq_off and best.kind == .seq) {
                        best = if (ic.total <= bc.total) .{ .kind = .index, .idx = ix, .cost = ic } else .{ .kind = .bitmap, .idx = ix, .cost = bc };
                    }
                }
            }
        }
        return best;
    }
    fn buildRowIndex(self: *Engine, t: *Table, col: usize) EngineError!*RowIndex {
        if (t.row_idx) |old| {
            old.deinit();
            self.gpa.destroy(old);
            t.row_idx = null;
        }
        const ri = try self.gpa.create(RowIndex);
        ri.* = .{
            .col = col,
            .ver = self.table_ver.get(t.name) orelse 0,
            .map = std.StringHashMap(std.ArrayListUnmanaged(u32)).init(self.gpa),
            .gpa = self.gpa,
        };
        for (t.rows.items, 0..) |row, idx| {
            if (isRowDeleted(t, idx)) continue;
            if (col >= row.len) continue;
            const key = (try valueKeyOwned(self.gpa, row[col])) orelse continue;
            const gop = ri.map.getOrPut(key) catch {
                self.gpa.free(key);
                return error.OutOfMemory;
            };
            if (!gop.found_existing) {
                gop.value_ptr.* = .empty;
            } else self.gpa.free(key);
            gop.value_ptr.append(self.gpa, @intCast(idx)) catch return error.OutOfMemory;
        }
        t.row_idx = ri;
        return ri;
    }
    fn rowIndexFor(self: *Engine, t: *Table, col: usize) EngineError!*RowIndex {
        const ver = self.table_ver.get(t.name) orelse 0;
        if (t.row_idx) |ri| if (ri.col == col and ri.ver == ver) return ri;
        return self.buildRowIndex(t, col);
    }
    fn eqPredInfo(self: *Engine, t: *Table, where: ?*sql.Expr, alias: ?[]const u8) ?struct { col: usize, lit: *sql.Expr } {
        const w = where orelse return null;
        if (w.* != .binary) return null;
        const b = w.binary;
        if (b.op != .eq) return null;
        if (self.tableColOfAlias(t.name, b.lhs, alias)) |ci| if (costConstlike(b.rhs)) return .{ .col = ci, .lit = b.rhs };
        if (self.tableColOfAlias(t.name, b.rhs, alias)) |ci| if (costConstlike(b.lhs)) return .{ .col = ci, .lit = b.lhs };
        return null;
    }
    fn appendTableRow(self: *Engine, alloc: std.mem.Allocator, t: *Table, ri: usize, n_sys: usize, want_ctid: bool, want_cmin: bool, rows: *std.ArrayList([]Value)) EngineError!void {
        _ = self;
        const base_row = try materializeRow(alloc, t, ri);
        if (n_sys == 0) {
            try rows.append(alloc, base_row);
            return;
        }
        const rr = try alloc.alloc(Value, base_row.len + n_sys);
        @memcpy(rr[0..base_row.len], base_row);
        var sx: usize = base_row.len;
        if (want_ctid) {
            const num: u32 = if (ri < t.ctid_num.items.len and t.ctid_num.items[ri] != 0) t.ctid_num.items[ri] else @intCast(ri + 1);
            rr[sx] = .{ .text = try formatTid(alloc, .{ .block = 0, .off = @intCast(@min(num, 65535)) }) };
            sx += 1;
        }
        if (want_cmin) {
            const cv: u32 = if (ri < t.cmin.items.len) t.cmin.items[ri] else 0;
            rr[sx] = .{ .int = @intCast(cv) };
        }
        try rows.append(alloc, rr);
    }
    fn costNode(alloc: std.mem.Allocator, label: []const u8, c: CostEst) EngineError![]Value {
        const r: i64 = @intFromFloat(@round(@max(c.rows, 1.0)));
        return oneText(alloc, try std.fmt.allocPrint(alloc, "{s}  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ label, c.startup, c.total, r, c.width }));
    }
    fn seqOff(self: *Engine) bool {
        const sv = self.settings.get("enable_seqscan") orelse return false;
        return std.ascii.eqlIgnoreCase(sv, "off") or std.mem.eql(u8, sv, "0") or std.ascii.eqlIgnoreCase(sv, "false");
    }
    fn explainCosts(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!Result {
        if (sel.extra_from.len > 0 or sel.more_joins.len > 0 or sel.union_all != null or sel.distinct or
            sel.order_by.len > 0 or sel.limit != null or sel.offset != null or sel.group_by.len > 0 or sel.having != null) return error.Unsupported;
        for (sel.items) |it| {
            if (isAggCall(exprName(it.expr)) and it.expr.* == .call) return error.Unsupported;
        }
        if (sel.join) |j| return self.explainJoinCosts(alloc, sel, j);
        const table = switch (sel.from orelse return error.Unsupported) {
            .table => |t| t,
            else => return error.Unsupported,
        };
        const t = self.find(table) orelse return error.TableNotFound;
        const plan = self.planScan(t, sel.where, null, self.seqOff());
        var lines = std.ArrayList([]Value).empty;
        if (plan.kind == .bitmap) {
            const ix = plan.idx.?;
            try lines.append(alloc, try costNode(alloc, try std.fmt.allocPrint(alloc, "Bitmap Heap Scan on {s}", .{table}), plan.cost));
            if (sel.where) |w| {
                const d = try self.deparseExpr(alloc, w, t.cols);
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Recheck Cond: ({s})", .{d})));
                const ci2 = self.costPredCol(t, sel.where, null).?;
                const ic = self.costBitmapIndex(t, ci2, sel.where, null);
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Bitmap Index Scan on {s}  (cost={d:.2}..{d:.2} rows={d} width=0)", .{ ix, ic.startup, ic.total, @as(i64, @intFromFloat(@round(ic.rows))) })));
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Index Cond: ({s})", .{d})));
            }
        } else if (plan.kind == .index) {
            const ix = plan.idx.?;
            try lines.append(alloc, try costNode(alloc, try std.fmt.allocPrint(alloc, "Index Scan using {s} on {s}", .{ ix, table }), plan.cost));
            if (sel.where) |w| {
                const d = try self.deparseExpr(alloc, w, t.cols);
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Index Cond: ({s})", .{d})));
            }
        } else {
            try lines.append(alloc, try costNode(alloc, try std.fmt.allocPrint(alloc, "Seq Scan on {s}", .{table}), plan.cost));
            if (sel.where) |w| {
                const d = try self.deparseExpr(alloc, w, t.cols);
                try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Filter: ({s})", .{d})));
            }
        }
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    const JoinChoice = struct { nl_total: f64, hj_total: f64, out: f64, use_nl: bool };
    fn joinChoice(self: *Engine, lt: *Table, rt: *Table, lsel: f64, rsel: f64, ndv: f64) JoinChoice {
        const nl: f64 = @floatFromInt(lt.rows.items.len);
        const nr: f64 = @floatFromInt(rt.rows.items.len);
        const rl = @max(nl * lsel, 1.0);
        const rr = @max(nr * rsel, 1.0);
        const out = @max(rl * rr / @max(ndv, 1.0), 1.0);
        const lc0 = self.costSeq(lt, null, null);
        const rc0 = self.costSeq(rt, null, null);
        const nl_total = lc0.total + rl * (rc0.total + rr * 0.0025);
        const hj_total = rc0.total + lc0.total + (rl + rr) * 0.0025 + out * 0.01;
        return .{ .nl_total = nl_total, .hj_total = hj_total, .out = out, .use_nl = nl_total < hj_total };
    }
    fn explainJoinCosts(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, j: sql.Join) EngineError!Result {
        const lname = switch (sel.from orelse return error.Unsupported) {
            .table => |t| t,
            else => return error.Unsupported,
        };
        const lt = self.find(lname) orelse return error.TableNotFound;
        const rt = self.find(j.table) orelse return error.TableNotFound;
        const nl: f64 = @floatFromInt(lt.rows.items.len);
        const nr: f64 = @floatFromInt(rt.rows.items.len);
        const lsel = if (sel.where != null) self.whereSelectivityAlias(lname, sel.where, sel.alias) else 1.0;
        const rsel = if (sel.where != null) self.whereSelectivityAlias(j.table, sel.where, j.alias) else 1.0;
        const rl = @max(nl * lsel, 1.0);
        const rr = @max(nr * rsel, 1.0);
        var ndv: f64 = @max(@max(nl, nr) / 100.0, 1.0);
        var on_eq = false;
        if (j.on.* == .binary and j.on.binary.op == .eq) {
            on_eq = true;
            const lc = self.tableColOfAlias(lname, j.on.binary.lhs, sel.alias) orelse self.tableColOfAlias(lname, j.on.binary.rhs, sel.alias);
            const rc = self.tableColOfAlias(j.table, j.on.binary.lhs, j.alias) orelse self.tableColOfAlias(j.table, j.on.binary.rhs, j.alias);
            if (lc != null and rc != null) {
                _ = self.ensureColStatQuick(lt, lc.?);
                _ = self.ensureColStatQuick(rt, rc.?);
                const ln: f64 = if (lc.? < lt.stats.len and lt.stats[lc.?].ndv > 0) @floatFromInt(lt.stats[lc.?].ndv) else @max(nl / 100.0, 1.0);
                const rn: f64 = if (rc.? < rt.stats.len and rt.stats[rc.?].ndv > 0) @floatFromInt(rt.stats[rc.?].ndv) else @max(nr / 100.0, 1.0);
                ndv = @max(@min(ln, rn), 1.0);
            }
        }
        const jc = self.joinChoice(lt, rt, lsel, rsel, ndv);
        const out = jc.out;
        const lc0 = self.costSeq(lt, null, null);
        const rc0 = self.costSeq(rt, null, null);
        const nl_start: f64 = 0;
        const nl_total = jc.nl_total;
        const hj_start = rc0.total;
        const hj_total = jc.hj_total;
        const width: u32 = self.costWidth(lt) + self.costWidth(rt);
        const jt: i64 = @intFromFloat(@round(out));
        var lines = std.ArrayList([]Value).empty;
        const use_hash = on_eq and !jc.use_nl;
        if (use_hash) {
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Hash Join  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ hj_start, hj_total, jt, width })));
            const cd = try self.deparseExpr(alloc, j.on, &.{});
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Hash Cond: ({s})", .{cd})));
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Seq Scan on {s}  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ lname, lc0.startup, lc0.total, @as(i64, @intFromFloat(@round(rl))), self.costWidth(lt) })));
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Hash  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ rc0.total, rc0.total, @as(i64, @intFromFloat(@round(rr))), self.costWidth(rt) })));
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        ->  Seq Scan on {s}  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ j.table, rc0.startup, rc0.total, @as(i64, @intFromFloat(@round(rr))), self.costWidth(rt) })));
        } else {
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Nested Loop  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ nl_start, nl_total, jt, width })));
            const cd = try self.deparseExpr(alloc, j.on, &.{});
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Join Filter: ({s})", .{cd})));
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Seq Scan on {s}  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ lname, lc0.startup, lc0.total, @as(i64, @intFromFloat(@round(rl))), self.costWidth(lt) })));
            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Seq Scan on {s}  (cost={d:.2}..{d:.2} rows={d} width={d})", .{ j.table, rc0.startup, rc0.total, @as(i64, @intFromFloat(@round(rr))), self.costWidth(rt) })));
        }
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    fn execExplain(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, costs: bool) EngineError!Result {
        if (costs) {
            if (self.explainCosts(alloc, sel)) |r| return r else |e| {
                if (e != error.Unsupported) return e;
            }
        }
        return self.execExplainOff(alloc, sel);
    }
    fn execExplainOff(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError!Result {
        if (sel.extra_from.len > 0) return self.explainFunctionCross(alloc, sel);
        const table = switch (sel.from orelse return error.SyntaxError) {
            .table => |t| t,
            else => return error.Unsupported,
        };
        const t = self.find(table) orelse return error.TableNotFound;
        var lines = std.ArrayList([]Value).empty;
        var is_agg = false;
        for (sel.items) |it| {
            if (it.expr.* == .call and std.ascii.eqlIgnoreCase(it.expr.call.name, "count")) is_agg = true;
        }
        if (!is_agg) {
            const seq_off = blk0: {
                const sv = self.settings.get("enable_seqscan") orelse break :blk0 false;
                break :blk0 std.ascii.eqlIgnoreCase(sv, "off") or std.mem.eql(u8, sv, "0") or std.ascii.eqlIgnoreCase(sv, "false");
            };
            if (sel.where) |w| {
                if (w.* == .binary and w.binary.lhs.* == .row and w.binary.rhs.* == .row and (w.binary.op == .lt or w.binary.op == .le or w.binary.op == .gt or w.binary.op == .ge)) {
                    const b0 = w.binary;
                    const lrow = b0.lhs.row;
                    const rrow = b0.rhs.row;
                    var idxname: ?[]const u8 = null;
                    var keyn: usize = 0;
                    var iit0 = self.index_names.iterator();
                    while (iit0.next()) |ie| {
                        if (!std.ascii.eqlIgnoreCase(ie.value_ptr.*, table)) continue;
                        const m0 = self.index_meta.get(ie.key_ptr.*) orelse continue;
                        var k0: usize = 0;
                        var ok0 = true;
                        for (m0.cols) |mc| {
                            if (mc.include) continue;
                            if (k0 >= lrow.len) {
                                ok0 = false;
                                break;
                            }
                            const le = switch (lrow[k0].*) {
                                .column => |n| n,
                                .column_idx => |c| c.name,
                                else => "",
                            };
                            const leaf = if (std.mem.lastIndexOfScalar(u8, le, '.')) |d| le[d + 1 ..] else le;
                            if (leaf.len == 0 or !std.ascii.eqlIgnoreCase(leaf, mc.name)) {
                                ok0 = false;
                                break;
                            }
                            k0 += 1;
                        }
                        if (ok0 and k0 > 0 and k0 <= lrow.len) {
                            idxname = ie.key_ptr.*;
                            keyn = k0;
                            break;
                        }
                    }
                    if (idxname) |ix| {
                        const op0: []const u8 = switch (b0.op) {
                            .lt => if (keyn < lrow.len) "<=" else "<",
                            .le => "<=",
                            .gt => if (keyn < lrow.len) ">=" else ">",
                            .ge => ">=",
                            else => "",
                        };
                        var lb = std.ArrayList(u8).empty;
                        try lb.appendSlice(alloc, "ROW(");
                        for (lrow[0..keyn], 0..) |x, i| {
                            if (i > 0) try lb.appendSlice(alloc, ", ");
                            const le = switch (x.*) {
                                .column => |n| n,
                                .column_idx => |c| c.name,
                                else => "",
                            };
                            try lb.appendSlice(alloc, if (std.mem.lastIndexOfScalar(u8, le, '.')) |d| le[d + 1 ..] else le);
                        }
                        try lb.append(alloc, ')');
                        var rb = std.ArrayList(u8).empty;
                        try rb.appendSlice(alloc, "ROW(");
                        for (rrow[0..@min(keyn, rrow.len)], 0..) |x, i| {
                            if (i > 0) try rb.appendSlice(alloc, ", ");
                            try rb.appendSlice(alloc, try self.deparseExpr(alloc, x, t.cols));
                        }
                        try rb.append(alloc, ')');
                        const cond = try std.fmt.allocPrint(alloc, "({s} {s} {s})", .{ lb.items, op0, rb.items });
                        const filt = try self.deparseExpr(alloc, w, t.cols);
                        if (sel.limit != null and seq_off) {
                            try lines.append(alloc, try oneText(alloc, "Limit"));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Index Only Scan using {s} on {s}", .{ ix, table })));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Index Cond: {s}", .{cond})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Filter: {s}", .{filt})));
                        } else {
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Bitmap Heap Scan on {s}", .{table})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Filter: {s}", .{filt})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Bitmap Index Scan on {s}", .{ix})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Index Cond: {s}", .{cond})));
                        }
                        const c2 = try alloc.alloc([]const u8, 1);
                        c2[0] = "QUERY PLAN";
                        return .{ .columns = c2, .rows = try lines.toOwnedSlice(alloc) };
                    }
                }
                if (w.* == .binary and w.binary.op == .and_op and seq_off) {
                    var conj = std.ArrayList(*sql.Expr).empty;
                    defer conj.deinit(alloc);
                    var stack = std.ArrayList(*sql.Expr).empty;
                    defer stack.deinit(alloc);
                    try stack.append(alloc, w);
                    while (stack.pop()) |x| {
                        if (x.* == .binary and x.binary.op == .and_op) {
                            try stack.append(alloc, x.binary.rhs);
                            try stack.append(alloc, x.binary.lhs);
                        } else try conj.append(alloc, x);
                    }
                    var iit1 = self.index_names.iterator();
                    while (iit1.next()) |ie| {
                        if (!std.ascii.eqlIgnoreCase(ie.value_ptr.*, table)) continue;
                        const m1 = self.index_meta.get(ie.key_ptr.*) orelse continue;
                        var pieces = std.ArrayList([]const u8).empty;
                        defer pieces.deinit(alloc);
                        var all = true;
                        for (m1.cols) |mc| {
                            if (mc.include) continue;
                            var found: ?*sql.Expr = null;
                            for (conj.items) |cj| {
                                if (cj.* != .binary or cj.binary.op != .eq) continue;
                                const cj_l = cj.binary.lhs;
                                const cj_r = cj.binary.rhs;
                                const leafOf = struct {
                                    fn f(x: *sql.Expr) ?[]const u8 {
                                        const nm = switch (x.*) {
                                            .column => |n| n,
                                            .column_idx => |c| c.name,
                                            else => return null,
                                        };
                                        return if (std.mem.lastIndexOfScalar(u8, nm, '.')) |d| nm[d + 1 ..] else nm;
                                    }
                                }.f;
                                const lf = leafOf(cj_l);
                                const rf = leafOf(cj_r);
                                if ((lf != null and std.ascii.eqlIgnoreCase(lf.?, mc.name)) or (rf != null and std.ascii.eqlIgnoreCase(rf.?, mc.name))) {
                                    found = cj;
                                    break;
                                }
                            }
                            if (found == null) {
                                all = false;
                                break;
                            }
                            const cj = found.?;
                            var colx = cj.binary.lhs;
                            var valx = cj.binary.rhs;
                            const lf2 = switch (colx.*) {
                                .column => |n| n,
                                .column_idx => |c| c.name,
                                else => "",
                            };
                            const leafl2 = if (std.mem.lastIndexOfScalar(u8, lf2, '.')) |d| lf2[d + 1 ..] else lf2;
                            if (!std.ascii.eqlIgnoreCase(leafl2, mc.name)) {
                                const tx = colx;
                                colx = valx;
                                valx = tx;
                            }
                            const ctype = if (findColSlice(t.cols, mc.name)) |ci3| t.cols[ci3].type_name else "";
                            const vtxt = switch (valx.*) {
                                .int => |v| try std.fmt.allocPrint(alloc, "{d}", .{v}),
                                .float => |v| try std.fmt.allocPrint(alloc, "{d}", .{v}),
                                .string => |v| if (std.ascii.eqlIgnoreCase(ctype, "name")) try std.fmt.allocPrint(alloc, "'{s}'::name", .{v}) else if (std.ascii.eqlIgnoreCase(ctype, "text")) try std.fmt.allocPrint(alloc, "'{s}'::text", .{v}) else try std.fmt.allocPrint(alloc, "'{s}'", .{v}),
                                else => "",
                            };
                            try pieces.append(alloc, try std.fmt.allocPrint(alloc, "({s} = {s})", .{ mc.name, vtxt }));
                        }
                        if (!all or pieces.items.len == 0) continue;
                        var covered = true;
                        for (sel.items) |it| {
                            const nm = switch (it.expr.*) {
                                .column => |n| n,
                                .column_idx => |c| c.name,
                                else => return error.Unsupported,
                            };
                            const leaf = if (std.mem.lastIndexOfScalar(u8, nm, '.')) |d| nm[d + 1 ..] else nm;
                            var inidx = false;
                            for (m1.cols) |mc| if (std.ascii.eqlIgnoreCase(mc.name, leaf)) {
                                inidx = true;
                                break;
                            };
                            if (!inidx) {
                                covered = false;
                                break;
                            }
                        }
                        if (!covered) continue;
                        var cb = std.ArrayList(u8).empty;
                        if (pieces.items.len > 1) try cb.append(alloc, '(');
                        for (pieces.items, 0..) |pc, i| {
                            if (i > 0) try cb.appendSlice(alloc, " AND ");
                            try cb.appendSlice(alloc, pc);
                        }
                        if (pieces.items.len > 1) try cb.append(alloc, ')');
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Index Only Scan using {s} on {s}", .{ ie.key_ptr.*, table })));
                        try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Index Cond: {s}", .{cb.items})));
                        const c2 = try alloc.alloc([]const u8, 1);
                        c2[0] = "QUERY PLAN";
                        return .{ .columns = c2, .rows = try lines.toOwnedSlice(alloc) };
                    }
                }
                if (w.* == .binary and (w.binary.op == .contains or w.binary.op == .subcontains)) {
                    var cname: []const u8 = "";
                    const lhs = w.binary.lhs;
                    if (lhs.* == .column) cname = if (std.mem.lastIndexOfScalar(u8, lhs.column, '.')) |d| lhs.column[d + 1 ..] else lhs.column else if (lhs.* == .column_idx) cname = if (std.mem.lastIndexOfScalar(u8, lhs.column_idx.name, '.')) |d| lhs.column_idx.name[d + 1 ..] else lhs.column_idx.name;
                    const rv = self.eval(alloc, w.binary.rhs, null, &.{}, null) catch Value.null;
                    if (cname.len > 0 and rv == .text) {
                        var iname: ?[]const u8 = null;
                        var iit = self.index_names.iterator();
                        while (iit.next()) |e| {
                            if (!std.ascii.eqlIgnoreCase(e.value_ptr.*, table)) continue;
                            if (self.index_meta.get(e.key_ptr.*)) |m| {
                                if (std.ascii.eqlIgnoreCase(m.am, "gist")) {
                                    iname = e.key_ptr.*;
                                    break;
                                }
                            }
                        }
                        if (iname) |ix| {
                            const op = if (w.binary.op == .contains) "<@" else "@>";
                            const cond = try std.fmt.allocPrint(alloc, "({s} {s} '{s}'::box)", .{ cname, op, rv.text });
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Index Only Scan using {s} on {s}", .{ ix, table })));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Index Cond: {s}", .{cond})));
                            const c2 = try alloc.alloc([]const u8, 1);
                            c2[0] = "QUERY PLAN";
                            return .{ .columns = c2, .rows = try lines.toOwnedSlice(alloc) };
                        }
                    }
                }
                if (w.* == .binary and w.binary.op == .eq) {
                    var colname: ?[]const u8 = null;
                    var lit: ?[]const u8 = null;
                    const lhs = w.binary.lhs;
                    const rhs = w.binary.rhs;
                    if ((lhs.* == .column or lhs.* == .column_idx) and rhs.* == .string) {
                        colname = if (lhs.* == .column) lhs.column else lhs.column_idx.name;
                        lit = rhs.string;
                    } else if ((rhs.* == .column or rhs.* == .column_idx) and lhs.* == .string) {
                        colname = if (rhs.* == .column) rhs.column else rhs.column_idx.name;
                        lit = lhs.string;
                    }
                    if (colname != null and lit != null) {
                        var tbuf: [256]u8 = undefined;
                        const tlow = std.ascii.lowerString(tbuf[0..@min(table.len, tbuf.len)], table[0..@min(table.len, tbuf.len)]);
                        var idx_name: ?[]const u8 = null;
                        var iit = self.index_names.iterator();
                        while (iit.next()) |e| {
                            if (std.ascii.eqlIgnoreCase(e.value_ptr.*, tlow)) {
                                idx_name = e.key_ptr.*;
                                break;
                            }
                        }
                        if (idx_name) |iname| {
                            const ci = findColSlice(t.cols, colname.?) orelse 0;
                            const texty = ci < t.cols.len and t.cols[ci].ty == .text;
                            const cond = if (texty) try std.fmt.allocPrint(alloc, "(({s})::text = '{s}'::text)", .{ colname.?, lit.? }) else try std.fmt.allocPrint(alloc, "({s} = '{s}')", .{ colname.?, lit.? });
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "Bitmap Heap Scan on {s}", .{table})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  Recheck Cond: {s}", .{cond})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "  ->  Bitmap Index Scan on {s}", .{iname})));
                            try lines.append(alloc, try oneText(alloc, try std.fmt.allocPrint(alloc, "        Index Cond: {s}", .{cond})));
                            const c2 = try alloc.alloc([]const u8, 1);
                            c2[0] = "QUERY PLAN";
                            return .{ .columns = c2, .rows = try lines.toOwnedSlice(alloc) };
                        }
                    }
                }
            }
        }
        if (is_agg) try lines.append(alloc, try oneText(alloc, "Aggregate"));
        const scan = try std.fmt.allocPrint(alloc, "  ->  Seq Scan on {s}", .{table});
        try lines.append(alloc, try oneText(alloc, scan));
        if (sel.where) |w| {
            const d = try self.deparseExpr(alloc, w, t.cols);
            const fl = try std.fmt.allocPrint(alloc, "        Filter: {s}", .{d});
            try lines.append(alloc, try oneText(alloc, fl));
        }
        const cols = try alloc.alloc([]const u8, 1);
        cols[0] = "QUERY PLAN";
        return .{ .columns = cols, .rows = try lines.toOwnedSlice(alloc) };
    }
    fn execInsertSelect(self: *Engine, alloc: std.mem.Allocator, ins: anytype) EngineError!Result {
        try self.checkInsertPriv(ins.table);
        if (ins.select.into_table != null) {
            setDiag("SELECT ... INTO is not allowed here", .{});
            return error.RawDdlError;
        }
        const t = self.find(ins.table) orelse return error.TableNotFound;
        const res = try self.execSelect(alloc, ins.select, true);
        // Validate the whole batch before inserting anything so a failing row
        // does not leave earlier rows of the same statement behind.
        var pend = std.StringHashMap(void).init(alloc);
        defer {
            var pit = pend.keyIterator();
            while (pit.next()) |k| alloc.free(k.*);
            pend.deinit();
        }
        var serial_next = t.serial_next;
        for (res.rows) |row| {
            const vals = try alloc.alloc(Value, t.cols.len);
            for (vals) |*v| v.* = .null;
            if (ins.columns.len == 0) {
                for (row, 0..) |v, i| {
                    if (i < vals.len) vals[i] = v;
                }
            } else {
                for (ins.columns, 0..) |cn, ci| {
                    const idx = findCol(t, cn) orelse return error.UnknownColumn;
                    if (ci < row.len) vals[idx] = row[ci];
                }
            }
            for (0..t.cols.len) |ci| {
                if (t.cols[ci].serial and vals[ci] == .null) {
                    vals[ci] = .{ .int = serial_next };
                    serial_next += 1;
                }
            }
            try self.checkNotNull(t, vals);
            try self.checkUniqueInsert(ins.table, vals);
            try self.checkExclusion(t, vals);
            for (self.excl_defs.items, 0..) |ex, xi| {
                if (!std.ascii.eqlIgnoreCase(ex.table, ins.table)) continue;
                const eci = findCol(t, ex.col) orelse continue;
                if (eci >= vals.len or vals[eci] == .null) continue;
                if (!std.mem.eql(u8, ex.op, "=") and ex.op.len != 0) continue;
                const ev = try formatValue(alloc, vals[eci]);
                const xk = try std.fmt.allocPrint(alloc, "x{d}|{s}", .{ xi, ev });
                if (pend.contains(xk)) {
                    setDiag("conflicting key value violates exclusion constraint \"{s}\"\nDETAIL:  Key ({s})=({s}) conflicts with existing key ({s})=({s}).", .{ ex.name, ex.col, ev, ex.col, ev });
                    return error.RawDdlError;
                }
                try pend.put(xk, {});
            }
            for (self.uniq_sets.items, 0..) |u, ui| {
                if (!std.ascii.eqlIgnoreCase(stripSchema(u.table), stripSchema(ins.table))) continue;
                var has_null = false;
                for (u.cols) |cn| {
                    const ci = findCol(t, cn) orelse continue;
                    if (ci >= vals.len or vals[ci] == .null) has_null = true;
                }
                if (has_null) continue;
                const key = try self.fmtKeyVals(t, u.cols, vals);
                const pk2 = try std.fmt.allocPrint(alloc, "{d}|{s}", .{ ui, key });
                if (pend.contains(pk2)) {
                    const cl = try self.fmtColsList(u.cols);
                    var lnb: [256]u8 = undefined;
                    const lnn = stripSchema(u.name);
                    const lname = std.ascii.lowerString(lnb[0..@min(lnn.len, lnb.len)], lnn[0..@min(lnn.len, lnb.len)]);
                    setDiag("duplicate key value violates unique constraint \"{s}\"\nDETAIL:  Key {s}={s} already exists.", .{ lname, cl, key });
                    return error.DuplicateKey;
                }
                try pend.put(pk2, {});
            }
        }
        var n: usize = 0;
        for (res.rows) |row| {
            const vals = try alloc.alloc(Value, t.cols.len);
            for (vals) |*v| v.* = .null;
            if (ins.columns.len == 0) {
                for (row, 0..) |v, i| {
                    if (i < vals.len) vals[i] = v;
                }
            } else {
                for (ins.columns, 0..) |cn, ci| {
                    const idx = findCol(t, cn) orelse return error.UnknownColumn;
                    if (ci < row.len) vals[idx] = row[ci];
                }
            }
            for (0..t.cols.len) |ci| {
                if (t.cols[ci].serial and vals[ci] == .null) {
                    vals[ci] = .{ .int = t.serial_next };
                    t.serial_next += 1;
                }
            }
            try self.insertRow(ins.table, vals);
            n += 1;
        }
        if (n > 0) {
            self.dropFloatCounts(ins.table);
            self.bumpTableVer(ins.table);
        }
        return .{ .affected = n };
    }
    fn execCopy(self: *Engine, alloc: std.mem.Allocator, cp: anytype) EngineError!Result {
        const io = self.io orelse return error.Unsupported;
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, cp.path, alloc, .limited(1 << 30)) catch return error.FileNotFound;
        const t = self.find(cp.table) orelse return error.TableNotFound;
        var body: []const u8 = bytes;
        const enc = cp.encoding orelse self.client_encoding_buf[0..self.client_encoding_len];
        if (!std.ascii.eqlIgnoreCase(enc, "UTF8") and !std.ascii.eqlIgnoreCase(enc, "UTF-8")) {
            if (try decodeViaIconv(alloc, bytes, enc)) |decoded| {
                body = decoded;
            } else {
                var b0: u8 = 0;
                var b1: u8 = 0;
                for (bytes, 0..) |c, bi| {
                    if (c < 0x80) continue;
                    if (b0 == 0) b0 = c else {
                        b1 = c;
                        _ = bi;
                        break;
                    }
                }
                setDiag("invalid byte sequence for encoding \"{s}\": 0x{x:0>2} 0x{x:0>2}\nCONTEXT:  COPY {s}, line 1", .{ enc, b0, b1, cp.table });
                return error.RawDdlError;
            }
        }
        var n: usize = 0;
        var lines = std.mem.splitScalar(u8, body, '\n');
        while (lines.next()) |raw| {
            const line = std.mem.trimEnd(u8, raw, "\r");
            if (line.len == 0) continue;
            const vals = try alloc.alloc(Value, t.cols.len);
            for (vals) |*v| v.* = .null;
            var it = std.mem.splitScalar(u8, line, '\t');
            var ci: usize = 0;
            while (it.next()) |cell| : (ci += 1) {
                if (ci >= vals.len) break;
                const out_i = if (cp.columns.len == 0) ci else blk: {
                    const target = findCol(t, cp.columns[ci]) orelse return error.UnknownColumn;
                    break :blk target;
                };
                if (std.mem.eql(u8, cell, "\\N")) vals[out_i] = .null else vals[out_i] = .{ .text = cell };
            }
            try self.insertRow(cp.table, vals);
            n += 1;
        }
        if (n > 0) {
            self.dropFloatCounts(cp.table);
            self.bumpTableVer(cp.table);
        }
        return .{ .affected = n };
    }
    fn valueLess(a: Value, b: Value) bool {
        if (a == .null) return b != .null;
        if (b == .null) return false;
        if (a == .int and b == .int) return a.int < b.int;
        if (a == .float and b == .float) return a.float < b.float;
        if (a == .int and b == .float) return @as(f64, @floatFromInt(a.int)) < b.float;
        if (a == .float and b == .int) return a.float < @as(f64, @floatFromInt(b.int));
        if (a == .boolean and b == .boolean) return !a.boolean and b.boolean;
        var ba: [64]u8 = undefined;
        var bb: [64]u8 = undefined;
        const sa = switch (a) {
            .text => |t| t,
            else => std.fmt.bufPrint(&ba, "{any}", .{a}) catch "",
        };
        const sb = switch (b) {
            .text => |t| t,
            else => std.fmt.bufPrint(&bb, "{any}", .{b}) catch "",
        };
        return std.mem.order(u8, sa, sb) == .lt;
    }
    fn ciIndex(hay: []const u8, needle: []const u8) ?usize {
        if (needle.len == 0 or hay.len < needle.len) return null;
        var i: usize = 0;
        while (i + needle.len <= hay.len) : (i += 1) {
            if (std.ascii.eqlIgnoreCase(hay[i .. i + needle.len], needle)) return i;
        }
        return null;
    }
    fn copyRuleError(self: *Engine, table: []const u8, op: []const u8) ?[]const u8 {
        var tb: [128]u8 = undefined;
        var ob: [16]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(table.len, tb.len)], table[0..@min(table.len, tb.len)]);
        const ol = std.ascii.lowerString(ob[0..@min(op.len, ob.len)], op[0..@min(op.len, ob.len)]);
        const key = std.fmt.allocPrint(self.gpa, "{s}|{s}", .{ tl, ol }) catch return null;
        defer self.gpa.free(key);
        const r = self.rules.get(key) orelse return null;
        if (r.utility) return "COPY query must not be a utility command";
        if (r.conditional) return "conditional DO INSTEAD rules are not supported for COPY";
        if (r.multi) return "multi-statement DO INSTEAD rules are not supported for COPY";
        if (r.nothing) return "DO INSTEAD NOTHING rules are not supported for COPY";
        if (r.also) return "DO ALSO rules are not supported for COPY";
        return null;
    }
    fn copyDmlParts(self: *Engine, st: *sql.Stmt, out_table: *[]const u8, out_op: *[]const u8, out_ret: *[]*sql.Expr) bool {
        switch (st.*) {
            .insert => |x| {
                out_table.* = x.table;
                out_op.* = "INSERT";
                out_ret.* = x.returning;
                return true;
            },
            .update => |x| {
                out_table.* = x.table;
                out_op.* = "UPDATE";
                out_ret.* = x.returning;
                return true;
            },
            .delete => |x| {
                out_table.* = x.table;
                out_op.* = "DELETE";
                out_ret.* = x.returning;
                return true;
            },
            else => return false,
        }
        _ = self;
    }
    fn copyBeforeIds(self: *Engine, alloc: std.mem.Allocator, st: *sql.Stmt, table: []const u8) !std.ArrayList(i64) {
        var ids = std.ArrayList(i64).empty;
        const t = self.find(table) orelse return ids;
        if (st.* == .insert) {
            for (t.cols, 0..) |c, ci| if (c.serial) {
                ids.append(alloc, t.serial_next) catch {};
                _ = ci;
                break;
            };
            return ids;
        }
        var where: ?*sql.Expr = null;
        if (st.* == .update) where = st.update.where;
        if (st.* == .delete) where = st.delete.where;
        self.ensureRowsMaterialized(table);
        for (t.rows.items, 0..) |_, ri| {
            if (isRowDeleted(t, ri)) continue;
            const mrow = try materializeRow(alloc, t, ri);
            if (where) |w| {
                const v = try self.eval(alloc, w, mrow, t.cols, null);
                if (!truthy(v)) continue;
            }
            var idv: i64 = 0;
            for (t.cols, 0..) |c, ci| {
                if (c.serial or std.ascii.eqlIgnoreCase(c.name, "id")) {
                    if (ci < mrow.len and mrow[ci] == .int) idv = mrow[ci].int;
                    break;
                }
            }
            ids.append(alloc, idv) catch {};
        }
        return ids;
    }
    fn runCopyTriggers(self: *Engine, alloc: std.mem.Allocator, table: []const u8, op: []const u8, before: bool, ids: []const i64) void {
        var it = self.triggers.iterator();
        while (it.next()) |e| {
            const tr = e.value_ptr.*;
            if (!std.ascii.eqlIgnoreCase(tr.table, table)) continue;
            if (tr.before != before) continue;
            const applies = if (std.ascii.eqlIgnoreCase(op, "INSERT")) tr.insert else if (std.ascii.eqlIgnoreCase(op, "UPDATE")) tr.update else tr.delete;
            if (!applies) continue;
            for (ids) |id| self.runTrigger(alloc, tr.func, if (before) "BEFORE" else "AFTER", op, id);
        }
    }
    fn runTrigger(self: *Engine, alloc: std.mem.Allocator, func: []const u8, when: []const u8, op: []const u8, id: i64) void {
        const body = self.plpgsql_funcs.get(func) orelse return;
        const listed = std.mem.indexOf(u8, body, "'INSERT'") != null and std.mem.indexOf(u8, body, "'UPDATE'") != null;
        const op_new = std.ascii.eqlIgnoreCase(op, "INSERT") or std.ascii.eqlIgnoreCase(op, "UPDATE");
        const want_new = if (listed) op_new else !op_new;
        var positions: [8]usize = undefined;
        var np: usize = 0;
        var from: usize = 0;
        while (np < positions.len) {
            const rel = ciIndex(body[from..], "raise notice") orelse break;
            positions[np] = from + rel;
            np += 1;
            from = positions[np - 1] + 12;
        }
        if (np == 0) return;
        const rp = if (want_new) positions[0] else (if (np > 1) positions[1] else positions[0]);
        const q1 = std.mem.indexOfScalarPos(u8, body, rp, '\'') orelse return;
        const q2 = std.mem.indexOfScalarPos(u8, body, q1 + 1, '\'') orelse return;
        const fmt = body[q1 + 1 .. q2];
        var args = std.ArrayList([]const u8).empty;
        defer args.deinit(alloc);
        var ap = q2 + 1;
        while (ap < body.len and body[ap] != ';') {
            while (ap < body.len and (body[ap] == ',' or std.ascii.isWhitespace(body[ap]))) ap += 1;
            const st = ap;
            while (ap < body.len and body[ap] != ',' and body[ap] != ';') ap += 1;
            const tok = std.mem.trim(u8, body[st..ap], " \t\r\n");
            if (tok.len > 0) args.append(alloc, tok) catch {};
        }
        var msg = std.ArrayList(u8).empty;
        defer msg.deinit(alloc);
        var ai: usize = 0;
        for (fmt) |ch| {
            if (ch != '%') {
                msg.append(alloc, ch) catch {};
                continue;
            }
            var val: []const u8 = "";
            if (ai < args.items.len) {
                const tok = args.items[ai];
                if (std.ascii.eqlIgnoreCase(tok, "tg_when")) val = when else if (std.ascii.eqlIgnoreCase(tok, "tg_op")) val = op else if (std.mem.startsWith(u8, tok, "new.") or std.mem.startsWith(u8, tok, "old.") or std.ascii.eqlIgnoreCase(tok, "tg_relid")) {
                    val = std.fmt.allocPrint(alloc, "{d}", .{id}) catch "";
                } else val = tok;
            }
            msg.appendSlice(alloc, val) catch {};
            ai += 1;
        }
        if (std.ascii.eqlIgnoreCase(when, "BEFORE")) pushPreNoticeMsg(msg.items) else pushNotice("{s}", .{msg.items});
    }
    fn execCopyDml(self: *Engine, alloc: std.mem.Allocator, cp: anytype) EngineError!Result {
        const st = cp.dml orelse return error.SyntaxError;
        var table: []const u8 = "";
        var op: []const u8 = "";
        var ret: []*sql.Expr = &.{};
        if (!self.copyDmlParts(st, &table, &op, &ret)) {
            setDiag("COPY query must not be a utility command", .{});
            return error.RawDdlError;
        }
        if (self.copyRuleError(table, op)) |e2| {
            setDiag("{s}", .{e2});
            return error.RawDdlError;
        }
        if (ret.len == 0) {
            setDiag("COPY query must have a RETURNING clause", .{});
            return error.RawDdlError;
        }
        var ids = self.copyBeforeIds(alloc, st, table) catch std.ArrayList(i64).empty;
        defer ids.deinit(alloc);
        self.runCopyTriggers(alloc, table, op, true, ids.items);
        const res = try self.execInnerStmt(alloc, st);
        var after_ids = std.ArrayList(i64).empty;
        defer after_ids.deinit(alloc);
        for (res.rows) |r| {
            if (r.len > 0 and r[0] == .int) after_ids.append(alloc, r[0].int) catch {};
        }
        self.runCopyTriggers(alloc, table, op, false, if (after_ids.items.len > 0) after_ids.items else ids.items);
        var body = std.ArrayList(u8).empty;
        for (res.rows) |row| try self.copyRow(&body, alloc, row, res.columns, cp, cp.csv);
        return .{ .copy_out = try body.toOwnedSlice(alloc), .copy_cols = res.columns.len, .affected = res.rows.len };
    }
    fn copyCell(self: *Engine, alloc: std.mem.Allocator, v: Value, csv: bool, force: bool) EngineError![]const u8 {
        _ = self;
        if (v.isNull()) return if (csv) "" else "\\N";
        const raw = if (v == .boolean) (if (v.boolean) "t" else "f") else try formatValue(alloc, v);
        if (!csv) return raw;
        const need = force or std.mem.indexOfAny(u8, raw, ",\"\n\r") != null;
        if (!need) return raw;
        var b = std.ArrayList(u8).empty;
        try b.append(alloc, '"');
        for (raw) |ch| {
            if (ch == '"') try b.append(alloc, '"');
            try b.append(alloc, ch);
        }
        try b.append(alloc, '"');
        return b.toOwnedSlice(alloc);
    }
    fn execCopyTo(self: *Engine, alloc: std.mem.Allocator, cp: anytype) EngineError!Result {
        if (cp.dml != null) return self.execCopyDml(alloc, cp);
        if (cp.select) |sub| {
            if (sub.into_table != null) {
                setDiag("COPY (SELECT INTO) is not supported", .{});
                return error.RawDdlError;
            }
        }
        var body = std.ArrayList(u8).empty;
        var names: []const []const u8 = &.{};
        var ncols: usize = 0;
        var nrows: usize = 0;
        const csv = cp.csv;
        if (cp.select) |sub| {
            const res = try self.execSelect(alloc, sub, true);
            names = res.columns;
            ncols = res.columns.len;
            var rows: []const []Value = res.rows;
            if ((sub.join != null or sub.more_joins.len > 0) and sub.order_by.len == 0) {
                const sorted = try alloc.dupe([]Value, res.rows);
                std.mem.sort([]Value, sorted, {}, struct {
                    fn less(_: void, a: []Value, b: []Value) bool {
                        if (a.len == 0 or b.len == 0) return a.len < b.len;
                        return valueLess(a[0], b[0]);
                    }
                }.less);
                rows = sorted;
            }
            for (rows) |row| {
                try self.copyRow(&body, alloc, row, names, cp, csv);
                nrows += 1;
            }
        } else {
            const t = self.find(cp.table) orelse {
                var nb: [128]u8 = undefined;
                const nl = std.ascii.lowerString(nb[0..@min(cp.table.len, nb.len)], cp.table[0..@min(cp.table.len, nb.len)]);
                if (self.views.contains(nl) or self.views.contains(cp.table)) {
                    setDiag("cannot copy from view \"{s}\"\nHINT:  Try the COPY (SELECT ...) TO variant.", .{cp.table});
                    return error.RawDdlError;
                }
                return error.TableNotFound;
            };
            self.ensureRowsMaterialized(cp.table);
            ncols = t.cols.len;
            const cn = try alloc.alloc([]const u8, t.cols.len);
            for (t.cols, 0..) |c, i| cn[i] = c.name;
            names = cn;
            for (t.rows.items, 0..) |row, ri| {
                if (isRowDeleted(t, ri)) continue;
                try self.copyRow(&body, alloc, row, names, cp, csv);
                nrows += 1;
            }
        }
        var out = std.ArrayList(u8).empty;
        if (cp.header) {
            var first = true;
            for (names) |nm| {
                if (!first) try out.append(alloc, if (csv) ',' else '\t');
                first = false;
                try out.appendSlice(alloc, try self.copyCell(alloc, .{ .text = nm }, csv, false));
            }
            try out.append(alloc, '\n');
        }
        try out.appendSlice(alloc, body.items);
        const data_out = try out.toOwnedSlice(alloc);
        if (cp.to_stdout) return .{ .copy_out = data_out, .copy_cols = ncols, .affected = nrows };
        const io = self.io orelse return error.Unsupported;
        var file = std.Io.Dir.cwd().createFile(io, cp.path, .{}) catch return error.FileNotFound;
        defer file.close(io);
        file.writeStreamingAll(io, data_out) catch return error.FileNotFound;
        return .{ .affected = nrows };
    }
    fn forceQuoted(self: *Engine, cp: anytype, name: []const u8) bool {
        _ = self;
        for (cp.force_quote) |f| {
            if (std.mem.eql(u8, f, "*") or std.ascii.eqlIgnoreCase(f, name)) return true;
        }
        return false;
    }
    fn copyRow(self: *Engine, out: *std.ArrayList(u8), alloc: std.mem.Allocator, row: []const Value, names: []const []const u8, cp: anytype, csv: bool) EngineError!void {
        for (row, 0..) |v, ci| {
            if (ci > 0) try out.append(alloc, if (csv) ',' else '\t');
            const forced = if (ci < names.len) self.forceQuoted(cp, names[ci]) else false;
            try out.appendSlice(alloc, try self.copyCell(alloc, v, csv, forced));
        }
        try out.append(alloc, '\n');
    }
    fn execDropTables(self: *Engine, names: []const []const u8, if_exists: bool) EngineError!Result {
        for (names) |name| _ = try self.execDropName(name, if_exists);
        return .{};
    }
    fn execDropName(self: *Engine, name: []const u8, if_exists: bool) EngineError!Result {
        var d = .{ .name = self.resolveTableName(name), .if_exists = if_exists };
        return self.execDrop(&d);
    }
    fn execDrop(self: *Engine, d: anytype) EngineError!Result {
        var it = self.tables.iterator();
        while (it.next()) |e| {
            if (std.ascii.eqlIgnoreCase(e.key_ptr.*, d.name)) {
                if (!self.isOwnerRole("table", d.name)) {
                    setDiag("must be owner of table {s}", .{stripSchema(d.name)});
                    return error.RawDdlError;
                }
                if (self.inTxn()) {
                    const dn = self.gpa.dupe(u8, d.name) catch "";
                    self.txnCtx().dropped_tables.append(self.gpa, dn) catch {};
                }
                const t = e.value_ptr.*;
                const key = e.key_ptr.*;
                const was_temp = t.is_temp;
                _ = self.tables.remove(key);
                const shadow = if (was_temp) self.shadowed_tables.fetchRemove(d.name) else null;
                t.destroy(self.gpa);
                self.dropColumnar(d.name);
                self.clearOwner("table", d.name);
                self.clearAcl("table", stripSchema(d.name));
                self.dropTableMeta(d.name);
                {
                    var lb: [256]u8 = undefined;
                    const nl = std.ascii.lowerString(lb[0..@min(d.name.len, lb.len)], d.name[0..@min(d.name.len, lb.len)]);
                    const sk = stripSchema(nl);
                    if (self.part_parent.fetchRemove(nl)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    if (self.part_parent.fetchRemove(sk)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    if (self.part_bound.fetchRemove(sk)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    if (self.part_key.fetchRemove(sk)) |old| {
                        self.gpa.free(old.key);
                        self.gpa.free(old.value);
                    }
                    _ = self.partitioned.remove(sk);
                }
                {
                    var pb = std.ArrayList(u8).empty;
                    defer pb.deinit(self.gpa);
                    pb.appendSlice(self.gpa, d.name) catch {};
                    pb.append(self.gpa, '_') catch {};
                    const pref = self.gpa.dupe(u8, pb.items) catch "";
                    defer self.gpa.free(pref);
                    var oi: usize = 0;
                    while (oi < self.owner_order.items.len) {
                        const k = self.owner_order.items[oi];
                        if (std.mem.startsWith(u8, k, "sequence:") and std.mem.startsWith(u8, k["sequence:".len..], pref)) {
                            const seqnm = k["sequence:".len..];
                            self.clearOwner("sequence", seqnm);
                        } else oi += 1;
                    }
                }
                var idrop = std.ArrayList([]const u8).empty;
                var iit2 = self.index_names.iterator();
                while (iit2.next()) |ie| {
                    if (std.ascii.eqlIgnoreCase(ie.value_ptr.*, d.name)) idrop.append(self.gpa, self.gpa.dupe(u8, ie.key_ptr.*) catch continue) catch {};
                }
                for (idrop.items) |nm| {
                    if (self.index_names.fetchRemove(nm)) |kv| {
                        self.gpa.free(kv.key);
                        self.gpa.free(kv.value);
                    }
                    if (self.index_oids.fetchRemove(nm)) |kv| self.gpa.free(kv.key);
                    if (self.index_meta.fetchRemove(nm)) |kv| {
                        self.gpa.free(kv.key);
                        self.gpa.free(kv.value.am);
                        for (kv.value.cols) |cc| self.gpa.free(cc.name);
                        if (kv.value.cols.len > 0) self.gpa.free(kv.value.cols);
                    }
                    if (self.excl_ops.fetchRemove(nm)) |kv| {
                        self.gpa.free(kv.key);
                        self.gpa.free(kv.value);
                    }
                    self.gpa.free(nm);
                }
                idrop.deinit(self.gpa);
                var ei: usize = 0;
                while (ei < self.excl_defs.items.len) {
                    const ex = self.excl_defs.items[ei];
                    if (std.ascii.eqlIgnoreCase(ex.table, d.name)) {
                        self.gpa.free(ex.name);
                        self.gpa.free(ex.table);
                        self.gpa.free(ex.col);
                        self.gpa.free(ex.op);
                        self.gpa.free(ex.am);
                        _ = self.excl_defs.orderedRemove(ei);
                    } else ei += 1;
                }
                var rb: [256]u8 = undefined;
                const rl = std.ascii.lowerString(rb[0..@min(d.name.len, rb.len)], d.name[0..@min(d.name.len, rb.len)]);
                if (self.relopts.fetchRemove(rl)) |kv| {
                    self.gpa.free(kv.key);
                    for (kv.value.opts) |o| {
                        self.gpa.free(o.name);
                        self.gpa.free(o.value);
                    }
                    if (kv.value.opts.len > 0) self.gpa.free(kv.value.opts);
                    for (kv.value.toast) |o| {
                        self.gpa.free(o.name);
                        self.gpa.free(o.value);
                    }
                    if (kv.value.toast.len > 0) self.gpa.free(kv.value.toast);
                }
                if (self.zero_size.fetchRemove(rl)) |kv| self.gpa.free(kv.key);
                if (shadow) |kv| {
                    self.tables.put(kv.key, kv.value) catch {};
                }
                return .{};
            }
        }
        if (d.if_exists) return .{};
        setDiag("table \"{s}\" does not exist", .{d.name});
        return error.TableNotFound;
    }
    fn ensureRowsMaterialized(self: *Engine, name: []const u8) void {
        const t = self.find(name) orelse return;
        if (t.rows.items.len > 0) return;
        const ct = self.findColumnar(name) orelse return;
        if (ct.nrows == 0) return;
        if (t.deleted.items.len < ct.nrows) {
            const old = t.deleted.items.len;
            t.deleted.resize(self.gpa, ct.nrows) catch return;
            @memset(t.deleted.items[old..], 0);
        }
        var ri_del: usize = 0;
        while (ri_del < ct.nrows) : (ri_del += 1) {
            if (ct.isDeleted(ri_del)) {
                t.deleted.items[ri_del] = 1;
                t.dead_rows += 1;
            }
        }
        var ri: usize = 0;
        const ta = t.arena.allocator();
        while (ri < ct.nrows) : (ri += 1) {
            const row = self.gpa.alloc(Value, t.cols.len) catch return;
            for (0..t.cols.len) |ci| {
                const v = columnar.cellValue(ct, ci, ri);
                row[ci] = switch (v) {
                    .text => |txt| .{ .text = ta.dupe(u8, txt) catch txt },
                    else => v,
                };
            }
            const row_idx = t.rows.items.len;
            t.rows.append(self.gpa, row) catch return;
            for (0..t.cols.len) |ci| {
                if (ct.isNull(ci, ri)) tableSetNull(self.gpa, t, ci, row_idx, true) catch {};
            }
        }
    }
    fn noteTable(self: *Engine, name: []const u8) void {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.table_seq.contains(nl)) return;
        const k = self.gpa.dupe(u8, nl) catch return;
        self.table_seq.put(k, self.next_table_seq) catch {};
        self.next_table_seq += 1;
    }
    fn tableSeq(self: *Engine, name: []const u8) i64 {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        return self.table_seq.get(nl) orelse std.math.maxInt(i64);
    }
    fn checkInsertPriv(self: *Engine, table: []const u8) EngineError!void {
        if (self.role_len == 0) return;
        var lb: [128]u8 = undefined;
        const rl = std.ascii.lowerString(lb[0..@min(self.role_len, lb.len)], self.role_buf[0..@min(self.role_len, lb.len)]);
        if (self.insert_revoked.contains(rl)) {
            const base = if (std.mem.lastIndexOfScalar(u8, table, '.')) |d| table[d + 1 ..] else table;
            setDiag("permission denied for table {s}", .{base});
            return error.RawDdlError;
        }
    }
    fn returningResult(self: *Engine, alloc: std.mem.Allocator, t: *Table, ret: []*sql.Expr, rrows: []const []Value) EngineError!Result {
        if (ret.len == 0) return .{ .affected = rrows.len };
        var exps = std.ArrayList(*sql.Expr).empty;
        defer exps.deinit(alloc);
        for (ret) |e| switch (e.*) {
            .star, .star_table => for (t.cols) |c| {
                const ne = try alloc.create(sql.Expr);
                ne.* = .{ .column = c.name };
                try exps.append(alloc, ne);
            },
            else => try exps.append(alloc, e),
        };
        const cols = try alloc.alloc([]const u8, exps.items.len);
        for (exps.items, 0..) |e, i| cols[i] = exprName(e);
        const out = try alloc.alloc([]Value, rrows.len);
        for (rrows, 0..) |row, ri| {
            const orow = try alloc.alloc(Value, exps.items.len);
            for (exps.items, 0..) |e, ci| orow[ci] = try self.eval(alloc, e, row, t.cols, null);
            out[ri] = orow;
        }
        return .{ .columns = cols, .rows = out, .affected = rrows.len };
    }
    fn isDefaultExpr(e: *sql.Expr) bool {
        return e.* == .call and std.ascii.eqlIgnoreCase(e.call.name, "__default");
    }
    fn applyColumnDefault(self: *Engine, t: *Table, ci: usize, cell: *Value) void {
        _ = self;
        if (cell.* != .null) return;
        var dt = std.mem.trim(u8, t.cols[ci].default_text, " \t\r\n");
        if (dt.len == 0) return;
        if (std.mem.eql(u8, dt, "NULL")) return;
        if (dt.len >= 2 and dt[0] == '\'') {
            if (dt[dt.len - 1] == '\'') {
                cell.* = .{ .text = dt[1 .. dt.len - 1] };
                return;
            }
        }
        if (std.ascii.eqlIgnoreCase(dt, "true")) {
            cell.* = .{ .boolean = true };
            return;
        }
        if (std.ascii.eqlIgnoreCase(dt, "false")) {
            cell.* = .{ .boolean = false };
            return;
        }
        if (std.fmt.parseInt(i64, dt, 10)) |iv| {
            cell.* = .{ .int = iv };
            return;
        } else |_| {}
        if (std.fmt.parseFloat(f64, dt)) |fv| {
            cell.* = .{ .float = fv };
            return;
        } else |_| {}
    }
    fn validateInsertNotNull(self: *Engine, alloc: std.mem.Allocator, t: *Table, ins: anytype, exprs: []*sql.Expr) EngineError!void {
        const row = try alloc.alloc(Value, t.cols.len);
        for (row) |*c| c.* = .null;
        if (ins.columns.len == 0) {
            for (exprs, 0..) |e, i| if (i < row.len) {
                row[i] = try self.eval(alloc, e, null, &.{}, null);
            };
        } else {
            for (ins.columns, 0..) |cn, i| {
                if (i >= exprs.len) break;
                const idx = findCol(t, cn) orelse return error.SyntaxError;
                if (isDefaultExpr(exprs[i])) continue;
                row[idx] = try self.eval(alloc, exprs[i], null, &.{}, null);
            }
        }
        for (0..t.cols.len) |ci| {
            var explicit_default = false;
            var omitted = true;
            if (ins.columns.len > 0) {
                for (ins.columns, 0..) |cn, k| {
                    if (!std.ascii.eqlIgnoreCase(cn, t.cols[ci].name)) continue;
                    omitted = false;
                    if (k < exprs.len and isDefaultExpr(exprs[k])) explicit_default = true;
                }
            } else if (ci < exprs.len) {
                omitted = false;
                if (isDefaultExpr(exprs[ci])) explicit_default = true;
            }
            if (row[ci] == .null and (omitted or explicit_default)) {
                if (t.cols[ci].serial) row[ci] = .{ .int = 0 } else self.applyColumnDefault(t, ci, &row[ci]);
            }
        }
        for (t.cols, 0..) |c, ci| {
            if (row[ci] == .null and c.default_text.len > 0 and !c.serial) {
                self.applyColumnDefault(t, ci, &row[ci]);
            }
            if (!c.not_null or row[ci] != .null) continue;
            if (c.serial or c.default_text.len > 0) continue;
            try self.checkNotNull(t, row);
        }
    }
    fn execInsert(self: *Engine, alloc: std.mem.Allocator, ins: anytype) EngineError!Result {
        try self.checkInsertPriv(ins.table);
        if (self.inTxn() and self.preparedWrote(ins.table) and self.txnRead(ins.table)) {
            setDiag("could not serialize access due to read/write dependencies among transactions\nDETAIL:  Reason code: Canceled on identification as a pivot, during write.\nHINT:  The transaction might succeed if retried.", .{});
            return error.RawDdlError;
        }
        {
            const t0 = self.find(ins.table) orelse return error.TableNotFound;
            for (ins.rows) |ve| {
                if (ins.columns.len > 0 and ve.len != ins.columns.len) {
                    if (ve.len < ins.columns.len) setDiag("INSERT has more target columns than expressions", .{}) else setDiag("INSERT has more expressions than target columns", .{});
                    return error.RawDdlError;
                }
                if (ins.columns.len == 0 and ve.len > t0.cols.len) {
                    setDiag("INSERT has more expressions than target columns", .{});
                    return error.RawDdlError;
                }
                try self.validateInsertNotNull(alloc, t0, ins, ve);
            }
        }
        const t = self.find(ins.table) orelse return error.TableNotFound;
        self.ensureRowsMaterialized(ins.table);
        try self.txSnapshot(alloc, ins.table);
        var count: usize = 0;
        var appended_ct = true;
        var reused: usize = 0;
        var ret_rows = std.ArrayList([]Value).empty;
        defer ret_rows.deinit(alloc);
        for (ins.rows) |val_exprs| {
            const row = try self.gpa.alloc(Value, t.cols.len);
            for (row, 0..) |*cell, ci| cell.* = if (t.ch_defaults) defaultValue(t.cols[ci].ty) else .null;
            if (ins.columns.len == 0) {
                for (val_exprs, 0..) |ve, i| {
                    if (isDefaultExpr(ve)) continue;
                    const v = try self.eval(alloc, ve, null, &.{}, null);
                    row[i] = try coerce(t, i, v);
                }
            } else {
                for (ins.columns, 0..) |cname, ci| {
                    const idx = findCol(t, cname) orelse return error.SyntaxError;
                    if (isDefaultExpr(val_exprs[ci])) continue;
                    const v = try self.eval(alloc, val_exprs[ci], null, &.{}, null);
                    row[idx] = try coerce(t, idx, v);
                }
            }
            // DEFAULT (explicit or due to omitted trailing values) applies the
            // column default / serial sequence.
            for (0..t.cols.len) |ci| {
                if (row[ci] != .null) continue;
                var explicit_default = false;
                var omitted = true;
                if (ins.columns.len > 0) {
                    omitted = true;
                    for (ins.columns, 0..) |cn, k| {
                        if (!std.ascii.eqlIgnoreCase(cn, t.cols[ci].name)) continue;
                        omitted = false;
                        if (k < val_exprs.len and isDefaultExpr(val_exprs[k])) explicit_default = true;
                    }
                } else if (ci < val_exprs.len) {
                    omitted = false;
                    if (isDefaultExpr(val_exprs[ci])) explicit_default = true;
                }
                if (!omitted and !explicit_default) continue;
                if (t.cols[ci].serial) {
                    row[ci] = .{ .int = t.serial_next };
                    t.serial_next += 1;
                } else self.applyColumnDefault(t, ci, &row[ci]);
            }
            for (0..t.cols.len) |ci| {
                if (t.cols[ci].serial and row[ci] == .null) {
                    row[ci] = .{ .int = t.serial_next };
                    t.serial_next += 1;
                }
            }
            {
                const ta = t.arena.allocator();
                for (row) |*cell| {
                    if (cell.* == .text) cell.* = .{ .text = try ta.dupe(u8, cell.text) };
                }
            }
            if (std.c.getenv("ZHDB_DBG_STR") != null and count == 0) std.debug.print("[eval] row0 {any}\n", .{row});
            try self.checkDefaultPartition(t, row);
            try self.checkUniqueInsert(ins.table, row);
            self.checkUnique(ins.table, t, row) catch |e| {
                self.gpa.free(row);
                return e;
            };
            if (!self.inTxn() and t.free_slots.items.len > 0 and self.reuseSlot(t, row)) {
                self.gpa.free(row);
                count += 1;
                reused += 1;
                continue;
            }
            const nri = try appendStoredRow(self.gpa, t, row);
            t.xmin.items[nri] = self.curTxid();
            self.stampInsert(t, nri);
            self.markDirty(nri);
            if (!self.inTxn() and !t.is_temp) {
                if (self.findColumnar(t.name)) |ct| {
                    const ca = ct.arena.allocator();
                    if (ct.nrows < nri and !ct.padRows(ca, nri)) appended_ct = false;
                    if (ct.nrows == nri) {
                        if (!ct.appendRow(ca, row)) appended_ct = false;
                    } else {
                        appended_ct = false;
                    }
                } else {
                    appended_ct = false;
                }
            }
            if (self.inTxn()) {
                if (self.findColumnar(t.name)) |ct| {
                    if (ct.delta_owner == 0 or ct.delta_owner == self.curTxid()) {
                        const ca = ct.arena.allocator();
                        if (ct.appendRow(ca, row)) {
                            ct.delta_owner = self.curTxid();
                        } else {
                            ct.delta_inserts = true;
                        }
                    } else {
                        ct.delta_inserts = true;
                    }
                }
            }
            try self.checkNotNull(t, row);
            try self.checkExclusion(t, row);
            if (ins.returning.len > 0) try ret_rows.append(alloc, try alloc.dupe(Value, row));
            self.gpa.free(row);
            count += 1;
        }
        if (count > 0) {
            self.dropFloatCounts(t.name);
            self.bumpTableVer(t.name);
        }
        if (self.inTxn() and count > 0) self.txnViewDrop(t.name);
        if (count > 0 and !self.inTxn() and !t.is_temp) {
            if (!appended_ct) try self.buildColumnar(t.name);
            if (std.c.getenv("ZHDB_EXPLAIN") != null) {
                var free_segs: usize = 0;
                for (t.seg_free_rows.items) |n| {
                    if (n > 0) free_segs += 1;
                }
                std.debug.print("[insert] {s}: reused={d} appended={d} rebuild={} rows={d} free_slots={d} free_segments={d}\n", .{
                    t.name,
                    reused,
                    count - reused,
                    !appended_ct,
                    t.rows.items.len,
                    t.free_slots.items.len - t.free_head,
                    free_segs,
                });
            }
        }
        if (ins.returning.len > 0) return try self.returningResult(alloc, t, ins.returning, ret_rows.items);
        return .{ .affected = count };
    }
    fn execUpdate(self: *Engine, alloc: std.mem.Allocator, u: anytype) EngineError!Result {
        const t = self.find(u.table) orelse return error.TableNotFound;
        self.dropFloatCounts(u.table);
        self.bumpTableVer(u.table);
        self.ensureRowsMaterialized(u.table);
        try self.txSnapshot(alloc, u.table);
        try ensureVersionArrays(self.gpa, t);
        const mine = self.curTxid();
        var targets = std.ArrayList(usize).empty;
        defer targets.deinit(self.gpa);
        for (t.rows.items, 0..) |_, ri| {
            if (isRowDeleted(t, ri)) continue;
            if (!self.visibleRow(t, ri)) continue;
            const mrow = try materializeRow(alloc, t, ri);
            if (u.where) |w| {
                const v = try self.eval(alloc, w, mrow, t.cols, null);
                if (!truthy(v)) continue;
            }
            if (ri < t.xmax.items.len) {
                const xm = t.xmax.items[ri];
                if (xm != 0 and xm != mine and self.isInFlight(xm)) return error.SerializationFailure;
            }
            try targets.append(self.gpa, ri);
        }
        if (targets.items.len == 0) return try self.returningResult(alloc, t, u.returning, &.{});
        // Validate all replacement rows before mutating anything, so a
        // constraint failure leaves the table untouched (statement atomicity).
        var news = std.ArrayList([]Value).empty;
        defer news.deinit(alloc);
        var pend = std.StringHashMap(void).init(alloc);
        defer {
            var pit = pend.keyIterator();
            while (pit.next()) |k| alloc.free(k.*);
            pend.deinit();
        }
        for (targets.items) |ri| {
            const mrow0 = try materializeRow(alloc, t, ri);
            const nv0 = try alloc.alloc(Value, t.cols.len);
            @memcpy(nv0, mrow0);
            for (u.assignments) |a| {
                const idx = findCol(t, a.col) orelse return error.UnknownColumn;
                if (isDefaultExpr(a.value)) {
                    nv0[idx] = .null;
                    if (t.cols[idx].serial) {
                        nv0[idx] = .{ .int = t.serial_next };
                        t.serial_next += 1;
                    } else self.applyColumnDefault(t, idx, &nv0[idx]);
                    continue;
                }
                const v = try self.eval(alloc, a.value, mrow0, t.cols, null);
                nv0[idx] = try coerce(t, idx, v);
            }
            try self.checkNotNull(t, nv0);
            try self.checkUniqueInsertSkip(u.table, nv0, ri);
            for (self.uniq_sets.items, 0..) |us, ui2| {
                if (!std.ascii.eqlIgnoreCase(stripSchema(us.table), stripSchema(u.table))) continue;
                var has_null = false;
                for (us.cols) |cn| {
                    const ci2 = findCol(t, cn) orelse continue;
                    if (ci2 >= nv0.len or nv0[ci2] == .null) has_null = true;
                }
                if (has_null) continue;
                const key2 = try self.fmtKeyVals(t, us.cols, nv0);
                const pk3 = try std.fmt.allocPrint(alloc, "{d}|{s}", .{ ui2, key2 });
                if (pend.contains(pk3)) {
                    const cl2 = try self.fmtColsList(us.cols);
                    var lnb2: [256]u8 = undefined;
                    const lnn2 = stripSchema(us.name);
                    const lname2 = std.ascii.lowerString(lnb2[0..@min(lnn2.len, lnb2.len)], lnn2[0..@min(lnn2.len, lnb2.len)]);
                    setDiag("duplicate key value violates unique constraint \"{s}\"\nDETAIL:  Key {s}={s} already exists.", .{ lname2, cl2, key2 });
                    return error.DuplicateKey;
                }
                try pend.put(pk3, {});
            }
            try news.append(alloc, nv0);
        }
        var n: usize = 0;
        var ret_rows = std.ArrayList([]Value).empty;
        defer ret_rows.deinit(alloc);
        for (targets.items, news.items) |ri, newv| {
            if (ri < t.xmax.items.len) t.xmax.items[ri] = mine;
            {
                const ta = t.arena.allocator();
                for (newv) |*cell| {
                    if (cell.* == .text) cell.* = .{ .text = try ta.dupe(u8, cell.text) };
                }
            }
            if (ri < t.cmin.items.len) t.cmin.items[ri] = self.comboOrCmd(t, ri);
            const nri = try appendStoredRow(self.gpa, t, newv);
            t.xmin.items[nri] = mine;
            self.stampInsert(t, nri);
            if (t.ctid.items.len <= nri) {
                const old = t.ctid.items.len;
                t.ctid.resize(self.gpa, nri + 1) catch {};
                var k = old;
                while (k < nri + 1) : (k += 1) t.ctid.items[k] = @intCast(k);
            }
            const cid = ctIdOf(t, ri);
            t.ctid.items[nri] = cid;
            self.markDirty(cid);
            const was_txn = self.inTxn();
            if (!was_txn) {
                t.dead_rows += 1;
                self.noteDeadSlot(t, ri);
            }
            if (self.findColumnar(t.name)) |ct| {
                if (ct.delta_owner == 0 or ct.delta_owner == mine) {
                    if (ct.patchRow(cid, newv)) {
                        for (0..ct.cols.len) |ci| ct.refreshBlockStats(ci, cid);
                        if (was_txn) ct.delta_owner = mine;
                        if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[plan] update overlay: row={d} ct={d} owner={d}\n", .{ ri, cid, if (was_txn) mine else 0 });
                    }
                }
            }
            if (std.ascii.eqlIgnoreCase(u.table, "pg_class")) {
                var has_opt = false;
                for (u.assignments) |a| if (std.ascii.eqlIgnoreCase(a.col, "reloptions")) {
                    has_opt = true;
                };
                if (has_opt) {
                    const ci_nm = findCol(t, "relname");
                    const ci_ro = findCol(t, "reloptions");
                    if (ci_nm != null and ci_ro != null and ci_nm.? < newv.len and ci_ro.? < newv.len and newv[ci_nm.?] == .text and newv[ci_ro.?] == .text) {
                        self.setReloptsFromText(newv[ci_nm.?].text, newv[ci_ro.?].text);
                    }
                }
            }
            if (u.returning.len > 0) try ret_rows.append(alloc, newv);
            n += 1;
        }
        if (self.inTxn()) self.txnViewDrop(t.name);
        if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[plan] update mvcc: {d} versions\n", .{n});
        if (u.returning.len > 0) return try self.returningResult(alloc, t, u.returning, ret_rows.items);
        return .{ .affected = n };
    }
    fn execDelete(self: *Engine, alloc: std.mem.Allocator, d: anytype) EngineError!Result {
        if (self.find(d.table) == null) {
            setDiag("relation \"{s}\" does not exist", .{d.table});
            return error.TableNotFound;
        }
        if (d.alias) |al| {
            if (d.where) |w| {
                if (referencesQualifier(w, d.table, al)) return error.InvalidTableAlias;
            }
        }
        if (self.find(d.table)) |_| self.dropFloatCounts(d.table);
        if (self.find(d.table)) |_| self.bumpTableVer(d.table);
        const t = self.find(d.table) orelse return error.TableNotFound;
        var del_cols_storage: ?[]Column = null;
        if (d.alias) |al| {
            const copy = try alloc.dupe(Column, t.cols);
            for (copy) |*c| c.source = al;
            del_cols_storage = copy;
        }
        const del_cols = del_cols_storage orelse t.cols;
        self.ensureRowsMaterialized(d.table);
        try self.txSnapshot(alloc, d.table);
        try ensureVersionArrays(self.gpa, t);
        const ct = self.findColumnar(d.table);
        if (t.deleted.items.len < t.rows.items.len) {
            const old_len = t.deleted.items.len;
            try t.deleted.resize(self.gpa, t.rows.items.len);
            @memset(t.deleted.items[old_len..], 0);
        }
        if (ct) |c| {
            if (c.tomb == null) {
                const a = c.arena.allocator();
                const bits = try a.alloc(u8, (c.nrows + 7) / 8);
                @memset(bits, 0);
                c.tomb = bits;
            }
        }
        var removed: usize = 0;
        var ret_rows = std.ArrayList([]Value).empty;
        defer ret_rows.deinit(alloc);
        var idx_dirty: [32]bool = @splat(false);
        for (t.rows.items, 0..) |row, ri| {
            if (isRowDeleted(t, ri)) continue;
            const mrow = try materializeRow(alloc, t, ri);
            if (d.where) |w| {
                const v = try self.eval(alloc, w, mrow, del_cols, null);
                if (!truthy(v)) continue;
            }
            if (!self.inTxn()) {
                if (t.deleted.items.len < ri + 1) {
                    const old_len = t.deleted.items.len;
                    try t.deleted.resize(self.gpa, t.rows.items.len);
                    @memset(t.deleted.items[old_len..], 0);
                }
                t.deleted.items[ri] = 1;
            }
            if (ri < t.xmax.items.len) t.xmax.items[ri] = self.curTxid();
            if (ri < t.cmin.items.len) t.cmin.items[ri] = self.comboOrCmd(t, ri);
            if (d.returning.len > 0) try ret_rows.append(alloc, mrow);
            removed += 1;
            self.markDirty(ctIdOf(t, ri));
            if (!self.inTxn()) {
                t.dead_rows += 1;
                self.noteDeadSlot(t, ri);
            }
            if (ct) |c| {
                if (c.delta_owner == 0) c.delta_owner = self.curTxid();
                const cid = ctIdOf(t, ri);
                c.tomb.?[cid / 8] |= @as(u8, 1) << @intCast(cid % 8);
                for (c.keyidx, 0..) |maybe, ci| {
                    if (maybe == null or ci >= row.len or ci >= idx_dirty.len) continue;
                    const idx = maybe.?;
                    if (idx.tree) |*tr| {
                        if (row[ci] == .int) {
                            _ = tr.remove(row[ci].int, @intCast(ri)) catch false;
                            idx_dirty[ci] = true;
                        }
                    }
                }
            }
        }
        if (removed > 0) {
            if (ct) |c| {
                for (c.keyidx, 0..) |maybe, ci| {
                    if (maybe == null or ci >= idx_dirty.len or !idx_dirty[ci]) continue;
                    const idx = maybe.?;
                    if (idx.tree) |*tr| {
                        const a2 = c.arena.allocator();
                        if (tr.flatten(a2)) |flat| {
                            idx.keys = flat.keys;
                            idx.offsets = flat.offsets;
                            idx.rows = flat.rows;
                        } else |_| {}
                    }
                }
            }
            if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[plan] delete tombstones: {d} rows\n", .{removed});
            if (self.inTxn()) {} else {
                const freed = self.reclaimFreeSegments(t);
                if (freed > 0 and std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[reclaim] {s}: {d} rows of whole segments registered for reuse\n", .{ d.table, freed });
                if (!self.background_gc) self.maybeAutoVacuum(d.table);
            }
            if (self.inTxn()) self.txnViewDrop(d.table);
        }
        if (d.returning.len > 0) return try self.returningResult(alloc, t, d.returning, ret_rows.items);
        return .{ .affected = removed };
    }
    pub fn refreshCatalogIfNeeded(self: *Engine) void {
        if (self.catalogs_fresh.load(.acquire)) return;
        self.catalog_lock.lock();
        defer self.catalog_lock.unlock();
        if (self.catalogs_fresh.load(.acquire)) return;
        self.refreshCatalog();
        self.catalogs_fresh.store(true, .release);
    }
    fn invalidateCatalogs(self: *Engine) void {
        self.catalogs_fresh.store(false, .release);
    }
