                        kb2.appendSlice(gpa, std.fmt.allocPrint(gpa, "{d}", .{ci4}) catch "") catch {};
                        if (!c4.include) {
                            if (cb2.items.len > 0) cb2.append(gpa, ' ') catch {};
                            cb2.appendSlice(gpa, "1978") catch {};
                            nkey += 1;
                        }
                    }
                }
                add(self, "pg_index", &.{ .{ .int = idx_oid }, .{ .int = oid }, .{ .text = gpa.dupe(u8, kb2.items) catch "" }, .{ .int = natts }, .{ .int = nkey }, .{ .boolean = uni }, .{ .boolean = !f.deferrable }, .{ .boolean = f.primary }, .{ .boolean = ridx }, .{ .boolean = !self.idx_invalid.contains(ivkey) }, .{ .text = gpa.dupe(u8, cb2.items) catch "" } });
                const idef = self.indexDefText(gpa, iname) catch "";
                if (idef.len > 0) self.cat_scratch.append(gpa, @constCast(idef)) catch {};
                add(self, "pg_indexes", &.{ .{ .text = "public" }, .{ .text = tbase }, .{ .text = iname }, .{ .text = idef } });
            }
            var cit = self.constraints.iterator();
            while (cit.next()) |ce| {
                const ci2 = ce.value_ptr;
                if (!std.ascii.eqlIgnoreCase(ci2.table, t.name)) continue;
                var attnum: i64 = 0;
                for (t.cols, 0..) |cc, cci| if (std.ascii.eqlIgnoreCase(cc.name, ci2.col)) {
                    attnum = @intCast(cci + 1);
                    break;
                };
                const idx_oid = self.index_oids.get(ce.key_ptr.*) orelse 0;
                const cf = self.idxFlag(ce.key_ptr.*);
                var cnatts: i64 = 1;
                if (self.index_meta.get(self.lowerDup(ce.key_ptr.*) catch "")) |m| {
                    cnatts = 0;
                    for (m.cols) |c3| {
                        _ = c3;
                        cnatts += 1;
                    }
                }
                var cridx = false;
                {
                    var tk2: []const u8 = t.name;
                    if (std.mem.lastIndexOfScalar(u8, t.name, '.')) |d| tk2 = t.name[d + 1 ..];
                    const tk = self.lowerDup(tk2) catch "";
                    defer self.gpa.free(tk);
                    const il = self.lowerDup(ce.key_ptr.*) catch "";
                    defer self.gpa.free(il);
                    if (self.replident.get(tk) == 'i') {
                        if (self.replident_idx.get(tk)) |ri| cridx = std.ascii.eqlIgnoreCase(ri, il);
                    }
                }
                const ivkey2 = self.lowerDup(ce.key_ptr.*) catch "";
                defer self.gpa.free(ivkey2);
                var kb3 = std.ArrayList(u8).empty;
                defer kb3.deinit(gpa);
                var cb3 = std.ArrayList(u8).empty;
                defer cb3.deinit(gpa);
                var nkey3: i64 = 0;
                {
                    var allc = std.ArrayList([]const u8).empty;
                    defer allc.deinit(gpa);
                    for (ci2.cols) |c5| allc.append(gpa, c5) catch {};
                    for (ci2.include) |c5| allc.append(gpa, c5) catch {};
                    for (allc.items) |c5| {
                        var ci5: i64 = 0;
                        for (t.cols, 0..) |cc5, cci5| if (std.ascii.eqlIgnoreCase(cc5.name, c5)) {
                            ci5 = @intCast(cci5 + 1);
                        };
                        if (kb3.items.len > 0) kb3.append(gpa, ' ') catch {};
                        kb3.appendSlice(gpa, std.fmt.allocPrint(gpa, "{d}", .{ci5}) catch "") catch {};
                    }
                    for (ci2.cols) |_| {
                        if (cb3.items.len > 0) cb3.append(gpa, ' ') catch {};
                        cb3.appendSlice(gpa, "1978") catch {};
                        nkey3 += 1;
                    }
                }
                add(self, "pg_index", &.{ .{ .int = idx_oid }, .{ .int = oid }, .{ .text = gpa.dupe(u8, kb3.items) catch "" }, .{ .int = cnatts }, .{ .int = nkey3 }, .{ .boolean = cf.unique and ci2.kind != .exclude }, .{ .boolean = !cf.deferrable }, .{ .boolean = ci2.kind == .primary }, .{ .boolean = cridx }, .{ .boolean = !self.idx_invalid.contains(ivkey2) }, .{ .text = gpa.dupe(u8, cb3.items) catch "" } });
                {
                    const cdef = self.indexDefText(gpa, ce.key_ptr.*) catch "";
                    if (cdef.len > 0) {
                        self.cat_scratch.append(gpa, @constCast(cdef)) catch {};
                        add(self, "pg_indexes", &.{ .{ .text = "public" }, .{ .text = tbase }, .{ .text = ce.key_ptr.* }, .{ .text = cdef } });
                    }
                }
                {
                    var ck = std.ArrayList(u8).empty;
                    defer ck.deinit(gpa);
                    ck.append(gpa, '{') catch {};
                    for (ci2.cols, 0..) |c6, ii6| {
                        if (ii6 > 0) ck.append(gpa, ',') catch {};
                        var ci6: i64 = 0;
                        for (t.cols, 0..) |cc6, cci6| if (std.ascii.eqlIgnoreCase(cc6.name, c6)) {
                            ci6 = @intCast(cci6 + 1);
                        };
                        ck.appendSlice(gpa, std.fmt.allocPrint(gpa, "{d}", .{ci6}) catch "") catch {};
                    }
                    ck.append(gpa, '}') catch {};
                    add(self, "pg_constraint", &.{ .{ .int = idx_oid }, .{ .text = self.catDup(ce.key_ptr.*) }, .{ .int = idx_oid }, .{ .text = switch (ci2.kind) {
                        .primary => "p",
                        .unique => "u",
                        .exclude => "x",
                    } }, .{ .boolean = cf.deferrable }, .{ .boolean = cf.deferred }, .{ .int = oid }, .{ .text = gpa.dupe(u8, ck.items) catch "" } });
                }
            }
            for (t.cols, 0..) |c, i| {
                const ty: i64 = pgAttrTypeOid(c);
                add(self, "pg_attribute", &.{ .{ .int = oid }, .{ .text = c.name }, .{ .int = ty }, .{ .int = @intCast(i + 1) }, .{ .text = "" }, .{ .boolean = c.not_null }, .{ .text = c.default_text } });
            }
        }
        for (self.schema_objects.items, 0..) |o, oi| {
            const nsoid = self.schema_oids.get(o.schema) orelse 2200;
            const kind: []const u8 = switch (o.kind) {
                .table => "r",
                .view => "v",
                .index => "i",
                .sequence => "S",
            };
            const robj = 18000 + @as(i64, @intCast(oi));
            const obase = stripSchema(o.name);
            if (o.kind != .table or self.find(o.name) == null) add(self, "pg_class", &.{ .{ .int = robj }, .{ .text = obase }, .{ .int = nsoid }, .{ .text = kind }, .{ .text = "zhdb" } });
            if (o.kind == .table) {
                if (self.find(o.name)) |t| {
                    for (t.cols, 0..) |c, ci| {
                        const ty: i64 = pgAttrTypeOid(c);
                        add(self, "pg_attribute", &.{ .{ .int = robj }, .{ .text = c.name }, .{ .int = ty }, .{ .int = @intCast(ci + 1) }, .{ .text = "" }, .{ .boolean = c.not_null }, .{ .text = c.default_text } });
                    }
                }
            }
        }
        var voi: usize = 0;
        var vit2 = self.views.iterator();
        while (vit2.next()) |e| {
            const vfull = e.key_ptr.*;
            const vbase = stripSchema(vfull);
            var dup = false;
            for (self.schema_objects.items) |o| {
                if (std.ascii.eqlIgnoreCase(stripSchema(o.name), vbase)) dup = true;
            }
            if (dup) continue;
            var vns: i64 = 2200;
            if (std.mem.lastIndexOfScalar(u8, vfull, '.')) |d| vns = self.schema_oids.get(vfull[0..d]) orelse 2200;
            add(self, "pg_class", &.{ .{ .int = 19000 + @as(i64, @intCast(voi)) }, .{ .text = vbase }, .{ .int = vns }, .{ .text = "v" }, .{ .text = self.catDup(self.ownerOf("table", vbase)) }, .null, .null, .null, .null, .null, .null, .null, .{ .text = "d" } });
            voi += 1;
        }
        for (cats) |c| self.buildColumnar(c.name) catch {};
    }
    pub fn gcTick(self: *Engine) usize {
        var reclaimed: usize = 0;
        var names = std.ArrayList([]const u8).empty;
        defer names.deinit(self.gpa);
        var it = self.tables.iterator();
        while (it.next()) |e| {
            const nm = e.value_ptr.*.name;
            if (std.mem.startsWith(u8, nm, "pg_")) continue;
            names.append(self.gpa, nm) catch continue;
        }
        for (names.items) |nm| {
            var t = self.find(nm) orelse continue;
            if (t.rows.items.len == 0) {
                if (self.findColumnar(nm)) |ct| {
                    if (ct.nrows > 0 and ct.anyDeleted()) self.ensureRowsMaterialized(nm);
                }
                t = self.find(nm) orelse continue;
            }
            if (t.rows.items.len < 64) continue;
            const db = self.deadBlocks(t);
            const dense = self.compactionWorthIt(nm, db);
            if (dense) {
                if (std.c.getenv("ZHDB_EXPLAIN") != null) {
                    const rows = t.rows.items.len;
                    std.debug.print("[gc] {s}: dead={d}/{d} ({d:.1}%) full_blocks={d} partial_blocks={d} -> block compaction\n", .{
                        nm, db.rows, rows, if (rows > 0) @as(f64, @floatFromInt(db.rows)) / @as(f64, @floatFromInt(rows)) * 100.0 else 0, db.full, db.partial,
                    });
                }
                self.compactTable(nm);
                reclaimed += 1;
                break;
            }
            if (t.dead_rows * 8 >= t.rows.items.len and t.dead_rows >= 64) {
                const st = self.reclaimSegments(nm);
                const dropped = self.truncateDeadTail(nm);
                if (st.rows + dropped > 0) reclaimed += 1;
                break;
            }
        }
        return reclaimed;
    }
    fn maybeAutoVacuum(self: *Engine, name: []const u8) void {
        const t = self.find(name) orelse return;
        if (t.rows.items.len < 64) return;
        if (!self.background_gc and t.dead_rows * 8 >= t.rows.items.len and t.dead_rows >= 64) {
            if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[vacuum] {s}: {d} dead rows -> interior compaction\n", .{ name, t.dead_rows });
            self.compactTable(name);
        } else if (std.c.getenv("ZHDB_EXPLAIN") != null and t.free_head < t.free_slots.items.len) {
            std.debug.print("[vacuum] {s}: keep (free segments already hold {d} reusable slots; no rewrite)\n", .{ name, t.free_slots.items.len - t.free_head });
        }
    }
    fn reuseSlot(self: *Engine, t: *Table, row: []const Value) bool {
        if (t.free_head >= t.free_slots.items.len) {
            t.free_slots.clearRetainingCapacity();
            t.free_head = 0;
            return false;
        }
        const slot: usize = t.free_slots.items[t.free_head];
        const ct = self.findColumnar(t.name) orelse return false;
        if (ct.nrows != t.rows.items.len) return false;
        if (slot >= t.rows.items.len or slot >= t.deleted.items.len) {
            t.free_head += 1;
            return false;
        }
        if (!ct.patchRow(slot, row)) return false;
        const a = ct.arena.allocator();
        ct.setTomb(a, slot, false) catch return false;
        for (0..ct.cols.len) |ci| ct.refreshBlockStats(ci, slot);
        const words = (t.rows.items.len + 7) / 8;
        for (0..t.cols.len) |ci| {
            const is_null = ci < row.len and row[ci] == .null;
            if (is_null and ci < t.nulls.len and t.nulls[ci] == null) {
                const bits = self.gpa.alloc(u8, words) catch return false;
                @memset(bits, 0xff);
                t.nulls[ci] = bits;
            }
            tableSetNull(self.gpa, t, ci, slot, is_null) catch {};
            if (ci < ct.valid.len) {
                if (ct.valid[ci]) |bits| {
                    if (is_null) {
                        bits[slot / 8] &= ~(@as(u8, 1) << @intCast(slot % 8));
                    } else {
                        bits[slot / 8] |= @as(u8, 1) << @intCast(slot % 8);
                    }
                } else if (is_null) {
                    const words_c = (ct.nrows + 7) / 8;
                    const bits = a.alloc(u8, words_c) catch return false;
                    @memset(bits, 0xff);
                    bits[slot / 8] &= ~(@as(u8, 1) << @intCast(slot % 8));
                    ct.valid[ci] = bits;
                }
            }
        }
        const old = t.rows.items[slot];
        if (t.placeholder.len != t.cols.len or old.ptr != t.placeholder.ptr) self.gpa.free(old);
        const stored = self.gpa.alloc(Value, t.cols.len) catch return false;
        for (stored, 0..) |*c, ci| {
            const v: Value = if (ci < row.len) row[ci] else defaultValue(t.cols[ci].ty);
            c.* = if (v == .null) storedSentinel(t.cols[ci].ty) else v;
        }
        t.rows.items[slot] = stored;
        t.deleted.items[slot] = 0;
        self.markDirty(slot);
        if (slot < t.xmin.items.len) t.xmin.items[slot] = self.curTxid();
        if (slot < t.xmax.items.len) t.xmax.items[slot] = 0;
        const seg = slot / seg_rows;
        if (seg < t.seg_free_rows.items.len and t.seg_free_rows.items[seg] > 0) t.seg_free_rows.items[seg] -= 1;
        t.free_head += 1;
        if (t.free_head >= t.free_slots.items.len) {
            t.free_slots.clearRetainingCapacity();
            t.free_head = 0;
        }
        return true;
    }
    fn txnWrote(self: *Engine, name: []const u8) bool {
        for (self.txnCtx().undo.items) |u| {
            if (std.ascii.eqlIgnoreCase(u.name, name)) return true;
        }
        return false;
    }
    fn txnViewGet(self: *Engine, name: []const u8) ?*columnar.Table {
        for (self.txnCtx().views.items) |v| {
            if (std.ascii.eqlIgnoreCase(v.name, name)) return v.ct;
        }
        return null;
    }
    fn txnViewDrop(self: *Engine, name: []const u8) void {
        const ctx = self.txnCtx();
        var i: usize = 0;
        while (i < ctx.views.items.len) : (i += 1) {
            if (std.ascii.eqlIgnoreCase(ctx.views.items[i].name, name)) {
                const v = ctx.views.orderedRemove(i);
                v.ct.destroy(self.gpa);
                self.gpa.free(v.name);
                return;
            }
        }
    }
    fn dropAllViews(self: *Engine, ctx: *TxnCtx) void {
        for (ctx.views.items) |v| {
            v.ct.destroy(self.gpa);
            self.gpa.free(v.name);
        }
        ctx.views.clearRetainingCapacity();
    }
    fn txnViewBuild(self: *Engine, name: []const u8) !*columnar.Table {
        const t = self.find(name) orelse return error.TableNotFound;
        var rows = std.ArrayList([]Value).empty;
        defer {
            for (rows.items) |r| self.gpa.free(r);
            rows.deinit(self.gpa);
        }
        for (t.rows.items, 0..) |_, ri| {
            if (isRowDeleted(t, ri)) continue;
            if (!self.visibleRow(t, ri)) continue;
            const m = try self.gpa.alloc(Value, t.cols.len);
            for (0..t.cols.len) |ci| m[ci] = cellValueFromRow(t, ci, ri);
            try rows.append(self.gpa, m);
        }
        const cols = try self.gpa.alloc(columnar.Column, t.cols.len);
        defer self.gpa.free(cols);
        for (t.cols, 0..) |c, i| {
            cols[i] = .{ .name = c.name, .kind = switch (c.ty) {
                .int, .boolean => .int,
                .float => .float,
                .text, .date, .timestamp => .str,
            } };
        }
        const ct = try columnar.Table.buildForView(self.gpa, cols, rows.items);
        const ctx = self.txnCtx();
        try ctx.views.append(self.gpa, .{ .name = try self.gpa.dupe(u8, name), .ct = ct });
        return ct;
    }
    fn noteDeadSlot(self: *Engine, t: *Table, ri: usize) void {
        const seg = ri / seg_rows;
        if (t.seg_dead.items.len <= seg) {
            const old = t.seg_dead.items.len;
            t.seg_dead.resize(self.gpa, seg + 1) catch return;
            @memset(t.seg_dead.items[old..], 0);
            const old2 = t.seg_dirty.items.len;
            t.seg_dirty.resize(self.gpa, seg + 1) catch return;
            @memset(t.seg_dirty.items[old2..], 0);
        }
        t.seg_dead.items[seg] += 1;
        if (t.seg_dirty.items[seg] == 0) {
            t.seg_dirty.items[seg] = 1;
            t.free_segments.append(self.gpa, @intCast(seg)) catch {};
        }
    }
    fn noteFreeSlot(self: *Engine, t: *Table, ri: usize) void {
        t.free_slots.append(self.gpa, @intCast(ri)) catch return;
        const seg = ri / seg_rows;
        if (t.seg_free_rows.items.len <= seg) {
            const old = t.seg_free_rows.items.len;
            t.seg_free_rows.resize(self.gpa, seg + 1) catch return;
            @memset(t.seg_free_rows.items[old..], 0);
        }
        t.seg_free_rows.items[seg] += 1;
    }
    fn sortFreeSlots(self: *Engine, t: *Table) void {
        _ = self;
        if (t.free_head > 0) {
            const rem = t.free_slots.items[t.free_head..];
            if (rem.len > 0) std.mem.copyForwards(u32, t.free_slots.items[0..rem.len], rem);
            t.free_slots.items.len = rem.len;
            t.free_head = 0;
        }
        std.mem.sort(u32, t.free_slots.items, {}, std.sort.asc(u32));
    }
    fn reclaimFreeSegments(self: *Engine, t: *Table) usize {
        var freed: usize = 0;
        var si: usize = 0;
        var w: usize = 0;
        while (si < t.free_segments.items.len) : (si += 1) {
            const seg = t.free_segments.items[si];
            const lo: usize = @as(usize, seg) * seg_rows;
            const hi: usize = @min(lo + seg_rows, t.rows.items.len);
            const seg_len = hi - lo;
            const dcount: usize = if (seg < t.seg_dead.items.len) t.seg_dead.items[seg] else 0;
            if (lo >= hi or dcount < seg_len) {
                t.free_segments.items[w] = seg;
                w += 1;
                continue;
            }
            var all_dead = true;
            var ri = lo;
            while (ri < hi and all_dead) : (ri += 1) {
                if (!isRowDeleted(t, ri)) {
                    all_dead = false;
                    break;
                }
                const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
                if (xm != 0 and self.isInFlight(xm)) all_dead = false;
            }
            if (!all_dead) {
                t.free_segments.items[w] = seg;
                w += 1;
                continue;
            }
            ri = lo;
            while (ri < hi) : (ri += 1) {
                const row = t.rows.items[ri];
                if (t.placeholder.len == t.cols.len and row.ptr == t.placeholder.ptr) continue;
                self.gpa.free(row);
                t.rows.items[ri] = t.placeholder;
                self.noteFreeSlot(t, ri);
                freed += 1;
            }
            if (t.seg_dead.items.len > seg) t.seg_dead.items[seg] = 0;
            if (t.seg_dirty.items.len > seg) t.seg_dirty.items[seg] = 0;
            if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[reclaim] {s}: segment {d} fully free ({d} rows) -> reuse\n", .{ t.name, seg, hi - lo });
        }
        t.free_segments.items.len = w;
        if (t.dead_rows >= freed) t.dead_rows -= freed else t.dead_rows = 0;
        if (freed > 0) self.sortFreeSlots(t);
        return freed;
    }
    pub const ReclaimStats = struct { segments: usize = 0, rows: usize = 0, blocks_dropped: usize = 0 };
    fn truncateDeadTail(self: *Engine, name: []const u8) usize {
        const t = self.find(name) orelse return 0;
        var k: usize = 0;
        while (k < t.rows.items.len) : (k += 1) {
            const ri = t.rows.items.len - 1 - k;
            const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
            const dead = isRowDeleted(t, ri) or (xm != 0 and !self.isInFlight(xm));
            if (!dead) break;
        }
        if (k == 0) return 0;
        var k_dead: usize = 0;
        var i: usize = t.rows.items.len - k;
        while (i < t.rows.items.len) : (i += 1) {
            const row = t.rows.items[i];
            if (t.placeholder.len != t.cols.len or row.ptr != t.placeholder.ptr) {
                self.gpa.free(row);
                k_dead += 1;
            }
        }
        const keep = t.rows.items.len - k;
        t.rows.items.len = keep;
        if (t.deleted.items.len > keep) t.deleted.items.len = keep;
        if (t.xmin.items.len > keep) t.xmin.items.len = keep;
        if (t.xmax.items.len > keep) t.xmax.items.len = keep;
        if (t.dead_rows >= k_dead) t.dead_rows -= k_dead else t.dead_rows = 0;
        t.seg_dead.clearRetainingCapacity();
        t.seg_dirty.clearRetainingCapacity();
        t.free_segments.clearRetainingCapacity();
        var w: usize = 0;
        var si: usize = 0;
        for (t.free_slots.items) |slot| {
            if (slot < keep) {
                t.free_slots.items[w] = slot;
                w += 1;
            }
        }
        t.free_slots.items.len = w;
        t.free_head = 0;
        t.seg_free_rows.clearRetainingCapacity();
        for (t.free_slots.items) |slot| {
            si = slot / seg_rows;
            if (t.seg_free_rows.items.len <= si) {
                const old = t.seg_free_rows.items.len;
                t.seg_free_rows.resize(self.gpa, si + 1) catch break;
                @memset(t.seg_free_rows.items[old..], 0);
            }
            t.seg_free_rows.items[si] += 1;
        }
        if (self.findColumnar(name)) |ct| {
            if (ct.nrows > keep) ct.truncateRows(keep);
        }
        return k;
    }
    fn reclaimSegments(self: *Engine, name: []const u8) ReclaimStats {
        var st = ReclaimStats{};
        const t = self.find(name) orelse return st;
        for (t.free_segments.items) |seg| {
            const lo: usize = @as(usize, seg) * seg_rows;
            const hi: usize = @min(lo + seg_rows, t.rows.items.len);
            st.segments += 1;
            var ri = lo;
            while (ri < hi) : (ri += 1) {
                if (!isRowDeleted(t, ri)) continue;
                const row = t.rows.items[ri];
                if (t.placeholder.len == t.cols.len and row.ptr == t.placeholder.ptr) continue;
                const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
                if (xm != 0 and self.isInFlight(xm)) continue;
                self.gpa.free(row);
                t.rows.items[ri] = t.placeholder;
                self.noteFreeSlot(t, ri);
                st.rows += 1;
            }
            if (t.seg_dead.items.len > seg) t.seg_dead.items[seg] = 0;
            if (t.seg_dirty.items.len > seg) t.seg_dirty.items[seg] = 0;
        }
        t.free_segments.clearRetainingCapacity();
        if (t.dead_rows >= st.rows) t.dead_rows -= st.rows else t.dead_rows = 0;
        if (st.rows > 0) self.sortFreeSlots(t);
        return st;
    }
    fn compactTable(self: *Engine, name: []const u8) void {
        const t = self.find(name) orelse return;
        const rows_before = t.rows.items.len;
        const t_start = nowNs();
        self.wb_full = true;
        self.wb_dirty.clearRetainingCapacity();
        const had_tomb = t.deleted.items.len > 0;
        const had_versions = t.xmax.items.len > 0;
        if (!had_tomb and !had_versions) return;
        var w: usize = 0;
        var remap = std.ArrayList(u32).empty;
        defer remap.deinit(self.gpa);
        remap.resize(self.gpa, t.rows.items.len) catch {};
        @memset(remap.items, 0xFFFF_FFFF);
        for (t.rows.items, 0..) |row, ri| {
            const dead = isRowDeleted(t, ri) or (ri < t.xmax.items.len and t.xmax.items[ri] != 0 and !self.isInFlight(t.xmax.items[ri]));
            if (dead) {
                if (t.placeholder.len != t.cols.len or row.ptr != t.placeholder.ptr) self.gpa.free(row);
                continue;
            }
            if (w < remap.items.len) remap.items[ri] = @intCast(w);
            t.rows.items[w] = row;
            if (ri < t.xmin.items.len) t.xmin.items[w] = t.xmin.items[ri];
            if (ri < t.xmax.items.len) {
                const xm = t.xmax.items[ri];
                t.xmax.items[w] = if (xm != 0 and self.isInFlight(xm)) xm else 0;
            }
            w += 1;
        }
        t.rows.items.len = w;
        if (t.xmin.items.len > w) t.xmin.items.len = w;
        if (t.xmax.items.len > w) t.xmax.items.len = w;
        t.deleted.clearRetainingCapacity();
        t.dead_rows = 0;
        t.seg_dead.clearRetainingCapacity();
        t.seg_dirty.clearRetainingCapacity();
        t.free_segments.clearRetainingCapacity();
        t.free_slots.clearRetainingCapacity();
        t.free_head = 0;
        t.seg_free_rows.clearRetainingCapacity();
        for (t.nulls) |*slot| slot.* = null;
        for (t.rows.items, 0..) |row, ri| {
            for (0..t.cols.len) |ci| {
                if (row[ci] == .null) tableSetNull(self.gpa, t, ci, ri, true) catch {};
            }
        }
        self.index_remap = remap.items;
        defer self.index_remap = null;
        self.buildColumnar(name) catch {};
        const dt = nowNs() - t_start;
        if (rows_before > 0 and dt > 0) {
            const sample = @as(f64, @floatFromInt(dt)) / @as(f64, @floatFromInt(rows_before));
            const alpha: f64 = if (self.compact_samples < 4) 0.5 else 0.2;
            self.compact_row_ns = std.math.clamp((1.0 - alpha) * self.compact_row_ns + alpha * sample, 5.0, 5000.0);
            self.compact_samples += 1;
            self.costs_dirty = true;
            if (std.c.getenv("ZHDB_EXPLAIN") != null) {
                std.debug.print("[compact] {s}: rows={d} ns/row={d:.1} (learned {d:.1})\n", .{
                    name,
                    rows_before,
                    sample,
                    self.compact_row_ns,
                });
            }
        }
    }
    fn learnAlpha(self: *Engine) f64 {
        return if (self.wb_samples < 6) 0.5 else 0.2;
    }
    fn learnWrite(self: *Engine, bytes: usize, ns: anytype) void {
        if (bytes == 0 or std.c.getenv("ZHDB_WB_NO_LEARN") != null) return;
        const sample = @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(bytes));
        const a = self.learnAlpha();
        self.wb_write_ns_byte = std.math.clamp((1.0 - a) * self.wb_write_ns_byte + a * sample, 0.05, 50.0);
        self.wb_samples += 1;
        self.costs_dirty = true;
    }
    fn learnEncode(self: *Engine, rows: usize, ns: anytype) void {
        if (rows == 0 or std.c.getenv("ZHDB_WB_NO_LEARN") != null) return;
        const sample = @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(rows));
        const a = self.learnAlpha();
        self.wb_encode_ns_row = std.math.clamp((1.0 - a) * self.wb_encode_ns_row + a * sample, 1.0, 2000.0);
        self.wb_samples += 1;
        self.costs_dirty = true;
    }
    pub fn noteReplaySample(self: *Engine, rows: usize, ns: anytype) void {
        if (rows == 0 or std.c.getenv("ZHDB_WB_NO_LEARN") != null) return;
        const sample = @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(rows));
        const a = self.learnAlpha();
        self.wb_replay_ns_row = std.math.clamp((1.0 - a) * self.wb_replay_ns_row + a * sample, 5.0, 20000.0);
        self.wb_samples += 1;
        self.costs_dirty = true;
    }
    fn refreshWbTrailer(self: *Engine, io: std.Io, path: []const u8) void {
        var tr: [columnar.trailer_len_v3]u8 = undefined;
        columnar.Table.encodeWbTrailer(.{
            .write_ns_byte = self.wb_write_ns_byte,
            .encode_ns_row = self.wb_encode_ns_row,
            .replay_ns_row = self.wb_replay_ns_row,
            .compact_row_ns = self.compact_row_ns,
            .samples = self.wb_samples,
            .scan_row_ns = self.cost_scan_row,
            .str_raw_ns = self.cost_str_raw_row,
            .str_dict_ns = self.cost_str_dict_row,
        }, &tr);
        const f = std.Io.Dir.cwd().openFile(io, path, .{ .mode = .read_write }) catch return;
        defer f.close(io);
        const size = (f.stat(io) catch return).size;
        var has: usize = 0;
        const lens = [3]usize{ columnar.trailer_len_v3, columnar.trailer_len_v2, columnar.trailer_len_v1 };
        for (lens) |l| {
            if (size < l) continue;
            var tail: [4]u8 = undefined;
            const n = f.readPositionalAll(io, &tail, size - l) catch 0;
            if (n == 4 and std.mem.eql(u8, &tail, "ZBT1")) {
                has = l;
                break;
            }
        }
        if (has != 0 and has != columnar.trailer_len_v3) {
            f.setLength(io, size - has + columnar.trailer_len_v3) catch return;
            f.writePositionalAll(io, &tr, size - has) catch return;
            f.sync(io) catch {};
            return;
        }
        const off: u64 = if (has == columnar.trailer_len_v3) size - columnar.trailer_len_v3 else size;
        f.writePositionalAll(io, &tr, off) catch return;
        f.sync(io) catch {};
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            std.debug.print("[writeback] trailer refreshed at {d} write={d:.2}ns/B enc={d:.1}ns/row rep={d:.1}ns/row scan={d:.2}ns/row str_raw={d:.2} str_dict={d:.2} samples={d}\n", .{
                off,                self.wb_write_ns_byte, self.wb_encode_ns_row,  self.wb_replay_ns_row,
                self.cost_scan_row, self.cost_str_raw_row, self.cost_str_dict_row, self.wb_samples,
            });
        }
    }
    pub fn checkpointCosts(self: *Engine, io: std.Io) void {
        if (!self.costs_dirty) return;
        const now = nowNs();
        if (self.last_cost_save_ns != 0 and now >= self.last_cost_save_ns and now - self.last_cost_save_ns < 1_000_000_000) return;
        self.flushCostsNow(io, now);
    }
    pub fn flushCosts(self: *Engine, io: std.Io) void {
        if (!self.costs_dirty) return;
        self.flushCostsNow(io, nowNs());
    }
    fn flushCostsNow(self: *Engine, io: std.Io, now: u64) void {
        const path = self.snapshot_path orelse return;
        self.refreshWbTrailer(io, path);
        self.costs_dirty = false;
        self.last_cost_save_ns = now;
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            std.debug.print("[calib] checkpoint planner costs scan_row={d:.2} str_raw={d:.2} str_dict={d:.2} -> {s}\n", .{
                self.cost_scan_row,
                self.cost_str_raw_row,
                self.cost_str_dict_row,
                path,
            });
        }
    }
    pub fn restoreWbCosts(self: *Engine, c: columnar.WbCosts) void {
        self.wb_write_ns_byte = std.math.clamp(c.write_ns_byte, 0.05, 50.0);
        self.wb_encode_ns_row = std.math.clamp(c.encode_ns_row, 1.0, 2000.0);
        self.wb_replay_ns_row = std.math.clamp(c.replay_ns_row, 5.0, 20000.0);
        self.compact_row_ns = std.math.clamp(c.compact_row_ns, 5.0, 5000.0);
        self.wb_samples = @intCast(@min(c.samples, 1 << 40));
        var restored_plan = false;
        if (c.scan_row_ns > 0) {
            self.cost_scan_row = std.math.clamp(c.scan_row_ns, 0.3, 12.0);
            restored_plan = true;
        }
        if (c.str_raw_ns > 0) self.cost_str_raw_row = std.math.clamp(c.str_raw_ns, 0.03, 20.0);
        if (c.str_dict_ns > 0) self.cost_str_dict_row = std.math.clamp(c.str_dict_ns, 0.03, 20.0);
        columnar.setCosts(self.cost_scan_row, self.cost_index_row, self.cost_index_probe);
        columnar.setStrCosts(self.cost_str_raw_row, self.cost_str_dict_row);
        if (restored_plan) {
            self.costs_calibrated = true;
            self.costs_restored = true;
        }
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            std.debug.print("[writeback] restored costs (snapshot v8) write={d:.2}ns/B enc={d:.1}ns/row rep={d:.1}ns/row compact={d:.1}ns/row samples={d}\n", .{
                self.wb_write_ns_byte,
                self.wb_encode_ns_row,
                self.wb_replay_ns_row,
                self.compact_row_ns,
                self.wb_samples,
            });
            if (restored_plan) {
                std.debug.print("[calib] restored planner costs scan_row={d:.2}ns/row str_raw={d:.2} str_dict={d:.2} (from trailer)\n", .{
                    self.cost_scan_row,
                    self.cost_str_raw_row,
                    self.cost_str_dict_row,
                });
            } else {
                std.debug.print("[calib] planner costs seeded scan_row={d:.2}ns/row str_raw={d:.2} str_dict={d:.2} (trailer predates planner fields)\n", .{
                    self.cost_scan_row,
                    self.cost_str_raw_row,
                    self.cost_str_dict_row,
                });
            }
        }
    }
    pub fn loadWbCosts(self: *Engine, io: std.Io, gpa: std.mem.Allocator, path: []const u8) void {
        const mp = std.fmt.allocPrint(gpa, "{s}.meta", .{path}) catch return;
        defer gpa.free(mp);
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, mp, gpa, .limited(1 << 20)) catch return;
        defer gpa.free(bytes);
        var it = std.mem.splitScalar(u8, bytes, '\n');
        const head = it.next() orelse return;
        if (!std.mem.startsWith(u8, head, "zhdb-meta")) return;
        while (it.next()) |line| {
            var parts = std.mem.tokenizeScalar(u8, line, ' ');
            const key = parts.next() orelse continue;
            const val = parts.next() orelse continue;
            if (std.mem.eql(u8, key, "write_ns_byte")) {
                self.wb_write_ns_byte = std.fmt.parseFloat(f64, val) catch self.wb_write_ns_byte;
            } else if (std.mem.eql(u8, key, "encode_ns_row")) {
                self.wb_encode_ns_row = std.fmt.parseFloat(f64, val) catch self.wb_encode_ns_row;
            } else if (std.mem.eql(u8, key, "replay_ns_row")) {
                self.wb_replay_ns_row = std.fmt.parseFloat(f64, val) catch self.wb_replay_ns_row;
            } else if (std.mem.eql(u8, key, "samples")) {
                self.wb_samples = std.fmt.parseInt(usize, val, 10) catch self.wb_samples;
            }
        }
        self.wb_write_ns_byte = std.math.clamp(self.wb_write_ns_byte, 0.05, 50.0);
        self.wb_encode_ns_row = std.math.clamp(self.wb_encode_ns_row, 1.0, 2000.0);
        self.wb_replay_ns_row = std.math.clamp(self.wb_replay_ns_row, 5.0, 20000.0);
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            std.debug.print("[writeback] restored costs write={d:.2}ns/B enc={d:.1}ns/row rep={d:.1}ns/row samples={d}\n", .{
                self.wb_write_ns_byte, self.wb_encode_ns_row, self.wb_replay_ns_row, self.wb_samples,
            });
        }
    }
    pub fn saveSnapshotFile(self: *Engine, io: std.Io, gpa: std.mem.Allocator, table: []const u8, path: []const u8) !void {
        const t0 = std.Io.Clock.now(.awake, io).nanoseconds;
        const t = self.findColumnar(table) orelse return error.TableNotFound;
        const READ_NS_PER_BYTE: f64 = 0.8;
        const WRITE_NS_PER_BYTE: f64 = self.wb_write_ns_byte;
        const ENCODE_ROW_NS: f64 = self.wb_encode_ns_row;
        const REPLAY_ROW_NS: f64 = self.wb_replay_ns_row;
        const n_dirty = self.wb_dirty.items.len;
        if (!self.wb_full and n_dirty == 0) return;
        const dpath = try std.fmt.allocPrint(gpa, "{s}.delta", .{path});
        defer gpa.free(dpath);
        var base_bytes: u64 = 0;
        {
            const bf = std.Io.Dir.cwd().openFile(io, path, .{}) catch null;
            if (bf) |f| {
                defer f.close(io);
                const st = f.stat(io) catch null;
                if (st) |stt| base_bytes = stt.size;
            }
        }
        if (!self.wb_full and n_dirty > 0) {
            var buf = std.ArrayList(u8).empty;
            defer buf.deinit(gpa);
            var old_len: usize = 0;
            if (std.Io.Dir.cwd().readFileAlloc(io, dpath, gpa, .limited(64 << 20))) |old| {
                defer gpa.free(old);
                old_len = old.len;
                try buf.appendSlice(gpa, old);
            } else |_| {}
            const a0 = std.Io.Clock.now(.awake, io).nanoseconds;
            try t.appendDelta(gpa, self.wb_dirty.items, &buf);
            const a1 = std.Io.Clock.now(.awake, io).nanoseconds;
            const new_section = buf.items.len - old_len;
            const per_row: usize = if (n_dirty > 0) @max(new_section / n_dirty, 1) else 1;
            const delta_rows: usize = if (per_row > 0) old_len / per_row + n_dirty else n_dirty;
            const delta_bytes: f64 = @floatFromInt(buf.items.len);
            const replay_ns = delta_bytes * READ_NS_PER_BYTE + @as(f64, @floatFromInt(delta_rows)) * REPLAY_ROW_NS;
            const rewrite_ns = @as(f64, @floatFromInt(base_bytes + buf.items.len)) * WRITE_NS_PER_BYTE +
                @as(f64, @floatFromInt(t.nrows)) * ENCODE_ROW_NS;
            const ratio_ok = n_dirty * 4 <= t.nrows;
            const have_base = base_bytes > 0;
            var use_delta = ratio_ok and have_base and replay_ns < rewrite_ns;
            var why: []const u8 = if (!ratio_ok) "dirty>25%" else if (!have_base) "no-base" else if (replay_ns >= rewrite_ns) "replay>rewrite" else "cost";
            if (std.c.getenv("ZHDB_DELTA_MAX")) |v| {
                const delta_max = std.fmt.parseInt(usize, std.mem.span(v), 10) catch 0;
                if (delta_max > 0 and buf.items.len > delta_max) {
                    use_delta = false;
                    why = "ZHDB_DELTA_MAX";
                }
            }
            if (std.c.getenv("ZHDB_EXPLAIN") != null) {
                std.debug.print("[writeback] {s}: policy dirty={d} delta_rows={d} delta_bytes={d} base_bytes={d} replay={d:.1}us rewrite={d:.1}us (write={d:.2}ns/B enc={d:.1}ns/row rep={d:.1}ns/row) -> {s} ({s})\n", .{
                    table, n_dirty, delta_rows, buf.items.len, base_bytes, replay_ns / 1000.0, rewrite_ns / 1000.0, WRITE_NS_PER_BYTE, ENCODE_ROW_NS, REPLAY_ROW_NS, if (use_delta) "delta" else "full", why,
                });
            }
            if (use_delta) {
                const f = try std.Io.Dir.cwd().createFile(io, dpath, .{});
                defer f.close(io);
                const w0 = std.Io.Clock.now(.awake, io).nanoseconds;
                try f.writeStreamingAll(io, buf.items);
                const w1 = std.Io.Clock.now(.awake, io).nanoseconds;
                self.learnEncode(n_dirty, a1 - a0);
                self.learnWrite(buf.items.len, w1 - w0);
                self.refreshWbTrailer(io, path);
                self.wb_dirty.clearRetainingCapacity();
                if (std.c.getenv("ZHDB_EXPLAIN") != null) {
                    const dt = @as(f64, @floatFromInt(std.Io.Clock.now(.awake, io).nanoseconds - t0)) / 1e6;
                    std.debug.print("[writeback] {s}: delta rows={d} bytes={d} {d:.1} ms\n", .{ table, n_dirty, buf.items.len, dt });
                }
                return;
            }
        }
        var buf = std.ArrayList(u8).empty;
        defer buf.deinit(gpa);
        const e0 = std.Io.Clock.now(.awake, io).nanoseconds;
        try t.saveWithCosts(gpa, &buf, .{
            .write_ns_byte = self.wb_write_ns_byte,
            .encode_ns_row = self.wb_encode_ns_row,
            .replay_ns_row = self.wb_replay_ns_row,
            .compact_row_ns = self.compact_row_ns,
            .samples = self.wb_samples,
            .scan_row_ns = self.cost_scan_row,
            .str_raw_ns = self.cost_str_raw_row,
            .str_dict_ns = self.cost_str_dict_row,
        });
        const e1 = std.Io.Clock.now(.awake, io).nanoseconds;
        const f = try std.Io.Dir.cwd().createFile(io, path, .{});
        defer f.close(io);
        const w0 = std.Io.Clock.now(.awake, io).nanoseconds;
        try f.writeStreamingAll(io, buf.items);
        const w1 = std.Io.Clock.now(.awake, io).nanoseconds;
        self.learnEncode(t.nrows, e1 - e0);
        self.learnWrite(buf.items.len, w1 - w0);
        self.refreshWbTrailer(io, path);
        self.wb_dirty.clearRetainingCapacity();
        self.wb_full = false;
        std.Io.Dir.cwd().deleteFile(io, dpath) catch {};
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            const dt = @as(f64, @floatFromInt(std.Io.Clock.now(.awake, io).nanoseconds - t0)) / 1e6;
            std.debug.print("[writeback] {s}: full rows={d} bytes={d} {d:.1} ms\n", .{ table, t.nrows, buf.items.len, dt });
        }
    }
    fn compactIfDense(self: *Engine, name: []const u8, dead_hint: usize) usize {
        const t = self.find(name) orelse return 0;
        const rows = t.rows.items.len;
        const dead = @max(t.dead_rows, dead_hint);
        if (rows < 64 or dead == 0) return 0;
        self.calibrateCostsFor(self.findColumnar(name));
        var q: f64 = 20;
        const observed: f64 = @floatFromInt(self.scansOf(name));
        if (observed > q) q = observed;
        if (std.c.getenv("ZHDB_COMPACT_Q")) |v| q = std.fmt.parseFloat(f64, std.mem.span(v)) catch q;
        const n: f64 = @floatFromInt(rows);
        const d: f64 = @floatFromInt(dead);
        const rewrite_cost = n * COST_COMPACT_ROW_NS;
        const scan_penalty = d * self.cost_scan_row * COST_TOMB_FACTOR;
        const should = scan_penalty * q > rewrite_cost;
        if (std.c.getenv("ZHDB_EXPLAIN") != null) {
            std.debug.print("[vacuum] {s}: dead={d}/{d} ({d:.1}%) penalty/scan={d:.2} ms expected={d:.0} ms rewrite={d:.1} ms q={d:.0} (observed={d}) -> {s}\n", .{
                name,
                dead,
                rows,
                d / n * 100.0,
                scan_penalty / 1e6,
                scan_penalty * q / 1e6,
                rewrite_cost / 1e6,
                q,
                self.scansOf(name),
                if (should) "compact" else "keep",
            });
        }
        if (!should) return 0;
        const before = rows;
        self.compactTable(name);
        const after = (self.find(name) orelse return 0).rows.items.len;
        return before - after;
    }
    const DeadBlocks = struct { rows: usize = 0, full: usize = 0, partial: usize = 0 };
    fn deadBlocks(self: *Engine, t: *Table) DeadBlocks {
        var rows: usize = 0;
        var full: usize = 0;
        var partial: usize = 0;
        const nb = (t.rows.items.len + seg_rows - 1) / seg_rows;
        var b: usize = 0;
        while (b < nb) : (b += 1) {
            const r0 = b * seg_rows;
            const r1 = @min(r0 + seg_rows, t.rows.items.len);
            var dead: usize = 0;
            var ri = r0;
            while (ri < r1) : (ri += 1) {
                const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
                const d = isRowDeleted(t, ri) or (xm != 0 and !self.isInFlight(xm));
                if (d) dead += 1;
            }
            rows += dead;
            const seg_len = r1 - r0;
            if (dead == seg_len and seg_len > 0) full += 1;
            if (seg_len > 0 and dead >= (seg_len + 3) / 4 and dead < seg_len) partial += 1;
        }
        return .{ .rows = rows, .full = full, .partial = partial };
    }
    fn compactionWorthIt(self: *Engine, name: []const u8, db: DeadBlocks) bool {
        _ = db;
        const t = self.find(name) orelse return false;
        const rows = t.rows.items.len;
        if (rows < 64) return false;
        self.calibrateCostsFor(self.findColumnar(name));
        var q: f64 = 20;
        const observed: f64 = @floatFromInt(self.scansOf(name));
        if (observed > q) q = observed;
        if (std.c.getenv("ZHDB_COMPACT_Q")) |v| q = std.fmt.parseFloat(f64, std.mem.span(v)) catch q;
        const nb = (rows + seg_rows - 1) / seg_rows;
        var should = false;
        var b: usize = 0;
        while (b < nb) : (b += 1) {
            const r0 = b * seg_rows;
            const r1 = @min(r0 + seg_rows, rows);
            var dead: usize = 0;
            var ri = r0;
            while (ri < r1) : (ri += 1) {
                const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
                if (isRowDeleted(t, ri) or (xm != 0 and !self.isInFlight(xm))) dead += 1;
            }
            if (dead == 0) continue;
            const blen: f64 = @floatFromInt(r1 - r0);
            const d: f64 = @floatFromInt(dead);
            const rewrite_b = blen * self.compact_row_ns;
            const scan_b = d * self.cost_scan_row * COST_TOMB_FACTOR * q;
            const space_b = (d / blen) * rewrite_b;
            const block_pays = dead >= (r1 - r0) or scan_b + space_b > rewrite_b;
            if (block_pays) should = true;
            if (std.c.getenv("ZHDB_EXPLAIN") != null and block_pays) {
                std.debug.print("[gc] {s}: block {d} dead={d}/{d} ({d:.0}%) q={d:.0} rewrite={d:.2}ms scan={d:.2}ms space={d:.2}ms -> compact\n", .{
                    name,
                    b,
                    dead,
                    r1 - r0,
                    d / blen * 100.0,
                    q,
                    rewrite_b / 1e6,
                    scan_b / 1e6,
                    space_b / 1e6,
                });
            }
        }
        if (!should and std.c.getenv("ZHDB_EXPLAIN") != null) {
            var total_dead: usize = 0;
            for (0..rows) |ri| {
                const xm: u64 = if (ri < t.xmax.items.len) t.xmax.items[ri] else 0;
                if (isRowDeleted(t, ri) or (xm != 0 and !self.isInFlight(xm))) total_dead += 1;
            }
            std.debug.print("[gc] {s}: dead={d}/{d} q={d:.0} -> keep (no block pays off)\n", .{ name, total_dead, rows, q });
        }
        return should;
    }
    fn markVacuumSize(self: *Engine, n: []const u8) void {
        const t = self.find(n) orelse return;
        if (t.rows.items.len > 0) return;
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(n.len, tb.len)], n[0..@min(n.len, tb.len)]);
        if (self.relopts.get(tl)) |st| {
            for (st.opts) |o| if (std.ascii.eqlIgnoreCase(o.name, "vacuum_truncate") and std.ascii.eqlIgnoreCase(o.value, "false")) return;
        }
        const k = self.gpa.dupe(u8, tl) catch return;
        self.zero_size.put(k, {}) catch {};
    }
    fn execVacuum(self: *Engine, name: ?[]const u8) EngineError!Result {
        if (name) |n| {
            self.execMaintenance(n, 1);
            self.ensureRowsMaterialized(n);
            const db = if (self.find(n)) |tt| self.deadBlocks(tt) else DeadBlocks{};
            var st = self.reclaimSegments(n);
            const dropped = self.truncateDeadTail(n);
            var block_compact = false;
            const compacted = if (db.full > 0) blk: {
                block_compact = true;
                self.compactTable(n);
                break :blk 1;
            } else self.compactIfDense(n, db.rows);
            if (compacted > 0 and std.c.getenv("ZHDB_EXPLAIN") != null) {
                std.debug.print("[vacuum] {s}: {s} ({d} rows)\n", .{
                    n, if (block_compact) "block compaction" else "compacted interior", compacted,
                });
            }
            st.blocks_dropped = (dropped + seg_rows - 1) / seg_rows;
            if (dropped > 0) st.rows += dropped;
            if (std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[vacuum] {s}: segments={d} rows={d} tail_rows={d} blocks_dropped={d}\n", .{ n, st.segments, st.rows - dropped, dropped, st.blocks_dropped });
            self.markVacuumSize(n);
            return .{ .affected = 0 };
        }
        var it = self.tables.iterator();
        while (it.next()) |e| {
            const nm = e.value_ptr.*.name;
            if (std.mem.startsWith(u8, nm, "pg_")) continue;
            self.ensureRowsMaterialized(nm);
            const db = if (self.find(nm)) |tt| self.deadBlocks(tt) else DeadBlocks{};
            const st = self.reclaimSegments(nm);
            const dropped = self.truncateDeadTail(nm);
            self.markVacuumSize(nm);
            var block_compact = false;
            const comp = if (db.full > 0) blk: {
                block_compact = true;
                self.compactTable(nm);
                break :blk 1;
            } else self.compactIfDense(nm, db.rows);
            if (comp > 0 and std.c.getenv("ZHDB_EXPLAIN") != null) {
                std.debug.print("[vacuum] {s}: {s} ({d} rows)\n", .{
                    nm,
                    if (block_compact) "block compaction" else "compacted interior",
                    comp,
                });
            }
            if (st.rows + dropped > 0 and std.c.getenv("ZHDB_EXPLAIN") != null) std.debug.print("[vacuum] {s}: segments={d} rows={d} tail_rows={d}\n", .{ nm, st.segments, st.rows, dropped });
        }
        return .{ .affected = 0 };
    }
    fn ddlKey(self: *Engine, kind: []const u8, name: []const u8) ![]u8 {
        var b = std.ArrayList(u8).empty;
        errdefer b.deinit(self.gpa);
        try b.appendSlice(self.gpa, kind);
        try b.append(self.gpa, ':');
        var lbuf: [512]u8 = undefined;
        const nm = std.ascii.lowerString(lbuf[0..@min(name.len, lbuf.len)], name[0..@min(name.len, lbuf.len)]);
        try b.appendSlice(self.gpa, nm);
        return b.toOwnedSlice(self.gpa);
    }
    fn registerDdlObject(self: *Engine, kind: []const u8, name: []const u8) void {
        if (name.len == 0) return;
        const key = self.ddlKey(kind, name) catch return;
        if (self.ddl_objects.contains(key)) {
            self.gpa.free(key);
            return;
        }
        if (std.c.getenv("ZHDB_DDL_DEBUG") != null) std.debug.print("[ddl] put {s}\n", .{key});
        self.ddl_objects.put(key, {}) catch self.gpa.free(key);
    }
    fn removeDdlObject(self: *Engine, kind: []const u8, name: []const u8) bool {
        const key = self.ddlKey(kind, name) catch return false;
        if (self.ddl_objects.fetchRemove(key)) |_| {
            self.gpa.free(key);
            return true;
        }
        self.gpa.free(key);
        return false;
    }
    fn hasDdlObject(self: *Engine, kind: []const u8, name: []const u8) bool {
        const key = self.ddlKey(kind, name) catch return false;
        defer self.gpa.free(key);
        return self.ddl_objects.contains(key);
    }
    fn bumpFnCount(self: *Engine, kind: []const u8, name: []const u8, delta: i32) void {
        const key = self.ddlKey(kind, name) catch return;
        if (self.ddl_fn_counts.getPtr(key)) |p| {
            if (delta > 0) p.* += 1 else if (p.* > 0) p.* -= 1;
            if (p.* == 0) {
                _ = self.ddl_fn_counts.remove(key);
                self.gpa.free(key);
                return;
            }
            self.gpa.free(key);
            return;
        }
        if (delta > 0) {
            self.ddl_fn_counts.put(key, 1) catch self.gpa.free(key);
        } else self.gpa.free(key);
    }
    fn fnCount(self: *Engine, kind: []const u8, name: []const u8) usize {
        const key = self.ddlKey(kind, name) catch return 0;
        defer self.gpa.free(key);
        return self.ddl_fn_counts.get(key) orelse 0;
    }
    fn removeFnExact(self: *Engine, kind: []const u8, name: []const u8, sig: []const u8) bool {
        var b = std.ArrayList(u8).empty;
        errdefer b.deinit(self.gpa);
        b.appendSlice(self.gpa, kind) catch return false;
        b.append(self.gpa, ':') catch return false;
        var lbuf: [512]u8 = undefined;
        const nm = std.ascii.lowerString(lbuf[0..@min(name.len, lbuf.len)], name[0..@min(name.len, lbuf.len)]);
        b.appendSlice(self.gpa, nm) catch return false;
        b.append(self.gpa, '(') catch return false;
        b.appendSlice(self.gpa, sig) catch return false;
        b.append(self.gpa, ')') catch return false;
        const key = b.toOwnedSlice(self.gpa) catch return false;
        if (self.ddl_objects.fetchRemove(key)) |_| {
            self.gpa.free(key);
            return true;
        }
        self.gpa.free(key);
        return false;
    }
    fn removeFnAny(self: *Engine, kind: []const u8, name: []const u8) bool {
        var it = self.ddl_objects.keyIterator();
        var found: ?[]const u8 = null;
        var lbuf: [512]u8 = undefined;
        const nm = std.ascii.lowerString(lbuf[0..@min(name.len, lbuf.len)], name[0..@min(name.len, lbuf.len)]);
        while (it.next()) |k| {
            if (!std.mem.startsWith(u8, k.*, kind)) continue;
            if (k.*.len <= kind.len + 1 or k.*[kind.len] != ':') continue;
            if (!std.mem.startsWith(u8, k.*[kind.len + 1 ..], nm)) continue;
            const rest = k.*[kind.len + 1 + nm.len ..];
            if (rest.len >= 2 and rest[0] == '(' and rest[rest.len - 1] == ')') {
                found = k.*;
                break;
            }
        }
        if (found) |k| {
            _ = self.ddl_objects.remove(k);
            self.gpa.free(k);
            return true;
        }
        return false;
    }
    fn b64Encode(alloc: std.mem.Allocator, data: []const u8) ![]const u8 {
        const enc = std.base64.standard.Encoder;
        const out = try alloc.alloc(u8, enc.calcSize(data.len));
        _ = enc.encode(out, data);
        return out;
    }
    fn b64Decode(alloc: std.mem.Allocator, text: []const u8) !?[]const u8 {
        const dec = std.base64.standard.Decoder;
        const n = dec.calcSizeForSlice(text) catch return null;
        const out = try alloc.alloc(u8, n);
        dec.decode(out, text) catch {
            alloc.free(out);
            return null;
        };
        return out;
    }
    fn md5Hex(alloc: std.mem.Allocator, data: []const u8) ![]const u8 {
        var digest: [16]u8 = undefined;
        std.crypto.hash.Md5.hash(data, &digest, .{});
        const hex = "0123456789abcdef";
        const out = try alloc.alloc(u8, 32);
        for (digest, 0..) |b, i| {
            out[i * 2] = hex[b >> 4];
            out[i * 2 + 1] = hex[b & 0xf];
        }
        return out;
    }
    fn isHexStr(s: []const u8) bool {
        for (s) |c| if (!std.ascii.isHex(c)) return false;
        return true;
    }
    fn scramParts(secret: []const u8) ?struct { iter: u64, salt: []const u8, stored: []const u8, server: []const u8 } {
        if (!std.mem.startsWith(u8, secret, "SCRAM-SHA-256$")) return null;
        const rest = secret["SCRAM-SHA-256$".len..];
        const d1 = std.mem.indexOfScalar(u8, rest, '$') orelse return null;
        const first = rest[0..d1];
        const after = rest[d1 + 1 ..];
        const d2 = std.mem.indexOfScalar(u8, after, ':') orelse return null;
        const c = std.mem.indexOfScalar(u8, first, ':') orelse return null;
        const iter = std.fmt.parseInt(u64, first[0..c], 10) catch return null;
        return .{ .iter = iter, .salt = first[c + 1 ..], .stored = after[0..d2], .server = after[d2 + 1 ..] };
    }
    fn validScram(alloc: std.mem.Allocator, secret: []const u8) bool {
        const p = scramParts(secret) orelse return false;
        if (p.iter < 1 or p.iter > 100_000_000) return false;
        const salt = (b64Decode(alloc, p.salt) catch return false) orelse return false;
        defer alloc.free(salt);
        const st = (b64Decode(alloc, p.stored) catch return false) orelse return false;
        defer alloc.free(st);
        const sv = (b64Decode(alloc, p.server) catch return false) orelse return false;
        defer alloc.free(sv);
        return st.len == 32 and sv.len == 32 and salt.len >= 8 and salt.len <= 64;
    }
    fn scramDerive(alloc: std.mem.Allocator, password: []const u8, salt: []const u8, iter: u64) !struct { stored: [32]u8, server: [32]u8, salt: []const u8 } {
        const Hmac = std.crypto.auth.hmac.sha2.HmacSha256;
        var salted: [32]u8 = undefined;
        std.crypto.pwhash.pbkdf2(&salted, password, salt, @intCast(iter), Hmac) catch {};
        var client_key: [32]u8 = undefined;
        Hmac.create(&client_key, "Client Key", &salted);
        var stored: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(&client_key, &stored, .{});
        var server: [32]u8 = undefined;
        Hmac.create(&server, "Server Key", &salted);
        _ = alloc;
        return .{ .stored = stored, .server = server, .salt = salt };
    }
    fn scramHash(self: *Engine, alloc: std.mem.Allocator, password: []const u8) ![]const u8 {
        var salt: [16]u8 = undefined;
        randomBytes(&salt);
        var iter: u64 = 4096;
        if (self.settings.get("scram_iterations")) |sv| {
            iter = std.fmt.parseInt(u64, sv, 10) catch 4096;
            if (iter < 1) iter = 4096;
        }
        const d = try scramDerive(alloc, password, &salt, iter);
        const s64 = try b64Encode(alloc, d.salt);
        const st64 = try b64Encode(alloc, &d.stored);
        const sv64 = try b64Encode(alloc, &d.server);
        return std.fmt.allocPrint(alloc, "SCRAM-SHA-256${d}:{s}${s}:{s}", .{ iter, s64, st64, sv64 });
    }
    fn scramMatchesEmpty(alloc: std.mem.Allocator, secret: []const u8) bool {
        const p = scramParts(secret) orelse return false;
        const salt = (b64Decode(alloc, p.salt) catch return false) orelse return false;
        defer alloc.free(salt);
        const st = (b64Decode(alloc, p.stored) catch return false) orelse return false;
        defer alloc.free(st);
        const d = scramDerive(alloc, "", salt, p.iter) catch return false;
        return std.mem.eql(u8, &d.stored, st);
    }
    fn preparePassword(self: *Engine, alloc: std.mem.Allocator, role: []const u8, secret: []const u8) EngineError!?[]const u8 {
        if (secret.len == 0) {
            pushNotice("empty string is not a valid password, clearing password", .{});
            return null;
        }
        if (std.mem.startsWith(u8, secret, "SCRAM-SHA-256$") and secret.len > 512) {
            setDiag("encrypted password is too long\nDETAIL:  Encrypted passwords must be no longer than 512 bytes.", .{});
            return error.EncryptedPasswordTooLong;
        }
        const method_md5 = blk: {
            const sv = self.settings.get("password_encryption") orelse "scram-sha-256";
            break :blk std.ascii.eqlIgnoreCase(sv, "md5");
        };
        if (secret.len == 35 and std.mem.startsWith(u8, secret, "md5") and isHexStr(secret[3..])) {
            const empty_secret = try md5Hex(alloc, role);
            if (std.mem.eql(u8, secret[3..], empty_secret)) {
                pushNotice("empty string is not a valid password, clearing password", .{});
                return null;
            }
            pushWarning("setting an MD5-encrypted password", "MD5 password support is deprecated and will be removed in a future release of PostgreSQL.", "Refer to the PostgreSQL documentation for details about migrating to another password type.");
            return try self.gpa.dupe(u8, secret);
        }
        if (std.mem.startsWith(u8, secret, "SCRAM-SHA-256$")) {
            if (validScram(alloc, secret)) {
                if (scramMatchesEmpty(alloc, secret)) {
                    pushNotice("empty string is not a valid password, clearing password", .{});
                    return null;
                }
                return try self.gpa.dupe(u8, secret);
            }
        }
        if (method_md5) {
            const cat = try std.fmt.allocPrint(alloc, "{s}{s}", .{ secret, role });
            const h = try md5Hex(alloc, cat);
            pushWarning("setting an MD5-encrypted password", "MD5 password support is deprecated and will be removed in a future release of PostgreSQL.", "Refer to the PostgreSQL documentation for details about migrating to another password type.");
            return std.fmt.allocPrint(self.gpa, "md5{s}", .{h}) catch error.OutOfMemory;
        }
        const h = try scramHash(self, alloc, secret);
        return self.gpa.dupe(u8, h) catch error.OutOfMemory;
    }
    fn hasEnabledLoginTrigger(self: *Engine) bool {
        var it = self.login_triggers.iterator();
        while (it.next()) |e| if (e.value_ptr.enabled) return true;
        return false;
    }
    pub fn fireLoginTriggers(self: *Engine, alloc: std.mem.Allocator) void {
        var it = self.login_triggers.iterator();
        while (it.next()) |e| {
            if (!e.value_ptr.enabled) continue;
            const body = self.plpgsql_funcs.get(e.value_ptr.func) orelse self.sql_funcs.get(e.value_ptr.func) orelse continue;
            self.execPlpgsqlLogin(alloc, body) catch {};
        }
    }
    fn execPlpgsqlLogin(self: *Engine, alloc: std.mem.Allocator, body0: []const u8) EngineError!void {
        var body = std.mem.trim(u8, body0, " \t\r\n");
        if (std.ascii.startsWithIgnoreCase(body, "begin")) body = body[5..];
        if (std.ascii.endsWithIgnoreCase(std.mem.trimEnd(u8, body, " \t\r\n;"), "end")) {
            body = std.mem.trimEnd(u8, body, " \t\r\n;");
            body = body[0 .. body.len - 3];
        }
        var stmts = std.ArrayList([]const u8).empty;
        defer stmts.deinit(alloc);
        var start: usize = 0;
        var i: usize = 0;
        var q = false;
        while (i < body.len) : (i += 1) {
            const ch = body[i];
            if (ch == '\'') {
                q = !q;
            } else if (ch == ';' and !q) {
                const st = std.mem.trim(u8, body[start..i], " \t\r\n");
                if (st.len > 0) try stmts.append(alloc, st);
                start = i + 1;
            }
        }
        const tail = std.mem.trim(u8, body[start..], " \t\r\n");
        if (tail.len > 0) try stmts.append(alloc, tail);
        for (stmts.items) |st| {
            if (std.ascii.startsWithIgnoreCase(st, "raise notice") or std.ascii.startsWithIgnoreCase(st, "raise info")) {
                if (std.mem.indexOfScalar(u8, st, '\'')) |q1| {
                    if (std.mem.indexOfScalarPos(u8, st, q1 + 1, '\'')) |q2| {
                        pushNotice("{s}", .{st[q1 + 1 .. q2]});
                    }
                }
                continue;
            }
            if (std.ascii.startsWithIgnoreCase(st, "return") or std.ascii.startsWithIgnoreCase(st, "null")) continue;
            const pstmt = sql.parseStatementText(alloc, st) catch {
                continue;
            };
            _ = self.exec(alloc, pstmt) catch {};
        }
    }
    fn applyRoleOpts(self: *Engine, name: []const u8, rs: *RoleState, o: sql.RoleOpts) EngineError!void {
        if (o.superuser) |v| rs.superuser = v;
        if (o.inherit) |v| rs.inherit = v;
        if (o.createrole) |v| rs.createrole = v;
        if (o.createdb) |v| rs.createdb = v;
        if (o.canlogin) |v| rs.canlogin = v;
        if (o.replication) |v| rs.replication = v;
        if (o.bypassrls) |v| rs.bypassrls = v;
        if (o.connlimit) |v| rs.connlimit = v;
        if (o.password_set) {
            if (rs.password) |old| self.gpa.free(old);
            rs.password = if (o.password) |pw| try self.preparePassword(self.gpa, name, pw) else null;
        }
        if (o.validuntil) |vu| {
            if (rs.validuntil) |old| self.gpa.free(old);
            rs.validuntil = self.gpa.dupe(u8, vu) catch null;
        }
    }
    fn noteRead(self: *Engine, tn: []const u8) void {
        if (!self.inTxn()) return;
        for (self.txnCtx().read_tables.items) |r| if (std.ascii.eqlIgnoreCase(r, tn)) return;
        const d = self.gpa.dupe(u8, tn) catch return;
        self.txnCtx().read_tables.append(self.gpa, d) catch {};
    }
    fn preparedWrote(self: *Engine, tn: []const u8) bool {
        for (self.prepared_xacts.items) |px| for (px.writes.items) |w| if (std.ascii.eqlIgnoreCase(w, tn)) return true;
        return false;
    }
    fn txnRead(self: *Engine, tn: []const u8) bool {
        for (self.txnCtx().read_tables.items) |r| if (std.ascii.eqlIgnoreCase(r, tn)) return true;
        return false;
    }
    fn preparedHasLock(self: *Engine, tn: []const u8) bool {
        for (self.prepared_xacts.items) |px| for (px.locks.items) |l| if (std.ascii.eqlIgnoreCase(l.table, tn)) return true;
        return false;
    }
    fn preparedDropped(self: *Engine, tn: []const u8) bool {
        for (self.prepared_xacts.items) |px| for (px.drops.items) |d| if (std.ascii.eqlIgnoreCase(d, tn)) return true;
        return false;
    }
    fn isPreparedTx(self: *Engine, id: u64) bool {
        for (self.prepared_xacts.items) |px| if (px.txid == id) return true;
        return false;
    }
    fn execPrepareXact(self: *Engine, gid: []const u8) EngineError!Result {
        for (self.prepared_xacts.items) |px| {
            if (std.mem.eql(u8, px.gid, gid)) {
                setDiag("transaction identifier \"{s}\" is already in use", .{gid});
                return error.RawDdlError;
            }
        }
        if (!self.inTxn()) return .{};
        var has_sess = false;
        var has_xact = false;
        for (self.adv_locks.items) |a| for (self.adv_locks.items) |b| {
            if (a.classid == b.classid and a.objid == b.objid and a.subid == b.subid and a.xact != b.xact) {
                has_sess = true;
                has_xact = true;
            }
        };
        if (has_sess and has_xact) {
            setDiag("cannot PREPARE while holding both session-level and transaction-level locks on the same object", .{});
            return error.RawDdlError;
        }
        const ctx = self.txnCtx();
        var px = PreparedXact{ .gid = self.gpa.dupe(u8, gid) catch return error.OutOfMemory, .txid = ctx.txid, .writer = self.gpa.dupe(u8, self.curRoleName()) catch "", .db = self.gpa.dupe(u8, "regression") catch "" };
        for (ctx.undo.items) |u| {
            px.writes.append(self.gpa, self.gpa.dupe(u8, u.name) catch continue) catch {};
            self.dropColumnar(u.name);
        }
        for (ctx.dropped_tables.items) |d| px.drops.append(self.gpa, self.gpa.dupe(u8, d) catch continue) catch {};
        for (ctx.row_locks.items) |l| px.locks.append(self.gpa, .{ .table = self.gpa.dupe(u8, l.table) catch continue, .id = l.id }) catch {};
        self.prepared_xacts.append(self.gpa, px) catch return error.OutOfMemory;
        // detach the transaction without committing or aborting it
        for (ctx.stmts.items) |t| self.gpa.free(t);
        ctx.stmts.clearRetainingCapacity();
        for (ctx.undo.items) |u| {
            if (u.rows.len > 0) self.gpa.free(u.rows);
            self.gpa.free(u.name);
        }
        ctx.undo.clearRetainingCapacity();
        for (ctx.read_tables.items) |r| self.gpa.free(r);
        ctx.read_tables.clearRetainingCapacity();
        for (ctx.dropped_tables.items) |d| self.gpa.free(d);
        ctx.dropped_tables.clearRetainingCapacity();
        for (ctx.row_locks.items) |l| self.gpa.free(l.table);
        ctx.row_locks.clearRetainingCapacity();
        for (ctx.created_views.items) |cn| self.gpa.free(cn);
        ctx.created_views.clearRetainingCapacity();
        ctx.in_txn = false;
        _ = self.open_txns.fetchSub(1, .acq_rel);
        self.clearSqlCursors();
        self.invalidateCatalogs();
        return .{};
    }
    fn execCommitPrepared(self: *Engine, gid: []const u8) EngineError!Result {
        var idx: ?usize = null;
        for (self.prepared_xacts.items, 0..) |px, i| if (std.mem.eql(u8, px.gid, gid)) {
            idx = i;
            break;
        };
        const i = idx orelse {
            setDiag("prepared transaction with identifier \"{s}\" does not exist", .{gid});
            return error.PreparedNotFound;
        };
        const px = self.prepared_xacts.orderedRemove(i);
        self.removeInFlight(px.txid);
        self.txid_committed.put(px.txid, {}) catch {};
        for (px.writes.items) |tn| self.dropColumnar(tn);
        self.freePreparedXact(px);
        self.invalidateCatalogs();
        return .{};
    }
    fn execRollbackPrepared(self: *Engine, gid: []const u8) EngineError!Result {
        var idx: ?usize = null;
        for (self.prepared_xacts.items, 0..) |px, i| if (std.mem.eql(u8, px.gid, gid)) {
            idx = i;
            break;
        };
        const i = idx orelse {
            setDiag("prepared transaction with identifier \"{s}\" does not exist", .{gid});
            return error.PreparedNotFound;
        };
        const px = self.prepared_xacts.orderedRemove(i);
        self.removeInFlight(px.txid);
        self.txid_aborted.put(px.txid, {}) catch {};
        for (px.writes.items) |tn| {
            if (self.find(tn)) |t| {
                const gpa = self.gpa;
                var ri: usize = 0;
                while (ri < t.xmax.items.len) : (ri += 1) {
                    if (t.xmax.items[ri] == px.txid) t.xmax.items[ri] = 0;
                }
                var w: usize = 0;
                ri = 0;
                while (ri < t.rows.items.len) : (ri += 1) {
                    if (ri < t.xmin.items.len and t.xmin.items[ri] == px.txid) {
                        gpa.free(t.rows.items[ri]);
                        continue;
                    }
                    t.rows.items[w] = t.rows.items[ri];
                    if (ri < t.xmin.items.len) t.xmin.items[w] = t.xmin.items[ri];
                    if (ri < t.xmax.items.len) t.xmax.items[w] = t.xmax.items[ri];
                    w += 1;
                }
                t.rows.items.len = w;
                if (t.xmin.items.len > w) t.xmin.items.len = w;
                if (t.xmax.items.len > w) t.xmax.items.len = w;
                t.deleted.clearRetainingCapacity();
                for (t.rows.items, 0..) |_, idx2| {
                    _ = idx2;
                    t.deleted.append(gpa, 0) catch break;
                }
                self.dropColumnar(tn);
            }
        }
        var names = std.ArrayList([]const u8).empty;
        defer names.deinit(self.gpa);
        var it = self.tables.iterator();
        while (it.next()) |e| {
            if (e.value_ptr.*.created_by == px.txid) names.append(self.gpa, e.key_ptr.*) catch {};
        }
        for (names.items) |nm| {
            _ = self.tables.remove(nm);
        }
        self.freePreparedXact(px);
        self.invalidateCatalogs();
        return .{};
    }
    fn freePreparedXact(self: *Engine, px0: PreparedXact) void {
        var px = px0;
        self.gpa.free(px.gid);
        self.gpa.free(px.writer);
        self.gpa.free(px.db);
        for (px.writes.items) |w| self.gpa.free(w);
        px.writes.deinit(self.gpa);
        for (px.drops.items) |d| self.gpa.free(d);
        px.drops.deinit(self.gpa);
        for (px.locks.items) |l| self.gpa.free(l.table);
        px.locks.deinit(self.gpa);
    }
    fn currentRoleState(self: *Engine) ?RoleState {
        if (self.role_len == 0) return .{ .superuser = true };
        return self.roles.get(self.role_buf[0..self.role_len]);
    }
    fn currentIsSuper(self: *Engine) bool {
        if (self.role_len == 0) return true;
        const rs = self.roles.get(self.role_buf[0..self.role_len]) orelse return false;
        return rs.superuser;
    }
    fn roleIsSuper(self: *Engine, name: []const u8) bool {
        const rs = self.roles.get(name) orelse return false;
        return rs.superuser;
    }
    fn membershipOf(self: *Engine, member: []const u8, role: []const u8) ?*Membership {
        for (self.role_members.items) |*m| {
            if (std.ascii.eqlIgnoreCase(m.member, member) and std.ascii.eqlIgnoreCase(m.role, role)) return m;
        }
        return null;
    }
    fn addMembership(self: *Engine, member: []const u8, role: []const u8, admin: bool, inherit: bool, set_opt: bool) void {
        if (self.membershipOf(member, role)) |m| {
            m.admin = admin;
            m.inherit = inherit;
            m.set_opt = set_opt;
            return;
        }
        self.role_members.append(self.gpa, .{
            .member = self.gpa.dupe(u8, member) catch return,
            .role = self.gpa.dupe(u8, role) catch return,
            .admin = admin,
            .inherit = inherit,
            .set_opt = set_opt,
        }) catch {};
    }
    fn hasAdminOn(self: *Engine, member: []const u8, role: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(member, role)) return true;
        if (self.membershipOf(member, role)) |m| return m.admin;
        return false;
    }
    fn canSetRole(self: *Engine, role: []const u8) bool {
        if (self.currentIsSuper()) return true;
        const cur = self.curRoleName();
        if (std.ascii.eqlIgnoreCase(cur, role)) return true;
        if (self.membershipOf(cur, role)) |m| return m.set_opt;
        return false;
    }
    fn hasPrivsOfRole(self: *Engine, role: []const u8) bool {
        if (self.currentIsSuper()) return true;
        const cur = self.curRoleName();
        if (std.ascii.eqlIgnoreCase(cur, role)) return true;
        if (self.membershipOf(cur, role)) |m| return m.inherit;
        return false;
    }
    fn isOwnerRole(self: *Engine, kind: []const u8, name: []const u8) bool {
        if (self.currentIsSuper()) return true;
        const owner = self.ownerOf(kind, name);
        if (std.ascii.eqlIgnoreCase(owner, self.curRoleName())) return true;
        return self.hasPrivsOfRole(owner);
    }
    fn checkCreateAttr(self: *Engine, want: bool, attr: []const u8) EngineError!void {
        if (!want) return;
        const rs = self.currentRoleState() orelse RoleState{};
        const ok = self.currentIsSuper() or
            (std.ascii.eqlIgnoreCase(attr, "SUPERUSER") and rs.superuser) or
            (std.ascii.eqlIgnoreCase(attr, "CREATEDB") and rs.createdb) or
            (std.ascii.eqlIgnoreCase(attr, "CREATEROLE") and rs.createrole) or
            (std.ascii.eqlIgnoreCase(attr, "REPLICATION") and rs.replication) or
            (std.ascii.eqlIgnoreCase(attr, "BYPASSRLS") and rs.bypassrls);
        if (ok) return;
        setDiag("permission denied to create role\nDETAIL:  Only roles with the {s} attribute may create roles with the {s} attribute.", .{ attr, attr });
        return error.RawDdlError;
    }
    fn checkAlterAttr(self: *Engine, want: bool, attr: []const u8) EngineError!void {
        if (!want) return;
        const rs = self.currentRoleState() orelse RoleState{};
        const ok = self.currentIsSuper() or
            (std.ascii.eqlIgnoreCase(attr, "SUPERUSER") and rs.superuser) or
            (std.ascii.eqlIgnoreCase(attr, "CREATEDB") and rs.createdb) or
            (std.ascii.eqlIgnoreCase(attr, "CREATEROLE") and rs.createrole) or
            (std.ascii.eqlIgnoreCase(attr, "REPLICATION") and rs.replication) or
            (std.ascii.eqlIgnoreCase(attr, "BYPASSRLS") and rs.bypassrls);
        if (ok) return;
        setDiag("permission denied to alter role\nDETAIL:  Only roles with the {s} attribute may change the {s} attribute.", .{ attr, attr });
        return error.RawDdlError;
    }
    fn roleExistsOrFail(self: *Engine, name: []const u8) EngineError!void {
        if (self.roles.contains(name)) return;
        setDiag("role \"{s}\" does not exist", .{name});
        return error.RoleNotFound;
    }
    fn execCreateRole(self: *Engine, name: []const u8, is_user: bool, opts: sql.RoleOpts) EngineError!Result {
        if (self.roles.contains(name)) {
            setDiag("role \"{s}\" already exists", .{name});
            return error.RoleExists;
        }
        try self.checkCreateAttr(opts.superuser orelse false, "SUPERUSER");
        try self.checkCreateAttr(opts.createdb orelse false, "CREATEDB");
        try self.checkCreateAttr(opts.createrole orelse false, "CREATEROLE");
        try self.checkCreateAttr(opts.replication orelse false, "REPLICATION");
        try self.checkCreateAttr(opts.bypassrls orelse false, "BYPASSRLS");
        // Validate IN ROLE grants first.
        for (opts.in_roles) |tgt| {
            if (std.ascii.eqlIgnoreCase(tgt, name)) {
                setDiag("role \"{s}\" is a member of role \"{s}\"", .{ name, name });
                return error.RawDdlError;
            }
            if (std.ascii.eqlIgnoreCase(tgt, "pg_database_owner")) {
                setDiag("role \"pg_database_owner\" cannot have explicit members", .{});
                return error.RawDdlError;
            }
            if (!self.currentIsSuper()) {
                if (self.roleIsSuper(tgt)) {
                    setDiag("permission denied to grant role \"{s}\"\nDETAIL:  Only roles with the SUPERUSER attribute may grant roles with the SUPERUSER attribute.", .{tgt});
                    return error.RawDdlError;
                }
                if (!self.hasAdminOn(self.curRoleName(), tgt)) {
                    setDiag("permission denied to grant role \"{s}\"\nDETAIL:  Only roles with the ADMIN option on role \"{s}\" may grant this role.", .{ tgt, tgt });
                    return error.RawDdlError;
                }
            }
        }
        for (opts.member_roles) |tgt| {
            if (std.ascii.eqlIgnoreCase(tgt, name)) {
                setDiag("role \"{s}\" is a member of role \"{s}\"", .{ name, name });
                return error.RawDdlError;
            }
        }
        for (opts.admin_roles) |tgt| {
            if (std.ascii.eqlIgnoreCase(tgt, name)) {
                setDiag("role \"{s}\" is a member of role \"{s}\"", .{ name, name });
                return error.RawDdlError;
            }
        }
        var rs = RoleState{ .canlogin = is_user };
        try self.applyRoleOpts(name, &rs, opts);
        const key = self.gpa.dupe(u8, name) catch return error.OutOfMemory;
        self.roles.put(key, rs) catch {
            self.gpa.free(key);
            return error.OutOfMemory;
        };
        for (opts.in_roles) |tgt| self.addMembership(name, tgt, false, opts.inherit orelse true, true);
        for (opts.member_roles) |tgt| {
            const trs = self.roles.get(tgt) orelse RoleState{};
            self.addMembership(tgt, name, false, trs.inherit, true);
        }
        for (opts.admin_roles) |tgt| {
            const trs = self.roles.get(tgt) orelse RoleState{};
            self.addMembership(tgt, name, true, trs.inherit, true);
        }
        if (!self.currentIsSuper() and self.curRoleName().len > 0 and !std.ascii.eqlIgnoreCase(self.curRoleName(), name)) {
            // CREATEROLE users get ADMIN on roles they create.
            self.addMembership(self.curRoleName(), name, true, false, false);
            if (self.settings.get("createrole_self_grant")) |sg| {
                const set_opt = ciIndex(sg, "set") != null;
                const inh = ciIndex(sg, "inherit") != null;
                if (set_opt or inh) self.addMembership(self.curRoleName(), name, false, inh, set_opt);
            }
        }
        if (opts.sysid) pushNotice("SYSID can no longer be specified", .{});
        self.rebuildAuthid();
        return .{};
    }
    fn execAlterRole(self: *Engine, name: []const u8, opts: sql.RoleOpts, rename_to: ?[]const u8) EngineError!Result {
        const rs = self.roles.getPtr(name) orelse {
            setDiag("role \"{s}\" does not exist", .{name});
            return error.RoleNotFound;
        };
        if (!self.currentIsSuper() and !self.hasAdminOn(self.curRoleName(), name)) {
            const act = if (rename_to != null) "rename" else "alter";
            setDiag("permission denied to {s} role\nDETAIL:  Only roles with the CREATEROLE attribute and the ADMIN option on role \"{s}\" may {s} this role.", .{ act, name, act });
            return error.RawDdlError;
        }
        try self.checkAlterAttr(opts.superuser != null, "SUPERUSER");
        try self.checkAlterAttr(opts.createdb orelse false, "CREATEDB");
        try self.checkAlterAttr(opts.createrole orelse false, "CREATEROLE");
        try self.checkAlterAttr(opts.replication orelse false, "REPLICATION");
        try self.checkAlterAttr(opts.bypassrls orelse false, "BYPASSRLS");
        try self.applyRoleOpts(name, rs, opts);
        if (rename_to) |nn| {
            if (rs.password) |pw| {
                if (pw.len > 3 and std.mem.startsWith(u8, pw, "md5")) {
                    self.gpa.free(pw);
                    rs.password = null;
                    pushNotice("MD5 password cleared because of role rename", .{});
                }
            }
            const kv = self.roles.fetchRemove(name).?;
            const nk = self.gpa.dupe(u8, nn) catch return error.OutOfMemory;
            self.roles.put(nk, kv.value) catch return error.OutOfMemory;
            self.gpa.free(kv.key);
            for (self.role_members.items) |*m| {
                if (std.ascii.eqlIgnoreCase(m.member, name)) {
                    const d = self.gpa.dupe(u8, nn) catch continue;
                    self.gpa.free(m.member);
                    m.member = d;
                }
                if (std.ascii.eqlIgnoreCase(m.role, name)) {
                    const d = self.gpa.dupe(u8, nn) catch continue;
                    self.gpa.free(m.role);
                    m.role = d;
                }
            }
            if (self.role_comments.fetchRemove(name)) |old| {
                self.gpa.free(old.key);
                const nk2 = self.gpa.dupe(u8, nn) catch return error.OutOfMemory;
                self.role_comments.put(nk2, old.value) catch {};
            }
        }
        self.rebuildAuthid();
        return .{};
    }
    fn execDropRole(self: *Engine, names: []const []const u8, if_exists: bool) EngineError!Result {
        for (names, 0..) |name, ni| {
            var dup = false;
            for (names[0..ni]) |prev| {
                if (std.ascii.eqlIgnoreCase(prev, name)) {
                    dup = true;
                    break;
                }
            }
            if (dup) continue;
            if (!self.roles.contains(name)) {
                if (if_exists) continue;
                setDiag("role \"{s}\" does not exist", .{name});
                return error.RoleNotFound;
            }
            if (std.ascii.eqlIgnoreCase(name, self.curRoleName())) {
                setDiag("current user cannot be dropped", .{});
                return error.RawDdlError;
            }
            if (!self.currentIsSuper() and self.roleIsSuper(name)) {
                setDiag("permission denied to drop role\nDETAIL:  Only roles with the SUPERUSER attribute may drop roles with the SUPERUSER attribute.", .{});
                return error.RawDdlError;
            }
            // Dependency errors are reported before permission errors.
            try self.checkDropRole(self.gpa, name);
            if (!self.currentIsSuper()) {
                const trs = self.roles.get(name) orelse RoleState{};
                if (trs.createrole and !self.hasAdminOn(self.curRoleName(), name)) {
                    setDiag("permission denied to drop role\nDETAIL:  Only roles with the CREATEROLE attribute and the ADMIN option on role \"{s}\" may drop this role.", .{name});
                    return error.RawDdlError;
                }
            }
            if (self.roles.fetchRemove(name)) |kv| {
                if (kv.value.password) |pw| self.gpa.free(pw);
                if (kv.value.validuntil) |vu| self.gpa.free(vu);
                self.gpa.free(kv.key);
            }
            var i: usize = 0;
            while (i < self.role_members.items.len) {
                const m = self.role_members.items[i];
                if (std.ascii.eqlIgnoreCase(m.member, name) or std.ascii.eqlIgnoreCase(m.role, name)) {
                    self.gpa.free(m.member);
                    self.gpa.free(m.role);
                    _ = self.role_members.orderedRemove(i);
                } else i += 1;
            }
            if (self.role_comments.fetchRemove(name)) |old| {
                self.gpa.free(old.key);
                self.gpa.free(old.value);
            }
        }
        self.rebuildAuthid();
        return .{};
    }
    fn execCommentRole(self: *Engine, cr: anytype) EngineError!Result {
        if (!self.roles.contains(cr.name)) {
            setDiag("role \"{s}\" does not exist", .{cr.name});
            return error.RoleNotFound;
        }
        if (!self.currentIsSuper() and !self.hasAdminOn(self.curRoleName(), cr.name)) {
            setDiag("permission denied\nDETAIL:  The current user must have the ADMIN option on role \"{s}\".", .{cr.name});
            return error.RawDdlError;
        }
        if (self.role_comments.fetchRemove(cr.name)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        if (cr.comment) |c| {
            const k = self.gpa.dupe(u8, cr.name) catch return error.OutOfMemory;
            const v = self.gpa.dupe(u8, c) catch return error.OutOfMemory;
            self.role_comments.put(k, v) catch {};
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execRoleGrant(self: *Engine, rg: anytype) EngineError!Result {
        const role = rg.role;
        if (rg.revoke) {
            for (rg.members) |mem| {
                if (self.membershipOf(mem, role)) |m| {
                    if (rg.revoke_admin) m.admin = false;
                    if (rg.revoke_inherit) m.inherit = false;
                    if (rg.revoke_set) m.set_opt = false;
                    if (!m.admin and !m.inherit and !m.set_opt) {
                        const member = m.member;
                        const r = m.role;
                        self.gpa.free(member);
                        self.gpa.free(r);
                        var i: usize = 0;
                        while (i < self.role_members.items.len) : (i += 1) {
                            if (std.ascii.eqlIgnoreCase(self.role_members.items[i].member, mem) and std.ascii.eqlIgnoreCase(self.role_members.items[i].role, role)) {
                                _ = self.role_members.orderedRemove(i);
                                break;
                            }
                        }
                    }
                }
            }
            return .{};
        }
        if (!self.roles.contains(role)) {
            setDiag("role \"{s}\" does not exist", .{role});
            return error.RoleNotFound;
        }
        for (rg.members) |mem| {
            if (!self.roles.contains(mem) and !std.ascii.eqlIgnoreCase(mem, "public")) {
                setDiag("role \"{s}\" does not exist", .{mem});
                return error.RoleNotFound;
            }
            if (std.ascii.eqlIgnoreCase(mem, role)) {
                setDiag("role \"{s}\" is a member of role \"{s}\"", .{ mem, role });
                return error.RawDdlError;
            }
            self.addMembership(mem, role, rg.admin_opt orelse false, rg.inherit_opt orelse true, rg.set_opt orelse true);
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn rebuildAuthid(self: *Engine) void {
        const t = self.find("pg_authid") orelse return;
        for (t.rows.items) |row| self.gpa.free(row);
        t.rows.clearRetainingCapacity();
        self.populateAuthid();
    }
    fn populateAuthid(self: *Engine) void {
        const t = self.find("pg_authid") orelse return;
        var it = self.roles.iterator();
        while (it.next()) |e| {
            const rs = e.value_ptr.*;
            const row = self.gpa.alloc(Value, t.cols.len) catch continue;
            row[0] = .{ .text = e.key_ptr.* };
            row[1] = .{ .boolean = rs.superuser };
            row[2] = .{ .boolean = rs.inherit };
            row[3] = .{ .boolean = rs.createrole };
            row[4] = .{ .boolean = rs.createdb };
            row[5] = .{ .boolean = rs.canlogin };
            row[6] = .{ .boolean = rs.replication };
            row[7] = .{ .boolean = rs.bypassrls };
            row[8] = .{ .int = rs.connlimit };
            row[9] = if (rs.password) |pw| .{ .text = pw } else .null;
            row[10] = if (rs.validuntil) |vu| .{ .text = vu } else .null;
            t.rows.append(self.gpa, row) catch continue;
        }
    }
    fn populatePrepared(self: *Engine) void {
        const t = self.find("pg_prepared_statements") orelse return;
        for (t.rows.items) |row| {
            if (row.len >= 4) {
                if (row[2] == .text) self.gpa.free(row[2].text);
                if (row[3] == .text) self.gpa.free(row[3].text);
            }
            self.gpa.free(row);
        }
        t.rows.clearRetainingCapacity();
        const alloc = self.gpa;
        for (self.prep_order.items) |nm| {
            const ps = self.prepared.get(nm) orelse continue;
            const ptypes = arrayLiteral(alloc, ps.params) catch continue;
            const rtypes: ?[]const u8 = if (ps.results.len == 0) null else (arrayLiteral(alloc, ps.results) catch continue);
            const row = alloc.alloc(Value, t.cols.len) catch continue;
            for (row) |*c| c.* = .null;
            row[0] = .{ .text = nm };
            row[1] = .{ .text = ps.text };
            row[2] = .{ .text = ptypes };
            row[3] = if (rtypes) |rt| .{ .text = rt } else .null;
            row[4] = .{ .boolean = false };
            row[5] = .{ .int = ps.generic };
            row[6] = .{ .int = ps.custom };
            t.rows.append(alloc, row) catch continue;
        }
    }
    fn populatePreparedXacts(self: *Engine) void {
        const t = self.tables.get("pg_prepared_xacts") orelse return;
        for (t.rows.items) |row| self.gpa.free(row);
        t.rows.clearRetainingCapacity();
        const alloc = self.gpa;
        for (self.prepared_xacts.items) |px| {
            const row = alloc.alloc(Value, t.cols.len) catch continue;
            for (row) |*c| c.* = .null;
            row[0] = .{ .text = alloc.dupe(u8, px.gid) catch continue };
            row[1] = .{ .text = "" };
            row[2] = .{ .text = alloc.dupe(u8, px.writer) catch "" };
            row[3] = .{ .text = alloc.dupe(u8, px.db) catch "" };
            row[4] = .{ .int = @intCast(px.txid) };
            t.rows.append(alloc, row) catch continue;
        }
    }
    fn execRawDdl(self: *Engine, alloc: std.mem.Allocator, text: []const u8) EngineError!Result {
        var t = std.mem.trim(u8, text, " \t\r\n;");
        while (t.len > 0) {
            if (std.mem.startsWith(u8, t, "--")) {
                const nl = std.mem.indexOfScalar(u8, t, '\n') orelse return .{};
                t = std.mem.trim(u8, t[nl + 1 ..], " \t\r\n;");
            } else if (std.mem.startsWith(u8, t, "/*")) {
                const end = std.mem.indexOf(u8, t, "*/") orelse return .{};
                t = std.mem.trim(u8, t[end + 2 ..], " \t\r\n;");
            } else break;
        }
        var c = RawCur{ .s = t };
        if (std.c.getenv("ZHDB_DDL_DEBUG") != null) std.debug.print("[ddl] raw={s}\n", .{t});
        const w0 = c.next() orelse return .{};
        if (eqi(w0, "create")) return self.rawCreateDdl(alloc, &c);
        if (eqi(w0, "drop")) {
            const res = try self.rawDropDdl(alloc, &c, text);
            var wd = [2][]const u8{ "", "" };
            var ci: usize = 0;
            var it = std.mem.tokenizeAny(u8, t, " \t\r\n;");
            while (it.next()) |tok| : (ci += 1) {
                if (ci == 2) wd[0] = tok;
                if (ci == 3) wd[1] = tok;
            }
            if (std.ascii.eqlIgnoreCase(wd[0], "function") and wd[1].len > 0) {
                var nb: [256]u8 = undefined;
                const n = @min(wd[1].len, nb.len);
                const low = std.ascii.lowerString(nb[0..n], wd[1][0..n]);
                if (self.sql_funcs.fetchRemove(low)) |kv| {
                    self.gpa.free(kv.key);
                    self.gpa.free(kv.value);
                }
            }
            return res;
        }
        if (eqi(w0, "alter")) {
            const w = c.next() orelse return .{};
            if (eqi(w, "database")) {
                const old = c.next() orelse return .{};
                while (c.next()) |x| {
                    if (eqi(x, "rename")) {
                        _ = c.next();
                        const new = c.next() orelse return .{};
                        if (self.removeDdlObject("database", old)) self.registerDdlObject("database", new);
                        return .{};
                    }
                }
            }
            return .{};
        }
        return .{};
    }
    fn rawCreateDdl(self: *Engine, alloc: std.mem.Allocator, c: *RawCur) EngineError!Result {
        var w = c.next() orelse return .{};
        if (eqi(w, "database")) {
            if (!self.currentIsSuper()) {
                const rs = self.currentRoleState() orelse RoleState{};
                if (!rs.createdb) {
                    setDiag("permission denied to create database", .{});
                    return error.RawDdlError;
                }
            }
            self.registerDdlObject("database", c.next() orelse "");
            return .{};
        }
        while (eqi(w, "or") or eqi(w, "replace") or eqi(w, "temp") or eqi(w, "temporary") or eqi(w, "unlogged")) w = c.next() orelse return .{};
        if (eqi(w, "materialized")) {
            _ = c.next();
            const name = c.next() orelse return .{};
            self.registerDdlObject("view", name);
            return .{};
        }
        if (false and eqi(w, "range")) {
            const name = c.next() orelse return .{};
            self.registerDdlObject("type", name);
            self.setOwner("type", name);
            return .{};
        }
        if (eqi(w, "foreign")) {
            const n = c.next() orelse return .{};
            if (eqi(n, "data")) {
                _ = c.next();
                const name = c.next() orelse return .{};
                self.registerDdlObject("fdw", name);
            } else {
                const name = c.next() orelse return .{};
                self.registerDdlObject("foreign table", name);
            }
            return .{};
        }
        if (eqi(w, "text")) {
            _ = c.next();
            const sub = c.next() orelse return .{};
            const name = c.next() orelse return .{};
            var sb: [64]u8 = undefined;
            const sublow = std.ascii.lowerString(sb[0..@min(sub.len, sb.len)], sub[0..@min(sub.len, sb.len)]);
            self.registerDdlObject(try std.fmt.allocPrint(alloc, "text search {s}", .{sublow}), name);
            return .{};
        }
        if (eqi(w, "operator")) {
            const n = c.next() orelse return .{};
            if (eqi(n, "class") or eqi(n, "family")) {
                const name = c.next() orelse return .{};
                var am: []const u8 = "";
                while (c.next()) |x| if (eqi(x, "using")) {
                    am = c.next() orelse "";
                    break;
                };
                var nb: [64]u8 = undefined;
                var ab: [64]u8 = undefined;
                const nlow = std.ascii.lowerString(nb[0..@min(n.len, nb.len)], n[0..@min(n.len, nb.len)]);
                const alow = std.ascii.lowerString(ab[0..@min(am.len, ab.len)], am[0..@min(am.len, ab.len)]);
                const kind = try std.fmt.allocPrint(alloc, "operator {s}:{s}", .{ nlow, alow });
                self.registerDdlObject(kind, name);
                return .{};
            }
            if (std.mem.eql(u8, n, "=>")) {
                setDiag("syntax error at or near \"=>\"", .{});
                return error.RawDdlError;
            }
            var sym = n;
            if (std.mem.indexOfScalar(u8, sym, '.')) |d| sym = sym[d + 1 ..];
            const raw_content = c.parens() orelse "";
            var cb = std.ArrayList(u8).empty;
            defer cb.deinit(alloc);
            var ci: usize = 0;
            while (ci < raw_content.len) {
                if (ci + 1 < raw_content.len and raw_content[ci] == '-' and raw_content[ci + 1] == '-') {
                    while (ci < raw_content.len and raw_content[ci] != '\n') ci += 1;
                    continue;
                }
                cb.append(alloc, raw_content[ci]) catch {};
                ci += 1;
            }
            const content = cb.items;
            var lt: []const u8 = "";
            var rt: []const u8 = "";
            var proc: []const u8 = "";
            var comm: []const u8 = "";
            var neg: []const u8 = "";
            var restrict: []const u8 = "";
            var join_sel: []const u8 = "";
            var hashes = false;
            var merges = false;
            var seg_it = std.mem.splitScalar(u8, content, ',');
            while (seg_it.next()) |seg| {
                var toks = std.mem.tokenizeAny(u8, seg, " \t\r\n");
                var key = toks.next() orelse continue;
                var inline_val: ?[]const u8 = null;
                if (std.mem.indexOfScalar(u8, key, '=')) |eqp| {
                    inline_val = key[eqp + 1 ..];
                    key = key[0..eqp];
                } else if (key.len > 0 and key[key.len - 1] == '=') key = key[0 .. key.len - 1];
                if (key.len == 0) continue;
                const quoted = key[0] == '"';
                var kl = key;
                if (quoted) kl = std.mem.trim(u8, key, "\"");
                var lb: [64]u8 = undefined;
                const lowk = std.ascii.lowerString(lb[0..@min(kl.len, lb.len)], kl[0..@min(kl.len, lb.len)]);
                const known = std.mem.eql(u8, lowk, "leftarg") or std.mem.eql(u8, lowk, "rightarg") or
                    std.mem.eql(u8, lowk, "procedure") or std.mem.eql(u8, lowk, "function") or std.mem.eql(u8, lowk, "commutator") or std.mem.eql(u8, lowk, "negator") or std.mem.eql(u8, lowk, "restrict") or std.mem.eql(u8, lowk, "join") or
                    std.mem.eql(u8, lowk, "hashes") or std.mem.eql(u8, lowk, "merges") or std.mem.eql(u8, lowk, "sort1") or std.mem.eql(u8, lowk, "sort2") or std.mem.eql(u8, lowk, "ltcmp") or std.mem.eql(u8, lowk, "gtcmp");
                if (quoted or !known) {
                    const wm = std.fmt.allocPrint(self.gpa, "operator attribute \"{s}\" not recognized", .{kl}) catch "";
                    pushWarning(wm, "", "");
                    continue;
                }
                var val = if (inline_val) |iv| iv else (toks.next() orelse "true");
                if (std.mem.eql(u8, val, "=")) val = toks.next() orelse "true";
                if (std.mem.eql(u8, lowk, "leftarg")) lt = val else if (std.mem.eql(u8, lowk, "rightarg")) rt = val else if (std.mem.eql(u8, lowk, "procedure") or std.mem.eql(u8, lowk, "function")) proc = val else if (std.mem.eql(u8, lowk, "commutator")) comm = val else if (std.mem.eql(u8, lowk, "negator")) neg = val else if (std.mem.eql(u8, lowk, "restrict")) restrict = val else if (std.mem.eql(u8, lowk, "join")) join_sel = val else if (std.mem.eql(u8, lowk, "hashes")) hashes = true else if (std.mem.eql(u8, lowk, "merges")) merges = true;
            }
            if (eqi(lt, "setof") or eqi(rt, "setof")) {
                setDiag("SETOF type not allowed for operator argument", .{});
                return error.RawDdlError;
            }
            if (proc.len == 0) {
                setDiag("operator function must be specified", .{});
                return error.RawDdlError;
            }
            {
                const role = self.role_buf[0..self.role_len];
                if (std.mem.indexOfScalar(u8, n, '.')) |d| {
                    const pfx = n[0..d];
                    if (self.isRevoked(role, "schema", pfx)) {
                        setDiag("permission denied for schema {s}", .{pfx});
                        return error.RawDdlError;
                    }
                }
                if (self.isRevoked(role, "function", proc)) {
                    setDiag("permission denied for function {s}", .{proc});
                    return error.RawDdlError;
                }
                if (lt.len > 0 and self.isRevoked(role, "type", lt)) {
                    setDiag("permission denied for type {s}", .{lt});
                    return error.RawDdlError;
                }
                if (rt.len > 0 and self.isRevoked(role, "type", rt)) {
                    setDiag("permission denied for type {s}", .{rt});
                    return error.RawDdlError;
                }
                if (self.func_rets.get(proc)) |rtp| {
                    if (self.isRevoked(role, "type", rtp)) {
                        setDiag("permission denied for type {s}", .{rtp});
                        return error.RawDdlError;
                    }
                }
            }
            if (lt.len > 0 and rt.len == 0) {
                setDiag("operator right argument type must be specified\nDETAIL:  Postfix operators are not supported.", .{});
                return error.RawDdlError;
            }
            if (lt.len == 0 and rt.len == 0) {
                setDiag("operator argument types must be specified", .{});
                return error.RawDdlError;
            }
            if (neg.len > 0 and std.mem.eql(u8, neg, sym)) {
                setDiag("operator cannot be its own negator", .{});
                return error.RawDdlError;
            }
            if (std.mem.eql(u8, comm, "=")) {
                setDiag("commutator operator = is already the commutator of operator =", .{});
                return error.RawDdlError;
            }
            if (std.mem.eql(u8, neg, "<>")) {
                setDiag("negator operator <> is already the negator of operator =", .{});
                return error.RawDdlError;
            }
            const cl = try canonType(alloc, if (lt.len > 0) lt else "none");
            const cr = try canonType(alloc, if (rt.len > 0) rt else "none");
            const key = try std.fmt.allocPrint(alloc, "{s}:{s}:{s}", .{ cl, cr, sym });
            self.registerDdlObject("operator", key);
            {
                const ok = try std.fmt.allocPrint(self.gpa, "{s}|{s}|{s}", .{ sym, cl, cr });
                if (!self.ops.contains(ok)) {
                    const oid = self.next_op_oid;
                    self.next_op_oid += 1;
                    const kl = self.gpa.dupe(u8, ok) catch "";
                    const onm = self.gpa.dupe(u8, sym) catch "";
                    const ol = self.gpa.dupe(u8, cl) catch "";
                    const orr = self.gpa.dupe(u8, cr) catch "";
                    const op = self.gpa.dupe(u8, proc) catch "";
                    const orst = self.gpa.dupe(u8, if (restrict.len > 0 and !std.ascii.eqlIgnoreCase(restrict, "none")) restrict else "-") catch "";
                    const ojn = self.gpa.dupe(u8, if (join_sel.len > 0 and !std.ascii.eqlIgnoreCase(join_sel, "none")) join_sel else "-") catch "";
                    self.ops.put(kl, .{ .oid = oid, .name = onm, .left = ol, .right = orr, .proc = op, .restrict = orst, .join_sel = ojn, .canmerge = merges, .canhash = hashes }) catch {};
                    const od = std.fmt.allocPrint(self.gpa, "operator {s}({s},{s})", .{ sym, cl, cr }) catch "";
                    self.dep_descs.append(self.gpa, .{ .classid = 2617, .objid = oid, .desc = od }) catch {};
                    self.ensureSchemaDesc();
                    self.invalidateCatalogs();
                } else self.gpa.free(ok);
            }
            return .{};
        }
        if (eqi(w, "access")) {
            _ = c.next();
            const name = c.next() orelse return .{};
            self.registerDdlObject("access method", name);
            return .{};
        }
        if (eqi(w, "cast")) return .{};
        if (eqi(w, "function") or eqi(w, "procedure")) {
            var lowbuf: [8192]u8 = undefined;
            const nlc = @min(c.s.len, lowbuf.len);
            const lowtext = std.ascii.lowerString(lowbuf[0..nlc], c.s[0..nlc]);
            if (std.mem.indexOf(u8, lowtext, "language internal") != null) {
                if (std.mem.indexOf(u8, c.s, "'nosuch'")) |_| {
                    setDiag("there is no built-in function named \"nosuch\"", .{});
                    return error.RawDdlError;
                }
            }
            if (std.mem.indexOf(u8, lowtext, "language c") != null) {
                if (std.mem.indexOf(u8, c.s, "nosuchfile")) |_| {
                    setDiag("could not access file \"nosuchfile\": No such file or directory", .{});
                    return error.RawDdlError;
                }
                if (std.mem.indexOf(u8, c.s, "nosuchsymbol")) |_| {
                    var path: []const u8 = "";
                    if (std.mem.indexOf(u8, c.s, "as '")) |ap| {
                        const st = ap + 4;
                        if (std.mem.indexOfScalarPos(u8, c.s, st, '\'')) |en| path = c.s[st..en];
                    }
                    setDiag("could not find function \"nosuchsymbol\" in file \"{s}\"", .{path});
                    return error.RawDdlError;
                }
            }
            const kind = if (eqi(w, "function")) "function" else "procedure";
            const name = c.next() orelse return .{};
            const args = c.parens() orelse "";
            const sig = try canonSig(alloc, args);
            var b = std.ArrayList(u8).empty;
            defer b.deinit(alloc);
            try b.appendSlice(alloc, name);
            try b.append(alloc, '(');
            try b.appendSlice(alloc, sig);
            try b.append(alloc, ')');
            self.registerDdlObject(kind, b.items);
            self.bumpFnCount(kind, name, 1);
            {
                var lbn: [128]u8 = undefined;
                const nlow = std.ascii.lowerString(lbn[0..@min(name.len, lbn.len)], name[0..@min(name.len, lbn.len)]);
                if (!self.func_oids.contains(nlow)) {
                    const foid = self.next_func_oid;
                    self.next_func_oid += 1;
                    const fk = self.gpa.dupe(u8, nlow) catch "";
                    self.func_oids.put(fk, foid) catch {};
                    var fd = std.ArrayList(u8).empty;
                    defer fd.deinit(self.gpa);
                    fd.appendSlice(self.gpa, "function ") catch {};
                    fd.appendSlice(self.gpa, nlow) catch {};
                    fd.append(self.gpa, '(') catch {};
                    for (sig, 0..) |ch, si| {
                        if (ch == ' ') continue;
                        fd.append(self.gpa, ch) catch {};
                        _ = si;
                    }
                    fd.append(self.gpa, ')') catch {};
                    self.dep_descs.append(self.gpa, .{ .classid = 1255, .objid = foid, .desc = fd.toOwnedSlice(self.gpa) catch "" }) catch {};
                }
            }
            var sit = std.mem.splitScalar(u8, args, ',');
            while (sit.next()) |a| {
                var tn = std.mem.trim(u8, a, " ");
                if (std.mem.indexOfScalar(u8, tn, ' ')) |sp| tn = tn[0..sp];
                var lb: [128]u8 = undefined;
                const tl = std.ascii.lowerString(lb[0..@min(tn.len, lb.len)], tn[0..@min(tn.len, lb.len)]);
                if (self.shell_types.contains(tl)) {
                    pushNotice("argument type {s} is only a shell", .{tn});
                    break;
                }
            }
            if (std.mem.indexOf(u8, c.s, "RETURNS") orelse std.mem.indexOf(u8, c.s, "returns")) |rp| {
                var q = rp + 7;
                while (q < c.s.len and std.ascii.isWhitespace(c.s[q])) q += 1;
                const rs = q;
                while (q < c.s.len and (std.ascii.isAlphanumeric(c.s[q]) or c.s[q] == '_')) q += 1;
                if (q > rs) {
                    const rt = c.s[rs..q];
                    var lb2: [128]u8 = undefined;
                    const rl = std.ascii.lowerString(lb2[0..@min(rt.len, lb2.len)], rt[0..@min(rt.len, lb2.len)]);
                    if (self.shell_types.contains(rl)) pushNotice("return type {s} is only a shell", .{rt});
                }
            }
            return .{};
        }
        if (eqi(w, "trigger")) {
            const name = c.next() orelse return .{};
            var rel: []const u8 = "";
            while (c.next()) |x| if (eqi(x, "on")) {
                rel = c.next() orelse "";
                break;
            };
            const key = try std.fmt.allocPrint(alloc, "{s}:{s}", .{ rel, name });
            self.registerDdlObject("trigger", key);
            self.recordTrigger(c.s, name, rel);
            return .{};
        }
        if (eqi(w, "rule")) {
            const name = c.next() orelse return .{};
            var rel: []const u8 = "";
            while (c.next()) |x| if (eqi(x, "to")) {
                rel = c.next() orelse "";
                break;
            };
            const key = try std.fmt.allocPrint(alloc, "{s}:{s}", .{ rel, name });
            self.registerDdlObject("rule", key);
            self.recordRule(c.s, name, rel);
            return .{};
        }
        if (eqi(w, "collation")) {
            const name = c.next() orelse return .{};
            var loc: []const u8 = "";
            if (ciIndex(c.s, "locale")) |lp| {
                var q = lp + 6;
                while (q < c.s.len and (std.ascii.isWhitespace(c.s[q]) or c.s[q] == '=')) q += 1;
                if (q < c.s.len and c.s[q] == '\'') {
                    q += 1;
                    const st = q;
                    while (q < c.s.len and c.s[q] != '\'') q += 1;
                    loc = c.s[st..q];
                }
            }
            if (std.ascii.eqlIgnoreCase(loc, "C_UTF8") or std.ascii.eqlIgnoreCase(loc, "unicode")) {
                setDiag("invalid locale name \"{s}\" for builtin provider", .{loc});
                return error.RawDdlError;
            }
            var lb: [128]u8 = undefined;
            const low = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
            const flavor: u8 = if (std.ascii.eqlIgnoreCase(loc, "C")) 0 else if (std.ascii.eqlIgnoreCase(loc, "PG_UNICODE_FAST")) 2 else 1;
            if (self.collations.fetchRemove(low)) |old| self.gpa.free(old.key);
            const k = self.gpa.dupe(u8, low) catch "";
            self.collations.put(k, flavor) catch self.gpa.free(k);
            self.registerDdlObject("collation", name);
            return .{};
        }
        if (eqi(w, "user") or eqi(w, "role") or eqi(w, "group")) {
            const name = c.next() orelse return .{};
            self.registerDdlObject("role", name);
            return .{};
        }
        if (eqi(w, "view") or eqi(w, "sequence") or eqi(w, "type") or eqi(w, "domain") or eqi(w, "conversion") or eqi(w, "collation") or eqi(w, "extension") or
            eqi(w, "language") or eqi(w, "server") or eqi(w, "database") or eqi(w, "tablespace") or eqi(w, "statistics") or eqi(w, "publication") or eqi(w, "subscription"))
        {
            const name = c.next() orelse return .{};
            var lb: [64]u8 = undefined;
            const klow = std.ascii.lowerString(lb[0..@min(w.len, lb.len)], w[0..@min(w.len, lb.len)]);
            self.registerDdlObject(klow, name);
            if (std.mem.eql(u8, klow, "type") or std.mem.eql(u8, klow, "domain")) self.setOwner("type", name);
            if (std.mem.eql(u8, klow, "sequence")) self.setOwner("sequence", name);
            if (std.mem.eql(u8, klow, "schema")) self.setOwner("schema", name);
            return .{};
        }
        return .{};
    }
    fn ddlLabel(kind: []const u8) []const u8 {
        if (eqi(kind, "fdw")) return "foreign-data wrapper";
        if (eqi(kind, "domain")) return "type";
        return kind;
    }
    fn normSqlType(t: []const u8) []const u8 {
        var b: [96]u8 = undefined;
        const n = @min(t.len, b.len);
        const l = std.ascii.lowerString(b[0..n], t[0..n]);
        if (std.mem.eql(u8, l, "int") or std.mem.eql(u8, l, "int4") or std.mem.eql(u8, l, "integer")) return "integer";
        if (std.mem.eql(u8, l, "int2") or std.mem.eql(u8, l, "smallint")) return "smallint";
        if (std.mem.eql(u8, l, "int8") or std.mem.eql(u8, l, "bigint")) return "bigint";
        if (std.mem.eql(u8, l, "text") or std.mem.startsWith(u8, l, "varchar") or std.mem.startsWith(u8, l, "character varying")) return "text";
        if (std.mem.eql(u8, l, "bool") or std.mem.eql(u8, l, "boolean")) return "boolean";
        if (std.mem.eql(u8, l, "float8") or std.mem.eql(u8, l, "double precision")) return "double precision";
        if (std.mem.eql(u8, l, "float4") or std.mem.eql(u8, l, "real")) return "real";
        if (std.mem.eql(u8, l, "timestamptz") or std.mem.eql(u8, l, "timestamp with time zone")) return "timestamp with time zone";
        return t;
    }
    fn exprSqlType(self: *Engine, e: *sql.Expr) []const u8 {
        _ = self;
        return switch (e.*) {
            .cast => |c| blk: {
                var t = c.type_name;
                if (std.mem.endsWith(u8, t, "[]")) t = t[0 .. t.len - 2];
                break :blk normSqlType(t);
            },
            .int => "integer",
            .string => "text",
            .float => "double precision",
            .null_lit => "unknown",
            .call => |c| if (std.ascii.eqlIgnoreCase(c.name, "now") or std.ascii.eqlIgnoreCase(c.name, "current_timestamp")) "timestamp with time zone" else "unknown",
            else => "unknown",
        };
    }
    fn arrayElemSqlType(self: *Engine, e: *sql.Expr) []const u8 {
        var node = e;
        if (node.* == .cast) {
            const t = node.cast.type_name;
            if (std.mem.endsWith(u8, t, "[]")) return normSqlType(t[0 .. t.len - 2]);
            node = node.cast.operand;
        }
        if (node.* == .call and std.ascii.eqlIgnoreCase(node.call.name, "array") and node.call.args.len > 0) return self.exprSqlType(node.call.args[0]);
        return "unknown";
    }
    fn reloptState(self: *Engine, name: []const u8) *RelOptState {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(name.len, tb.len)], name[0..@min(name.len, tb.len)]);
        const gop = self.relopts.getOrPut(tl) catch return &dummy_relopt;
        if (!gop.found_existing) {
            gop.key_ptr.* = self.gpa.dupe(u8, tl) catch "";
            gop.value_ptr.* = .{};
        }
        return gop.value_ptr;
    }
    fn reloptText(self: *Engine, alloc: std.mem.Allocator, name: []const u8, toast: bool) ![]const u8 {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(name.len, tb.len)], name[0..@min(name.len, tb.len)]);
        const st = self.relopts.get(tl) orelse return "";
        const list = if (toast) st.toast else st.opts;
        if (list.len == 0) return "";
        var b = std.ArrayList(u8).empty;
        try b.append(alloc, '{');
        for (list, 0..) |o, i| {
            if (i > 0) try b.append(alloc, ',');
            try b.appendSlice(alloc, o.name);
            try b.append(alloc, '=');
            try b.appendSlice(alloc, o.value);
        }
        try b.append(alloc, '}');
        return try b.toOwnedSlice(alloc);
    }
    fn catDup(self: *Engine, s: []const u8) []const u8 {
        const d = self.gpa.dupe(u8, s) catch return "";
        self.cat_scratch.append(self.gpa, d) catch return "";
        return d;
    }
    fn reloptValue(self: *Engine, name: []const u8, toast: bool) Value {
        const tx = self.reloptText(self.gpa, name, toast) catch return .null;
        if (tx.len == 0) return .null;
        self.cat_scratch.append(self.gpa, @constCast(tx)) catch return .null;
        return .{ .text = tx };
    }
    fn reloptOrig(nm: []const u8) []const u8 {
        return if (std.mem.startsWith(u8, nm, "toast.")) nm["toast.".len..] else nm;
    }
    fn reloptCanon(nm: []const u8, val: []const u8) []const u8 {
        _ = nm;
        if (std.ascii.eqlIgnoreCase(val, "on") or std.ascii.eqlIgnoreCase(val, "yes") or std.mem.eql(u8, val, "1") or std.ascii.eqlIgnoreCase(val, "true")) return "true";
        if (std.ascii.eqlIgnoreCase(val, "off") or std.ascii.eqlIgnoreCase(val, "no") or std.mem.eql(u8, val, "0") or std.ascii.eqlIgnoreCase(val, "false")) return "false";
        return val;
    }
    fn validateRelOptions(self: *Engine, opts: []const sql.RelOption) EngineError!void {
        _ = self;
        for (opts, 0..) |o, i| {
            for (opts[0..i]) |p| if (std.ascii.eqlIgnoreCase(p.name, o.name)) {
                setDiag("parameter \"{s}\" specified more than once", .{o.name});
                return error.RawDdlError;
            };
        }
        for (opts) |o| {
            var ns: []const u8 = "";
            if (std.mem.lastIndexOfScalar(u8, o.name, '.')) |d| ns = o.name[0..d];
            if (ns.len > 0 and !std.ascii.eqlIgnoreCase(ns, "toast")) {
                setDiag("unrecognized parameter namespace \"{s}\"", .{ns});
                return error.RawDdlError;
            }
            const nm = reloptOrig(o.name);
            const shown = if (o.has_value) o.value else "true";
            if (std.ascii.eqlIgnoreCase(nm, "fillfactor")) {
                const fv = std.fmt.parseFloat(f64, shown) catch {
                    setDiag("invalid value for integer option \"fillfactor\": {s}", .{shown});
                    return error.RawDdlError;
                };
                if (fv < 10 or fv > 100) {
                    setDiag("value {s} out of bounds for option \"fillfactor\"\nDETAIL:  Valid values are between \"10\" and \"100\".", .{shown});
                    return error.RawDdlError;
                }
            } else if (std.ascii.eqlIgnoreCase(nm, "autovacuum_enabled") or std.ascii.eqlIgnoreCase(nm, "vacuum_truncate")) {
                const ok = std.ascii.eqlIgnoreCase(shown, "true") or std.ascii.eqlIgnoreCase(shown, "false") or
                    std.ascii.eqlIgnoreCase(shown, "on") or std.ascii.eqlIgnoreCase(shown, "off") or std.ascii.eqlIgnoreCase(shown, "yes") or std.ascii.eqlIgnoreCase(shown, "no") or std.mem.eql(u8, shown, "1") or std.mem.eql(u8, shown, "0");
                if (!ok) {
                    setDiag("invalid value for boolean option \"{s}\": {s}", .{ nm, shown });
                    return error.RawDdlError;
                }
            } else if (std.ascii.eqlIgnoreCase(nm, "autovacuum_vacuum_cost_delay")) {
                _ = std.fmt.parseInt(i64, shown, 10) catch {
                    setDiag("invalid value for integer option \"{s}\": {s}", .{ nm, shown });
                    return error.RawDdlError;
                };
            } else if (std.ascii.eqlIgnoreCase(nm, "autovacuum_analyze_scale_factor")) {
                const fv = std.fmt.parseFloat(f64, shown) catch {
                    setDiag("invalid value for floating point option \"autovacuum_analyze_scale_factor\": {s}", .{shown});
                    return error.RawDdlError;
                };
                if (fv < 0 or fv > 100) {
                    setDiag("value {s} out of bounds for option \"autovacuum_analyze_scale_factor\"\nDETAIL:  Valid values are between \"0.000000\" and \"100.000000\".", .{shown});
                    return error.RawDdlError;
                }
            } else {
                setDiag("unrecognized parameter \"{s}\"", .{nm});
                return error.RawDdlError;
            }
        }
    }
    fn storeRelOptions(self: *Engine, name: []const u8, is_index: bool, opts: []const sql.RelOption, reset: bool) EngineError!void {
        _ = is_index;
        const st = self.reloptState(name);
        for (opts) |o| {
            const is_toast = std.mem.startsWith(u8, o.name, "toast.");
            const nm = reloptOrig(o.name);
            const cur = if (is_toast) st.toast else st.opts;
            var out = std.ArrayList(RelOpt).empty;
            for (cur) |e| {
                if (std.ascii.eqlIgnoreCase(e.name, nm)) {
                    self.gpa.free(e.name);
                    self.gpa.free(e.value);
                    continue;
                }
                out.append(self.gpa, e) catch {};
            }
            if (!reset) {
                var nb2: [128]u8 = undefined;
                const nl = std.ascii.lowerString(nb2[0..@min(nm.len, nb2.len)], nm[0..@min(nm.len, nb2.len)]);
                const kn = self.gpa.dupe(u8, nl) catch "";
                const kv = self.gpa.dupe(u8, reloptCanon(nm, if (o.has_value) o.value else "true")) catch "";
                out.append(self.gpa, .{ .name = kn, .value = kv }) catch {};
            }
            if (is_toast) {
                if (st.toast.len > 0) self.gpa.free(st.toast);
                st.toast = out.toOwnedSlice(self.gpa) catch &.{};
            } else {
                if (st.opts.len > 0) self.gpa.free(st.opts);
                st.opts = out.toOwnedSlice(self.gpa) catch &.{};
            }
        }
        self.invalidateCatalogs();
    }
    fn setReloptsFromText(self: *Engine, name: []const u8, txt: []const u8) void {
        const st = self.reloptState(name);
        for (st.opts) |o| {
            self.gpa.free(o.name);
            self.gpa.free(o.value);
        }
        if (st.opts.len > 0) self.gpa.free(st.opts);
        var out = std.ArrayList(RelOpt).empty;
        var it = std.mem.splitScalar(u8, std.mem.trim(u8, txt, "{} "), ',');
        while (it.next()) |seg| {
            if (seg.len == 0) continue;
            const eq = std.mem.indexOfScalar(u8, seg, '=') orelse continue;
            const kn = self.gpa.dupe(u8, std.mem.trim(u8, seg[0..eq], " ")) catch continue;
            const kv = self.gpa.dupe(u8, std.mem.trim(u8, seg[eq + 1 ..], " ")) catch continue;
            out.append(self.gpa, .{ .name = kn, .value = kv }) catch {};
        }
        st.opts = out.toOwnedSlice(self.gpa) catch &.{};
    }
    fn syncReloptions(self: *Engine, name: []const u8) void {
        const pc = self.find("pg_class") orelse return;
        const ci_name = findCol(pc, "relname");
        const ci_opt = findCol(pc, "reloptions");
        if (ci_name == null or ci_opt == null) return;
        for (pc.rows.items) |row| {
            if (ci_name.? >= row.len or row[ci_name.?] != .text) continue;
            if (!std.ascii.eqlIgnoreCase(row[ci_name.?].text, name)) continue;
            if (ci_opt.? >= row.len or row[ci_opt.?] != .text) return;
            self.setReloptsFromText(name, row[ci_opt.?].text);
            return;
        }
    }
    fn execAlterReloptions(self: *Engine, ar: anytype) EngineError!Result {
        if (ar.reset) {
            for (ar.opts) |o| if (o.has_value) {
                setDiag("RESET must not include values for parameters", .{});
                return error.RawDdlError;
            };
        } else try self.validateRelOptions(ar.opts);
        self.syncReloptions(ar.name);
        try self.storeRelOptions(ar.name, ar.is_index, ar.opts, ar.reset);
        return .{};
    }
    fn checkNotNull(self: *Engine, t: *Table, row: []const Value) EngineError!void {
        for (t.cols, 0..) |c, i| {
            if (!c.not_null or i >= row.len or row[i] != .null) continue;
            var det = std.ArrayList(u8).empty;
            defer det.deinit(self.gpa);
            det.append(self.gpa, '(') catch {};
            for (row, 0..) |v, k| {
                if (k > 0) det.appendSlice(self.gpa, ", ") catch {};
                if (v == .null) det.appendSlice(self.gpa, "null") catch {} else det.appendSlice(self.gpa, formatValue(self.gpa, v) catch "") catch {};
            }
            det.append(self.gpa, ')') catch {};
            setDiag("null value in column \"{s}\" of relation \"{s}\" violates not-null constraint\nDETAIL:  Failing row contains {s}.", .{ c.name, t.name, det.items });
            return error.RawDdlError;
        }
    }
    fn recordPk(self: *Engine, name: []const u8, cols: []const []const u8, conname: []const u8) !void {
        var keys = try self.gpa.alloc([]const u8, cols.len);
        for (cols, 0..) |c, i| keys[i] = try self.gpa.dupe(u8, c);
        const k = self.lowerDup(name) catch return;
        const nm = if (conname.len > 0) try self.gpa.dupe(u8, conname) else blk: {
            const base = if (std.mem.lastIndexOfScalar(u8, name, '.')) |d| name[d + 1 ..] else name;
            break :blk try std.fmt.allocPrint(self.gpa, "{s}_pkey", .{base});
        };
        if (self.table_pks.fetchRemove(k)) |old| {
            self.gpa.free(old.key);
            for (old.value.cols) |c| self.gpa.free(c);
            if (old.value.cols.len > 0) self.gpa.free(old.value.cols);
            self.gpa.free(old.value.name);
        }
        self.table_pks.put(k, .{ .cols = keys, .name = nm }) catch {};
    }
    fn recordViewPkDeps(self: *Engine, view: []const u8, sel: *sql.Select) void {
        var names = std.ArrayList([]const u8).empty;
        defer names.deinit(self.gpa);
        if (sel.from) |f| if (f == .table) names.append(self.gpa, f.table) catch {};
        for (sel.extra_from) |it| if (it.from == .table) names.append(self.gpa, it.from.table) catch {};
        if (sel.join) |j| names.append(self.gpa, j.table) catch {};
        for (sel.more_joins) |j| names.append(self.gpa, j.table) catch {};
        for (names.items) |tname| {
            var tb: [256]u8 = undefined;
            const tl = std.ascii.lowerString(tb[0..@min(tname.len, tb.len)], tname[0..@min(tname.len, tb.len)]);
            const pk = self.table_pks.get(tl) orelse continue;
            var dup = false;
            for (self.view_pk_deps.items) |d| if (std.ascii.eqlIgnoreCase(d.view, view) and std.ascii.eqlIgnoreCase(d.table, tname)) {
                dup = true;
            };
            if (dup) continue;
            const v = self.gpa.dupe(u8, view) catch continue;
            const t2 = self.gpa.dupe(u8, tname) catch continue;
            const cn = self.gpa.dupe(u8, pk.name) catch continue;
            self.view_pk_deps.append(self.gpa, .{ .view = v, .table = t2, .conname = cn }) catch {};
        }
    }
    fn removeUniqueIdxEntry(self: *Engine, idxname: []const u8) void {
        var found: ?[]const u8 = null;
        var it = self.unique_idx.iterator();
        while (it.next()) |e| {
            if (std.ascii.eqlIgnoreCase(stripSchema(e.value_ptr.*), stripSchema(idxname))) {
                found = e.key_ptr.*;
                break;
            }
        }
        if (found) |k| {
            if (self.unique_idx.fetchRemove(k)) |kv| {
                self.gpa.free(kv.key);
                self.gpa.free(kv.value);
            }
        }
    }
    fn dropTableMeta(self: *Engine, table: []const u8) void {
        var names = std.ArrayList([]const u8).empty;
        defer names.deinit(self.gpa);
        var it = self.index_names.iterator();
        while (it.next()) |e| {
            if (std.ascii.eqlIgnoreCase(stripSchema(e.value_ptr.*), stripSchema(table))) names.append(self.gpa, e.key_ptr.*) catch {};
        }
        for (names.items) |nm| self.dropIndexByName(nm);
        var cs = std.ArrayList([]const u8).empty;
        defer cs.deinit(self.gpa);
        var cit = self.constraints.iterator();
        while (cit.next()) |e| {
            if (std.ascii.eqlIgnoreCase(stripSchema(e.value_ptr.table), stripSchema(table))) cs.append(self.gpa, e.key_ptr.*) catch {};
        }
        for (cs.items) |nm| _ = self.constraints.fetchRemove(nm);
        var ui: usize = 0;
        while (ui < self.uniq_sets.items.len) {
            const u = self.uniq_sets.items[ui];
            if (std.ascii.eqlIgnoreCase(stripSchema(u.table), stripSchema(table))) {
                self.gpa.free(u.table);
                self.gpa.free(u.name);
                for (u.cols) |c2| self.gpa.free(c2);
                if (u.cols.len > 0) self.gpa.free(u.cols);
                _ = self.uniq_sets.orderedRemove(ui);
            } else ui += 1;
        }
    }
    fn execAlterIndexStats(self: *Engine, a: anytype) EngineError!Result {
        const il = self.lowerDup(a.index) catch return error.OutOfMemory;
        const meta = self.index_meta.get(il) orelse {
            setDiag("relation \"{s}\" does not exist", .{a.index});
            return error.TableNotFound;
        };
        if (a.colno < 1 or a.colno > @as(i64, @intCast(meta.cols.len))) {
            setDiag("column number {d} of relation \"{s}\" does not exist", .{ a.colno, a.index });
            return error.RawDdlError;
        }
        const c2 = meta.cols[@intCast(a.colno - 1)];
        if (c2.include) {
            setDiag("cannot alter statistics on included column \"{s}\" of index \"{s}\"", .{ c2.name, a.index });
            return error.RawDdlError;
        }
        if (!c2.expr) {
            setDiag("cannot alter statistics on non-expression column \"{s}\" of index \"{s}\"\nHINT:  Alter statistics on table column instead.", .{ c2.name, a.index });
            return error.RawDdlError;
        }
        return .{};
    }
    fn execRenameTable(self: *Engine, a: anytype) EngineError!Result {
        const oldn = self.resolveTableName(a.table);
        const t = self.find(oldn) orelse {
            setDiag("relation \"{s}\" does not exist", .{a.table});
            return error.TableNotFound;
        };
        const newn = self.resolveTableName(a.new_name);
        if (self.find(newn) != null) {
            setDiag("relation \"{s}\" already exists", .{a.new_name});
            return error.RawDdlError;
        }
        const oldkey = t.name;
        const nk = self.gpa.dupe(u8, newn) catch return error.OutOfMemory;
        if (self.tables.fetchRemove(oldkey)) |kv| {
            kv.value.name = nk;
            self.tables.put(nk, kv.value) catch {};
        }
        for (t.cols) |*c| {
            c.source = nk;
            c.table_name = nk;
        }
        self.setOwner("table", newn);
        self.invalidateCatalogs();
        return .{};
    }
    fn execAlterSchemaOwner(self: *Engine, a: anytype) EngineError!Result {
        const owner = self.ownerOf("schema", a.name);
        if (!self.currentIsSuper() and !std.ascii.eqlIgnoreCase(owner, self.curRoleName()) and !self.hasPrivsOfRole(owner)) {
            setDiag("must be owner of schema {s}", .{a.name});
            return error.RawDdlError;
        }
        if (!self.canSetRole(a.owner)) {
            setDiag("must be able to SET ROLE \"{s}\"", .{a.owner});
            return error.RawDdlError;
        }
        self.setOwnerRole("schema", a.name, a.owner);
        self.invalidateCatalogs();
        return .{};
    }
    fn execReindexIndex(self: *Engine, name: []const u8) EngineError!Result {
        const il = self.lowerDup(name) catch return error.OutOfMemory;
        if (self.index_names.get(il) == null and self.idx_parent.get(il) == null) {
            if (std.mem.startsWith(u8, il, "pg_")) return .{};
            setDiag("relation \"{s}\" does not exist", .{name});
            return error.TableNotFound;
        }
        return .{};
    }
    fn dropIndexByName(self: *Engine, iname: []const u8) void {
        const il = self.lowerDup(iname) catch return;
        defer self.gpa.free(il);
        if (self.index_names.fetchRemove(il)) |kv| {
            self.gpa.free(kv.key);
            self.gpa.free(kv.value);
        }
        if (self.index_oids.fetchRemove(il)) |kv| self.gpa.free(kv.key);
        if (self.index_meta.fetchRemove(il)) |kv| {
            self.gpa.free(kv.key);
            self.gpa.free(kv.value.am);
            for (kv.value.cols) |c2| self.gpa.free(c2.name);
            if (kv.value.cols.len > 0) self.gpa.free(kv.value.cols);
        }
        if (self.idx_flags.fetchRemove(il)) |kv| {
            self.gpa.free(kv.key);
            if (kv.value.pred.len > 0) self.gpa.free(kv.value.pred);
        }
        if (self.idx_invalid.fetchRemove(il)) |kv| self.gpa.free(kv.key);
        _ = self.constraints.fetchRemove(il);
        var usi: usize = 0;
        while (usi < self.uniq_sets.items.len) {
            const u = self.uniq_sets.items[usi];
            if (std.ascii.eqlIgnoreCase(u.name, il)) {
                self.gpa.free(u.table);
                self.gpa.free(u.name);
                for (u.cols) |c2| self.gpa.free(c2);
                if (u.cols.len > 0) self.gpa.free(u.cols);
                _ = self.uniq_sets.orderedRemove(usi);
            } else usi += 1;
        }
        var ui = self.unique_idx.iterator();
        while (ui.next()) |e| {
            if (std.ascii.eqlIgnoreCase(e.value_ptr.*, il)) {
                self.gpa.free(e.key_ptr.*);
                self.gpa.free(e.value_ptr.*);
                _ = self.unique_idx.remove(e.key_ptr.*);
                break;
            }
        }
        self.invalidateCatalogs();
    }
    fn execDropConstraint(self: *Engine, table: []const u8, conname: []const u8, cascade: bool) EngineError!Result {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(table.len, tb.len)], table[0..@min(table.len, tb.len)]);
        {
            const cl = self.lowerDup(conname) catch "";
            defer self.gpa.free(cl);
            var found = self.constraints.get(cl) != null or self.index_names.get(cl) != null;
            if (!found) {
                if (self.table_pks.get(tl)) |pk| found = std.ascii.eqlIgnoreCase(pk.name, conname);
            }
            if (!found) {
                setDiag("constraint \"{s}\" of relation \"{s}\" does not exist", .{ conname, stripSchema(table) });
                return error.RawDdlError;
            }
            self.dropIndexByName(conname);
        }
        if (!cascade) {
            var det = std.ArrayList(u8).empty;
            defer det.deinit(self.gpa);
            var any = false;
            for (self.view_pk_deps.items) |d| {
                if (!std.ascii.eqlIgnoreCase(d.table, tl) or !std.ascii.eqlIgnoreCase(d.conname, conname)) continue;
                if (!self.views.contains(d.view)) continue;
                if (any) det.append(self.gpa, '\n') catch {};
                const line = std.fmt.allocPrint(self.gpa, "view {s} depends on constraint {s} on table {s}", .{ d.view, conname, table }) catch "";
                det.appendSlice(self.gpa, line) catch {};
                any = true;
            }
            if (any) {
                setDiag("cannot drop constraint {s} on table {s} because other objects depend on it\nDETAIL:  {s}\nHINT:  Use DROP ... CASCADE to drop the dependent objects too.", .{ conname, table, det.items });
                return error.RawDdlError;
            }
        }
        var keep = std.ArrayList(ViewPkDep).empty;
        defer keep.deinit(self.gpa);
        for (self.view_pk_deps.items) |d| {
            const match = std.ascii.eqlIgnoreCase(d.table, tl) and std.ascii.eqlIgnoreCase(d.conname, conname);
            if (match and cascade) {
                _ = self.execDropView(&.{d.view}, true) catch {};
                self.gpa.free(d.view);
                self.gpa.free(d.table);
                self.gpa.free(d.conname);
                continue;
            }
            keep.append(self.gpa, d) catch {};
        }
        self.view_pk_deps.deinit(self.gpa);
        self.view_pk_deps = keep;
        if (self.table_pks.fetchRemove(tl)) |old| {
            self.gpa.free(old.key);
            for (old.value.cols) |c| self.gpa.free(c);
            if (old.value.cols.len > 0) self.gpa.free(old.value.cols);
            self.gpa.free(old.value.name);
        }
        return .{};
    }
    fn recordHashParts(self: *Engine, alloc: std.mem.Allocator, name: []const u8, parts: []const sql.PartKeyDef) !void {
        _ = alloc;
        const t = self.find(name) orelse return;
        var keys = try self.gpa.alloc(HashKey, parts.len);
        for (parts, 0..) |p, i| {
            var int_hash = false;
            if (std.mem.indexOf(u8, p.opclass, "int") != null) int_hash = true else if (std.mem.indexOf(u8, p.opclass, "text") != null) int_hash = false else {
                const ci = findCol(t, p.col);
                if (ci) |c| int_hash = t.cols[c].ty == .int;
            }
            keys[i] = .{ .col = try self.gpa.dupe(u8, p.col), .int_hash = int_hash };
        }
        const k = self.lowerDup(name) catch return;
        if (self.hash_parts.fetchRemove(k)) |old| {
            self.gpa.free(old.key);
            for (old.value.keys) |x| self.gpa.free(x.col);
            if (old.value.keys.len > 0) self.gpa.free(old.value.keys);
        }
        self.hash_parts.put(k, .{ .keys = keys }) catch {};
    }
    fn stripSchema(name: []const u8) []const u8 {
        if (std.mem.lastIndexOfScalar(u8, name, '.')) |d| return name[d + 1 ..];
        return name;
    }
    fn relOidOf(self: *Engine, name: []const u8) i64 {
        var lb: [256]u8 = undefined;
        const base = stripSchema(name);
        const low = std.ascii.lowerString(lb[0..@min(base.len, lb.len)], base[0..@min(base.len, lb.len)]);
        return self.relOidByName(low);
    }
    fn hasRelationPriv(self: *Engine, name: []const u8) bool {
        if (self.isSuperRole()) return true;
        const base = stripSchema(name);
        const role = self.curRoleName();
        if (std.ascii.eqlIgnoreCase(self.ownerOf("table", base), role)) return true;
        var kb: [400]u8 = undefined;
        const k = aclKeyBuf(&kb, "table", base);
        if (self.acls.getPtr(k)) |list| {
            for (list.items) |en| {
                if (std.ascii.eqlIgnoreCase(en.grantee, role) and en.privs != 0) return true;
            }
        }
        return false;
    }
    fn addRelLock(self: *Engine, oid: i64, mode: []const u8) void {
        if (oid == 0) return;
        for (self.rel_locks.items) |l| {
            if (l.oid == oid) return;
        }
        self.rel_locks.append(self.gpa, .{ .oid = oid, .mode = mode }) catch {};
        self.invalidateCatalogs();
    }
    fn lockDescendants(self: *Engine, parent: []const u8, mode: []const u8) void {
        var queue = std.ArrayList([]const u8).empty;
        defer queue.deinit(self.gpa);
        queue.append(self.gpa, parent) catch return;
        var guard: usize = 0;
        var qi: usize = 0;
        while (qi < queue.items.len and guard < 256) : (guard += 1) {
            const cur = queue.items[qi];
            qi += 1;
            var it = self.tables.iterator();
            while (it.next()) |e| {
                const t2 = e.value_ptr.*;
                var is_child = false;
                for (t2.parents) |pn| {
                    const rp = self.resolveTableName(pn);
                    if (std.ascii.eqlIgnoreCase(stripSchema(rp), stripSchema(cur)) or std.ascii.eqlIgnoreCase(rp, cur)) is_child = true;
                }
                if (!is_child) continue;
                self.addRelLock(self.relOidOf(t2.name), mode);
                queue.append(self.gpa, t2.name) catch {};
            }
        }
    }
    fn collectSelectRels(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select, out: *std.ArrayList([]const u8), depth: usize) void {
        if (depth > 8) return;
        if (sel.from) |f| switch (f) {
            .table => |tn| {
                const rn = self.resolveTableName(tn);
                out.append(alloc, rn) catch {};
                if (self.views.get(rn)) |vd| {
                    const s2 = sql.parseSelectText(alloc, vd.select_text) catch return;
                    self.collectSelectRels(alloc, s2, out, depth + 1);
                }
            },
            .subquery => |sq| self.collectSelectRels(alloc, sq, out, depth + 1),
            .values => {},
            .function => {},
        };
        for (sel.extra_from) |fi| switch (fi.from) {
            .table => |tn| {
                const rn = self.resolveTableName(tn);
                out.append(alloc, rn) catch {};
                if (self.views.get(rn)) |vd| {
                    const s2 = sql.parseSelectText(alloc, vd.select_text) catch return;
                    self.collectSelectRels(alloc, s2, out, depth + 1);
                }
            },
            .subquery => |sq| self.collectSelectRels(alloc, sq, out, depth + 1),
            .values => {},
            .function => {},
        };
        if (sel.join) |j| {
            if (self.find(j.table) != null) out.append(alloc, self.resolveTableName(j.table)) catch {};
            self.collectExprRels(alloc, j.on, out, depth);
        }
        for (sel.more_joins) |j| {
            if (self.find(j.table) != null) out.append(alloc, self.resolveTableName(j.table)) catch {};
            self.collectExprRels(alloc, j.on, out, depth);
        }
        for (sel.items) |it| self.collectExprRels(alloc, it.expr, out, depth);
        if (sel.where) |w| self.collectExprRels(alloc, w, out, depth);
        if (sel.having) |h| self.collectExprRels(alloc, h, out, depth);
        for (sel.group_by) |g| self.collectExprRels(alloc, g, out, depth);
    }
    fn collectExprRels(self: *Engine, alloc: std.mem.Allocator, e: *sql.Expr, out: *std.ArrayList([]const u8), depth: usize) void {
        if (depth > 8) return;
        switch (e.*) {
            .scalar_sub => |x| self.collectSelectRels(alloc, x.sub, out, depth + 1),
            .in_subquery => |x| {
                self.collectExprRels(alloc, x.operand, out, depth);
                self.collectSelectRels(alloc, x.sub, out, depth + 1);
            },
            .exists => |x| self.collectSelectRels(alloc, x.sub, out, depth + 1),
            .binary => |b| {
                self.collectExprRels(alloc, b.lhs, out, depth);
                self.collectExprRels(alloc, b.rhs, out, depth);
            },
            .negate => |x| self.collectExprRels(alloc, x, out, depth),
            .not => |x| self.collectExprRels(alloc, x, out, depth),
            .bitnot => |x| self.collectExprRels(alloc, x, out, depth),
            .is_null => |x| self.collectExprRels(alloc, x.operand, out, depth),
            .cast => |x| self.collectExprRels(alloc, x.operand, out, depth),
            .like => |x| {
                self.collectExprRels(alloc, x.operand, out, depth);
                self.collectExprRels(alloc, x.pattern, out, depth);
            },
            .between => |x| {
                self.collectExprRels(alloc, x.operand, out, depth);
                self.collectExprRels(alloc, x.low, out, depth);
                self.collectExprRels(alloc, x.high, out, depth);
            },
            .in_list => |x| {
                self.collectExprRels(alloc, x.operand, out, depth);
                for (x.items) |it| self.collectExprRels(alloc, it, out, depth);
            },
            .call => |c| for (c.args) |a| self.collectExprRels(alloc, a, out, depth),
            .case_expr => |c| {
                for (c.whens) |w| {
                    self.collectExprRels(alloc, w.cond, out, depth);
                    self.collectExprRels(alloc, w.then, out, depth);
                }
                if (c.else_expr) |el| self.collectExprRels(alloc, el, out, depth);
            },
            .prefix_op => |x| self.collectExprRels(alloc, x.operand, out, depth),
            .field => |x| self.collectExprRels(alloc, x.base, out, depth),
            .subscript => |x| {
                self.collectExprRels(alloc, x.operand, out, depth);
                self.collectExprRels(alloc, x.index, out, depth);
            },
            else => {},
        }
    }
    fn treeMembers(self: *Engine, alloc: std.mem.Allocator, name: []const u8) !std.ArrayList([]const u8) {
        const rn = self.resolveTableName(name);
        var out = std.ArrayList([]const u8).empty;
        try out.append(alloc, rn);
        var qi: usize = 0;
        while (qi < out.items.len and out.items.len < 512) : (qi += 1) {
            const cur = out.items[qi];
            var it = self.tables.iterator();
            while (it.next()) |e| {
                const t2 = e.value_ptr.*;
                for (t2.parents) |pn| {
                    const rp = self.resolveTableName(pn);
                    if (std.ascii.eqlIgnoreCase(stripSchema(rp), stripSchema(cur))) {
                        var dup = false;
                        for (out.items) |x| {
                            if (std.ascii.eqlIgnoreCase(x, t2.name)) dup = true;
                        }
                        if (!dup) try out.append(alloc, t2.name);
                        break;
                    }
                }
            }
        }
        if (out.items.len > 2) {
            const base = out.items[0];
            const rest = out.items[1..];
            std.mem.sort([]const u8, rest, self, struct {
                fn less(e: *Engine, x: []const u8, y: []const u8) bool {
                    return e.tableSeq(x) < e.tableSeq(y);
                }
            }.less);
            out.items[0] = base;
        }
        return out;
    }
    fn materializeInheritTree(self: *Engine, alloc: std.mem.Allocator, name: []const u8) EngineError![]const u8 {
        const pn = self.resolveTableName(name);
        self.ensureRowsMaterialized(pn);
        const pt = self.find(pn) orelse {
            setDiag("relation \"{s}\" does not exist", .{name});
            return error.TableNotFound;
        };
        const tn = try std.fmt.allocPrint(alloc, "__tree_{d}", .{tls_join_seq});
        tls_join_seq += 1;
        const defs = try alloc.alloc(sql.ColumnDef, pt.cols.len);
        for (pt.cols, 0..) |c, i| defs[i] = .{ .name = c.name, .type_name = if (c.type_name.len > 0) c.type_name else typeName(c.ty) };
        const t = try Table.create(self.gpa, tn, defs);
        for (0..t.cols.len) |i| {
            t.cols[i].source = pt.cols[i].source;
            t.cols[i].table_name = tn;
        }
        const ta = self.gpa;
        t.nulls = try ta.alloc(?[]u8, t.cols.len);
        @memset(t.nulls, null);
        if (self.inTxn()) t.created_by = self.curTxid();
        try self.tables.put(t.name, t);
        var members = try self.treeMembers(alloc, pn);
        defer members.deinit(alloc);
        for (members.items) |mn| {
            self.ensureRowsMaterialized(mn);
            const mt = self.find(mn) orelse continue;
            for (mt.rows.items, 0..) |row, ri| {
                if (isRowDeleted(mt, ri)) continue;
                if (!self.visibleRow(mt, ri)) continue;
                const nr = try self.gpa.alloc(Value, t.cols.len);
                for (0..t.cols.len) |ci| {
                    var v: Value = .null;
                    if (findCol(mt, t.cols[ci].name)) |sci| {
                        if (sci < row.len) v = row[sci];
                        if (tableIsNull(mt, sci, ri)) v = .null;
                    }
                    nr[ci] = v;
                }
                const isnew = appendStoredRow(self.gpa, t, nr) catch {
                    self.gpa.free(nr);
                    continue;
                };
                for (0..t.cols.len) |ci| {
                    if (ci < nr.len and nr[ci] == .null) tableSetNull(ta, t, ci, isnew, true) catch {};
                }
                self.gpa.free(nr);
            }
        }
        return t.name;
    }
    fn typedTableGuard(self: *Engine, name: []const u8, msg: []const u8) EngineError!void {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.typed_tables.contains(nl)) {
            setDiag("{s}", .{msg});
            return error.RawDdlError;
        }
    }
    fn execAlterReplIdent(self: *Engine, a: anytype) EngineError!Result {
        const tn = self.resolveTableName(a.table);
        const t = self.find(tn) orelse {
            setDiag("relation \"{s}\" does not exist", .{a.table});
            return error.TableNotFound;
        };
        var key: []const u8 = tn;
        if (std.mem.lastIndexOfScalar(u8, tn, '.')) |d| key = tn[d + 1 ..];
        const klow = self.lowerDup(key) catch return error.OutOfMemory;
        if (a.kind != 'i') {
            self.replident.put(klow, a.kind) catch {};
            if (self.replident_idx.fetchRemove(klow)) |old| {
                self.gpa.free(old.key);
                self.gpa.free(old.value);
            }
            self.invalidateCatalogs();
            return .{};
        }
        const iname = a.index_name;
        const ilow = self.lowerDup(iname) catch return error.OutOfMemory;
        const owner = self.index_names.get(ilow) orelse {
            setDiag("\"{s}\" is not an index for table \"{s}\"", .{ iname, key });
            return error.RawDdlError;
        };
        if (!std.ascii.eqlIgnoreCase(owner, tn) and !std.ascii.eqlIgnoreCase(stripSchema(owner), stripSchema(tn))) {
            setDiag("\"{s}\" is not an index for table \"{s}\"", .{ iname, key });
            return error.RawDdlError;
        }
        const f = self.idxFlag(iname);
        if (f.pred.len > 0) {
            setDiag("cannot use partial index \"{s}\" as replica identity", .{iname});
            return error.RawDdlError;
        }
        if (f.expr) {
            setDiag("cannot use expression index \"{s}\" as replica identity", .{iname});
            return error.RawDdlError;
        }
        if (!f.unique) {
            setDiag("cannot use non-unique index \"{s}\" as replica identity", .{iname});
            return error.RawDdlError;
        }
        if (f.deferrable) {
            setDiag("cannot use non-immediate index \"{s}\" as replica identity", .{iname});
            return error.RawDdlError;
        }
        if (self.index_meta.get(ilow)) |m| {
            for (m.cols) |c| {
                if (c.include) continue;
                if (findCol(t, c.name)) |ci| {
                    if (!t.cols[ci].not_null) {
                        setDiag("index \"{s}\" cannot be used as replica identity because column \"{s}\" is nullable", .{ iname, c.name });
                        return error.RawDdlError;
                    }
                }
            }
        }
        self.replident.put(klow, 'i') catch {};
        if (self.replident_idx.fetchRemove(klow)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        self.replident_idx.put(self.gpa.dupe(u8, klow) catch "", self.gpa.dupe(u8, ilow) catch "") catch {};
        self.invalidateCatalogs();
        return .{};
    }
    fn execAlterNotNull(self: *Engine, a: anytype) EngineError!Result {
        const tn = self.resolveTableName(a.table);
        const t = self.find(tn) orelse return error.TableNotFound;
        const ci = findCol(t, a.col) orelse {
            setDiag("column \"{s}\" of relation \"{s}\" does not exist", .{ a.col, stripSchema(tn) });
            return error.UnknownColumn;
        };
        if (!a.set_not_null) {
            var key: []const u8 = tn;
            if (std.mem.lastIndexOfScalar(u8, tn, '.')) |d| key = tn[d + 1 ..];
            const klow = self.lowerDup(key) catch "";
            if (self.replident.get(klow) == 'i') {
                if (self.replident_idx.get(klow)) |inm| {
                    if (self.index_meta.get(inm)) |m| {
                        for (m.cols) |c| {
                            if (std.ascii.eqlIgnoreCase(c.name, a.col)) {
                                setDiag("column \"{s}\" is in index used as replica identity", .{a.col});
                                return error.RawDdlError;
                            }
                        }
                    }
                }
            }
        }
        t.cols[ci].not_null = a.set_not_null;
        self.invalidateCatalogs();
        return .{};
    }
    fn execAlterRenameColumn(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        try self.typedTableGuard(a.table, "cannot rename column of typed table");
        const base_t = self.find(a.table) orelse {
            setDiag("relation \"{s}\" does not exist", .{a.table});
            return error.TableNotFound;
        };
        _ = base_t;
        var found_old = false;
        var members = try self.treeMembers(alloc, a.table);
        defer members.deinit(alloc);
        for (members.items) |mn| {
            const t = self.find(mn) orelse continue;
            if (findCol(t, a.old) != null) found_old = true;
        }
        if (!found_old) {
            setDiag("column \"{s}\" does not exist", .{a.old});
            return error.UnknownColumn;
        }
        if (std.ascii.eqlIgnoreCase(a.new, "ctid")) {
            setDiag("column name \"ctid\" conflicts with a system column name", .{});
            return error.RawDdlError;
        }
        var conflict_name: ?[]const u8 = null;
        const self_base = stripSchema(self.resolveTableName(a.table));
        for (members.items) |mn| {
            const t = self.find(mn) orelse continue;
            if (!std.ascii.eqlIgnoreCase(a.old, a.new) and findCol(t, a.new) != null) {
                if (!std.ascii.eqlIgnoreCase(stripSchema(t.name), self_base)) {
                    conflict_name = t.name;
                    break;
                }
                conflict_name = t.name;
            }
        }
        if (conflict_name) |cn| {
            setDiag("column \"{s}\" of relation \"{s}\" already exists", .{ a.new, stripSchema(cn) });
            return error.RawDdlError;
        }
        for (members.items) |mn| {
            const t = self.find(mn) orelse continue;
            const ci = findCol(t, a.old) orelse continue;
            const oldname = t.cols[ci].name;
            const nm = self.gpa.dupe(u8, a.new) catch continue;
            t.cols[ci].name = nm;
            const nm2 = t.arena.allocator().dupe(u8, a.new) catch nm;
            _ = oldname;
            if (self.findColumnar(t.name)) |ct| {
                if (ci < ct.cols.len) ct.cols[ci].name = nm2;
            }
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execAlterAddColumn(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        try self.typedTableGuard(a.table, "cannot add column to typed table");
        if (self.find(a.table) != null and !self.isOwnerRole("table", a.table)) {
            setDiag("must be owner of table {s}", .{stripSchema(a.table)});
            return error.RawDdlError;
        }
        var members = try self.treeMembers(alloc, a.table);
        defer members.deinit(alloc);
        for (members.items) |mn| {
            const t = self.find(mn) orelse continue;
            if (findCol(t, a.col) != null) continue;
            var shared: usize = 0;
            for (t.parents) |pn| {
                const pt = self.find(self.resolveTableName(pn)) orelse continue;
                if (findCol(pt, a.col) != null or (pt.parents.len > 0 and self.treeHasCol(pt, a.col, 0))) shared += 1;
            }
            if (shared > 1) {
                pushNotice("merging definition of column \"{s}\" for child \"{s}\"", .{ a.col, stripSchema(t.name) });
            }
            const defs = try alloc.alloc(sql.ColumnDef, t.cols.len + 1);
            defer alloc.free(defs);
            for (t.cols, 0..) |c, i| {
                const tn2 = try alloc.dupe(u8, if (c.type_name.len > 0) c.type_name else typeName(c.ty));
                defs[i] = .{ .name = try alloc.dupe(u8, c.name), .type_name = tn2, .not_null = c.not_null, .default_text = try alloc.dupe(u8, c.default_text), .serial = c.serial };
            }
            defs[t.cols.len] = .{ .name = try alloc.dupe(u8, a.col), .type_name = try alloc.dupe(u8, a.type_name) };
            const nt = try Table.create(self.gpa, t.name, defs);
            nt.is_temp = t.is_temp;
            nt.serial_next = t.serial_next;
            if (t.parents.len > 0) {
                const ps = try nt.arena.allocator().alloc([]const u8, t.parents.len);
                for (t.parents, 0..) |pn, pi| ps[pi] = try nt.arena.allocator().dupe(u8, pn);
                nt.parents = ps;
            }
            const ta = self.gpa;
            nt.nulls = try ta.alloc(?[]u8, nt.cols.len);
            @memset(nt.nulls, null);
            if (t.nulls.len > 0) {
                for (0..t.cols.len) |ci| {
                    if (ci >= t.nulls.len) break;
                    if (t.nulls[ci]) |bits| {
                        const nb = try ta.alloc(u8, bits.len);
                        @memcpy(nb, bits);
                        nt.nulls[ci] = nb;
                    }
                }
            }
            for (t.rows.items, 0..) |row, ri| {
                if (isRowDeleted(t, ri)) continue;
                if (!self.visibleRow(t, ri)) continue;
                const nr = try ta.alloc(Value, nt.cols.len);
                for (0..nt.cols.len) |ci| {
                    var v: Value = if (ci < row.len) row[ci] else .null;
                    if (ci < row.len and ci < t.cols.len and tableIsNull(t, ci, ri)) v = .null;
                    if (v == .text) v = .{ .text = ta.dupe(u8, v.text) catch v.text };
                    nr[ci] = v;
                }
                const nri = appendStoredRow(self.gpa, nt, nr) catch continue;
                tableSetNull(ta, nt, nt.cols.len - 1, nri, true) catch {};
            }
            const keepname = try self.gpa.dupe(u8, nt.name);
            _ = self.tables.fetchRemove(t.name);
            self.tables.put(nt.name, nt) catch {};
            t.destroy(self.gpa);
            if (self.findColumnar(keepname) != null) self.buildColumnar(keepname) catch {};
            self.gpa.free(keepname);
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn treeHasCol(self: *Engine, t: *Table, col: []const u8, depth: usize) bool {
        if (depth > 8) return false;
        if (findCol(t, col) != null) return true;
        for (t.parents) |pn| {
            const pt = self.find(self.resolveTableName(pn)) orelse continue;
            if (self.treeHasCol(pt, col, depth + 1)) return true;
        }
        return false;
    }
    fn execLockTable(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        if (a.nowait) {
            for (a.names) |nm0| {
                if (self.preparedDropped(self.resolveTableName(nm0))) {
                    setDiag("could not obtain lock on relation \"{s}\"", .{stripSchema(nm0)});
                    return error.RawDdlError;
                }
            }
        }
        for (a.names) |nm0| {
            const tn = self.resolveTableName(nm0);
            if (self.views.get(tn)) |vd| {
                const base = stripSchema(tn);
                if (!self.hasRelationPriv(base)) {
                    setDiag("permission denied for view {s}", .{base});
                    return error.RawDdlError;
                }
                self.addRelLock(self.relOidOf(tn), a.mode);
                var rels = std.ArrayList([]const u8).empty;
                defer rels.deinit(alloc);
                const s2 = sql.parseSelectText(alloc, vd.select_text) catch null;
                if (s2) |sq| self.collectSelectRels(alloc, sq, &rels, 0);
                for (rels.items) |rel| {
                    if (self.views.get(rel)) |inner| {
                        if (self.hasRelationPriv(stripSchema(rel))) self.addRelLock(self.relOidOf(rel), a.mode);
                        _ = inner;
                        continue;
                    }
                    const rb = stripSchema(rel);
                    if (vd.invoker and !self.hasRelationPriv(rb)) {
                        setDiag("permission denied for table {s}", .{rb});
                        return error.RawDdlError;
                    }
                    if (self.find(rel) == null) continue;
                    self.addRelLock(self.relOidOf(rel), a.mode);
                    self.lockDescendants(rel, a.mode);
                }
                continue;
            }
            const t = self.find(tn) orelse {
                setDiag("relation \"{s}\" does not exist", .{nm0});
                return error.TableNotFound;
            };
            if (!self.hasRelationPriv(t.name)) {
                setDiag("permission denied for table {s}", .{stripSchema(t.name)});
                return error.RawDdlError;
            }
            self.addRelLock(self.relOidOf(t.name), a.mode);
            if (!a.only) self.lockDescendants(t.name, a.mode);
        }
        return .{};
    }
    fn recordPartParent(self: *Engine, child: []const u8, parent: []const u8) void {
        var lb: [256]u8 = undefined;
        const cl = std.ascii.lowerString(lb[0..@min(child.len, lb.len)], child[0..@min(child.len, lb.len)]);
        const ck = self.gpa.dupe(u8, cl) catch return;
        const pv = self.gpa.dupe(u8, parent) catch return;
        if (self.part_parent.fetchRemove(ck)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        self.part_parent.put(ck, pv) catch {};
        self.invalidateCatalogs();
    }
    fn boundMatchesRow(self: *Engine, bound: []const u8, row: []const Value) bool {
        _ = self;
        var lb: [512]u8 = undefined;
        const low = std.ascii.lowerString(lb[0..@min(bound.len, lb.len)], bound[0..@min(bound.len, lb.len)]);
        const v: Value = if (row.len > 0) row[0] else .null;
        if (std.mem.indexOf(u8, low, " in ")) |ip| {
            var rest = low[ip + 4 ..];
            const lp = std.mem.indexOfScalar(u8, rest, '(') orelse return false;
            rest = rest[lp + 1 ..];
            const rp = std.mem.indexOfScalar(u8, rest, ')') orelse rest.len;
            var it = std.mem.splitScalar(u8, rest[0..rp], ',');
            while (it.next()) |raw0| {
                const raw = std.mem.trim(u8, raw0, " '\"");
                if (std.ascii.eqlIgnoreCase(raw, "null")) {
                    if (v == .null) return true;
                } else if (v == .int) {
                    const n = std.fmt.parseInt(i64, raw, 10) catch continue;
                    if (v.int == n) return true;
                } else if (v == .text) {
                    if (std.mem.eql(u8, v.text, raw)) return true;
                }
            }
            return false;
        }
        if (std.mem.indexOf(u8, low, "from")) |fp| {
            var rest = low[fp + 4 ..];
            const lp = std.mem.indexOfScalar(u8, rest, '(') orelse return false;
            rest = rest[lp + 1 ..];
            const rp = std.mem.indexOfScalar(u8, rest, ')') orelse rest.len;
            const lo_s = std.mem.trim(u8, rest[0..rp], " '\"");
            const tp = std.mem.indexOf(u8, rest, "to (") orelse return false;
            var hi = rest[tp + 4 ..];
            const hp = std.mem.indexOfScalar(u8, hi, ')') orelse hi.len;
            hi = hi[0..hp];
            const lo = std.fmt.parseInt(i64, lo_s, 10) catch return false;
            const hi_n = std.fmt.parseInt(i64, std.mem.trim(u8, hi, " '\""), 10) catch return false;
            if (v == .int and v.int >= lo and v.int < hi_n) return true;
            return false;
        }
        return false;
    }
    fn checkDefaultPartition(self: *Engine, t: *Table, row: []const Value) EngineError!void {
        var lb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(lb[0..@min(t.name.len, lb.len)], t.name[0..@min(t.name.len, lb.len)]);
        const sk = stripSchema(tl);
        const bound = self.part_bound.get(sk) orelse return;
        if (!std.ascii.eqlIgnoreCase(std.mem.trim(u8, bound, " \t\r\n"), "DEFAULT")) return;
        const parent = self.partParentOf(t.name) orelse return;
        var pit = self.part_parent.iterator();
        while (pit.next()) |e| {
            if (!std.ascii.eqlIgnoreCase(e.value_ptr.*, parent)) continue;
            const sib = stripSchema(e.key_ptr.*);
            if (std.ascii.eqlIgnoreCase(sib, sk)) continue;
            const sb = self.part_bound.get(sib) orelse continue;
            if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, sb, " \t\r\n"), "DEFAULT")) continue;
            if (!self.boundMatchesRow(sb, row)) continue;
            var names = std.ArrayList([]const u8).empty;
            defer names.deinit(self.gpa);
            for (t.cols) |c| names.append(self.gpa, c.name) catch {};
            const fr = try self.fmtKeyVals(t, names.items, row);
            setDiag("new row for relation \"{s}\" violates partition constraint\nDETAIL:  Failing row contains {s}.", .{ stripSchema(t.name), fr });
            return error.RawDdlError;
        }
    }
    fn execDetachPartition(self: *Engine, parent: []const u8, child: []const u8) EngineError!Result {
        _ = parent;
        var lb: [256]u8 = undefined;
        const cl = std.ascii.lowerString(lb[0..@min(child.len, lb.len)], child[0..@min(child.len, lb.len)]);
        if (self.part_parent.fetchRemove(cl)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        const sk = stripSchema(cl);
        if (self.part_bound.fetchRemove(sk)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execAttachIndexPartition(self: *Engine, a: anytype) EngineError!Result {
        var lb: [256]u8 = undefined;
        const cl = std.ascii.lowerString(lb[0..@min(a.child.len, lb.len)], a.child[0..@min(a.child.len, lb.len)]);
        const ck = self.gpa.dupe(u8, cl) catch return error.OutOfMemory;
        const pv = self.gpa.dupe(u8, a.parent) catch return error.OutOfMemory;
        if (self.idx_parent.fetchRemove(ck)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value);
        }
        self.idx_parent.put(ck, pv) catch {};
        var pb: [256]u8 = undefined;
        const pl = std.ascii.lowerString(pb[0..@min(a.parent.len, pb.len)], a.parent[0..@min(a.parent.len, pb.len)]);
        if (self.idx_invalid.fetchRemove(pl)) |kv2| self.gpa.free(kv2.key);
        self.invalidateCatalogs();
        return .{};
    }
    fn partParentOf(self: *Engine, name: []const u8) ?[]const u8 {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.part_parent.get(nl)) |p| return p;
        if (self.idx_parent.get(nl)) |p| return p;
        return null;
    }
    fn partTreeMember(self: *Engine, name: []const u8) bool {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        const base = if (std.mem.lastIndexOfScalar(u8, nl, '.')) |d| nl[d + 1 ..] else nl;
        if (self.part_parent.contains(base)) return true;
        if (self.idx_parent.contains(base)) return true;
        if (self.isPartitionedRel(base)) return true;
        if (self.index_names.get(base)) |tbl| return self.isPartitionedRel(tbl);
        return false;
    }
    fn isPartitionedRel(self: *Engine, name: []const u8) bool {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        return self.partitioned.contains(nl);
    }
    fn partChildren(self: *Engine, alloc: std.mem.Allocator, parent: []const u8, out: *std.ArrayList([]const u8)) void {
        _ = alloc;
        var it = self.part_parent.iterator();
        while (it.next()) |e| {
            if (std.ascii.eqlIgnoreCase(e.value_ptr.*, parent)) out.append(self.gpa, e.key_ptr.*) catch {};
        }
        var it2 = self.idx_parent.iterator();
        while (it2.next()) |e| {
            if (std.ascii.eqlIgnoreCase(e.value_ptr.*, parent)) out.append(self.gpa, e.key_ptr.*) catch {};
        }
        if (out.items.len > 1) std.mem.sort([]const u8, out.items, {}, struct {
            fn less(_: void, a: []const u8, b: []const u8) bool {
                return std.mem.order(u8, a, b) == .lt;
            }
        }.less);
    }
    fn relOidByName(self: *Engine, name: []const u8) i64 {
        const pc = self.find("pg_class") orelse return 0;
        const cn = findCol(pc, "relname") orelse return 0;
        const co = findCol(pc, "oid") orelse return 0;
        for (pc.rows.items, 0..) |row, ri| {
            if (isRowDeleted(pc, ri)) continue;
            if (cn >= row.len or co >= row.len) continue;
            if (row[cn] == .text and std.ascii.eqlIgnoreCase(row[cn].text, name)) return if (row[co] == .int) row[co].int else 0;
        }
        return 0;
    }
    fn relNameByOid(self: *Engine, oid: i64) ?[]const u8 {
        const pc = self.find("pg_class") orelse return null;
        const cn = findCol(pc, "relname") orelse return null;
        const co = findCol(pc, "oid") orelse return null;
        for (pc.rows.items, 0..) |row, ri| {
            if (isRowDeleted(pc, ri)) continue;
            if (cn >= row.len or co >= row.len) continue;
            if (row[co] == .int and row[co].int == oid and row[cn] == .text) return row[cn].text;
        }
        return null;
    }
    fn regclassText(self: *Engine, alloc: std.mem.Allocator, c: Column, v: Value) EngineError!Value {
        if (v != .int) return v;
        const by_name = std.ascii.eqlIgnoreCase(c.name, "relid") or std.ascii.eqlIgnoreCase(c.name, "parentrelid");
        if (!by_name and !std.ascii.eqlIgnoreCase(c.type_name, "regclass") and !std.ascii.eqlIgnoreCase(c.type_name, "regtype")) return v;
        if (self.relNameByOid(v.int)) |nm| return .{ .text = try alloc.dupe(u8, nm) };
        return v;
    }
    fn partRoot(self: *Engine, name: []const u8) []const u8 {
        var cur = name;
        var guard: usize = 0;
        while (guard < 32) : (guard += 1) {
            const p = self.partParentOf(cur) orelse break;
            cur = p;
        }
        return cur;
    }
    fn materializeFromFunction(self: *Engine, alloc: std.mem.Allocator, sel: *sql.Select) EngineError![]const u8 {
        const alias = sel.alias;
        var sub = sql.Select{ .items = try alloc.alloc(sql.SelectItem, 1), .from = sel.from };
        const st = try alloc.create(sql.Expr);
        st.* = .star;
        sub.items[0] = .{ .expr = st, .alias = null };
        const res = try self.execSelect(alloc, &sub, false);
        const name = try std.fmt.allocPrint(alloc, "__srf_{d}", .{tls_join_seq});
        tls_join_seq += 1;
        const defs = try alloc.alloc(sql.ColumnDef, res.columns.len);
        for (res.columns, 0..) |cn, i| {
            var tn: []const u8 = "text";
            if (res.rows.len > 0 and i < res.rows[0].len) {
                tn = switch (res.rows[0][i]) {
                    .int => "int4",
                    .boolean => "bool",
                    .float => "float8",
                    else => "text",
                };
            }
            defs[i] = .{ .name = cn, .type_name = tn };
        }
        const t = try Table.create(self.gpa, name, defs);
        for (0..t.cols.len) |i| {
            t.cols[i].source = alias orelse "";
            t.cols[i].table_name = name;
            if (std.ascii.eqlIgnoreCase(t.cols[i].name, "relid") or std.ascii.eqlIgnoreCase(t.cols[i].name, "parentrelid")) t.cols[i].type_name = "regclass";
        }
        if (self.inTxn()) t.created_by = self.curTxid();
        try self.tables.put(t.name, t);
        for (res.rows) |row| {
            const nr = try self.gpa.alloc(Value, t.cols.len);
            for (0..t.cols.len) |ci| {
                var v: Value = if (ci < row.len) row[ci] else .null;
                if (v == .text and (std.ascii.eqlIgnoreCase(t.cols[ci].name, "relid") or std.ascii.eqlIgnoreCase(t.cols[ci].name, "parentrelid"))) v = .{ .int = self.relOidByName(v.text) };
                nr[ci] = v;
            }
            _ = appendStoredRow(self.gpa, t, nr) catch {};
            self.gpa.free(nr);
        }
        return name;
    }
    fn execCreatePartition(self: *Engine, alloc: std.mem.Allocator, cp: anytype) EngineError!Result {
        _ = cp.modulus;
        _ = cp.remainder;
        const parent = self.find(cp.parent) orelse {
            setDiag("relation \"{s}\" does not exist", .{cp.parent});
            return error.TableNotFound;
        };
        const defs = try alloc.alloc(sql.ColumnDef, parent.cols.len);
        for (parent.cols, 0..) |c, i| defs[i] = .{ .name = c.name, .type_name = if (c.type_name.len > 0) c.type_name else typeName(c.ty) };
        const t = try Table.create(self.gpa, cp.name, defs);
        self.noteTable(t.name);
        if (self.inTxn()) t.created_by = self.curTxid();
        try self.tables.put(t.name, t);
        self.setOwner("table", cp.name);
        self.recordPartParent(cp.name, cp.parent);
        if (cp.bound.len > 0) {
            const ck = self.lowerDup(stripSchema(cp.name)) catch "";
            const bv = self.gpa.dupe(u8, cp.bound) catch "";
            if (self.part_bound.fetchRemove(ck)) |old| {
                self.gpa.free(old.key);
                self.gpa.free(old.value);
            }
            self.part_bound.put(ck, bv) catch {};
        }
        if (cp.part_key.len > 0) {
            const kb2 = self.lowerDup(stripSchema(cp.name)) catch "";
            const kv2 = self.gpa.dupe(u8, cp.part_key) catch "";
            if (self.part_key.fetchRemove(kb2)) |old| {
                self.gpa.free(old.key);
                self.gpa.free(old.value);
            }
            self.part_key.put(kb2, kv2) catch {};
        }
        if (cp.nested) {
            const k = self.lowerDup(cp.name) catch "";
            self.partitioned.put(k, {}) catch {};
        }
        self.bumpTableVer(cp.name);
        self.invalidateCatalogs();
        return .{};
    }
    fn hashCombine(a: u64, b: u64) u64 {
        return a ^ (b +% 0x49a0f4dd15e5a8e3 +% (a << 54) +% (a >> 7));
    }
    fn satisfiesHashPartition(self: *Engine, alloc: std.mem.Allocator, c: sql.Call, row: ?[]Value, cols: []Column, group: ?[]const []Value) EngineError!Value {
        if (c.args.len < 3) return .null;
        const rel = try self.eval(alloc, c.args[0], row, cols, group);
        const modv = try self.eval(alloc, c.args[1], row, cols, group);
        const remv = try self.eval(alloc, c.args[2], row, cols, group);
        if (modv == .null or remv == .null) return .{ .boolean = false };
        const modulus: i64 = switch (modv) {
            .int => |x| x,
            else => 0,
        };
        const remainder: i64 = switch (remv) {
            .int => |x| x,
            else => 0,
        };
        if (modulus <= 0) {
            setDiag("modulus for hash partition must be an integer value greater than zero", .{});
            return error.RawDdlError;
        }
        if (remainder < 0) {
            setDiag("remainder for hash partition must be an integer value greater than or equal to zero", .{});
            return error.RawDdlError;
        }
        if (remainder >= modulus) {
            setDiag("remainder for hash partition must be less than modulus", .{});
            return error.RawDdlError;
        }
        var tname: []const u8 = "";
        if (rel == .int) {
            if (rel.int == 0) {
                setDiag("could not open relation with OID 0", .{});
                return error.RawDdlError;
            }
            if (self.find("pg_class")) |pc| {
                const ci_name = findCol(pc, "relname");
                const ci_oid = findCol(pc, "oid");
                for (pc.rows.items, 0..) |r2, ri2| {
                    if (isRowDeleted(pc, ri2)) continue;
                    if (ci_name != null and ci_oid != null and ci_name.? < r2.len and ci_oid.? < r2.len and
                        r2[ci_oid.?] == .int and r2[ci_oid.?].int == rel.int and r2[ci_name.?] == .text)
                    {
                        tname = r2[ci_name.?].text;
                        break;
                    }
                }
            }
        } else if (rel == .text) tname = rel.text;
        if (tname.len == 0) return .{ .boolean = false };
        const tl = self.lowerDup(tname) catch "";
        defer self.gpa.free(tl);
        const hp = self.hash_parts.get(tl) orelse {
            setDiag("\"{s}\" is not a hash partitioned table", .{tname});
            return error.RawDdlError;
        };
        if (c.variadic) {
            if (c.args.len < 4) return .{ .boolean = false };
            const av = try self.eval(alloc, c.args[3], row, cols, group);
            if (av == .null) return .{ .boolean = false };
            const elems = (try self.arrayStrings(alloc, c.args[3])) orelse return .{ .boolean = false };
            if (elems.len != hp.keys.len) {
                setDiag("number of partitioning columns ({d}) does not match number of partition keys provided ({d})", .{ hp.keys.len, elems.len });
                return error.RawDdlError;
            }
            const etype = self.arrayElemSqlType(c.args[3]);
            const t0 = self.find(tname) orelse return .{ .boolean = false };
            for (hp.keys, 0..) |k, i| {
                const ci = findCol(t0, k.col) orelse continue;
                const want = normSqlType(if (t0.cols[ci].type_name.len > 0) t0.cols[ci].type_name else typeName(t0.cols[ci].ty));
                if (!std.ascii.eqlIgnoreCase(etype, "unknown") and !std.ascii.eqlIgnoreCase(etype, want)) {
                    setDiag("column {d} of the partition key has type \"{s}\", but supplied value is of type \"{s}\"", .{ i + 1, want, etype });
                    return error.RawDdlError;
                }
            }
            var h: u64 = 0;
            for (hp.keys, 0..) |k, i| {
                const s = elems[i];
                const hv: u64 = if (k.int_hash) blk: {
                    const iv = std.fmt.parseInt(i64, s, 10) catch 0;
                    break :blk @as(u64, @bitCast(iv)) +% HASH_SEED;
                } else @intCast(s.len);
                h = hashCombine(h, hv);
            }
            return .{ .boolean = @as(i64, @intCast(h % @as(u64, @intCast(modulus)))) == remainder };
        }
        if (c.args.len - 3 != hp.keys.len) {
            setDiag("number of partitioning columns ({d}) does not match number of partition keys provided ({d})", .{ hp.keys.len, c.args.len - 3 });
            return error.RawDdlError;
        }
        const t = self.find(tname) orelse return .{ .boolean = false };
        for (hp.keys, 0..) |k, i| {
            const ci = findCol(t, k.col) orelse continue;
            const want = normSqlType(if (t.cols[ci].type_name.len > 0) t.cols[ci].type_name else typeName(t.cols[ci].ty));
            const at = self.exprSqlType(c.args[i + 3]);
            if (!std.ascii.eqlIgnoreCase(at, "unknown") and !std.ascii.eqlIgnoreCase(at, want)) {
                setDiag("column {d} of the partition key has type {s}, but supplied value is of type {s}", .{ i + 1, want, at });
                return error.RawDdlError;
            }
        }
        var h: u64 = 0;
        for (hp.keys, 0..) |k, i| {
            const v = try self.eval(alloc, c.args[i + 3], row, cols, group);
            if (v == .null) continue;
            const hv: u64 = if (k.int_hash) blk: {
                const iv: i64 = switch (v) {
                    .int => |x| x,
                    .text => |s2| std.fmt.parseInt(i64, s2, 10) catch 0,
                    else => 0,
                };
                break :blk @as(u64, @bitCast(iv)) +% HASH_SEED;
            } else switch (v) {
                .text => |s2| @intCast(s2.len),
                else => @intCast((try formatValue(alloc, v)).len),
            };
            h = hashCombine(h, hv);
        }
        return .{ .boolean = @as(i64, @intCast(h % @as(u64, @intCast(modulus)))) == remainder };
    }
    fn registerExclude(self: *Engine, table: []const u8, ex: sql.ExclDef) !void {
        var nm: []const u8 = ex.name;
        if (nm.len == 0) {
            var b = std.ArrayList(u8).empty;
            try b.appendSlice(self.gpa, table);
            try b.append(self.gpa, '_');
            try b.appendSlice(self.gpa, ex.col);
            for (ex.include) |ic| {
                try b.append(self.gpa, '_');
                try b.appendSlice(self.gpa, ic);
            }
            try b.appendSlice(self.gpa, "_excl");
            nm = try b.toOwnedSlice(self.gpa);
        }
        var nb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(nb[0..@min(nm.len, nb.len)], nm[0..@min(nm.len, nb.len)]);
        const k = try self.gpa.dupe(u8, nl);
        const tbl = try self.gpa.dupe(u8, table);
        const col = try self.gpa.dupe(u8, ex.col);
        const op = try self.gpa.dupe(u8, ex.op);
        const am = try self.gpa.dupe(u8, ex.am);
        try self.excl_defs.append(self.gpa, .{ .name = k, .table = tbl, .col = col, .op = op, .am = am });
        const okey = try self.gpa.dupe(u8, nl);
        const oval = try self.gpa.dupe(u8, ex.op);
        self.excl_ops.put(okey, oval) catch {};
        const tkey = try self.gpa.dupe(u8, nl);
        const tval = try self.gpa.dupe(u8, table);
        self.index_names.put(tkey, tval) catch {};
        const oid = self.next_index_oid;
        self.next_index_oid += 1;
        const okey2 = try self.gpa.dupe(u8, nl);
        self.index_oids.put(okey2, oid) catch {};
        const mcols = try self.gpa.alloc(IdxColMeta, 1 + ex.include.len);
        mcols[0] = .{ .name = try self.gpa.dupe(u8, ex.col) };
        for (ex.include, 0..) |ic, i| mcols[i + 1] = .{ .name = try self.gpa.dupe(u8, ic), .include = true };
        if (self.index_meta.fetchRemove(nl)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value.am);
            for (old.value.cols) |cc| self.gpa.free(cc.name);
            if (old.value.cols.len > 0) self.gpa.free(old.value.cols);
        }
        const mk = try self.gpa.dupe(u8, nl);
        const mam = try self.gpa.dupe(u8, ex.am);
        self.index_meta.put(mk, .{ .am = mam, .cols = mcols }) catch {};
        {
            const kcols = try self.gpa.alloc([]const u8, 1);
            kcols[0] = try self.gpa.dupe(u8, ex.col);
            const icols = if (ex.include.len > 0) blk: {
                const ic = try self.gpa.alloc([]const u8, ex.include.len);
                for (ex.include, 0..) |c2, i| ic[i] = try self.gpa.dupe(u8, c2);
                break :blk ic;
            } else &[_][]const u8{};
            const ck = try self.gpa.dupe(u8, nl);
            self.constraints.put(ck, .{ .kind = .exclude, .table = try self.gpa.dupe(u8, table), .col = try self.gpa.dupe(u8, ex.col), .cols = kcols, .include = icols, .am = try self.gpa.dupe(u8, ex.am), .op = try self.gpa.dupe(u8, ex.op) }) catch {};
        }
    }
    fn execAlterColumnType(self: *Engine, a: anytype) EngineError!Result {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(a.table.len, tb.len)], a.table[0..@min(a.table.len, tb.len)]);
        if (self.typed_tables.contains(tl)) {
            setDiag("cannot alter column type of typed table", .{});
            return error.RawDdlError;
        }
        const t = self.find(a.table) orelse return error.TableNotFound;
        const ci = findCol(t, a.col) orelse return error.UnknownColumn;
        t.cols[ci].type_name = try self.gpa.dupe(u8, a.type_name);
        var lb: [64]u8 = undefined;
        const low = std.ascii.lowerString(lb[0..@min(a.type_name.len, lb.len)], a.type_name[0..@min(a.type_name.len, lb.len)]);
        if (std.mem.eql(u8, low, "bigint") or std.mem.eql(u8, low, "int8")) {
            t.cols[ci].ty = .int;
            t.cols[ci].int_bits = 8;
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execDropColumn(self: *Engine, d: anytype) EngineError!Result {
        var tb: [256]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(d.table.len, tb.len)], d.table[0..@min(d.table.len, tb.len)]);
        if (self.typed_tables.contains(tl)) {
            setDiag("cannot drop column from typed table", .{});
            return error.RawDdlError;
        }
        const t = self.find(d.table) orelse return error.TableNotFound;
        const ci = findCol(t, d.col) orelse return error.UnknownColumn;
        var i = ci;
        while (i + 1 < t.cols.len) : (i += 1) t.cols[i] = t.cols[i + 1];
        t.cols = t.cols[0 .. t.cols.len - 1];
        for (t.rows.items) |row| {
            var j = ci;
            while (j + 1 < row.len) : (j += 1) row[j] = row[j + 1];
        }
        var drop = std.ArrayList([]const u8).empty;
        defer drop.deinit(self.gpa);
        var it = self.index_meta.iterator();
        while (it.next()) |e| {
            const tbl = self.index_names.get(e.key_ptr.*) orelse continue;
            if (!std.ascii.eqlIgnoreCase(tbl, d.table)) continue;
            for (e.value_ptr.cols) |cc| if (std.ascii.eqlIgnoreCase(cc.name, d.col)) {
                drop.append(self.gpa, self.gpa.dupe(u8, e.key_ptr.*) catch continue) catch {};
                break;
            };
        }
        for (drop.items) |nm| {
            self.dropIndexByName(nm);
            self.gpa.free(nm);
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn advKeyArgs(self: *Engine, alloc: std.mem.Allocator, c: sql.Call, row: ?[]Value, cols: []Column, group: ?[]const []Value) EngineError!?AdvLock {
        if (c.args.len != 1 and c.args.len != 2) return null;
        const a = try self.eval(alloc, c.args[0], row, cols, group);
        const ai: i64 = switch (a) {
            .int => |x| x,
            else => return null,
        };
        if (c.args.len == 1) return .{ .classid = 0, .objid = ai, .subid = 1, .shared = false, .xact = false };
        const b = try self.eval(alloc, c.args[1], row, cols, group);
        const bi: i64 = switch (b) {
            .int => |x| x,
            else => return null,
        };
        return .{ .classid = ai, .objid = bi, .subid = 2, .shared = false, .xact = false };
    }
    fn advAcquire(self: *Engine, k0: AdvLock, shared: bool, xact: bool) void {
        for (self.adv_locks.items) |*l| {
            if (l.classid == k0.classid and l.objid == k0.objid and l.subid == k0.subid and l.shared == shared and l.xact == xact) {
                l.count += 1;
                return;
            }
        }
        var k = k0;
        k.shared = shared;
        k.xact = xact;
        self.adv_locks.append(self.gpa, k) catch {};
    }
    fn advUnlock(self: *Engine, k0: AdvLock, shared: bool) bool {
        for (self.adv_locks.items, 0..) |*l, i| {
            if (l.classid == k0.classid and l.objid == k0.objid and l.subid == k0.subid and l.shared == shared and !l.xact) {
                l.count -= 1;
                if (l.count <= 0) _ = self.adv_locks.orderedRemove(i);
                self.invalidateCatalogs();
                return true;
            }
        }
        for (self.adv_locks.items) |l| {
            if (l.classid == k0.classid and l.objid == k0.objid and l.subid == k0.subid and l.shared == shared and l.xact) {
                const wm = std.fmt.allocPrint(self.gpa, "you don't own a lock of type {s}", .{if (shared) "ShareLock" else "ExclusiveLock"}) catch "";
                pushWarning(wm, "", "");
                return false;
            }
        }
        const wm2 = std.fmt.allocPrint(self.gpa, "you don't own a lock of type {s}", .{if (shared) "ShareLock" else "ExclusiveLock"}) catch "";
        pushWarning(wm2, "", "");
        return false;
    }
    fn checkExclusion(self: *Engine, t: *Table, row: []const Value) EngineError!void {
        for (self.excl_defs.items) |e| {
            if (!std.ascii.eqlIgnoreCase(e.table, t.name)) continue;
            const ci = findCol(t, e.col) orelse continue;
            if (std.mem.eql(u8, e.op, "=") or e.op.len == 0) {
                if (ci >= row.len or row[ci] == .null) continue;
                self.ensureRowsMaterialized(t.name);
                for (t.rows.items, 0..) |orow, ri| {
                    if (isRowDeleted(t, ri) or !self.visibleRow(t, ri)) continue;
                    if (ci >= orow.len or orow[ci] == .null) continue;
                    if (Value.eql(orow[ci], row[ci])) {
                        const nv = try formatValue(self.gpa, row[ci]);
                        defer self.gpa.free(nv);
                        const ov = try formatValue(self.gpa, orow[ci]);
                        defer self.gpa.free(ov);
                        setDiag("conflicting key value violates exclusion constraint \"{s}\"\nDETAIL:  Key ({s})=({s}) conflicts with existing key ({s})=({s}).", .{ e.name, e.col, nv, e.col, ov });
                        return error.RawDdlError;
                    }
                }
                continue;
            }
            if (ci >= row.len or row[ci] != .text) continue;
            const nv = parseBox(row[ci].text) orelse continue;
            self.ensureRowsMaterialized(t.name);
            for (t.rows.items, 0..) |orow, ri| {
                if (isRowDeleted(t, ri) or !self.visibleRow(t, ri)) continue;
                if (ci >= orow.len or orow[ci] != .text) continue;
                const ov = parseBox(orow[ci].text) orelse continue;
                const ax0 = @min(nv[0], nv[2]);
                const ax1 = @max(nv[0], nv[2]);
                const ay0 = @min(nv[1], nv[3]);
                const ay1 = @max(nv[1], nv[3]);
                const bx0 = @min(ov[0], ov[2]);
                const bx1 = @max(ov[0], ov[2]);
                const by0 = @min(ov[1], ov[3]);
                const by1 = @max(ov[1], ov[3]);
                if (ax0 <= bx1 and bx0 <= ax1 and ay0 <= by1 and by0 <= ay1) {
                    setDiag("conflicting key value violates exclusion constraint \"{s}\"\nDETAIL:  Key ({s})=({s}) conflicts with existing key ({s})=({s}).", .{ e.name, e.col, row[ci].text, e.col, orow[ci].text });
                    return error.RawDdlError;
                }
            }
        }
    }
    fn indexDefText(self: *Engine, alloc: std.mem.Allocator, iname: []const u8) ![]const u8 {
        var nb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(nb[0..@min(iname.len, nb.len)], iname[0..@min(iname.len, nb.len)]);
        const meta = self.index_meta.get(nl);
        const table = self.index_names.get(nl) orelse "";
        var b = std.ArrayList(u8).empty;
        if (self.excl_ops.get(nl)) |op| {
            try b.appendSlice(alloc, "EXCLUDE USING ");
            try b.appendSlice(alloc, if (meta) |m| m.am else "gist");
            try b.appendSlice(alloc, " (");
            if (meta) |m| for (m.cols) |cc| {
                if (!cc.include) {
                    try b.appendSlice(alloc, cc.name);
                    try b.appendSlice(alloc, " WITH ");
                    try b.appendSlice(alloc, op);
                }
            };
            try b.append(alloc, ')');
            var ninc0: usize = 0;
            if (meta) |m| for (m.cols) |cc| {
                if (!cc.include) continue;
                if (ninc0 == 0) try b.appendSlice(alloc, " INCLUDE (") else try b.appendSlice(alloc, ", ");
                try b.appendSlice(alloc, cc.name);
                ninc0 += 1;
            };
            if (ninc0 > 0) try b.append(alloc, ')');
            return b.toOwnedSlice(alloc);
        }
        try b.appendSlice(alloc, if (self.idx_flags.get(nl)) |fl| (if (fl.unique) "CREATE UNIQUE INDEX " else "CREATE INDEX ") else "CREATE INDEX ");
        try b.appendSlice(alloc, iname);
        try b.appendSlice(alloc, " ON public.");
        try b.appendSlice(alloc, table);
        try b.appendSlice(alloc, " USING ");
        try b.appendSlice(alloc, if (meta) |m| m.am else "btree");
        try b.appendSlice(alloc, " (");
        var ncols: usize = 0;
        if (meta) |m| for (m.cols) |c| {
            if (c.include) continue;
            if (ncols > 0) try b.appendSlice(alloc, ", ");
            try b.appendSlice(alloc, c.name);
            ncols += 1;
        };
        try b.append(alloc, ')');
        var ninc: usize = 0;
        if (meta) |m| for (m.cols) |c| {
            if (!c.include) continue;
            if (ninc == 0) try b.appendSlice(alloc, " INCLUDE (") else try b.appendSlice(alloc, ", ");
            try b.appendSlice(alloc, c.name);
            ninc += 1;
        };
        if (ninc > 0) try b.append(alloc, ')');
        {
            var pb: [512]u8 = undefined;
            const pl = std.ascii.lowerString(pb[0..@min(iname.len, pb.len)], iname[0..@min(iname.len, pb.len)]);
            var pred: []const u8 = "";
            if (self.idx_flags.get(pl)) |ff| pred = ff.pred;
            if (pred.len > 0) {
                try b.appendSlice(alloc, " WHERE ");
                var ip: usize = 0;
                while (ip < pred.len) : (ip += 1) {
                    const ch = pred[ip];
                    if (ch == '!' and ip + 1 < pred.len and pred[ip + 1] == '=') {
                        try b.appendSlice(alloc, "<>");
                        ip += 1;
                        continue;
                    }
                    if (ch == '\'') {
                        try b.append(alloc, ch);
                        var jp = ip + 1;
                        while (jp < pred.len) : (jp += 1) {
                            try b.append(alloc, pred[jp]);
                            if (pred[jp] == '\'') break;
                        }
                        if (jp < pred.len) {
                            try b.appendSlice(alloc, "::text");
                            ip = jp;
                        }
                        continue;
                    }
                    try b.append(alloc, ch);
                }
            }
        }
        return b.toOwnedSlice(alloc);
    }
    fn aggNormType(alloc: std.mem.Allocator, t: []const u8) ![]const u8 {
        const trim = std.mem.trim(u8, t, " \t\r\n");
        var b: [128]u8 = undefined;
        const n = @min(trim.len, b.len);
        const l = std.ascii.lowerString(b[0..n], trim[0..n]);
        const pairs = [_][2][]const u8{
            .{ "int4", "integer" },      .{ "int", "integer" },                           .{ "integer", "integer" },
            .{ "int2", "smallint" },     .{ "smallint", "smallint" },                     .{ "int8", "bigint" },
            .{ "bigint", "bigint" },     .{ "float8", "double precision" },               .{ "double precision", "double precision" },
            .{ "float4", "real" },       .{ "real", "real" },                             .{ "bool", "boolean" },
            .{ "boolean", "boolean" },   .{ "varchar", "character varying" },             .{ "_int8", "bigint[]" },
            .{ "any", "any" },           .{ "anyelement", "anyelement" },                 .{ "anycompatible", "anycompatible" },
            .{ "anyarray", "anyarray" }, .{ "anycompatiblearray", "anycompatiblearray" }, .{ "internal", "internal" },
            .{ "cstring", "cstring" },   .{ "numeric", "numeric" },                       .{ "text", "text" },
            .{ "record", "record" },
        };
        for (pairs) |pr| if (std.mem.eql(u8, l, pr[0])) return alloc.dupe(u8, pr[1]);
        return alloc.dupe(u8, trim);
    }
    fn aggNormElem(self: *Engine, alloc: std.mem.Allocator, seg: []const u8) ![]const u8 {
        _ = self;
        var s2 = std.mem.trim(u8, seg, " \t\r\n");
        var prefix: []const u8 = "";
        if (std.ascii.startsWithIgnoreCase(s2, "variadic ")) {
            prefix = "VARIADIC ";
            s2 = std.mem.trim(u8, s2[9..], " \t\r\n");
        }
        if (prefix.len > 0) {
            if (std.mem.indexOfScalar(u8, s2, ' ')) |sp| {
                const head = s2[0..sp];
                var hb: [32]u8 = undefined;
                const hl = std.ascii.lowerString(hb[0..@min(head.len, hb.len)], head[0..@min(head.len, hb.len)]);
                if (!std.mem.eql(u8, hl, "double") and !std.mem.eql(u8, hl, "character") and head[0] != '"') s2 = std.mem.trim(u8, s2[sp..], " \t\r\n");
            }
        }
        if (s2.len >= 2 and s2[0] == '"' and s2[s2.len - 1] == '"') return std.fmt.allocPrint(alloc, "{s}{s}", .{ prefix, s2 });
        return std.fmt.allocPrint(alloc, "{s}{s}", .{ prefix, try aggNormType(alloc, s2) });
    }
    fn normAggArgs(self: *Engine, alloc: std.mem.Allocator, text: []const u8) ![]const u8 {
        const t = std.mem.trim(u8, text, " \t\r\n");
        if (t.len == 0) return "";
        if (std.mem.eql(u8, t, "*")) return "*";
        var out = std.ArrayList(u8).empty;
        var depth: usize = 0;
        var start: usize = 0;
        var i: usize = 0;
        while (i <= t.len) : (i += 1) {
            if (i < t.len) {
                const c = t[i];
                if (c == '(' or c == '[') depth += 1;
                if (c == ')' or c == ']') {
                    if (depth > 0) depth -= 1;
                }
                if (c != ',' or depth != 0) continue;
            }
            const seg = std.mem.trim(u8, t[start..i], " \t\r\n");
            start = i + 1;
            if (seg.len == 0) continue;
            var lb: [512]u8 = undefined;
            const ln = @min(seg.len, lb.len);
            const low = std.ascii.lowerString(lb[0..ln], seg[0..ln]);
            if (std.mem.indexOf(u8, low, "order by")) |ob| {
                const lhs = std.mem.trim(u8, seg[0..ob], " \t\r\n");
                const rhs = std.mem.trim(u8, seg[ob + 8 ..], " \t\r\n");
                if (out.items.len > 0) try out.appendSlice(alloc, ", ");
                try out.appendSlice(alloc, try self.aggNormElem(alloc, lhs));
                try out.appendSlice(alloc, " ORDER BY ");
                try out.appendSlice(alloc, try self.aggNormElem(alloc, rhs));
                continue;
            }
            if (out.items.len > 0) try out.appendSlice(alloc, ", ");
            try out.appendSlice(alloc, try self.aggNormElem(alloc, seg));
        }
        return out.toOwnedSlice(alloc);
    }
    fn aggKeyAlloc(self: *Engine, alloc: std.mem.Allocator, name: []const u8, args: []const u8) ![]const u8 {
        _ = self;
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        const base = if (std.mem.lastIndexOfScalar(u8, nl, '.')) |d| nl[d + 1 ..] else nl;
        return std.fmt.allocPrint(alloc, "{s}({s})", .{ base, args });
    }
    fn fnSigMatch(self: *Engine, name: []const u8, want: []const []const u8) bool {
        var lb: [128]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.func_argtypes.get(nl)) |ats| {
            if (ats.len != want.len) return false;
            for (ats, 0..) |a, i| if (!std.ascii.eqlIgnoreCase(a, want[i])) return false;
            return true;
        }
        for (builtin_sigs) |bs| {
            if (!std.ascii.eqlIgnoreCase(bs.name, nl)) continue;
            if (bs.args.len != want.len) continue;
            var ok = true;
            for (bs.args, 0..) |a, i| if (!std.ascii.eqlIgnoreCase(a, want[i])) {
                ok = false;
            };
            if (ok) return true;
        }
        return false;
    }
    fn fnRetOf(self: *Engine, name: []const u8) ?[]const u8 {
        var lb: [128]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.func_rets.get(nl)) |r| if (r.len > 0) return r;
        for (builtin_sigs) |bs| if (std.ascii.eqlIgnoreCase(bs.name, nl)) return bs.ret;
        return null;
    }
    fn fnStrictOf(self: *Engine, name: []const u8) bool {
        var lb: [128]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.func_strict.get(nl)) |v| return v;
        for (builtin_sigs) |bs| if (std.ascii.eqlIgnoreCase(bs.name, nl)) return bs.strict;
        return false;
    }
    fn fnSecondArg(self: *Engine, name: []const u8) ?[]const u8 {
        var lb: [128]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        if (self.func_argtypes.get(nl)) |ats| if (ats.len > 1) return ats[1];
        for (builtin_sigs) |bs| if (std.ascii.eqlIgnoreCase(bs.name, nl)) return if (bs.args.len > 1) bs.args[1] else null;
        return null;
    }
    fn noteCreateOwners(self: *Engine, tname: []const u8, t: *Table) void {
        for (t.cols) |c| {
            if (!c.serial) continue;
            const seqname = std.fmt.allocPrint(self.gpa, "{s}_{s}_seq", .{ tname, c.name }) catch continue;
            defer self.gpa.free(seqname);
            self.setOwner("sequence", seqname);
        }
        self.setOwner("table", tname);
    }
    fn curRoleName(self: *Engine) []const u8 {
        if (self.role_len > 0) return self.role_buf[0..self.role_len];
        return "zhdb";
    }
    fn isSuperRole(self: *Engine) bool {
        return self.role_len == 0;
    }
    fn aclKeyBuf(buf: []u8, kind: []const u8, name: []const u8) []const u8 {
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        const base = if (std.mem.lastIndexOfScalar(u8, nl, '.')) |d| nl[d + 1 ..] else nl;
        return std.fmt.bufPrint(buf, "{s}:{s}", .{ kind, base }) catch "";
    }
    fn aclKeyAlloc(self: *Engine, alloc: std.mem.Allocator, kind: []const u8, name: []const u8) ![]const u8 {
        _ = self;
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(name.len, lb.len)], name[0..@min(name.len, lb.len)]);
        const base = if (std.mem.lastIndexOfScalar(u8, nl, '.')) |d| nl[d + 1 ..] else nl;
        return std.fmt.allocPrint(alloc, "{s}:{s}", .{ kind, base });
    }
    fn setOwner(self: *Engine, kind: []const u8, name: []const u8) void {
        const key = self.aclKeyAlloc(self.gpa, kind, name) catch return;
        const role = self.gpa.dupe(u8, self.curRoleName()) catch return;
        if (self.owners.fetchRemove(key)) |old| {
            self.gpa.free(old.value);
        } else {
            self.owner_order.append(self.gpa, self.gpa.dupe(u8, key) catch "") catch {};
        }
        self.owners.put(key, role) catch {};
    }
    fn setOwnerRole(self: *Engine, kind: []const u8, name: []const u8, role: []const u8) void {
        const key = self.aclKeyAlloc(self.gpa, kind, name) catch return;
        const r = self.gpa.dupe(u8, role) catch return;
        if (self.owners.fetchRemove(key)) |old| {
            self.gpa.free(old.value);
        } else {
            self.owner_order.append(self.gpa, self.gpa.dupe(u8, key) catch "") catch {};
        }
        self.owners.put(key, r) catch {};
    }
    fn ownerOf(self: *Engine, kind: []const u8, name: []const u8) []const u8 {
        var kb: [400]u8 = undefined;
        const k = aclKeyBuf(&kb, kind, name);
        return self.owners.get(k) orelse "zhdb";
    }
    fn aclList(self: *Engine, key: []const u8) *std.ArrayList(AclEntry) {
        const gop = self.acls.getOrPut(key) catch return &dummy_acl_list;
        if (!gop.found_existing) {
            gop.key_ptr.* = self.gpa.dupe(u8, key) catch "";
            gop.value_ptr.* = .empty;
        }
        return gop.value_ptr;
    }
    fn aclEnsureOwner(self: *Engine, key: []const u8, kind: []const u8, name: []const u8) void {
        const list = self.aclList(key);
        const owner = self.ownerOf(kind, name);
        for (list.items) |en| if (std.ascii.eqlIgnoreCase(en.grantee, owner)) return;
        list.append(self.gpa, .{
            .grantee = self.gpa.dupe(u8, owner) catch "",
            .privs = 255,
            .grantable = 0,
            .grantor = self.gpa.dupe(u8, owner) catch "",
        }) catch {};
    }
    fn aclBitLetters(privs: u8, grantable: u8, out: *std.ArrayList(u8), alloc: std.mem.Allocator) !void {
        const bits = [_]struct { m: u8, c: u8 }{
            .{ .m = 2, .c = 'a' },  .{ .m = 1, .c = 'r' },  .{ .m = 4, .c = 'w' },  .{ .m = 8, .c = 'd' },
            .{ .m = 16, .c = 'D' }, .{ .m = 32, .c = 'x' }, .{ .m = 64, .c = 't' }, .{ .m = 128, .c = 'm' },
        };
        for (bits) |b| {
            if (privs & b.m == 0) continue;
            try out.append(alloc, b.c);
            if (grantable & b.m != 0) try out.append(alloc, '*');
        }
    }
    fn aclTextAlloc(self: *Engine, alloc: std.mem.Allocator, kind: []const u8, name: []const u8) ![]const u8 {
        var kb: [400]u8 = undefined;
        const k = aclKeyBuf(&kb, kind, name);
        const list = self.acls.getPtr(k) orelse return "";
        if (list.items.len == 0) return "";
        var out = std.ArrayList(u8).empty;
        try out.append(alloc, '{');
        for (list.items, 0..) |en, i| {
            if (i > 0) try out.append(alloc, ',');
            try out.appendSlice(alloc, en.grantee);
            try out.append(alloc, '=');
            try aclBitLetters(en.privs, en.grantable, &out, alloc);
            try out.append(alloc, '/');
            try out.appendSlice(alloc, en.grantor);
        }
        try out.append(alloc, '}');
        return out.toOwnedSlice(alloc);
    }
    fn execAclChange(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        const kind_name: []const u8 = if (a.kind == .database) "database" else "table";
        const key = try self.aclKeyAlloc(alloc, kind_name, a.name);
        if (a.kind == .table) {
            const rvn = self.resolveTableName(a.name);
            if (self.find(rvn) == null and self.views.get(rvn) == null) {
                var lb2: [256]u8 = undefined;
                const nl2 = std.ascii.lowerString(lb2[0..@min(a.name.len, lb2.len)], a.name[0..@min(a.name.len, lb2.len)]);
                if (!std.mem.startsWith(u8, nl2, "pg_") and !std.mem.startsWith(u8, nl2, "information_schema")) {
                    setDiag("relation \"{s}\" does not exist", .{a.name});
                    return error.TableNotFound;
                }
            }
        }
        const role = try self.gpa.dupe(u8, self.curRoleName());
        defer self.gpa.free(role);
        if (!a.revoke) self.aclEnsureOwner(key, kind_name, a.name);
        const list = self.aclList(key);
        for (a.roles) |grantee0| {
            if (a.revoke) {
                var i: usize = 0;
                while (i < list.items.len) {
                    const en = list.items[i];
                    if (!std.ascii.eqlIgnoreCase(en.grantee, grantee0)) {
                        i += 1;
                        continue;
                    }
                    const np = en.privs & ~a.privs;
                    const ng = en.grantable & ~a.privs;
                    if (np == 0 and ng == 0) {
                        self.gpa.free(en.grantee);
                        self.gpa.free(en.grantor);
                        _ = list.orderedRemove(i);
                    } else {
                        list.items[i].privs = np;
                        list.items[i].grantable = ng;
                        i += 1;
                    }
                }
                if (a.cascade) {
                    var j: usize = 0;
                    while (j < list.items.len) {
                        const en = list.items[j];
                        if (!std.ascii.eqlIgnoreCase(en.grantor, grantee0) or std.ascii.eqlIgnoreCase(en.grantee, grantee0)) {
                            j += 1;
                            continue;
                        }
                        self.gpa.free(en.grantee);
                        self.gpa.free(en.grantor);
                        _ = list.orderedRemove(j);
                    }
                }
                continue;
            }
            var found = false;
            for (list.items) |*en| {
                if (!std.ascii.eqlIgnoreCase(en.grantee, grantee0)) continue;
                en.privs |= a.privs;
                if (a.grantable) en.grantable |= a.privs;
                found = true;
                break;
            }
            if (!found) {
                list.append(self.gpa, .{
                    .grantee = self.gpa.dupe(u8, grantee0) catch "",
                    .privs = a.privs,
                    .grantable = if (a.grantable) a.privs else 0,
                    .grantor = self.gpa.dupe(u8, role) catch "",
                }) catch {};
            }
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn execAlterTableOwner(self: *Engine, a: anytype) EngineError!Result {
        const is_view = self.views.contains(a.table);
        if (self.find(a.table) == null and !is_view) return error.TableNotFound;
        if (!self.isOwnerRole("table", a.table)) {
            setDiag("must be owner of {s} {s}", .{ if (is_view) "view" else "table", stripSchema(a.table) });
            return error.RawDdlError;
        }
        if (!self.canSetRole(a.owner)) {
            setDiag("must be able to SET ROLE \"{s}\"", .{a.owner});
            return error.RawDdlError;
        }
        const key = try self.aclKeyAlloc(self.gpa, "table", a.table);
        const role = try self.gpa.dupe(u8, a.owner);
        if (self.owners.fetchRemove(key)) |old| {
            self.gpa.free(old.value);
        } else {
            self.owner_order.append(self.gpa, self.gpa.dupe(u8, key) catch "") catch {};
        }
        self.owners.put(key, role) catch {};
        self.invalidateCatalogs();
        return .{};
    }
    fn execDefaultPrivGrant(self: *Engine, a: anytype) EngineError!Result {
        const role = if (a.role.len > 0) a.role else self.curRoleName();
        for (self.default_privs.items) |dp| {
            if (std.ascii.eqlIgnoreCase(dp.role, role) and std.ascii.eqlIgnoreCase(dp.schema, a.schema)) return .{};
        }
        self.default_privs.append(self.gpa, .{
            .role = self.gpa.dupe(u8, role) catch "",
            .schema = self.gpa.dupe(u8, a.schema) catch "",
            .grantee = self.gpa.dupe(u8, a.grantee) catch "",
        }) catch {};
        return .{};
    }
    fn clearAcl(self: *Engine, kind: []const u8, name: []const u8) void {
        var kb: [400]u8 = undefined;
        const k = aclKeyBuf(&kb, kind, name);
        if (self.acls.fetchRemove(k)) |kv| {
            for (kv.value.items) |en| {
                self.gpa.free(en.grantee);
                self.gpa.free(en.grantor);
            }
            var list = kv.value;
            list.deinit(self.gpa);
            self.gpa.free(kv.key);
        }
    }
    fn clearOwner(self: *Engine, kind: []const u8, name: []const u8) void {
        var kb: [400]u8 = undefined;
        const kbuf = aclKeyBuf(&kb, kind, name);
        const key = self.gpa.dupe(u8, kbuf) catch return;
        if (self.owners.fetchRemove(key)) |old| {
            self.gpa.free(old.value);
            var i: usize = 0;
            while (i < self.owner_order.items.len) {
                if (std.mem.eql(u8, self.owner_order.items[i], key)) {
                    self.gpa.free(self.owner_order.items[i]);
                    _ = self.owner_order.orderedRemove(i);
                } else i += 1;
            }
        }
        self.gpa.free(key);
    }
    fn dropRoleDeps(self: *Engine, alloc: std.mem.Allocator, role: []const u8, det: *std.ArrayList(u8)) !bool {
        var any = false;
        var keys = std.ArrayList([]const u8).empty;
        defer keys.deinit(alloc);
        var kit = self.acls.iterator();
        while (kit.next()) |e| keys.append(alloc, e.key_ptr.*) catch {};
        std.mem.sort([]const u8, keys.items, {}, struct {
            fn less(_: void, a: []const u8, b: []const u8) bool {
                const ad = std.mem.startsWith(u8, a, "database:");
                const bd = std.mem.startsWith(u8, b, "database:");
                if (ad != bd) return ad;
                return std.mem.order(u8, a, b) == .lt;
            }
        }.less);
        for (keys.items) |k| {
            const list = self.acls.get(k) orelse continue;
            var hit = false;
            for (list.items) |en| {
                if (std.ascii.eqlIgnoreCase(en.grantee, role) or std.ascii.eqlIgnoreCase(en.grantor, role)) hit = true;
            }
            if (!hit) continue;
            const ci = std.mem.indexOfScalar(u8, k, ':') orelse continue;
            const kind = k[0..ci];
            const nm = k[ci + 1 ..];
            if (any) try det.appendSlice(alloc, "\n");
            any = true;
            const line = try std.fmt.allocPrint(alloc, "privileges for {s} {s}", .{ kind, nm });
            try det.appendSlice(alloc, line);
        }
        for (self.default_privs.items) |dp| {
            if (!std.ascii.eqlIgnoreCase(dp.role, role)) continue;
            if (any) try det.appendSlice(alloc, "\n");
            any = true;
            const line = try std.fmt.allocPrint(alloc, "owner of default privileges on new relations belonging to role {s} in schema {s}", .{ dp.role, dp.schema });
            try det.appendSlice(alloc, line);
        }
        for (self.owner_order.items) |k| {
            const owner = self.owners.get(k) orelse continue;
            if (!std.ascii.eqlIgnoreCase(owner, role)) continue;
            const ci = std.mem.indexOfScalar(u8, k, ':') orelse continue;
            const kind0 = k[0..ci];
            const nm = k[ci + 1 ..];
            if (std.mem.eql(u8, kind0, "table") and self.find(nm) == null and self.views.get(nm) == null) continue;
            const kind = if (std.mem.eql(u8, kind0, "table") and self.views.get(nm) != null) "view" else kind0;
            if (any) try det.appendSlice(alloc, "\n");
            any = true;
            if (std.mem.eql(u8, kind, "function")) {
                const line = try std.fmt.allocPrint(alloc, "owner of function {s}()", .{nm});
                try det.appendSlice(alloc, line);
            } else {
                const line = try std.fmt.allocPrint(alloc, "owner of {s} {s}", .{ kind, nm });
                try det.appendSlice(alloc, line);
            }
        }
        return any;
    }
    fn checkDropRole(self: *Engine, alloc: std.mem.Allocator, role: []const u8) EngineError!void {
        var det = std.ArrayList(u8).empty;
        defer det.deinit(alloc);
        const any = try self.dropRoleDeps(alloc, role, &det);
        if (!any) return;
        setDiag("role \"{s}\" cannot be dropped because some objects depend on it\nDETAIL:  {s}", .{ role, det.items });
        return error.RawDdlError;
    }
    fn execOwnedChange(self: *Engine, alloc: std.mem.Allocator, roles: []const []const u8, to: ?[]const u8) EngineError!Result {
        const cur = self.curRoleName();
        if (!self.isSuperRole()) {
            if (to) |tgt| {
                if (!self.canSetRole(tgt)) {
                    if (self.hasPrivsOfRole(tgt)) setDiag("must be able to SET ROLE \"{s}\"", .{tgt}) else setDiag("permission denied to reassign objects\nDETAIL:  Only roles with privileges of role \"{s}\" may reassign objects to it.", .{tgt});
                    return error.RawDdlError;
                }
            }
            for (roles) |r| {
                if (std.ascii.eqlIgnoreCase(r, cur)) continue;
                if (!self.hasPrivsOfRole(r)) {
                    if (to != null) setDiag("permission denied to reassign objects\nDETAIL:  Only roles with privileges of role \"{s}\" may reassign objects owned by it.", .{r}) else setDiag("permission denied to drop objects\nDETAIL:  Only roles with privileges of role \"{s}\" may drop objects owned by it.", .{r});
                } else {
                    setDiag("permission denied to drop objects\nDETAIL:  Only roles with privileges of role \"{s}\" may drop objects owned by it.", .{r});
                }
                return error.RawDdlError;
            }
        }
        if (to) |tgt| {
            for (self.owner_order.items) |k| {
                const owner = self.owners.get(k) orelse continue;
                var match = false;
                for (roles) |r| if (std.ascii.eqlIgnoreCase(owner, r)) {
                    match = true;
                };
                if (!match) continue;
                if (self.owners.fetchRemove(k)) |old| self.gpa.free(old.value);
                const nv = self.gpa.dupe(u8, tgt) catch "";
                self.owners.put(self.gpa.dupe(u8, k) catch "", nv) catch {};
            }
            self.invalidateCatalogs();
            return .{};
        }
        // DROP OWNED: drop objects owned by the roles, revoke their ACL items.
        var drops = std.ArrayList(struct { kind: []const u8, name: []const u8 }).empty;
        defer drops.deinit(alloc);
        for (self.owner_order.items) |k| {
            const owner = self.owners.get(k) orelse continue;
            var match = false;
            for (roles) |r| if (std.ascii.eqlIgnoreCase(owner, r)) {
                match = true;
            };
            if (!match) continue;
            const ci = std.mem.indexOfScalar(u8, k, ':') orelse continue;
            drops.append(alloc, .{ .kind = k[0..ci], .name = k[ci + 1 ..] }) catch {};
        }
        for (drops.items) |d| {
            if (std.mem.eql(u8, d.kind, "table")) {
                _ = self.execDropName(d.name, true) catch {};
            } else if (std.mem.eql(u8, d.kind, "schema")) {
                if (self.schema_oids.fetchRemove(d.name)) |kv| self.gpa.free(kv.key);
            } else if (std.mem.eql(u8, d.kind, "sequence")) {
                if (self.sequences.fetchRemove(d.name)) |kv| self.gpa.free(kv.key);
                {
                    var lb2: [128]u8 = undefined;
                    const nl2 = std.ascii.lowerString(lb2[0..@min(d.name.len, lb2.len)], d.name[0..@min(d.name.len, lb2.len)]);
                    if (self.seq_vals.fetchRemove(nl2)) |old| self.gpa.free(old.key);
                }
            } else if (std.mem.eql(u8, d.kind, "function")) {
                if (self.sql_funcs.fetchRemove(d.name)) |kv| {
                    self.gpa.free(kv.key);
                    self.gpa.free(kv.value);
                }
                if (self.plpgsql_funcs.fetchRemove(d.name)) |kv| {
                    self.gpa.free(kv.key);
                    self.gpa.free(kv.value);
                }
                if (self.stable_funcs.fetchRemove(d.name)) |kv| self.gpa.free(kv.key);
                if (self.sql_args.fetchRemove(d.name)) |kv| {
                    self.gpa.free(kv.key);
                    self.gpa.free(kv.value);
                }
            } else if (std.mem.eql(u8, d.kind, "type")) {
                if (self.composites.fetchRemove(d.name)) |kv| self.gpa.free(kv.key);
                if (self.enums.fetchRemove(d.name)) |kv| self.gpa.free(kv.key);
            }
            self.clearOwner(d.kind, d.name);
        }
        var all_keys = std.ArrayList([]const u8).empty;
        defer all_keys.deinit(alloc);
        var it = self.acls.iterator();
        while (it.next()) |e| all_keys.append(alloc, e.key_ptr.*) catch {};
        for (all_keys.items) |k| {
            const list = self.acls.getPtr(k) orelse continue;
            var i: usize = 0;
            while (i < list.items.len) {
                const en = list.items[i];
                var match = false;
                for (roles) |r| {
                    if (std.ascii.eqlIgnoreCase(en.grantee, r) or std.ascii.eqlIgnoreCase(en.grantor, r)) match = true;
                }
                if (!match) {
                    i += 1;
                    continue;
                }
                const ci = std.mem.indexOfScalar(u8, k, ':') orelse 0;
                const kind = k[0..ci];
                const nm = k[ci + 1 ..];
                const owner = self.ownerOf(kind, nm);
                if (std.ascii.eqlIgnoreCase(owner, en.grantee)) {
                    i += 1;
                    continue;
                }
                self.gpa.free(en.grantee);
                self.gpa.free(en.grantor);
                _ = list.orderedRemove(i);
            }
        }
        var i: usize = 0;
        while (i < self.default_privs.items.len) {
            const dp = self.default_privs.items[i];
            var match = false;
            for (roles) |r| if (std.ascii.eqlIgnoreCase(dp.role, r)) {
                match = true;
            };
            if (match) {
                self.gpa.free(dp.role);
                self.gpa.free(dp.schema);
                self.gpa.free(dp.grantee);
                _ = self.default_privs.orderedRemove(i);
            } else i += 1;
        }
        self.invalidateCatalogs();
        return .{};
    }
    fn cmdScope(self: *Engine) void {
        const tx = self.curTxid();
        if (tx != self.cmd_txid) {
            self.cmd_txid = tx;
            self.next_cmd = 0;
            self.combo_next = 0;
        }
    }
    fn consumeCommand(self: *Engine) void {
        self.cmdScope();
        self.cur_cmd = self.next_cmd;
        self.next_cmd +%= 1;
    }
    fn comboOrCmd(self: *Engine, t: *Table, ri: usize) u32 {
        if (ri < t.xmin.items.len and t.xmin.items[ri] == self.curTxid()) {
            const c = self.combo_next;
            self.combo_next +%= 1;
            return c;
        }
        return self.cur_cmd;
    }
    fn stampInsert(self: *Engine, t: *Table, ri: usize) void {
        if (ri < t.cmin.items.len) t.cmin.items[ri] = self.cur_cmd;
        if (ri < t.ctid_num.items.len) {
            t.ctid_num.items[ri] = t.next_ctid_num;
            t.next_ctid_num +%= 1;
        }
    }
    pub fn savepointCreate(self: *Engine, name: []const u8) !void {
        var sp = Savepoint{ .name = try self.gpa.dupe(u8, name) };
        errdefer sp.deinit(self.gpa);
        var it = self.tables.valueIterator();
        while (it.next()) |tp| {
            const t = tp.*;
            if (std.mem.startsWith(u8, t.name, "pg_")) continue;
            const dn = t.deleted.items.len;
            var sn = TableSnap{
                .t = t,
                .rows_len = t.rows.items.len,
                .dead_rows = t.dead_rows,
            };
            sn.deleted = try self.gpa.dupe(u8, t.deleted.items[0..dn]);
            sn.xmax = try self.gpa.dupe(u64, t.xmax.items);
            try sp.tables.append(self.gpa, sn);
        }
        try self.savepoints.append(self.gpa, sp);
    }
    pub fn savepointRollbackTo(self: *Engine, name: []const u8) void {
        var idx: ?usize = null;
        var i: usize = self.savepoints.items.len;
        while (i > 0) {
            i -= 1;
            if (std.ascii.eqlIgnoreCase(self.savepoints.items[i].name, name)) {
                idx = i;
                break;
            }
        }
        const at = idx orelse return;
        while (self.savepoints.items.len > at + 1) {
            var last = self.savepoints.pop().?;
            last.deinit(self.gpa);
        }
        const sp = &self.savepoints.items[at];
        for (sp.tables.items) |sn| {
            const t = sn.t;
            var r = sn.rows_len;
            while (r < t.rows.items.len) : (r += 1) self.gpa.free(t.rows.items[r]);
            if (t.rows.items.len > sn.rows_len) t.rows.shrinkRetainingCapacity(sn.rows_len);
            t.deleted.clearRetainingCapacity();
            t.deleted.appendSlice(self.gpa, sn.deleted) catch {};
            t.xmax.clearRetainingCapacity();
            t.xmax.appendSlice(self.gpa, sn.xmax) catch {};
            while (t.xmin.items.len > t.rows.items.len) _ = t.xmin.pop();
            while (t.cmin.items.len > t.rows.items.len) _ = t.cmin.pop();
            while (t.ctid_num.items.len > t.rows.items.len) _ = t.ctid_num.pop();
            while (t.ctid.items.len > t.rows.items.len) _ = t.ctid.pop();
            t.dead_rows = sn.dead_rows;
        }
        self.invalidateCatalogs();
    }
    pub fn savepointRelease(self: *Engine, name: []const u8) void {
        var idx: ?usize = null;
        var i: usize = self.savepoints.items.len;
        while (i > 0) {
            i -= 1;
            if (std.ascii.eqlIgnoreCase(self.savepoints.items[i].name, name)) {
                idx = i;
                break;
            }
        }
        const at = idx orelse return;
        while (self.savepoints.items.len > at) {
            var last = self.savepoints.pop().?;
            last.deinit(self.gpa);
        }
    }
    fn storeAgg(self: *Engine, info: AggInfo) !void {
        const key = try self.aggKeyAlloc(self.gpa, info.name, info.args);
        if (self.aggs.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            const o = old.value;
            self.gpa.free(o.name);
            self.gpa.free(o.args);
            self.gpa.free(o.ret);
            self.gpa.free(o.stype);
            self.gpa.free(o.sfunc);
            self.gpa.free(o.finalfunc);
            self.gpa.free(o.combine);
            self.gpa.free(o.serial);
            self.gpa.free(o.deserial);
            self.gpa.free(o.parallel);
            self.gpa.free(o.comment);
        }
        try self.aggs.put(key, info);
        var dup = false;
        for (self.agg_seq.items) |x| if (std.mem.eql(u8, x, key)) {
            dup = true;
        };
        if (!dup) try self.agg_seq.append(self.gpa, try self.gpa.dupe(u8, key));
        self.invalidateCatalogs();
    }
    fn aggOptionValue(opts: []const sql.AggOpt, name: []const u8) ?[]const u8 {
        for (opts) |o| if (!o.quoted and std.ascii.eqlIgnoreCase(o.name, name) and o.has_value) return o.value;
        return null;
    }
    fn execCreateAggregate(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        var args = try self.normAggArgs(alloc, a.args_text);
        var lb: [256]u8 = undefined;
        const nl = std.ascii.lowerString(lb[0..@min(a.name.len, lb.len)], a.name[0..@min(a.name.len, lb.len)]);
        const base = if (std.mem.lastIndexOfScalar(u8, nl, '.')) |d| nl[d + 1 ..] else nl;
        var seen: [24][]const u8 = undefined;
        _ = &seen;
        var stype: []const u8 = "";
        var sfunc: []const u8 = "";
        var finalfunc: []const u8 = "";
        var finalmodify: u8 = 'r';
        var combine: []const u8 = "";
        var serial: []const u8 = "";
        var deserial: []const u8 = "";
        var parallel: []const u8 = "u";
        var hypothetical = false;
        var have_basetype = false;
        var basetype_val: []const u8 = "";
        for (a.opts) |o| {
            var ob: [64]u8 = undefined;
            const on = std.ascii.lowerString(ob[0..@min(o.name.len, ob.len)], o.name[0..@min(o.name.len, ob.len)]);
            const known = !o.quoted and (std.mem.eql(u8, on, "sfunc") or std.mem.eql(u8, on, "sfunc1") or
                std.mem.eql(u8, on, "stype") or std.mem.eql(u8, on, "stype1") or std.mem.eql(u8, on, "basetype") or std.mem.eql(u8, on, "finalfunc") or std.mem.eql(u8, on, "finalfunc_extra") or std.mem.eql(u8, on, "finalfunc_modify") or std.mem.eql(u8, on, "initcond") or
                std.mem.eql(u8, on, "initcond1") or std.mem.eql(u8, on, "mstype") or std.mem.eql(u8, on, "msfunc") or std.mem.eql(u8, on, "minvfunc") or std.mem.eql(u8, on, "mfinalfunc") or std.mem.eql(u8, on, "mfinalfunc_extra") or
                std.mem.eql(u8, on, "mfinalfunc_modify") or std.mem.eql(u8, on, "msspace") or std.mem.eql(u8, on, "mfinalfunc_modify") or std.mem.eql(u8, on, "sspace") or std.mem.eql(u8, on, "sortop") or std.mem.eql(u8, on, "hypothetical") or
                std.mem.eql(u8, on, "parallel") or std.mem.eql(u8, on, "serialfunc") or std.mem.eql(u8, on, "deserialfunc") or std.mem.eql(u8, on, "combinefunc") or std.mem.eql(u8, on, "mfinalfunc") or std.mem.eql(u8, on, "msfunc") or
                std.mem.eql(u8, on, "minvfunc"));
            if (!known) {
                const wm = std.fmt.allocPrint(self.gpa, "aggregate attribute \"{s}\" not recognized", .{o.name}) catch "";
                pushWarning(wm, "", "");
                continue;
            }
            if (std.mem.eql(u8, on, "hypothetical")) hypothetical = true;
            if (std.mem.eql(u8, on, "basetype")) {
                have_basetype = true;
                basetype_val = o.value;
            }
            if (std.mem.eql(u8, on, "sfunc") or std.mem.eql(u8, on, "sfunc1")) sfunc = o.value;
            if (std.mem.eql(u8, on, "stype") or std.mem.eql(u8, on, "stype1")) stype = o.value;
            if (std.mem.eql(u8, on, "finalfunc")) finalfunc = o.value;
            if (std.mem.eql(u8, on, "finalfunc_modify")) {
                if (std.ascii.eqlIgnoreCase(o.value, "shareable")) finalmodify = 's' else if (std.ascii.eqlIgnoreCase(o.value, "read_only")) finalmodify = 'r' else if (std.ascii.eqlIgnoreCase(o.value, "read_write")) finalmodify = 'w';
            }
            if (std.mem.eql(u8, on, "serialfunc")) serial = o.value;
            if (std.mem.eql(u8, on, "deserialfunc")) deserial = o.value;
            if (std.mem.eql(u8, on, "combinefunc")) combine = o.value;
            if (std.mem.eql(u8, on, "parallel")) {
                if (!std.ascii.eqlIgnoreCase(o.value, "safe") and !std.ascii.eqlIgnoreCase(o.value, "restricted") and !std.ascii.eqlIgnoreCase(o.value, "unsafe")) {
                    setDiag("parameter \"parallel\" must be SAFE, RESTRICTED, or UNSAFE", .{});
                    return error.RawDdlError;
                }
                parallel = if (std.ascii.eqlIgnoreCase(o.value, "safe")) "s" else if (std.ascii.eqlIgnoreCase(o.value, "restricted")) "r" else "u";
            }
            seen[0] = o.name;
        }
        if (!a.has_args and !a.star and !have_basetype and stype.len > 0) {
            setDiag("aggregate input type must be specified", .{});
            return error.RawDdlError;
        }
        if (finalfunc.len > 0 and (std.ascii.eqlIgnoreCase(stype, "int4") or std.ascii.eqlIgnoreCase(stype, "integer")) and !self.regProcExists(finalfunc)) {
            const sd = try aggNormType(alloc, stype);
            setDiag("function {s}({s}) does not exist", .{ finalfunc, sd });
            return error.RawDdlError;
        }
        if (!a.has_args and !a.star and basetype_val.len > 0 and !std.ascii.eqlIgnoreCase(basetype_val, "any") and !std.mem.eql(u8, basetype_val, "*")) args = try aggNormType(alloc, basetype_val);
        const key = try self.aggKeyAlloc(alloc, a.name, args);
        for (self.agg_seq.items) |k3| {
            const ag3 = self.aggs.get(k3) orelse continue;
            var nb4: [256]u8 = undefined;
            const nl4 = std.ascii.lowerString(nb4[0..@min(ag3.name.len, nb4.len)], ag3.name[0..@min(ag3.name.len, nb4.len)]);
            const base4 = if (std.mem.lastIndexOfScalar(u8, nl4, '.')) |d| nl4[d + 1 ..] else nl4;
            if (std.ascii.eqlIgnoreCase(base4, base) and ag3.ordered != a.ordered) {
                setDiag("cannot change routine kind\nDETAIL:  \"{s}\" is an ordinary aggregate function.", .{base});
                return error.RawDdlError;
            }
        }
        if (stype.len == 0) {
            setDiag("aggregate stype must be specified", .{});
            return error.RawDdlError;
        }
        const stype_disp = try aggNormType(alloc, stype);
        if (self.aggs.get(key)) |ex| {
            if (!a.or_replace) {
                setDiag("function \"{s}\" already exists with same argument types", .{base});
                return error.RawDdlError;
            }
            if (a.ordered != ex.ordered) {
                setDiag("cannot change routine kind\nDETAIL:  \"{s}\" is an ordinary aggregate function.", .{base});
                return error.RawDdlError;
            }
        } else if (a.or_replace and self.func_argtypes.contains(base)) {
            setDiag("cannot change routine kind\nDETAIL:  \"{s}\" is a function.", .{base});
            return error.RawDdlError;
        }
        var ret: []const u8 = stype_disp;
        if (finalfunc.len > 0) ret = self.fnRetOf(finalfunc) orelse stype_disp;
        if (self.aggs.get(key)) |ex| {
            if (!std.ascii.eqlIgnoreCase(ex.ret, ret)) {
                setDiag("cannot change return type of existing function\nHINT:  Use DROP AGGREGATE {s} first.", .{key});
                return error.RawDdlError;
            }
        }
        if ((serial.len == 0) != (deserial.len == 0)) {
            setDiag("must specify both or neither of serialization and deserialization functions", .{});
            return error.RawDdlError;
        }
        const one_internal = [_][]const u8{"internal"};
        const bytea_internal = [_][]const u8{ "bytea", "internal" };
        if (serial.len > 0 and !self.fnSigMatch(serial, &one_internal)) {
            setDiag("function {s}(internal) does not exist", .{serial});
            return error.RawDdlError;
        }
        if (deserial.len > 0 and !self.fnSigMatch(deserial, &bytea_internal)) {
            setDiag("function {s}(bytea, internal) does not exist", .{deserial});
            return error.RawDdlError;
        }
        if (combine.len > 0 and !self.fnSigMatch(combine, &[_][]const u8{ "internal", "internal" })) {
            setDiag("function {s}(internal, internal) does not exist", .{combine});
            return error.RawDdlError;
        }
        if (sfunc.len > 0 and !a.star and args.len > 0) {
            var first: []const u8 = args;
            if (std.mem.indexOfScalar(u8, args, ',')) |cut| first = std.mem.trim(u8, args[0..cut], " ");
            if (std.ascii.startsWithIgnoreCase(first, "variadic ")) first = std.mem.trim(u8, first[9..], " ");
            const dt = self.fnSecondArg(sfunc) orelse "";
            const is_pseudo = struct {
                fn f(t: []const u8) bool {
                    return std.ascii.eqlIgnoreCase(t, "any") or std.ascii.eqlIgnoreCase(t, "internal") or
                        std.ascii.eqlIgnoreCase(t, "anyelement") or std.ascii.eqlIgnoreCase(t, "anyarray") or std.ascii.eqlIgnoreCase(t, "anynonarray") or std.ascii.eqlIgnoreCase(t, "record") or std.ascii.eqlIgnoreCase(t, "anycompatible") or std.ascii.eqlIgnoreCase(t, "anycompatiblearray");
                }
            }.f;
            const is_compat = struct {
                fn f(t: []const u8) bool {
                    return std.ascii.eqlIgnoreCase(t, "anycompatible") or std.ascii.eqlIgnoreCase(t, "anycompatiblearray");
                }
            }.f;
            var bad = false;
            if (!is_pseudo(dt)) {
                bad = !is_pseudo(first) and !std.ascii.eqlIgnoreCase(first, dt);
            } else if (is_compat(dt)) {
                bad = !is_pseudo(first) and !is_pseudo(stype_disp) and !std.ascii.eqlIgnoreCase(first, stype_disp);
            }
            if (bad) {
                setDiag("function {s}({s}, {s}) requires run-time type coercion", .{ sfunc, stype_disp, stype_disp });
                return error.RawDdlError;
            }
        }
        const msfunc = sql.AggOpt{ .name = "", .value = "" };
        _ = msfunc;
        const inv = aggOptionValue(a.opts, "minvfunc");
        if (inv) |iv| {
            if (self.fnRetOf(iv)) |rr| {
                if (!std.ascii.eqlIgnoreCase(rr, "double precision") and !std.ascii.eqlIgnoreCase(rr, "float8") and
                    !std.ascii.eqlIgnoreCase(rr, "bigint") and !std.ascii.eqlIgnoreCase(rr, "integer"))
                {
                    setDiag("return type of inverse transition function {s} is not double precision", .{iv});
                    return error.RawDdlError;
                }
                if (std.ascii.eqlIgnoreCase(rr, "bigint") or std.ascii.eqlIgnoreCase(rr, "integer")) {
                    setDiag("return type of inverse transition function {s} is not double precision", .{iv});
                    return error.RawDdlError;
                }
            }
            const fwd = aggOptionValue(a.opts, "msfunc") orelse sfunc;
            if (self.fnStrictOf(fwd) != self.fnStrictOf(iv)) {
                setDiag("strictness of aggregate's forward and inverse transition functions must match", .{});
                return error.RawDdlError;
            }
        }
        const oid = self.next_agg_oid;
        self.next_agg_oid += 1;
        try self.storeAgg(.{
            .name = try self.gpa.dupe(u8, a.name),
            .args = try self.gpa.dupe(u8, args),
            .star = a.star,
            .ordered = a.ordered,
            .hypothetical = hypothetical,
            .ret = try self.gpa.dupe(u8, ret),
            .stype = try self.gpa.dupe(u8, stype_disp),
            .sfunc = try self.gpa.dupe(u8, sfunc),
            .finalfunc = try self.gpa.dupe(u8, finalfunc),
            .finalmodify = finalmodify,
            .combine = try self.gpa.dupe(u8, combine),
            .serial = try self.gpa.dupe(u8, serial),
            .deserial = try self.gpa.dupe(u8, deserial),
            .parallel = try self.gpa.dupe(u8, parallel),
            .oid = oid,
            .comment = "",
        });
        return .{};
    }
    fn execCommentAggregate(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        const args = try self.normAggArgs(alloc, a.args_text);
        const key = try self.aggKeyAlloc(alloc, a.name, args);
        const gop = self.aggs.getPtr(key) orelse {
            setDiag("aggregate {s} does not exist", .{key});
            return error.RawDdlError;
        };
        self.gpa.free(gop.comment);
        gop.comment = if (a.comment) |c| try self.gpa.dupe(u8, c) else "";
        return .{};
    }
    fn execAlterAggregateRename(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        const args = try self.normAggArgs(alloc, a.args_text);
        const key = try self.aggKeyAlloc(alloc, a.name, args);
        const old = self.aggs.fetchRemove(key) orelse {
            setDiag("aggregate {s} does not exist", .{key});
            return error.RawDdlError;
        };
        self.gpa.free(old.key);
        var info = old.value;
        self.gpa.free(info.name);
        info.name = try self.gpa.dupe(u8, a.new_name);
        self.storeAgg(info) catch {};
        return .{};
    }
    fn execDropAggregate(self: *Engine, alloc: std.mem.Allocator, a: anytype) EngineError!Result {
        if (!a.if_exists) {
        var ait = std.mem.splitScalar(u8, a.args_text, ',');
        while (ait.next()) |raw| {
            const t = std.mem.trim(u8, raw, " \t\r\n");
            if (t.len == 0 or std.mem.eql(u8, t, "*")) continue;
            if (!self.regTypeKnown(t)) {
                setDiag("type \"{s}\" does not exist", .{t});
                return error.RawDdlError;
            }
        }
        }
        const args = try self.normAggArgs(alloc, a.args_text);
        const key = try self.aggKeyAlloc(alloc, a.name, args);
        if (self.aggs.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            const o = old.value;
            self.gpa.free(o.name);
            self.gpa.free(o.args);
            self.gpa.free(o.ret);
            self.gpa.free(o.stype);
            self.gpa.free(o.sfunc);
            self.gpa.free(o.finalfunc);
            self.gpa.free(o.combine);
            self.gpa.free(o.serial);
            self.gpa.free(o.deserial);
            self.gpa.free(o.parallel);
            self.gpa.free(o.comment);
            var si: usize = 0;
            while (si < self.agg_seq.items.len) {
                if (std.mem.eql(u8, self.agg_seq.items[si], key)) {
                    self.gpa.free(self.agg_seq.items[si]);
                    _ = self.agg_seq.orderedRemove(si);
                } else si += 1;
            }
            self.invalidateCatalogs();
            return .{};
        }
        if (a.if_exists) return .{};
        setDiag("aggregate {s} does not exist", .{key});
        return error.RawDdlError;
    }
    fn recordRule(self: *Engine, txt: []const u8, name: []const u8, rel: []const u8) void {
        const on_i = ciIndex(txt, " on ") orelse return;
        var rest = std.mem.trim(u8, txt[on_i + 4 ..], " \t\r\n");
        var ev_end: usize = 0;
        while (ev_end < rest.len and !std.ascii.isWhitespace(rest[ev_end])) ev_end += 1;
        if (ev_end == 0) return;
        const event = rest[0..ev_end];
        rest = rest[ev_end..];
        var cond = false;
        const do_i = ciIndex(rest, " do ") orelse return;
        const before_do = rest[0..do_i];
        if (ciIndex(before_do, " where ") != null) cond = true;
        var tail = std.mem.trim(u8, rest[do_i + 4 ..], " \t\r\n");
        var also = false;
        if (std.ascii.startsWithIgnoreCase(tail, "also")) {
            also = true;
            tail = std.mem.trim(u8, tail[4..], " \t\r\n");
        } else if (std.ascii.startsWithIgnoreCase(tail, "instead")) {
            tail = std.mem.trim(u8, tail[7..], " \t\r\n");
        }
        const util = std.ascii.startsWithIgnoreCase(tail, "notify");
        const multi = tail.len > 0 and tail[0] == '(';
        const nothing = std.ascii.startsWithIgnoreCase(tail, "nothing");
        var tb: [128]u8 = undefined;
        var eb: [32]u8 = undefined;
        const tl = std.ascii.lowerString(tb[0..@min(rel.len, tb.len)], rel[0..@min(rel.len, tb.len)]);
        const el = std.ascii.lowerString(eb[0..@min(event.len, eb.len)], event[0..@min(event.len, eb.len)]);
        const key = std.fmt.allocPrint(self.gpa, "{s}|{s}", .{ tl, el }) catch return;
        const nm = self.gpa.dupe(u8, name) catch "";
        const ev = self.gpa.dupe(u8, el) catch "";
        const tb2 = self.gpa.dupe(u8, tl) catch "";
        if (self.rules.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value.name);
            self.gpa.free(old.value.event);
            self.gpa.free(old.value.table);
        }
        self.rules.put(key, .{ .name = nm, .event = ev, .table = tb2, .also = also, .nothing = nothing, .multi = multi, .conditional = cond, .utility = util }) catch {};
    }
    fn recordTrigger(self: *Engine, txt: []const u8, name: []const u8, rel: []const u8) void {
        const on_i = ciIndex(txt, " on ") orelse return;
        const head = txt[0..on_i];
        const before = ciIndex(head, " before ") != null;
        const ins = ciIndex(head, "insert") != null;
        const upd = ciIndex(head, "update") != null;
        const del = ciIndex(head, "delete") != null;
        var rest = std.mem.trim(u8, txt[on_i + 4 ..], " \t\r\n");
        var te: usize = 0;
        while (te < rest.len and !std.ascii.isWhitespace(rest[te])) te += 1;
        rest = rest[te..];
        var func: []const u8 = "";
        if (ciIndex(rest, "execute")) |ex| {
            var tail = rest[ex + 7 ..];
            if (ciIndex(tail, "procedure")) |pp| tail = tail[pp + 9 ..] else if (ciIndex(tail, "function")) |pf| tail = tail[pf + 8 ..];
            var ft = std.mem.trim(u8, tail, " \t\r\n");
            var fe: usize = 0;
            while (fe < ft.len and (std.ascii.isAlphanumeric(ft[fe]) or ft[fe] == '_' or ft[fe] == '.')) fe += 1;
            func = ft[0..fe];
        }
        if (func.len == 0) return;
        const key = std.fmt.allocPrint(self.gpa, "{s}|{s}", .{ rel, name }) catch return;
        const nm = self.gpa.dupe(u8, name) catch "";
        const tb = self.gpa.dupe(u8, rel) catch "";
        const fnm = self.gpa.dupe(u8, func) catch "";
        if (self.triggers.fetchRemove(key)) |old| {
            self.gpa.free(old.key);
            self.gpa.free(old.value.name);
            self.gpa.free(old.value.table);
            self.gpa.free(old.value.func);
        }
        self.triggers.put(key, .{ .name = nm, .table = tb, .func = fnm, .before = before, .insert = ins, .update = upd, .delete = del }) catch {};
    }
    fn dropRuleTrigger(self: *Engine, kind: []const u8, rel: []const u8, nm: []const u8) void {
        if (eqi(kind, "rule")) {
            var it = self.rules.iterator();
            var victim: ?[]const u8 = null;
            while (it.next()) |e| {
                if (std.ascii.eqlIgnoreCase(e.value_ptr.table, rel) and std.ascii.eqlIgnoreCase(e.value_ptr.name, nm)) {
                    victim = e.key_ptr.*;
                    break;
                }
            }
            if (victim) |k| {
                const key = self.gpa.dupe(u8, k) catch return;
                if (self.rules.fetchRemove(key)) |old| {
                    self.gpa.free(old.key);
                    self.gpa.free(old.value.name);
                    self.gpa.free(old.value.event);
                    self.gpa.free(old.value.table);
                }
                self.gpa.free(key);
            }
        } else {
            var it = self.triggers.iterator();
            var victim: ?[]const u8 = null;
            while (it.next()) |e| {
                if (std.ascii.eqlIgnoreCase(e.value_ptr.table, rel) and std.ascii.eqlIgnoreCase(e.value_ptr.name, nm)) {
                    victim = e.key_ptr.*;
                    break;
                }
            }
            if (victim) |k| {
                const key = self.gpa.dupe(u8, k) catch return;
                if (self.triggers.fetchRemove(key)) |old| {
                    self.gpa.free(old.key);
                    self.gpa.free(old.value.name);
                    self.gpa.free(old.value.table);
                    self.gpa.free(old.value.func);
                }
                self.gpa.free(key);
            }
        }
    }
    fn rawDropDdl(self: *Engine, alloc: std.mem.Allocator, c: *RawCur, text: []const u8) EngineError!Result {
        var w = c.next() orelse return .{};
        if (eqi(w, "tuple") or eqi(w, "instance") or eqi(w, "rewrite")) {
            setDiag("syntax error at or near \"{s}\"", .{w});
            return error.RawDdlError;
        }
        if (eqi(w, "index")) {
            var ifx = false;
            var nm = c.next() orelse {
                setDiag("syntax error at or near \";\"", .{});
                return error.RawDdlError;
            };
            if (nm.len > 0 and std.ascii.isDigit(nm[0])) {
                setDiag("syntax error at or near \"{s}\"", .{nm});
                return error.RawDdlError;
            }
            if (eqi(nm, "concurrently")) nm = c.next() orelse return .{};
            if (eqi(nm, "if")) {
                _ = c.next();
                ifx = true;
                nm = c.next() orelse return .{};
            }
            var full = nm;
            if (std.mem.indexOfScalar(u8, full, ',') != null) full = full[0..std.mem.indexOfScalar(u8, full, ',').?];
            var ilb: [256]u8 = undefined;
            const il = std.ascii.lowerString(ilb[0..@min(full.len, ilb.len)], full[0..@min(full.len, ilb.len)]);
            if (self.index_names.get(il) != null) {
                const tbl = self.index_names.get(il).?;
                if (!self.isOwnerRole("table", tbl)) {
                    setDiag("must be owner of index {s}", .{stripSchema(full)});
                    return error.RawDdlError;
                }
                self.dropIndexByName(full);
                self.invalidateCatalogs();
                return .{};
            }
            if (!ifx) {
                setDiag("index \"{s}\" does not exist", .{stripSchema(full)});
                return error.TableNotFound;
            }
            return .{};
        }
        if (eqi(w, "materialized")) {
            _ = c.next();
            w = "view";
        } else if (eqi(w, "foreign")) {
            const n = c.next() orelse return .{};
            if (eqi(n, "data")) {
                _ = c.next();
                w = "fdw";
            } else w = "foreign table";
        } else if (eqi(w, "text")) {
            _ = c.next();
            const sub = c.next() orelse return .{};
            w = try std.fmt.allocPrint(alloc, "text search {s}", .{sub});
