            const n = c.next() orelse {
                setDiag("syntax error at or near \";\"", .{});
                return error.RawDdlError;
            };
            if (eqi(n, "class") or eqi(n, "family")) {
                var ifx = false;
                var nm = c.next() orelse return .{};
