                    }
                    if (r == .text and exprIsMacaddr8Column(b.lhs, cols)) {
                        if (parseMacaddr8(r.text)) |m| rv = .{ .text = try formatMacaddr8(alloc, m) };
                    } else if (l == .text and exprIsMacaddr8Column(b.rhs, cols)) {
