    fn srfEval(self: *Engine, alloc: std.mem.Allocator, c: sql.Call, row: ?[]Value, cols: []Column, group: ?[]const []Value) EngineError!?[]Value {
        const lname = blk: {
            if (std.mem.lastIndexOfScalar(u8, c.name, '.')) |d| break :blk c.name[d + 1 ..];
            break :blk c.name;
        };
        var out = std.ArrayList(Value).empty;
        if (std.ascii.eqlIgnoreCase(lname, "generate_series")) {
            if (c.args.len < 2) return error.SyntaxError;
            const av0 = if (c.args[0].* == .call and isSrfCall(c.args[0].call.name)) (try self.srfEval(alloc, c.args[0].call, row, cols, group)) orelse (try alloc.alloc(Value, 0)) else blk: {
                const one = try alloc.alloc(Value, 1);
                one[0] = try self.eval(alloc, c.args[0], row, cols, group);
                break :blk one;
            };
            const av1 = if (c.args[1].* == .call and isSrfCall(c.args[1].call.name))
                (try self.srfEval(alloc, c.args[1].call, row, cols, group)) orelse (try alloc.alloc(Value, 0))
            else blk: {
                const one = try alloc.alloc(Value, 1);
                one[0] = try self.eval(alloc, c.args[1], row, cols, group);
                break :blk one;
            };
            const n = @max(av0.len, av1.len);
            var step: i64 = 1;
            if (c.args.len >= 3) {
                const sv = try self.eval(alloc, c.args[2], row, cols, group);
                step = switch (sv) {
                    .int => |x| x,
                    else => 1,
                };
            }
            if (step == 0) return error.StepZero;
            var pi: usize = 0;
            while (pi < n) : (pi += 1) {
                const lo: i64 = if (pi < av0.len) switch (av0[pi]) {
                    .int => |v| v,
                    else => 0,
                } else if (av0.len == 1) switch (av0[0]) {
                    .int => |v| v,
                    else => 0,
                } else 0;
                const hi: i64 = if (pi < av1.len) switch (av1[pi]) {
                    .int => |v| v,
                    else => 0,
                } else if (av1.len == 1) switch (av1[0]) {
                    .int => |v| v,
                    else => 0,
                } else 0;
                var x = lo;
                while ((step > 0 and x <= hi) or (step < 0 and x >= hi)) {
                    try out.append(alloc, .{ .int = x });
                    const nx = @addWithOverflow(x, step);
                    if (nx[1] != 0) break;
                    x = nx[0];
                }
            }
            return out.items;
        }
        if (std.ascii.eqlIgnoreCase(lname, "unnest")) {
            if (c.args.len < 1) return error.SyntaxError;
            const v = try self.eval(alloc, c.args[0], row, cols, group);
            if (v == .text) {
                var t = std.mem.trim(u8, v.text, " \t\r\n");
                if (t.len >= 2 and t[0] == '{' and t[t.len - 1] == '}') {
                    t = t[1 .. t.len - 1];
                    var it = std.mem.splitScalar(u8, t, ',');
                    while (it.next()) |el0| {
                        var el = std.mem.trim(u8, el0, " \t\r\n");
                        if (el.len >= 2 and el[0] == '"' and el[el.len - 1] == '"') el = el[1 .. el.len - 1];
                        try out.append(alloc, .{ .text = el });
                    }
                }
            } else if (v != .null) try out.append(alloc, v);
            return out.items;
        }
        if (std.ascii.eqlIgnoreCase(lname, "generate_subscripts")) {
            if (c.args.len < 1) return error.SyntaxError;
            const v = try self.eval(alloc, c.args[0], row, cols, group);
            if (v == .text) {
                const t = std.mem.trim(u8, v.text, " \t\r\n");
                if (t.len >= 2 and t[0] == '{' and t[t.len - 1] == '}') {
                    const inner = t[1 .. t.len - 1];
                    var n: usize = 0;
                    if (inner.len > 0) {
                        n = 1;
                        for (inner) |ch| if (ch == ',') {
                            n += 1;
                        };
                    }
                    var i: i64 = 1;
                    while (i <= @as(i64, @intCast(n))) : (i += 1) try out.append(alloc, .{ .int = i });
                }
            }
            return out.items;
        }
        if (std.ascii.eqlIgnoreCase(lname, "txid_snapshot_xip") or std.ascii.eqlIgnoreCase(lname, "pg_snapshot_xip")) {
            if (c.args.len < 1) return error.SyntaxError;
            const v = try self.eval(alloc, c.args[0], row, cols, group);
            if (v == .text) if (snapBounds(v.text)) |b| {
                var it = std.mem.splitScalar(u8, b.rest, ',');
                while (it.next()) |part| {
                    const t = std.mem.trim(u8, part, " \t\r\n");
                    if (t.len == 0) continue;
                    const x = std.fmt.parseInt(i64, t, 10) catch continue;
                    try out.append(alloc, .{ .int = x });
                }
            };
            return out.items;
        }
        return null;
    }
