        .{ .tag = "[[:alnum:]]", .kind = 1 }, .{ .tag = "[[:alpha:]]", .kind = 2 }, .{ .tag = "[[:upper:]]", .kind = 3 }, .{ .tag = "[[:digit:]]", .kind = 4 },
