                return error.MoneyOutOfRange;
            }
            return .{ .text = try formatMoney(alloc, @divTrunc(a, r.int)) };
        }
        if (lm and r == .float) {
            const a = moneyCents(l) orelse return null;
            return try moneyRint(alloc, a, r.float, true);
        }
