                    .text => |t| std.fmt.parseFloat(f64, std.mem.trim(u8, t, " \t\r\n")) catch 0,
                    else => l.asFloat(),
                };
                const b: f64 = switch (r) {
                    .text => |t| std.fmt.parseFloat(f64, std.mem.trim(u8, t, " \t\r\n")) catch 0,
                    else => r.asFloat(),
                };
                if (b == 0) return error.DivisionByZero;
                return .{ .text = try std.fmt.allocPrint(alloc, "{d}", .{a / b}) };
            }
            if (both_int) {
                if (r.int == 0) return error.DivisionByZero;
                return .{ .int = @divTrunc(l.int, r.int) };
            }
            const d = r.asFloat();
            if (d == 0) return error.DivisionByZero;
            return .{ .float = l.asFloat() / d };
        },
        .shl, .shr => {
            if (l == .text and r == .text) {
                if (parsePoint(l.text)) |lp| {
                    if (parsePoint(r.text)) |rp| {
                        return .{ .boolean = if (op == .shl) fplt(lp[0], rp[0]) else fpgt(lp[0], rp[0]) };
                    }
                }
            }
            if (both_int) {
                const sh: u6 = @intCast(@as(u64, @bitCast(r.int)) & 63);
                const u: u64 = @bitCast(l.int);
                const shifted: u64 = if (op == .shl) u << sh else u >> sh;
                return .{ .int = @bitCast(shifted) };
            }
            return .null;
        },
        .mod => {
            if (both_int) {
                if (r.int == 0) return error.DivisionByZero;
                return .{ .int = @rem(l.int, r.int) };
            }
            const d = r.asFloat();
            if (d == 0) return error.DivisionByZero;
            return .{ .float = @mod(l.asFloat(), d) };
        },
        else => return .null,
    }
}
fn roundHalfEven(x: f64) i64 {
    const fl = @floor(x);
    const diff = x - fl;
    if (diff < 0.5) return @intFromFloat(fl);
    if (diff > 0.5) return @intFromFloat(fl + 1);
    const i: i64 = @intFromFloat(fl);
    return if (@mod(i, 2) == 0) i else i + 1;
}
fn castValue(alloc: std.mem.Allocator, v: Value, type_name: []const u8) EngineError!Value {
    return castValueMode(alloc, v, type_name, false);
}
fn castValueMode(alloc: std.mem.Allocator, v: Value, type_name: []const u8, numeric_mode: bool) EngineError!Value {
    if (v == .null) return .null;
    if (std.ascii.eqlIgnoreCase(type_name, "xid") or std.ascii.eqlIgnoreCase(type_name, "xid8")) {
        if (v == .uint) return if (std.ascii.eqlIgnoreCase(type_name, "xid")) .{ .uint = v.uint & 0xFFFFFFFF } else v;
        const t = switch (v) {
            .text => |x| x,
            else => try formatValue(alloc, v),
        };
        const bits: u8 = if (std.ascii.eqlIgnoreCase(type_name, "xid")) 32 else 64;
        switch (parseXidText(t, bits)) {
            .value => |x| return .{ .uint = x },
            .invalid => {
                setDiag("invalid input syntax for type {s}: \"{s}\"", .{ if (bits == 32) "xid" else "xid8", t });
                return error.RawDdlError;
            },
            .out_of_range => {
                setDiag("value \"{s}\" is out of range for type {s}", .{ t, if (bits == 32) "xid" else "xid8" });
                return error.RawDdlError;
            },
        }
    }
    if (std.ascii.eqlIgnoreCase(type_name, "txid_snapshot") or std.ascii.eqlIgnoreCase(type_name, "pg_snapshot")) {
        const t = switch (v) {
            .text => |x| x,
            else => try formatValue(alloc, v),
        };
        if (canonSnapshot(alloc, t)) |out| return .{ .text = out } else |_| {}
        setDiag("invalid input syntax for type pg_snapshot: \"{s}\"", .{t});
        return error.RawDdlError;
    }
    if (std.ascii.eqlIgnoreCase(type_name, "jsonb") or std.ascii.eqlIgnoreCase(type_name, "json")) {
        const t = switch (v) {
            .text => |x| x,
            else => try formatValue(alloc, v),
        };
        const isb = std.ascii.eqlIgnoreCase(type_name, "jsonb");
        const out = (try jsonValidate(alloc, t, isb)) orelse return error.JsonInvalid;
        return .{ .text = out };
    }
    if (std.ascii.eqlIgnoreCase(type_name, "pg_lsn")) {
