                .invalid => {
                    setDiag("invalid input syntax for type money: \"{s}\"", .{t});
                    return error.InvalidMoney;
                },
                .out_of_range => {
                    setDiag("value \"{s}\" is out of range for type money", .{t});
                    return error.MoneyOutOfRange;
