            .text => |x| x,
            else => try formatValue(alloc, v),
        };
        const p = parseTidText(t) orelse {
            setDiag("invalid input syntax for type tid: \"{s}\"", .{t});
            return error.RawDdlError;
        };
        return .{ .text = try formatTid(alloc, p) };
    }
    if (isTimetzTypeName(type_name)) {
