    return switch (ty) {
        .int => switch (v) {
            .int => v,
            .float => |f| .{ .int = if (numeric_mode) @intFromFloat(@round(f)) else roundHalfEven(f) },
            .text => |s| .{ .int = std.fmt.parseInt(i64, s, 10) catch 0 },
            else => .{ .int = 0 },
        },
        .float => switch (v) {
            .float => v,
            .int => |i| .{ .float = @as(f64, @floatFromInt(i)) },
            .text => |s| .{ .float = std.fmt.parseFloat(f64, s) catch 0 },
            else => .{ .float = 0 },
        },
        .text, .date, .timestamp => .{ .text = try formatValue(alloc, v) },
        .boolean => .{ .boolean = truthy(v) },
    };
}
fn fmtKey(alloc: std.mem.Allocator, v: Value) EngineError![]const u8 {
    return switch (v) {
        .text => |t| t,
        .int => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
        .uint => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
        .float => |f| try std.fmt.allocPrint(alloc, "{d}", .{f}),
        .boolean => |b| if (b) "true" else "false",
        .null => "",
    };
}
pub fn formatValue(alloc: std.mem.Allocator, v: Value) EngineError![]const u8 {
    return switch (v) {
        .null => "\\N",
        .int => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
        .uint => |i| try std.fmt.allocPrint(alloc, "{d}", .{i}),
        .float => |f| blk: {
            if (f != 0 and (@abs(f) >= 1e15 or @abs(f) < 1e-4)) {
                const se = try std.fmt.allocPrint(alloc, "{e}", .{f});
                if (std.mem.indexOfScalar(u8, se, 'e')) |ep| {
                    if (ep + 1 < se.len and se[ep + 1] != '-' and se[ep + 1] != '+') {
                        const nb = try alloc.alloc(u8, se.len + 1);
                        @memcpy(nb[0 .. ep + 1], se[0 .. ep + 1]);
                        nb[ep + 1] = '+';
                        @memcpy(nb[ep + 2 ..], se[ep + 1 ..]);
                        break :blk nb;
                    }
                }
                break :blk se;
            }
            const s0 = try std.fmt.allocPrint(alloc, "{d}", .{f});
            if (!pg_float_style and std.mem.indexOfAny(u8, s0, ".eE") == null)
                break :blk try std.fmt.allocPrint(alloc, "{s}.0", .{s0});
            break :blk s0;
        },
        .text => |s| s,
        .boolean => |b| if (b) "true" else "false",
    };
}
const InputErrorInfo = struct { message: []const u8, code: []const u8 };
fn parseBoolInput(text: []const u8) ?bool {
    const s = std.mem.trim(u8, text, " \t\r\n");
    const true_vals = [_][]const u8{ "t", "tr", "tru", "true", "y", "ye", "yes", "on", "1" };
    const false_vals = [_][]const u8{ "f", "fa", "fal", "fals", "false", "n", "no", "of", "off", "0" };
    for (true_vals) |v| if (std.ascii.eqlIgnoreCase(s, v)) return true;
    for (false_vals) |v| if (std.ascii.eqlIgnoreCase(s, v)) return false;
    return null;
}
fn sqlParamSubst(alloc: std.mem.Allocator, body: []const u8, sig: []const u8) ![]const u8 {
    var names = std.ArrayList([]const u8).empty;
    defer names.deinit(alloc);
    var it = std.mem.splitScalar(u8, sig, ',');
    while (it.next()) |part| {
        var toks = std.mem.tokenizeAny(u8, part, " \t\r\n");
        var nm = toks.next() orelse continue;
        if (nm.len > 0 and nm[0] == '"') nm = nm[1..@max(1, nm.len - 1)];
        if (std.ascii.eqlIgnoreCase(nm, "out") or std.mem.eql(u8, nm, "IN")) continue;
        try names.append(alloc, nm);
    }
    if (names.items.len == 0) return body;
    var out = std.ArrayList(u8).empty;
    var i: usize = 0;
    while (i < body.len) {
        const c = body[i];
        if (c == '\'') {
            const st = i;
            i += 1;
            while (i < body.len) {
                if (body[i] == '\'') {
                    if (i + 1 < body.len and body[i + 1] == '\'') {
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                i += 1;
            }
            try out.appendSlice(alloc, body[st..i]);
            continue;
        }
        if (std.ascii.isAlphabetic(c) or c == '_') {
            const st = i;
            i += 1;
            while (i < body.len and (std.ascii.isAlphanumeric(body[i]) or body[i] == '_')) i += 1;
            const tok = body[st..i];
            var idx: ?usize = null;
            for (names.items, 0..) |nm, k| if (std.ascii.eqlIgnoreCase(nm, tok)) {
                idx = k;
                break;
            };
            if (idx) |k| try out.appendSlice(alloc, try std.fmt.allocPrint(alloc, "${d}", .{k + 1})) else try out.appendSlice(alloc, tok);
            continue;
        }
        try out.append(alloc, c);
        i += 1;
    }
    return out.toOwnedSlice(alloc);
}
