        const b = pts.items[(k + 1) % n];
        if (segDist2(p, a, b) <= 1e-30) return true;
    }
    var inside = false;
    var j = n - 1;
    for (0..n) |k| {
        const a = pts.items[k];
        const b = pts.items[j];
        if ((a[1] > p[1]) != (b[1] > p[1])) {
            const xint = (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0];
            if (p[0] < xint) inside = !inside;
        }
        j = k;
    }
    return inside;
}
fn circleOf(text: []const u8) ?[3]f64 {
