                    if (i + 1 < end and txt[i + 1] == '"') {
                        try elem.append(alloc, '"');
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                if (txt[i] == '\\' and i + 1 < end) {
                    try elem.append(alloc, txt[i + 1]);
                    i += 2;
                    continue;
                }
                try elem.append(alloc, txt[i]);
                i += 1;
            }
            try out.append(alloc, .{ .text = try elem.toOwnedSlice(alloc) });
        } else {
            while (i < end and txt[i] != ',') : (i += 1) {
                if (txt[i] == '\\' and i + 1 < end) {
                    try elem.append(alloc, txt[i + 1]);
                    i += 1;
                    continue;
